  // ==================== BIO-ENDOCRINE HORMONE & CONNECTOME SYSTEM ====================
  // Mengadaptasi sistem hormon mahluk hidup: Dopamin vs Kortisol (Stres)
  // Mengetahui bug, error, dan kode yang tidak berhubungan / terisolasi secara seketika!
  const BioEndocrine = {
    hormones: {
      dopamine: 100,
      cortisol: 0,
      serotonin: 100,
      adrenaline: 0
    },
    history: [],
    isolatedNodes: [],
    connectedCount: 0,
    totalAudited: 0,

    init() {
      // 1. Tangkap seluruh unhandled error / promise rejection di browser secara global
      window.addEventListener('error', (evt) => {
        const errorMsg = evt.message || (evt.error && evt.error.message) || 'Script exception';
        const file = evt.filename ? evt.filename.split('/').pop() : 'script';
        const line = evt.lineno || '?';
        this.secreteStress(30, `Exception di ${file}:${line} (${errorMsg})`);
      });

      window.addEventListener('unhandledrejection', (evt) => {
        const reason = evt.reason ? (evt.reason.message || String(evt.reason)) : 'Unhandled Promise';
        this.secreteStress(25, `Unhandled Promise Rejection: ${reason}`);
      });

      // 2. Pasang audit connectome awal setelah DOM stabil
      setTimeout(() => {
        this.auditConnectome(true);
        this.updateUI();
      }, 1200);

      // 3. Metabolisme berkala: homeostatik setiap 15 detik
      setInterval(() => {
        if (this.hormones.cortisol > 0) {
          this.hormones.cortisol = Math.max(0, Math.round((this.hormones.cortisol - 2) * 10) / 10);
        }
        if (this.hormones.dopamine < 100 && this.hormones.cortisol <= 10) {
          this.hormones.dopamine = Math.min(100, this.hormones.dopamine + 1);
        }
        if (this.hormones.adrenaline > 0) {
          this.hormones.adrenaline = Math.max(0, this.hormones.adrenaline - 3);
        }
        this.hormones.serotonin = Math.round((this.hormones.dopamine * 0.7) + ((100 - this.hormones.cortisol) * 0.3));
        this.updateUI();
      }, 15000);
    },

    secreteDopamine(amount, reason) {
      this.hormones.dopamine = Math.min(100, Math.round((this.hormones.dopamine + amount) * 10) / 10);
      this.hormones.cortisol = Math.max(0, Math.round((this.hormones.cortisol - (amount * 0.35)) * 10) / 10);
      this.log('dopamine', amount, reason);
      this.updateUI();
    },

    secreteStress(amount, reason, isIsolatedCode = false) {
      this.hormones.cortisol = Math.min(100, Math.round((this.hormones.cortisol + amount) * 10) / 10);
      this.hormones.dopamine = Math.max(5, Math.round((this.hormones.dopamine - (amount * 0.5)) * 10) / 10);
      this.hormones.adrenaline = Math.min(100, Math.round((this.hormones.adrenaline + (amount * 0.6)) * 10) / 10);
      this.log('cortisol', amount, reason);
      this.updateUI();
      try {
        if (typeof AudioEngine !== 'undefined' && AudioEngine.playBeep && STATE.soundEnabled && amount >= 25) {
          AudioEngine.playBeep(220, 'sawtooth', 0.12, 0.04);
        }
      } catch (_) {}
    },

    auditConnectome(silent = false) {
      const issues = [];
      let connected = 0;
      let total = 0;

      if (typeof els === 'object') {
        for (const [key, val] of Object.entries(els)) {
          total++;
          let isNodeConnected = false;
          if (val instanceof NodeList || Array.isArray(val)) {
            isNodeConnected = val.length > 0;
          } else {
            isNodeConnected = Boolean(val);
          }

          if (!isNodeConnected) {
            issues.push(`Reseptor DOM terisolasi: els.${key} tidak ditemukan di DOM`);
          } else {
            connected++;
          }
        }
      }

      this.connectedCount = connected;
      this.totalAudited = total;
      this.isolatedNodes = issues;

      if (issues.length > 0) {
        this.secreteStress(issues.length * 12, `Terdeteksi ${issues.length} simpul kode terisolasi / reseptor hilang!`, true);
      } else if (!silent) {
        this.secreteDopamine(12, `Audit connectome: Semua ${connected} simpul kode terhubung harmonis (0 terisolasi)`);
      }
      this.updateUI();
      return { connected, total, issues };
    },

    purgeStress() {
      this.hormones.cortisol = 0;
      this.hormones.dopamine = 100;
      this.hormones.serotonin = 100;
      this.hormones.adrenaline = 0;
      this.isolatedNodes = [];
      this.log('endorphin', 50, 'Suntikan Endorfin: Keseimbangan & kestabilan dipulihkan penuh');
      this.updateUI();
      try {
        if (typeof AudioEngine !== 'undefined' && AudioEngine.playBeep && STATE.soundEnabled) {
          AudioEngine.playBeep(880, 'sine', 0.18, 0.06);
          setTimeout(() => AudioEngine.playBeep(1320, 'triangle', 0.22, 0.05), 120);
        }
      } catch (_) {}
      if (typeof showToast === 'function') {
        showToast('🌿 Endorfin disuntikkan: Stres netral (0%), Dopamin 100%!', 'success');
      }
    },

    log(type, amount, reason) {
      this.history.unshift({
        time: new Date().toLocaleTimeString(),
        type,
        amount: Math.round(amount),
        reason,
        dopamine: Math.round(this.hormones.dopamine),
        cortisol: Math.round(this.hormones.cortisol)
      });
      if (this.history.length > 40) this.history.pop();
    },

    updateUI() {
      const btn = document.getElementById('endocrineMonitorBtn');
      const heartIcon = document.getElementById('endocrineHeartIcon');
      if (btn) {
        const d = Math.round(this.hormones.dopamine);
        const c = Math.round(this.hormones.cortisol);

        btn.classList.remove('status-happy', 'status-stressed', 'status-critical');
        if (c >= 60) {
          btn.classList.add('status-critical');
          if (heartIcon) heartIcon.style.color = '#FF0055';
          btn.title = `⚠️ PERINGATAN STRES KODE TINGGI (${c}%): Terdeteksi bug atau komponen terisolasi! Klik untuk cek telemetri.`;
        } else if (c >= 30) {
          btn.classList.add('status-stressed');
          if (heartIcon) heartIcon.style.color = '#FFB703';
          btn.title = `Stres Kode Meningkat (${c}%): Ada gangguan atau peringatan. Klik untuk cek telemetri.`;
        } else {
          btn.classList.add('status-happy');
          if (heartIcon) heartIcon.style.color = '#00FFC2';
          btn.title = `Kondisi Kode Sangat Kuat & Prima (Dopamin ${d}%, Bebas Bug). Klik untuk melihat bio-telemetri.`;
        }
      }

      const modal = document.getElementById('endocrineTelemetryModal');
      if (modal && modal.classList.contains('show')) {
        this.renderModalContent();
      }
    },

    renderModalContent() {
      const esc = (s) => (typeof escapeHtml === 'function' ? escapeHtml(s) : String(s).replace(/[&<>"']/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m])));
      const d = Math.round(this.hormones.dopamine);
      const c = Math.round(this.hormones.cortisol);
      const s = Math.round(this.hormones.serotonin);
      const a = Math.round(this.hormones.adrenaline);

      const dVal = document.getElementById('endocrineDopamineVal');
      const dBar = document.getElementById('endocrineDopamineBar');
      const cVal = document.getElementById('endocrineCortisolVal');
      const cBar = document.getElementById('endocrineCortisolBar');
      const sVal = document.getElementById('endocrineSerotoninVal');
      const aVal = document.getElementById('endocrineAdrenalineVal');
      const connVal = document.getElementById('endocrineConnectomeVal');

      if (dVal) dVal.innerText = `${d}%`;
      if (dBar) dBar.style.width = `${d}%`;
      if (cVal) {
        if (c === 0) {
          cVal.innerHTML = `<span style="color:#00FFC2; font-weight:700;">0%</span> <span style="font-size:0.75rem; color:#00FFC2; font-weight:600;">(Bebas Bug / 0% Kerusakan)</span>`;
        } else if (c < 30) {
          cVal.innerHTML = `<span style="color:#FFD166; font-weight:700;">${c}%</span> <span style="font-size:0.75rem; color:#FFD166; font-weight:600;">(Stres Ringan)</span>`;
        } else {
          cVal.innerHTML = `<span style="color:#FF4D4D; font-weight:700;">${c}%</span> <span style="font-size:0.75rem; color:#FF4D4D; font-weight:bold;">(Peringatan Bug Aktif!)</span>`;
        }
      }
      if (cBar) cBar.style.width = `${c}%`;
      if (sVal) sVal.innerText = `${s}%`;
      if (aVal) aVal.innerText = `${a}%`;

      const cDesc = document.getElementById('endocrineCortisolDesc');
      if (cDesc) {
        if (c === 0) {
          cDesc.innerHTML = `<span style="color:#00FFC2; font-weight:600;">● Kondisi Prima:</span> Tidak ada bug, jaringan stabil, dan seluruh ${this.connectedCount || 249} simpul kode terhubung harmonis.`;
        } else {
          const lastCortisol = this.history.find(h => h.type === 'cortisol');
          cDesc.innerHTML = `<span style="color:#FFB703; font-weight:600;">⚠️ Pemicu Stres Terakhir:</span> ${esc(lastCortisol?.reason || 'Terdeteksi anomali pada alur kode/jaringan.')}`;
        }
      }

      const isolatedBox = document.getElementById('endocrineIsolatedBox');
      const isolatedTag = document.getElementById('endocrineIsolatedTag');
      const isolatedContent = document.getElementById('endocrineIsolatedContent');

      if (this.isolatedNodes.length > 0) {
        if (connVal) connVal.innerText = `${this.connectedCount}/${this.totalAudited} Simpul (${this.isolatedNodes.length} Terisolasi)`;
        if (isolatedBox) isolatedBox.classList.add('has-issues');
        if (isolatedTag) {
          isolatedTag.className = 'isolated-status-tag tag-warning';
          isolatedTag.innerText = `⚠️ ${this.isolatedNodes.length} Terisolasi`;
        }
        if (isolatedContent) {
          isolatedContent.innerHTML = `
            <div style="color:#FFB703; font-weight:700; margin-bottom:4px;">Terdeteksi komponen kode/DOM yang tidak terhubung:</div>
            <ul style="margin:0; padding-left:18px; color:var(--text-main);">
              ${this.isolatedNodes.map(err => `<li><code>${esc(err)}</code></li>`).join('')}
            </ul>
          `;
        }
      } else {
        if (connVal) connVal.innerText = `100% Harmonis (${this.connectedCount} Simpul)`;
        if (isolatedBox) isolatedBox.classList.remove('has-issues');
        if (isolatedTag) {
          isolatedTag.className = 'isolated-status-tag tag-healthy';
          isolatedTag.innerText = 'Semua Terhubung Sempurna';
        }
        if (isolatedContent) {
          isolatedContent.innerHTML = `Semua modul logika, pemanggil antarmuka, dan reseptor DOM saling terikat dengan harmonis. Tidak ditemukan kode terisolasi atau bug struktural.`;
        }
      }

      const logsList = document.getElementById('endocrineLogsList');
      if (logsList) {
        if (this.history.length === 0) {
          logsList.innerHTML = `<div style="color:var(--text-dim); font-size:0.75rem; text-align:center; padding:12px;">Belum ada fluktuasi hormon tercatat.</div>`;
        } else {
          logsList.innerHTML = this.history.map(item => {
            const isDop = item.type === 'dopamine';
            const isEnd = item.type === 'endorphin';
            const cls = isDop ? 'log-dopamine' : (isEnd ? 'log-endorphin' : 'log-cortisol');
            const sign = (isDop || isEnd) ? `+${item.amount}%` : `+${item.amount}% Stres`;
            const label = isDop ? 'Dopamin' : (isEnd ? 'Endorfin' : 'Kortisol');
            return `
              <div class="endocrine-log-entry ${cls}">
                <span class="log-time">${item.time}</span>
                <span class="log-badge">${sign} ${label}</span>
                <span class="log-msg" title="${esc(item.reason)}">${esc(item.reason)}</span>
              </div>
            `;
          }).join('');
        }
      }
    }
  };

  // Expose to window for global bio-telemetry, console inspection, and diagnostic audit
  window.BioEndocrine = BioEndocrine;

  // ==================== FULL-SCREEN IMAGE LIGHTBOX (ChatGPT & Gemini Style) ====================
  const ImageLightbox = {
    modal: null,
    img: null,
    imgWrapper: null,
    counter: null,
    prevBtn: null,
    nextBtn: null,
    images: [],
    currentIndex: 0,
    isZoomed: false,
    touchStartX: 0,
    touchEndX: 0,

    init() {
      this.modal = els.imageLightboxModal;
      this.img = els.lightboxImg;
      this.imgWrapper = els.lightboxImgWrapper;
      this.counter = els.lightboxCounter;
      this.prevBtn = els.lightboxPrevBtn;
      this.nextBtn = els.lightboxNextBtn;

      els.lightboxCloseBtn?.addEventListener('click', () => this.close());
      els.lightboxBackdrop?.addEventListener('click', () => this.close());
      this.prevBtn?.addEventListener('click', (e) => { e.stopPropagation(); this.prev(); });
      this.nextBtn?.addEventListener('click', (e) => { e.stopPropagation(); this.next(); });
      
      els.lightboxZoomInBtn?.addEventListener('click', (e) => { e.stopPropagation(); this.toggleZoom(true); });
      els.lightboxZoomOutBtn?.addEventListener('click', (e) => { e.stopPropagation(); this.toggleZoom(false); });
      els.lightboxDownloadBtn?.addEventListener('click', (e) => { e.stopPropagation(); this.download(); });

      // Double-click image to toggle zoom
      this.img?.addEventListener('dblclick', () => this.toggleZoom());
      this.img?.addEventListener('click', (e) => {
        if (this.isZoomed) {
          e.stopPropagation();
          this.toggleZoom(false);
        }
      });

      // Keyboard navigation
      document.addEventListener('keydown', (e) => {
        if (!this.isOpen()) return;
        if (e.key === 'Escape') this.close();
        if (e.key === 'ArrowLeft') this.prev();
        if (e.key === 'ArrowRight') this.next();
      });

      // Mobile Touch Swipe support
      const stage = $('#lightboxImageStage');
      if (stage) {
        stage.addEventListener('touchstart', (e) => {
          if (e.touches && e.touches[0]) this.touchStartX = e.touches[0].clientX;
        }, { passive: true });

        stage.addEventListener('touchend', (e) => {
          if (this.isZoomed) return; // Nonaktifkan swipe berganti foto saat pengguna sedang zoom & panning
          if (e.changedTouches && e.changedTouches[0]) {
            this.touchEndX = e.changedTouches[0].clientX;
            const diff = this.touchStartX - this.touchEndX;
            if (Math.abs(diff) > 45) {
              if (diff > 0) this.next();
              else this.prev();
            }
          }
        }, { passive: true });
      }
    },

    isOpen() {
      return this.modal && this.modal.style.display === 'flex';
    },

    open(imagesArray, index = 0) {
      if (!Array.isArray(imagesArray) || imagesArray.length === 0) return;
      this.images = imagesArray;
      this.currentIndex = Math.max(0, Math.min(index, imagesArray.length - 1));
      this.isZoomed = false;
      this.imgWrapper?.classList.remove('is-zoomed');
      
      this.updateView();
      if (this.modal) {
        this.modal.style.display = 'flex';
        document.body.style.overflow = 'hidden';
        history.pushState({ modal: 'lightbox' }, '');
      }
      AudioEngine.click();
    },

    updateView() {
      if (!this.img || this.images.length === 0) return;
      const currentSrc = this.images[this.currentIndex];
      this.img.src = currentSrc;

      if (this.counter) {
        this.counter.innerText = `${this.currentIndex + 1} / ${this.images.length}`;
      }

      if (this.prevBtn) {
        this.prevBtn.style.display = this.images.length > 1 ? 'flex' : 'none';
      }
      if (this.nextBtn) {
        this.nextBtn.style.display = this.images.length > 1 ? 'flex' : 'none';
      }
    },

    next() {
      if (this.images.length <= 1) return;
      this.currentIndex = (this.currentIndex + 1) % this.images.length;
      this.toggleZoom(false);
      this.updateView();
      AudioEngine.click();
    },

    prev() {
      if (this.images.length <= 1) return;
      this.currentIndex = (this.currentIndex - 1 + this.images.length) % this.images.length;
      this.toggleZoom(false);
      this.updateView();
      AudioEngine.click();
    },

    toggleZoom(forceState = null) {
      this.isZoomed = forceState !== null ? forceState : !this.isZoomed;
      if (this.imgWrapper) {
        this.imgWrapper.classList.toggle('is-zoomed', this.isZoomed);
      }
    },

    async download() {
      if (!this.images[this.currentIndex]) return;
      const src = this.images[this.currentIndex];
      showToast('Mengunduh foto resolusi tinggi...', 'info');
      const fileName = `zoz_foto_${Date.now()}_${this.currentIndex + 1}.png`;
      try {
        if (src.startsWith('data:')) {
          const a = document.createElement('a');
          a.href = src;
          a.download = fileName;
          document.body.appendChild(a);
          a.click();
          setTimeout(() => a.remove(), 500);
          return;
        }
        const resp = await fetch(src, { mode: 'cors' });
        const blob = await resp.blob();
        const blobUrl = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = blobUrl;
        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        setTimeout(() => {
          a.remove();
          URL.revokeObjectURL(blobUrl);
        }, 3000);
        showToast('Foto berhasil diunduh.');
      } catch (err) {
        const a = document.createElement('a');
        a.href = src;
        a.download = fileName;
        a.target = '_blank';
        document.body.appendChild(a);
        a.click();
        setTimeout(() => a.remove(), 500);
        // F14: jalur fallback TIDAK boleh menampilkan toast "berhasil" — unduhan
        // otomatis sering diblokir CORS dan tab baru hanya membuka gambar.
        showToast('Gagal mengunduh langsung (CORS) — gambar dibuka di tab baru, gunakan klik-kanan → Simpan Gambar.', 'error');
      }
      AudioEngine.click();
    },

    close(triggerHistoryBack = true) {
      if (!this.modal || this.modal.style.display === 'none') return;
      this.modal.style.display = 'none';
      document.body.style.overflow = '';
      this.toggleZoom(false);
      AudioEngine.click();

      if (triggerHistoryBack && history.state?.modal === 'lightbox') {
        history.back();
      }
    }
  };

  // ==================== INDEXEDDB CHAT VAULT ====================
  const ChatDB = {
    db: null,
    async init() {
      return new Promise((resolve) => {
        try {
          const req = indexedDB.open('ZozRouterChatDB_v2', 1);
          req.onupgradeneeded = (e) => {
            const db = e.target.result;
            if (!db.objectStoreNames.contains('sessions')) {
              db.createObjectStore('sessions', { keyPath: 'id' });
            }
          };
          req.onsuccess = (e) => {
            this.db = e.target.result;
            resolve(this.db);
          };
          req.onerror = () => resolve(null);
        } catch (e) {
          resolve(null);
        }
      });
    },
    async saveSession(session) {
      if (!session || !session.id) return false;
      if (!this.db) await this.init();
      if (!this.db) return false;
      return new Promise((resolve) => {
        try {
          const tx = this.db.transaction('sessions', 'readwrite');
          tx.objectStore('sessions').put(session);
          tx.oncomplete = () => resolve(true);
          tx.onerror = () => resolve(false);
        } catch (e) {
          resolve(false);
        }
      });
    },
    async getSession(id) {
      if (!id) return null;
      if (!this.db) await this.init();
      if (!this.db) return null;
      return new Promise((resolve) => {
        try {
          const tx = this.db.transaction('sessions', 'readonly');
          const req = tx.objectStore('sessions').get(id);
          req.onsuccess = () => resolve(req.result || null);
          req.onerror = () => resolve(null);
        } catch (e) {
          resolve(null);
        }
      });
    },
    async saveAllSessions(sessions) {
      if (!this.db) await this.init();
      if (!this.db || !Array.isArray(sessions)) return false;
      return new Promise((resolve) => {
        try {
          const tx = this.db.transaction('sessions', 'readwrite');
          const store = tx.objectStore('sessions');
          // TANPA perintah clear() pada store: metode ini dipakai untuk import/penyimpanan batch,
          // jadi menghapus seluruh store dulu berarti sesi lain yang tidak ikut
          // dikirim ikut terhapus. Penghapusan sesi kini eksplisit (ChatDB.deleteSession).
          sessions.forEach(s => store.put(s));
          tx.oncomplete = () => resolve(true);
          tx.onerror = () => resolve(false);
        } catch (e) {
          resolve(false);
        }
      });
    },
    async getAllSessions() {
      if (!this.db) await this.init();
      if (!this.db) return [];
      return new Promise((resolve) => {
        try {
          const tx = this.db.transaction('sessions', 'readonly');
          const req = tx.objectStore('sessions').getAll();
          req.onsuccess = () => resolve(req.result || []);
          req.onerror = () => resolve([]);
        } catch (e) {
          resolve([]);
        }
      });
    },
    async deleteSession(id) {
      if (!this.db) await this.init();
      if (!this.db) return false;
      return new Promise((resolve) => {
        try {
          const tx = this.db.transaction('sessions', 'readwrite');
          tx.objectStore('sessions').delete(id);
          tx.oncomplete = () => resolve(true);
          tx.onerror = () => resolve(false);
        } catch (e) {
          resolve(false);
        }
      });
    },
    async clearAllSessions() {
      if (!this.db) await this.init();
      if (!this.db) return false;
      return new Promise((resolve) => {
        try {
          const tx = this.db.transaction('sessions', 'readwrite');
          tx.objectStore('sessions').clear();
          tx.oncomplete = () => resolve(true);
          tx.onerror = () => resolve(false);
        } catch (e) {
          resolve(false);
        }
      });
    }
  };

  // ==================== INDEXEDDB WORKSPACE VAULT (v260) ====================
  const WorkspaceDB = {
    db: null,
    async init() {
      return new Promise((resolve) => {
        try {
          const req = indexedDB.open('ZozRouterWorkspaceDB_v1', 1);
          req.onupgradeneeded = (e) => {
            const db = e.target.result;
            if (!db.objectStoreNames.contains('workspace')) {
              db.createObjectStore('workspace', { keyPath: 'key' });
            }
          };
          req.onsuccess = (e) => {
            this.db = e.target.result;
            resolve(this.db);
          };
          req.onerror = () => resolve(null);
        } catch (_) {
          resolve(null);
        }
      });
    },
    async saveWorkspace(workspaceState) {
      if (!this.db) await this.init();
      if (!this.db) return false;
      return new Promise((resolve) => {
        try {
          const tx = this.db.transaction('workspace', 'readwrite');
          const cleanFiles = (workspaceState.files || []).map(f => ({
            name: f.name,
            path: f.path || f.name,
            size: f.size,
            type: f.type || 'text/plain',
            lastModified: f.lastModified || Date.now(),
            content: f.content || ''
          }));
          tx.objectStore('workspace').put({
            key: 'current_workspace',
            dirName: workspaceState.dirName || '',
            platform: workspaceState.platform || 'auto',
            enabled: Boolean(workspaceState.enabled),
            files: cleanFiles,
            snapshots: workspaceState.snapshots || {},
            timestamp: Date.now()
          });
          tx.oncomplete = () => resolve(true);
          tx.onerror = () => resolve(false);
        } catch (_) {
          resolve(false);
        }
      });
    },
    async loadWorkspace() {
      if (!this.db) await this.init();
      if (!this.db) return null;
      return new Promise((resolve) => {
        try {
          const tx = this.db.transaction('workspace', 'readonly');
          const req = tx.objectStore('workspace').get('current_workspace');
          req.onsuccess = () => resolve(req.result || null);
          req.onerror = () => resolve(null);
        } catch (_) {
          resolve(null);
        }
      });
    },
    async clearWorkspace() {
      if (!this.db) await this.init();
      if (!this.db) return false;
      return new Promise((resolve) => {
        try {
          const tx = this.db.transaction('workspace', 'readwrite');
          tx.objectStore('workspace').delete('current_workspace');
          tx.oncomplete = () => resolve(true);
          tx.onerror = () => resolve(false);
        } catch (_) {
          resolve(false);
        }
      });
    }
  };

  function findWorkspaceFile(targetName) {
    if (!targetName || !STATE.localWorkspace || !Array.isArray(STATE.localWorkspace.files) || STATE.localWorkspace.files.length === 0) return null;
    const clean = String(targetName).trim().toLowerCase();
    const norm = clean.replace(/^[./\\]+/, '').replace(/\\/g, '/');
    const base = norm.split('/').pop();

    return STATE.localWorkspace.files.find(f => {
      const fn = (f.name || '').toLowerCase();
      const fp = (f.path || '').toLowerCase().replace(/^[./\\]+/, '').replace(/\\/g, '/');
      const fb = fn.split('/').pop();
      return fn === clean || fp === clean || fn === norm || fp === norm || fb === base || fp.endsWith('/' + base);
    }) || null;
  }

  // ==================== CLAUDE-CODE PARITY NATIVE SERVER WORKSPACE API ====================
  // Mengizinkan modifikasi langsung file fisik di disk lokal proyek tanpa unduh berkas baru
  const ServerWorkspaceAPI = {
    isAvailable: false,
    dirName: '',
    rootDir: '',

    async checkStatus() {
      if (IS_GITHUB_PAGES || IS_CLOUD_HOSTED) {
        this.isAvailable = false;
        return false;
      }
      try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 2500);
        const res = await fetch('/api/workspace/status', {
          method: 'GET',
          headers: { 'X-User-ID': STATE.userId },
          signal: controller.signal
        });
        clearTimeout(timeoutId);
        if (res.ok) {
          const data = await res.json();
          this.isAvailable = Boolean(data && data.available && data.canWrite);
          this.dirName = (data && data.dirName) || 'zoz-router';
          this.rootDir = (data && data.root) || '';
          return this.isAvailable;
        }
      } catch (_) {
        this.isAvailable = false;
      }
      return false;
    },

    async getFiles() {
      if (!this.isAvailable) return [];
      try {
        const res = await fetch('/api/workspace/files', {
          headers: { 'X-User-ID': STATE.userId }
        });
        if (res.ok) {
          const data = await res.json();
          return data.files || [];
        }
      } catch (e) {
        console.warn('ServerWorkspaceAPI getFiles failed:', e.message);
      }
      return [];
    },

    async readFile(filePath) {
      if (!this.isAvailable) return null;
      try {
        const res = await fetch(`/api/workspace/read?path=${encodeURIComponent(filePath)}`, {
          headers: { 'X-User-ID': STATE.userId }
        });
        if (res.ok) {
          const data = await res.json();
          return data.content;
        }
      } catch (e) {
        console.warn('ServerWorkspaceAPI readFile failed:', e.message);
      }
      return null;
    },

    async writeFile(filePath, content, note = '', encoding = 'utf8') {
      try {
        const res = await fetch('/api/workspace/write', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-User-ID': STATE.userId
          },
          body: JSON.stringify({
            path: filePath,
            content: content,
            encoding: encoding || 'utf8',
            backup: true,
            note: note
          })
        });
        if (res.ok) {
          return await res.json();
        }
        const errData = await res.json().catch(() => ({}));
        throw new Error(errData.error || `HTTP ${res.status}`);
      } catch (e) {
        throw e;
      }
    },

    async deleteFile(filePath) {
      try {
        const res = await fetch('/api/workspace/delete', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-User-ID': STATE.userId
          },
          body: JSON.stringify({ path: filePath })
        });
        if (res.ok) return await res.json();
        const err = await res.json().catch(() => ({}));
        throw new Error(err.error || `HTTP ${res.status}`);
      } catch (e) {
        throw e;
      }
    }
  };

  // ==================== DEVICE-FIRST NATIVE STORAGE & PERSISTENCE ====================
  const DeviceStorage = {
    isDeviceBackendAvailable: false,

    async init() {
      if (IS_GITHUB_PAGES || IS_CLOUD_HOSTED) {
        this.isDeviceBackendAvailable = false;
        return;
      }
      try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 2000);
        const res = await fetch('/api/health', {
          method: 'GET',
          headers: { 'X-User-ID': STATE.userId },
          signal: controller.signal
        });
        clearTimeout(timeoutId);
        if (res.ok) {
          const data = await res.json();
          if (data && data.storage === 'device-disk' && !IS_CLOUD_HOSTED) {
            this.isDeviceBackendAvailable = true;
          }
        }
      } catch (e) {
        this.isDeviceBackendAvailable = false;
      }
    },

    async getSessionsList() {
      if (!this.isDeviceBackendAvailable) return null;
      try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 2500);
        const res = await fetch('/api/sessions', {
          headers: { 'X-User-ID': STATE.userId },
          signal: controller.signal
        });
        clearTimeout(timeoutId);
        if (res.ok) {
          const data = await res.json();
          return data.sessions || [];
        }
      } catch (e) {
        console.warn('DeviceStorage getSessionsList failed:', e.message);
      }
      return null;
    },

    async getSession(id) {
      if (this.isDeviceBackendAvailable) {
        try {
          const controller = new AbortController();
          const timeoutId = setTimeout(() => controller.abort(), 3000);
          const res = await fetch(`/api/sessions/${encodeURIComponent(id)}`, {
            headers: { 'X-User-ID': STATE.userId },
            signal: controller.signal
          });
          clearTimeout(timeoutId);
          if (res.ok) {
            return await res.json();
          }
        } catch (e) {
          console.warn('DeviceStorage getSession failed, falling back to ChatDB:', e.message);
        }
      }
      try {
        const localSess = await ChatDB.getSession(id);
        if (localSess) return localSess;
      } catch (dbErr) {
        console.warn('ChatDB getSession fallback error:', dbErr.message);
      }
      return null;
    },

    async saveSession(session) {
      if (!session || !session.id) return;
      session.userId = STATE.userId;
      // Safety guard: Never overwrite disk storage with an unhydrated lazy-loaded session
      if (session._isLazyDisk) {
        return;
      }
      if (this.isDeviceBackendAvailable) {
        try {
          const res = await fetch('/api/sessions', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'X-User-ID': STATE.userId
            },
            body: JSON.stringify({ ...session, userId: STATE.userId })
          });
          if (!res.ok) console.warn('[DeviceStorage] save gagal:', res.status);
        } catch (e) {
          console.warn('DeviceStorage saveSession failed:', e.message);
        }
      }
      // Also save in local ChatDB vault
      await ChatDB.saveSession(session);
    },

    async updateSessionMetadata(id, patch) {
      if (!id || !patch) return;
      if (this.isDeviceBackendAvailable) {
        try {
          await fetch(`/api/sessions/${encodeURIComponent(id)}`, {
            method: 'PATCH',
            headers: {
              'Content-Type': 'application/json',
              'X-User-ID': STATE.userId
            },
            body: JSON.stringify({ ...patch, userId: STATE.userId })
          });
        } catch (e) {
          console.warn('DeviceStorage updateSessionMetadata failed:', e.message);
        }
      }
      const sess = STATE.sessions.find(s => s.id === id);
      if (sess) {
        Object.assign(sess, patch);
        sess.userId = STATE.userId;
        if (!sess._isLazyDisk || (sess.messages && sess.messages.length > 0)) {
          await ChatDB.saveSession(sess);
        }
      }
    },

    async renameSession(id, newTitle) {
      if (!id || !newTitle) return;
      if (this.isDeviceBackendAvailable) {
        try {
          await fetch(`/api/sessions/${encodeURIComponent(id)}`, {
            method: 'PUT',
            headers: {
              'Content-Type': 'application/json',
              'X-User-ID': STATE.userId
            },
            body: JSON.stringify({ title: newTitle, userId: STATE.userId })
          });
        } catch (e) {
          console.warn('DeviceStorage renameSession failed:', e.message);
        }
      }
      const sess = STATE.sessions.find(s => s.id === id);
      if (sess) {
        sess.title = newTitle;
        sess.userId = STATE.userId;
        await ChatDB.saveSession(sess);
      }
    },

    async deleteSession(id) {
      if (!id) return;
      if (this.isDeviceBackendAvailable) {
        try {
          await fetch(`/api/sessions/${encodeURIComponent(id)}`, {
            method: 'DELETE',
            headers: { 'X-User-ID': STATE.userId }
          });
        } catch (e) {
          console.warn('DeviceStorage deleteSession failed:', e.message);
        }
      }
      await ChatDB.deleteSession(id);
    },

    async clearAllSessions() {
      if (this.isDeviceBackendAvailable) {
        try {
          await fetch('/api/sessions', {
            method: 'DELETE',
            headers: { 'X-User-ID': STATE.userId }
          });
        } catch (e) {
          console.warn('DeviceStorage clearAllSessions failed:', e.message);
        }
      }
      await ChatDB.clearAllSessions();
    },

    async uploadFile(base64Data) {
      if (!this.isDeviceBackendAvailable || !base64Data) return null;
      try {
        const res = await fetch('/api/upload', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-User-ID': STATE.userId || 'default',
            'x-user-id': STATE.userId || 'default'
          },
          body: JSON.stringify({ data: base64Data, userId: STATE.userId || 'default' })
        });
        if (res.ok) {
          const data = await res.json();
          return data.url;
        }
      } catch (e) {
        console.warn('DeviceStorage uploadFile failed:', e.message);
      }
      return null;
    }
  };

  // Safe Session Storage Helper (absorbs Safari Private Browsing QuotaExceededError & SecurityError)
  const safeSessionStorage = {
    getItem(key) {
      try { return sessionStorage.getItem(key); } catch (_) { return null; }
    },
    setItem(key, val) {
      try { sessionStorage.setItem(key, String(val)); } catch (_) {}
    },
    removeItem(key) {
      try { sessionStorage.removeItem(key); } catch (_) {}
    }
  };

  // Safe Local Storage Helper (absorbs Safari Private Browsing QuotaExceededError & SecurityError)
  const safeLocalStorage = {
    getItem(key) {
      try { return localStorage.getItem(key); } catch (_) { return null; }
    },
    setItem(key, val) {
      try { localStorage.setItem(key, String(val)); } catch (_) {}
    },
    removeItem(key) {
      try { localStorage.removeItem(key); } catch (_) {}
    }
  };

  function loadPersistedStateSync() {
    try {
      const savedSettings = localStorage.getItem('zoz_router_settings_v1');
      if (savedSettings) {
        try {
          const parsedSettings = JSON.parse(savedSettings);
          if (parsedSettings && typeof parsedSettings === 'object') {
            STATE.settings = { ...STATE.settings, ...parsedSettings };
          }
        } catch (parseErr) {
          console.warn('Gagal mengurai zoz_router_settings_v1 dari localStorage:', parseErr.message);
        }
      }

      // Sinkronkan preferensi tool pencarian YouTube
      STATE.isYouTubeSearchMode = Boolean(STATE.settings.youtubeSearchTool);

      // Sinkronkan preferensi direktori lokal pengguna
      if (typeof STATE.settings.localWorkspaceEnabled === 'boolean') {
        STATE.localWorkspace.enabled = STATE.settings.localWorkspaceEnabled;
      }
      if (typeof STATE.settings.workspaceAiCanRead === 'boolean') {
        STATE.localWorkspace.aiCanRead = STATE.settings.workspaceAiCanRead;
      }
      if (typeof STATE.settings.workspaceAiCanWrite === 'boolean') {
        STATE.localWorkspace.aiCanWrite = STATE.settings.workspaceAiCanWrite;
      }
      if (typeof STATE.settings.workspaceIncludeTree === 'boolean') {
        STATE.localWorkspace.includeTree = STATE.settings.workspaceIncludeTree;
      }
      if (typeof STATE.settings.workspaceEnableSnapshots === 'boolean') {
        STATE.localWorkspace.enableSnapshots = STATE.settings.workspaceEnableSnapshots;
      }
      if (typeof STATE.settings.workspaceAutoTaskTracker === 'boolean') {
        STATE.taskTracker.enabled = STATE.settings.workspaceAutoTaskTracker;
      }
      if (typeof STATE.settings.workspaceRequireApproval === 'boolean') {
        STATE.localWorkspace.requireApproval = STATE.settings.workspaceRequireApproval;
      }

      // Pulihkan metadata direktori sebelumnya jika tersimpan
      try {
        const rawMeta = localStorage.getItem('zoz_local_workspace_meta');
        if (rawMeta) {
          const parsedMeta = JSON.parse(rawMeta);
          if (parsedMeta && parsedMeta.dirName) {
            STATE.localWorkspace.dirName = parsedMeta.dirName;
            STATE.localWorkspace.platform = parsedMeta.platform || 'auto';
            loadWorkspaceSnapshots();
          }
        }
      } catch (_) {}

      // Pastikan customSystemPrompt terinisialisasi jika user sebelumnya sudah punya persona kustom
      if (typeof STATE.settings.customSystemPrompt !== 'string') {
        const isStandardPreset = Object.keys(SYSTEM_PRESETS).some(k => k !== 'default' && SYSTEM_PRESETS[k] === STATE.settings.systemPrompt);
        if (!isStandardPreset && STATE.settings.systemPrompt) {
          STATE.settings.customSystemPrompt = STATE.settings.systemPrompt;
        } else {
          STATE.settings.customSystemPrompt = '';
        }
      }

      // Pastikan endpoint Ollama Cloud terdefinisi dengan baik (100% Cloud Native)
      if (!STATE.settings.ollamaEndpoint || STATE.settings.ollamaEndpoint.includes('127.0.0.1') || STATE.settings.ollamaEndpoint.includes('localhost')) {
        STATE.settings.ollamaEndpoint = 'https://ollama.com';
      }

      // Pastikan model Ollama valid
      if (!STATE.settings.ollamaModel) {
        STATE.settings.ollamaModel = 'qwen2.5:1.5b';
      }

      // Auto-Migration: Alihkan model OpenRouter lama / rusak / mati ke model aktif terpercaya
      if (!STATE.settings.openRouterModel || DEACTIVATED_OR_BROKEN_OPENROUTER_MODELS.has(STATE.settings.openRouterModel)) {
        STATE.settings.openRouterModel = 'nvidia/nemotron-3.5-lightning:free';
      }

      // Jika baru pertama kali dibuka di cloud (Vercel) dan mode masih default 'ollama',
      // jadikan mode auto secara default.
      // H1 FIX: `saved` tidak pernah dideklarasikan → ReferenceError tiap load di cloud
      // host yang ditelan catch luar, sehingga SELURUH sisa load preferensi + mirror
      // sesi dilewatkan. `STATE.settings.mode` juga tidak pernah ada — mode hidup di
      // STATE.mode. Kini memakai savedSettings (ada = pernah disimpan) & STATE.mode.
      if (IS_CLOUD_HOSTED && !savedSettings && STATE.mode === 'ollama') {
        STATE.mode = 'auto';
      }

      if (!STATE.settings.imageModel) {
        STATE.settings.imageModel = 'flux';
      }

      const savedSound = safeLocalStorage.getItem('zoz_router_sound_v1');
      if (savedSound !== null) {
        STATE.soundEnabled = savedSound === 'true';
      }
      const savedSearchMode = safeLocalStorage.getItem('zoz_router_search_mode_v1');
      const searchModeAutonomousMigrated = safeLocalStorage.getItem('zoz_router_search_mode_autonomous_v2') === 'true';
      if (!searchModeAutonomousMigrated) {
        // Migrasi: Jadikan Autonomous Web Explorer sebagai default awal
        STATE.searchMode = 'autonomous';
        safeLocalStorage.setItem('zoz_router_search_mode_v1', 'autonomous');
        safeLocalStorage.setItem('zoz_router_search_mode_autonomous_v2', 'true');
      } else if (savedSearchMode && ['off', 'default', 'premium', 'autonomous'].includes(savedSearchMode)) {
        STATE.searchMode = savedSearchMode;
      } else {
        STATE.searchMode = 'autonomous';
        safeLocalStorage.setItem('zoz_router_search_mode_v1', 'autonomous');
      }
      const savedPromptHidden = safeLocalStorage.getItem('zoz_prompt_hidden');
      if (savedPromptHidden !== null) {
        STATE.isPromptHidden = savedPromptHidden === 'true';
      }

      // Fast synchronous load from localStorage (0ms startup)
      const savedSessions = safeLocalStorage.getItem('zoz_router_sessions_v1');
      if (savedSessions) {
        try {
          const parsed = JSON.parse(savedSessions);
          if (Array.isArray(parsed) && parsed.length > 0) {
            // KEAMANAN KETAT: Bersihkan sesi lazy disk asing dan sesi yang memiliki userId milik orang lain
            STATE.sessions = parsed.filter(s => {
              if (s._isLazyDisk) return false;
              if (s.userId && s.userId !== STATE.userId) return false;
              return true;
            });
            STATE.sessions.forEach(s => {
              if (!s.userId) s.userId = STATE.userId;
            });
          }
        } catch (e) {}
      }

      // Synchronous load favorite models & update badge count
      STATE.favoriteModels = loadFavoriteModels();
      updateCatalogFavBadge();
    } catch (err) {
      console.error('Error loading persisted state sync:', err);
    }
  }

  async function syncPersistedStorageBackground(isTabReload = false, savedActiveId = null) {
    try {
      // 1. Initialize Device-First Storage
      await DeviceStorage.init();

      // 2. Sync from IndexedDB Vault
      const dbSessions = await ChatDB.getAllSessions();
      if (Array.isArray(dbSessions) && dbSessions.length > 0) {
        // KEAMANAN KETAT: Prune sesi yang berasal dari user lain atau lazy disk asing
        const validDbSessions = dbSessions.filter(s => {
          if (s._isLazyDisk) return false;
          if (s.userId && s.userId !== STATE.userId) return false;
          return true;
        });
        validDbSessions.forEach(s => {
          if (!s.userId) s.userId = STATE.userId;
        });
        if (validDbSessions.length !== dbSessions.length) {
          // saveAllSessions() tak lagi mem-clear store, jadi sesi asing/lazy yang
          // tersaring harus dihapus eksplisit agar tidak "bangkit" dari vault lokal.
          await ChatDB.saveAllSessions(validDbSessions);
          const validIds = new Set(validDbSessions.map(s => s.id));
          for (const s of dbSessions) {
            if (!validIds.has(s.id)) await ChatDB.deleteSession(s.id);
          }
        }
        if (validDbSessions.length >= STATE.sessions.length) {
          STATE.sessions = validDbSessions;
          renderChatHistory();
          if (STATE.currentSessionId) renderCurrentSession(false);
        }
      }

      // 3. Sync lightweight session headers from Device Disk Storage HANYA bila backend lokal online dan bukan cloud
      if (DeviceStorage.isDeviceBackendAvailable && !IS_CLOUD_HOSTED) {
        const diskList = await DeviceStorage.getSessionsList();
        if (Array.isArray(diskList) && diskList.length > 0) {
          let hasNewSessions = false;
          for (const diskItem of diskList) {
            const existing = STATE.sessions.find(s => s.id === diskItem.id);
            if (!existing) {
              STATE.sessions.push({
                id: diskItem.id,
                userId: STATE.userId,
                title: diskItem.title || 'Obrolan Baru',
                mode: diskItem.mode || 'ollama',
                createdAt: diskItem.createdAt,
                updatedAt: diskItem.updatedAt,
                messages: [],
                messageCount: diskItem.messageCount || 0,
                isPinned: !!diskItem.isPinned,
                _isLazyDisk: true
              });
              hasNewSessions = true;
            } else if (diskItem.isPinned !== undefined && existing.isPinned === undefined) {
              existing.isPinned = !!diskItem.isPinned;
            }
          }
          if (hasNewSessions) {
            renderChatHistory();
          }
        }

        // Hydrate active session from Device Disk Storage to ensure background messages are never overwritten
        const targetSid = savedActiveId || STATE.currentSessionId;
        if (targetSid) {
          const activeSess = STATE.sessions.find(s => s.id === targetSid);
          if (activeSess) {
            try {
              const full = await DeviceStorage.getSession(targetSid);
              if (full && Array.isArray(full.messages)) {
                const diskLen = full.messages.length;
                const memLen = activeSess.messages ? activeSess.messages.length : 0;
                const diskLast = full.messages[diskLen - 1];
                const memLast = activeSess.messages ? activeSess.messages[memLen - 1] : null;

                if (activeSess._isLazyDisk || diskLen > memLen || (diskLast && memLast && diskLast.content !== memLast.content && ((diskLast.content || '').length > (memLast.content || '').length || diskLast.backgroundCompleted))) {
                  activeSess.messages = full.messages;
                  delete activeSess._isLazyDisk;
                  activeSess.userId = STATE.userId;
                  await ChatDB.saveSession(activeSess);
                  renderCurrentSession(false);
                  renderChatHistory();
                }
              }
            } catch (e) {
              console.warn('Notice hydrating active session from disk:', e);
            }
          }
        }
      }

      // 4. Sinkronisasi Direktori Lokal Pengguna dari WorkspaceDB Vault & Server Workspace (Claude Code Mode)
      try {
        const serverAvailable = await ServerWorkspaceAPI.checkStatus();
        const savedWs = await WorkspaceDB.loadWorkspace();

        if (savedWs && Array.isArray(savedWs.files) && savedWs.files.length > 0) {
          STATE.localWorkspace.dirName = savedWs.dirName || STATE.localWorkspace.dirName || 'Direktori Dokumen';
          STATE.localWorkspace.platform = savedWs.platform || (serverAvailable ? 'server-fs' : (isDesktopFileSystemSupported() ? 'desktop-fs' : 'mobile-virtual'));
          STATE.localWorkspace.files = savedWs.files;
          STATE.localWorkspace.enabled = Boolean(STATE.settings.localWorkspaceEnabled && savedWs.enabled);
          STATE.localWorkspace.snapshots = savedWs.snapshots || STATE.localWorkspace.snapshots || {};
          STATE.settings.localWorkspaceEnabled = STATE.localWorkspace.enabled;

          // Jika platform server-fs dan workspace aktif, refresh berkas dari disk server agar selalu terkini
          if (STATE.localWorkspace.platform === 'server-fs' && serverAvailable && STATE.localWorkspace.enabled) {
            ServerWorkspaceAPI.getFiles().then(latestFiles => {
              if (Array.isArray(latestFiles) && latestFiles.length > 0) {
                STATE.localWorkspace.files = latestFiles;
                WorkspaceDB.saveWorkspace(STATE.localWorkspace).catch(() => {});
                updateLocalWorkspaceUI();
              }
            }).catch(() => {});
          }

          loadWorkspaceSnapshots();
          updateLocalWorkspaceUI();
        } else if (serverAvailable && STATE.settings.localWorkspaceEnabled) {
          // Hanya pasang jika pengguna memang mengaktifkan preferensi direktori lokal
          const serverFiles = await ServerWorkspaceAPI.getFiles();
          if (Array.isArray(serverFiles) && serverFiles.length > 0) {
            STATE.localWorkspace.dirName = ServerWorkspaceAPI.dirName || 'zoz-router';
            STATE.localWorkspace.platform = 'server-fs';
            STATE.localWorkspace.files = serverFiles;
            STATE.localWorkspace.enabled = true;
            STATE.settings.localWorkspaceEnabled = true;
            loadWorkspaceSnapshots();
            updateLocalWorkspaceUI();
            WorkspaceDB.saveWorkspace(STATE.localWorkspace).catch(() => {});
          }
        }
      } catch (wsErr) {
        console.warn('Notice restoring workspace:', wsErr);
      }

      // 5. Periksa apakah ada tugas chat latar belakang yang sedang berjalan atau baru selesai
      await checkBackgroundChatTasksSync();
    } catch (err) {
      console.warn('Background storage sync notice:', err);
    }
  }

  // ==================== CLAUDE AI RESILIENCE: BACKGROUND CHAT SYNC & POLLING ====================
  let activeChatPollTimer = null;
  let isCheckingBackgroundSync = false;

  function findCurrentActiveSession() {
    if (STATE.currentSessionId) {
      return STATE.sessions.find(s => s.id === STATE.currentSessionId) || null;
    }
    const lastSid = safeSessionStorage.getItem('zoz_active_session_id') || safeLocalStorage.getItem('zoz_last_active_session_id');
    if (lastSid) {
      return STATE.sessions.find(s => s.id === lastSid) || null;
    }
    return null;
  }

  async function handleBackgroundChatCompletion(activeSession, data) {
    setGeneratingState(false);
    const diskSess = await DeviceStorage.getSession(activeSession.id);
    const diskMsgs = (diskSess && Array.isArray(diskSess.messages)) ? diskSess.messages : [];
    const activeMsgs = Array.isArray(activeSession.messages) ? activeSession.messages : [];
    let diskLast = null;
    if (diskMsgs.length > 0) {
      diskLast = diskMsgs[diskMsgs.length - 1];
    }
    let activeLast = null;
    if (activeMsgs.length > 0) {
      activeLast = activeMsgs[activeMsgs.length - 1];
    }

    const hasNewMessages = diskMsgs.length > activeMsgs.length ||
      (diskLast && activeLast && diskLast.content !== activeLast.content && ((diskLast.content || '').length > (activeLast.content || '').length || diskLast.backgroundCompleted));

    if (hasNewMessages) {
      activeSession.messages = diskMsgs;
      delete activeSession._isLazyDisk;
      savePersistedState();
      renderCurrentSession(false);
      renderChatHistory();
      AudioEngine.success();
      showToast('✨ AI telah selesai menjawab di latar belakang saat Anda keluar.');
    } else if (data.text && data.text.trim()) {
      const trimmed = data.text.trim();
      if (!Array.isArray(activeSession.messages)) activeSession.messages = [];
      let curLast = null;
      if (activeSession.messages.length > 0) {
        curLast = activeSession.messages[activeSession.messages.length - 1];
      }
      if (curLast && curLast.role === 'assistant') {
        if (curLast.content !== trimmed && (trimmed.length > (curLast.content || '').length || !curLast.content)) {
          curLast.content = trimmed;
          curLast.backgroundCompleted = true;
          if (data.isDeepResearch) {
            curLast.isDeepResearch = true;
            if (data.chatSummary) curLast.chatSummary = data.chatSummary;
            if (Array.isArray(data.sources)) curLast.sources = data.sources;
          }
          activeSession.updatedAt = new Date().toISOString();
          savePersistedState();
          renderCurrentSession(false);
          renderChatHistory();
          AudioEngine.success();
          showToast('✨ AI telah selesai menjawab di latar belakang saat Anda keluar.');
        }
      } else {
        activeSession.messages.push({
          role: 'assistant',
          content: trimmed,
          model: data.model || 'AI Model',
          timestamp: new Date().toISOString(),
          backgroundCompleted: true,
          isDeepResearch: !!data.isDeepResearch,
          chatSummary: data.chatSummary || null,
          sources: data.sources || null
        });
        activeSession.updatedAt = new Date().toISOString();
        savePersistedState();
        renderCurrentSession(false);
        renderChatHistory();
        AudioEngine.success();
        showToast('✨ AI telah selesai menjawab di latar belakang saat Anda keluar.');
      }
    }
  }

  async function checkBackgroundChatTasksSync() {
    // JANGAN menyela pengiriman/generasi yang sedang berjalan: sync ini bisa
    // memanggil setGeneratingState(true) + attachToActiveBackgroundChat dan
    // membajak gelembung yang sedang dipakai stream aktif.
    if (STATE.isGenerating || STATE.isSending) return;
    if (IS_GITHUB_PAGES || isCheckingBackgroundSync) return;
    isCheckingBackgroundSync = true;
    try {
      const activeSession = findCurrentActiveSession();

      // 1. Jika sesi aktif ditemukan, periksa sesi tersebut secara langsung
      if (activeSession) {
        const res = await fetch(`/api/chat/status/${encodeURIComponent(activeSession.id)}`, {
          headers: { 'X-User-ID': STATE.userId }
        }).catch(() => null);
        if (res && res.ok) {
          const data = await res.json();
          if (data && data.status === 'streaming') {
            attachToActiveBackgroundChat(activeSession, data.model, data.text || '');
            return;
          } else if (data && data.status === 'completed' && data.completedAt) {
            await handleBackgroundChatCompletion(activeSession, data);
            return;
          }
        }
      }

      // 2. Periksa status tugas latar belakang milik user ini jika ada sesi user yang belum selesai
      const globalRes = await fetch(`/api/chat/status?userId=${encodeURIComponent(STATE.userId)}`, {
        headers: { 'X-User-ID': STATE.userId }
      }).catch(() => null);
      if (globalRes && globalRes.ok) {
        const globalData = await globalRes.json();
        if (globalData && globalData.activeSessions && globalData.activeSessions.length > 0) {
          // KEAMANAN KETAT: Hanya tangani tugas yang sessionId-nya SUDAH ADA di STATE.sessions milik user ini!
          const targetTask = globalData.activeSessions.find(t => STATE.sessions.some(s => s.id === t.sessionId));
          if (targetTask) {
            const targetSid = targetTask.sessionId;
            const targetSession = STATE.sessions.find(s => s.id === targetSid);
            if (targetSession) {
              await switchSession(targetSid);
              if (attachToActiveBackgroundChat(targetSession, targetTask.model, targetTask.text || '')) {
                showToast('⚡ Menyambung kembali ke respons AI Anda yang sedang diproses di latar belakang...', 'info');
              }
              return;
            }
          }
        }

        if (globalData && globalData.recentlyCompletedSessions && globalData.recentlyCompletedSessions.length > 0) {
          const lastActiveId = safeSessionStorage.getItem('zoz_active_session_id') || safeLocalStorage.getItem('zoz_last_active_session_id');
          // KEAMANAN KETAT: Hanya sinkronkan tugas milik user saat ini
          const matchedTask = globalData.recentlyCompletedSessions.find(s => s.sessionId === lastActiveId && STATE.sessions.some(sess => sess.id === s.sessionId)) ||
                              globalData.recentlyCompletedSessions.find(s => STATE.sessions.some(sess => sess.id === s.sessionId));
          if (matchedTask) {
            let matchedSession = STATE.sessions.find(s => s.id === matchedTask.sessionId);
            if (matchedSession) {
              const fullDisk = await DeviceStorage.getSession(matchedSession.id);
              if (fullDisk && Array.isArray(fullDisk.messages)) {
                matchedSession.messages = fullDisk.messages;
                delete matchedSession._isLazyDisk;
                matchedSession.userId = STATE.userId;
                await ChatDB.saveSession(matchedSession);
                savePersistedState();
                renderChatHistory();
              }
            }
          }
        }
      }
    } catch (_) {
    } finally {
      setTimeout(() => {
        isCheckingBackgroundSync = false;
      }, 350);
    }
  }

  // Encoder untuk estimasi panjang byte (UTF-8) teks poll latar belakang —
  // dipakai saat server mengirim bentuk full-text (tanpa delta) sebagai nilai `since`.
  const POLL_TEXT_ENCODER = new TextEncoder();

  function attachToActiveBackgroundChat(session, modelName, initialText = '') {
    // Guard sama dengan checkBackgroundChatTasksSync: tidak boleh ada poll/sinkronisasi
    // latar belakang yang mengambil alih DOM saat user sedang mengirim/menghasilkan
    // (guard di sini penting karena pemanggil melewati beberapa await dulu).
    if (STATE.isGenerating || STATE.isSending) return false;
    setGeneratingState(true); // dipindah ke sini agar guard di atas benar-benar efektif
    if (activeChatPollTimer) clearInterval(activeChatPollTimer);

    // Dapatkan baris asisten terakhir atau buat baris baru jika belum ada di DOM
    let assistantRow = els.messagesList?.querySelector('.message-row.assistant:last-child');
    if (!assistantRow) {
      assistantRow = appendMessageElement('assistant', '', null, modelName || 'AI Assistant');
    }

    const bubbleText = assistantRow?.querySelector('.msg-text-content');
    const metaBox = assistantRow?.querySelector('.message-meta');
    if (bubbleText) {
      bubbleText.innerHTML = renderMarkdown(initialText || '') + '<span class="typing-cursor"></span>';
    }
    smartScrollChatToBottom(true);

    const startTime = performance.now();

    // M7: proteksi overlap — poll lambat (latensi > interval 800ms) tak boleh
    // meluncurkan tick baru sebelum yang selesai berjalan. Tanpa ini, handler
    // "selesai" bisa dieksekusi berulang oleh tick antrian: toast sukses, save,
    // dan notifikasi ganda. pollDone mengunci tick yang terlanjur masuk.
    let pollBusy = false;
    let pollDone = false;
    // M16: diff-guard render + sinkron inkremental (kontrak /api/chat/status?since=):
    // server bisa membalas { delta: true, text: <potongan>, fullBytes } sehingga kita
    // cukup menumpuk potongannya, bukan menarik teks penuh tiap 800ms.
    let lastRenderedPollText = null;
    let pollFullBytes = 0;
    let pollEpoch = 0; // epoch truncation server (kontrak /api/chat/status?since=&epoch=)
    let pollBufferText = '';
    // Teks terakhir yang DIKETAHUI tampil (initialText + akumulasi poll yang valid).
    // Dipakai sebagai fallback saat finalize menerima respons KOSONG — status 'none'
    // (task sudah dihapus server: stop dari tab lain / kadaluwarsa) datang tanpa field
    // teks sehingga cabang non-delta di bawah mereset buffer menjadi ''.
    let lastKnownText = initialText || '';
    activeChatPollTimer = setInterval(async () => {
      if (pollBusy || pollDone) return;
      pollBusy = true;
      try {
        if (STATE.currentSessionId !== session.id) {
          clearInterval(activeChatPollTimer);
          activeChatPollTimer = null;
          pollBufferText = '';
          pollFullBytes = 0;
          pollEpoch = 0;
          return;
        }

        if (performance.now() - startTime > 15 * 60 * 1000) {
          clearInterval(activeChatPollTimer);
          activeChatPollTimer = null;
          pollBufferText = '';
          pollFullBytes = 0;
          pollEpoch = 0;
          setGeneratingState(false);
          return;
        }

        const res = await fetch(`/api/chat/status?sessionId=${encodeURIComponent(session.id)}&since=${pollFullBytes}&epoch=${pollEpoch}`, {
          headers: { 'X-User-ID': STATE.userId }
        }).catch(() => null);
        if (!res || !res.ok) return;
        const data = await res.json();
        if (!data) return;

        if (data.isDeepResearch && data.taskId) {
          STATE.currentDeepResearchTaskId = data.taskId;
        }

        // Bentuk delta (baru): data.text hanya POTONGAN + fullBytes = total byte.
        // Bentuk lama: data.text = teks penuh → jadikan buffer baru & hitung byte-nya.
        let currentText = '';
        if (data.delta === true) {
          pollBufferText += (data.text || '');
          // Fallback bila fullBytes tidak dikirim: hitung byte UTF-8 dari buffer,
          // JANGAN .length (char UTF-16) — untuk teks non-ASCII (emoji/CJK) keduanya
          // beda dan offset since berikutnya akan menyimpang dari byte sebenarnya.
          pollFullBytes = data.fullBytes || POLL_TEXT_ENCODER.encode(pollBufferText).length;
          currentText = pollBufferText;
        } else {
          pollBufferText = data.text || '';
          pollFullBytes = POLL_TEXT_ENCODER.encode(pollBufferText).length;
          currentText = pollBufferText;
        }
        // Sinkron epoch truncation dari server: server mengirim fullEpoch di SETIAP
        // payload; delta hanya valid dalam epoch yang sama (truncation menggeser
        // offset byte, jadi potongan epoch lama tak boleh ditumpuk lagi).
        if (typeof data.fullEpoch === 'number') pollEpoch = data.fullEpoch;
        // Catat teks valid terakhir SEBELUM cabang finalize di bawah berpotensi
        // mereset buffer (respons 'none' kosong) — inilah penyelamat parsial.
        if (currentText && currentText.trim()) lastKnownText = currentText;
        if (bubbleText && currentText) {
          if (data.isDeepResearch && data.status === 'streaming') {
            // Diff-guard: hanya render ulang bila teks benar-benar bertambah.
            if (currentText !== lastRenderedPollText) {
              lastRenderedPollText = currentText;
              bubbleText.innerHTML = `
              <div class="deep-research-live-card" style="padding:14px; border:1px solid rgba(0,240,255,0.3); border-radius:12px; background:rgba(10,15,25,0.7); backdrop-filter:blur(8px);">
                <div style="display:flex; align-items:center; gap:10px; margin-bottom:8px; color:var(--neon-cyan); font-weight:600; font-size:0.95rem;">
                  <i class="fa-solid fa-atom fa-spin"></i> Deep Research Pro Aktif di Latar Belakang
                </div>
                <div style="font-size:0.85rem; color:var(--text-secondary); margin-bottom:6px;">${escapeHtml(currentText)}</div>
                <div style="width:100%; background:rgba(255,255,255,0.1); border-radius:4px; height:4px; overflow:hidden;">
                  <div style="width:65%; height:100%; background:linear-gradient(90deg, var(--neon-cyan), var(--neon-purple)); border-radius:4px; animation: progress-indeterminate 1.5s infinite linear;"></div>
                </div>
              </div>
            `;
            }
          } else if (currentText !== lastRenderedPollText) {
            lastRenderedPollText = currentText;
            bubbleText.innerHTML = renderMarkdown(currentText) + (data.status === 'streaming' ? '<span class="typing-cursor"></span>' : '');
          }
          smartScrollChatToBottom(false);
        }

        if (data.status === 'completed' || data.status === 'none' || data.status === 'aborted') {
          pollDone = true; // M7: kunci — tick antrian yang tersisa tidak boleh mengulang handler ini
          clearInterval(activeChatPollTimer);
          activeChatPollTimer = null;
          STATE.currentDeepResearchTaskId = null;
          pollBufferText = '';
          pollFullBytes = 0;
          pollEpoch = 0;

          // Jangan pernah memperlakukan respons KOSONG sebagai konten final: status
          // 'none' datang tanpa field teks sehingga buffer sudah ter-reset di atas.
          // Fallback ke teks terakhir yang tampil agar parsial tidak hilang dari DOM.
          const finalReportText = (currentText && currentText.trim()) ? currentText : lastKnownText;
          const actualModelName = modelName || data.model || (data.isDeepResearch ? 'Deep Research Pro' : 'AI Model');
          if (bubbleText) {
            if (!finalReportText.trim()) {
              // Konten kosong total (tanpa initialText & tanpa stream) — jangan timpa
              // bubble; cukup buang kursor streaming yang menggantung.
              bubbleText.querySelector('.typing-cursor')?.remove();
            } else if (data.isDeepResearch) {
              const allSources = Array.isArray(data.sources) ? data.sources : [];
              const chatSummary = data.chatSummary || '';
              const nowIso = new Date().toISOString();
              bubbleText.innerHTML = buildDeepResearchSummaryCardHtml(finalReportText, actualModelName, allSources, nowIso, chatSummary);
              enhanceCodeBlocks(bubbleText);
              attachDeepResearchCardEvents(assistantRow, finalReportText, actualModelName, allSources, nowIso);
            } else {
              bubbleText.innerHTML = renderMarkdown(finalReportText);
              enhanceCodeBlocks(bubbleText);
              enhanceChatImages(bubbleText);
            }
          }
          if (assistantRow) assistantRow.dataset.fullContent = finalReportText;

          const duration = ((performance.now() - startTime) / 1000).toFixed(1);
          if (metaBox) {
            metaBox.innerHTML = `
              <strong>${escapeHtml(actualModelName)}</strong>
              <span class="meta-model-badge" style="background:rgba(0,240,255,0.15); color:var(--neon-cyan);">${data.isDeepResearch ? 'Deep Research Sync' : 'Background Sync'}</span>
              <span>⏱️ ${duration}s</span>
            `;
          }

          // Simpan ke pesan sesi jika belum tersimpan atau perbarui jika teks masih parsial
          if (!Array.isArray(session.messages)) session.messages = [];
          let lastMsg = null;
          if (session.messages.length > 0) {
            lastMsg = session.messages[session.messages.length - 1];
          }
          // Hanya push bila benar-benar ada isi — respons kosong ('none' tanpa
          // fallback) tidak boleh membuat pesan assistant kosong di riwayat.
          // Struktur if/else dipertahankan seperti semula agar cabang else HANYA
          // berjalan saat lastMsg assistant (bukan saat lastMsg null + teks kosong).
          if (!lastMsg || lastMsg.role !== 'assistant') {
            if (finalReportText.trim()) {
              session.messages.push({
                role: 'assistant',
                content: finalReportText,
                model: modelName || data.model,
                timestamp: new Date().toISOString(),
                backgroundCompleted: true,
                isDeepResearch: !!data.isDeepResearch,
                chatSummary: data.chatSummary || null,
                sources: data.sources || null
              });
            }
          } else {
            if (finalReportText) {
              lastMsg.content = finalReportText;
            }
            lastMsg.model = modelName || data.model || lastMsg.model;
            lastMsg.backgroundCompleted = true;
            if (data.isDeepResearch) {
              lastMsg.isDeepResearch = true;
              if (data.chatSummary) lastMsg.chatSummary = data.chatSummary;
              if (Array.isArray(data.sources)) lastMsg.sources = data.sources;
            }
          }
          session.updatedAt = new Date().toISOString();
          savePersistedState();
          renderChatHistory(els.searchHistoryInput?.value || '');

          setGeneratingState(false);
          if (data.status === 'aborted') {
            showToast('Generasi dihentikan oleh pengguna.');
          } else if (data.status === 'none') {
            // Task sudah tidak dikenal server (dihentikan tab lain / kadaluwarsa).
            // Jangan klaim "selesai" — teks parsial (bila ada) tetap dipertahankan.
            showToast(finalReportText.trim()
              ? '⚡ Tugas AI di sesi ini sudah berakhir di server — teks parsial dipertahankan.'
              : 'Tidak ada tugas aktif untuk sesi ini.');
          } else {
            AudioEngine.receive();
            notifyAiCompletion('🤖 ' + (modelName || data.model), finalReportText);
            showToast('✨ AI selesai menjawab di latar belakang.');
          }
        } else if (data.status === 'error') {
          pollDone = true; // M7: kunci agar handler error tidak berjalan dua kali
          clearInterval(activeChatPollTimer);
          activeChatPollTimer = null;
          STATE.currentDeepResearchTaskId = null;
          setGeneratingState(false);
          // currentText sudah menampung buffer lengkap (baik bentuk delta maupun full),
          // jadi diambil SEBELUM buffer di-reset di bawah.
          const partialText = currentText;
          pollBufferText = '';
          pollFullBytes = 0;
          pollEpoch = 0;
          const errDetail = typeof data.error === 'object' && data.error ? (data.error.message || JSON.stringify(data.error)) : String(data.error || 'Terjadi kesalahan koneksi');
          if (bubbleText) {
            if (partialText.trim()) {
              bubbleText.innerHTML = renderMarkdown(partialText) + `\n\n<div style="color:var(--neon-crimson); font-size:0.82rem; margin-top:8px; padding:6px 10px; border-left:2px solid var(--neon-crimson); background:rgba(255,0,85,0.08); border-radius:4px;"><i class="fa-solid fa-triangle-exclamation"></i> Respons terputus: ${escapeHtml(errDetail)}</div>`;
              enhanceCodeBlocks(bubbleText);
              enhanceChatImages(bubbleText);
            } else {
              bubbleText.innerHTML = `<div style="color:var(--neon-crimson); font-size:0.85rem;"><i class="fa-solid fa-triangle-exclamation"></i> Gagal menyelesaikan respons di latar belakang: ${escapeHtml(errDetail)}</div>`;
            }
          }
          if (partialText.trim()) {
            if (!Array.isArray(session.messages)) session.messages = [];
            let lastMsg = null;
            if (session.messages.length > 0) {
              lastMsg = session.messages[session.messages.length - 1];
            }
            const interruptedText = partialText + `\n\n*[Respons terputus: ${errDetail}]*`;
            if (!lastMsg || lastMsg.role !== 'assistant') {
              session.messages.push({
                role: 'assistant',
                content: interruptedText,
                model: modelName || data.model,
                timestamp: new Date().toISOString()
              });
            } else {
              lastMsg.content = interruptedText;
              lastMsg.model = modelName || data.model || lastMsg.model;
            }
            session.updatedAt = new Date().toISOString();
            savePersistedState();
            renderChatHistory(els.searchHistoryInput?.value || '');
          }
        }
      } catch (pollErr) {
        console.warn('Error polling background chat:', pollErr);
      } finally {
        pollBusy = false; // M7: lepas kunci tick setiap iterasi selesai
      }
    }, 800);
    return true; // poll terpasang (guard di atas tidak memblokir)
  }

  // ==================== PERSISTENCE SCHEDULER (DEBOUNCE) ====================
  // Menulis localStorage + mirror sesi + IndexedDB + POST DeviceStorage di SETIAP
  // perubahan state ternyata mahal (triple-write). Semua panggilan kini dijadwalkan
  // dulu (debounce 700ms); hanya panggilan {immediate:true} — hapus sesi, hapus
  // semua riwayat, flush saat tab ditutup — yang menulis sinkron sekarang juga.
  let savePersistTimer = null;
  let savePersistDirty = false;
  let lastPersistedSessionMeta = new Map(); // id -> updatedAt terakhir yang masuk IndexedDB
  let localStorageMirrorBroken = false;     // kuota mirror penuh → tahan dulu tulis mirror
  let localStorageMirrorRetryTimer = null;
  let localStorageMirrorWarned = false;

  function savePersistedState(options = {}) {
    savePersistDirty = true;
    if (options.immediate) {
      if (savePersistTimer) {
        clearTimeout(savePersistTimer);
        savePersistTimer = null;
      }
      flushPersistedState();
      return;
    }
    if (savePersistTimer) return;
    savePersistTimer = setTimeout(() => {
      savePersistTimer = null;
      flushPersistedState();
    }, 700);
  }

  function flushPersistedState() {
    if (!savePersistDirty) return;
    savePersistDirty = false;
    performPersistedStateSave();
  }

  function performPersistedStateSave() {
    try {
      try {
        localStorage.setItem('zoz_router_settings_v1', JSON.stringify(STATE.settings));
      } catch (e) {
        console.warn('Failed to save settings:', e);
      }
      try {
        localStorage.setItem('zoz_router_sound_v1', String(STATE.soundEnabled));
      } catch (e) {
        console.warn('Failed to save sound setting:', e);
      }
      try {
        localStorage.setItem('zoz_router_search_mode_v1', STATE.searchMode || 'autonomous');
      } catch (e) {
        console.warn('Failed to save search mode:', e);
      }
      saveFavoriteModels();

      // Save active session to Device Disk Storage
      if (STATE.currentSessionId) {
        const activeSess = STATE.sessions.find(s => s.id === STATE.currentSessionId);
        if (activeSess) {
          activeSess.userId = STATE.userId;
          DeviceStorage.saveSession(activeSess);
        }
      }

      // Save to IndexedDB (asynchronous & practically unlimited quota)
      // Sesi AKTIF sudah tercakup oleh DeviceStorage.saveSession() di atas (yang di
      // dalamnya memanggil ChatDB.saveSession). Di sini hanya sesi yang updatedAt-nya
      // berubah sejak save terakhir — dulu SELURUH STATE.sessions ditulis ulang pada
      // SETIAP save (transaksi besar berulang-ulang tanpa perlu).
      const dirtySessions = STATE.sessions.filter(s =>
        s.id !== STATE.currentSessionId && lastPersistedSessionMeta.get(s.id) !== s.updatedAt);
      if (dirtySessions.length) {
        ChatDB.saveAllSessions(dirtySessions);
      }
      lastPersistedSessionMeta = new Map(STATE.sessions.map(s => [s.id, s.updatedAt]));

      // Mirror lightweight summaries to localStorage.
      // Dilewati sementara bila sebelumnya kena quota: kunci asli 'zoz_router_sessions_v1'
      // masih berisi mirror LAMA yang utuh dan justru dipertahankan (lihat catch di bawah).
      // Tulisan IndexedDB + server di atas TETAP jalan.
      if (localStorageMirrorBroken) return;
      try {
        const lightweight = STATE.sessions.map(s => ({
          id: s.id,
          title: s.title,
          mode: s.mode,
          isPinned: !!s.isPinned,
          createdAt: s.createdAt,
          updatedAt: s.updatedAt,
          _isLazyDisk: !!s._isLazyDisk,
          messageCount: typeof s.messageCount === 'number' ? s.messageCount : (Array.isArray(s.messages) ? s.messages.length : 0),
          messages: (s.messages || []).map((m, mIdx) => {
            let safeImages = undefined;
            if (Array.isArray(m.images)) {
              safeImages = m.images.map(img => (typeof img === 'string' && img.startsWith('data:')) ? '[data:image]' : img);
            }
            let safeImage = (typeof m.image === 'string' && m.image.startsWith('data:')) ? '[data:image]' : m.image;
            let safeDocs = undefined;
            if (Array.isArray(m.docs)) {
              safeDocs = m.docs.map(d => ({ name: d.name, size: d.size }));
            }
            // File buatan AI (AI File Studio): isi konten (content) adalah bagian
            // terbesar dari ukuran mirror dan membuat kuota ~5MB 'zoz_router_sessions_v1'
            // mudah penuh. IndexedDB tetap sumber kebenaran; mirror hanya menyimpan
            // isi file untuk 5 pesan terakhir per sesi — kartu yang paling mungkin
            // dibuka pengguna sesaat setelah reload sebelum sinkronisasi IDB selesai.
            const keepFileContent = mIdx >= ((s.messages || []).length - 5);
            let safeFiles = undefined;
            if (Array.isArray(m.files) && m.files.length > 0) {
              safeFiles = m.files.map(f => ({
                name: f.name, mime: f.mime, lang: f.lang,
                content: keepFileContent ? f.content : '',
                byteSize: f.byteSize, lineCount: f.lineCount,
                size: f.size, desc: f.desc, isGeneratedByAI: true
              }));
            }
            return {
              role: m.role,
              content: m.content,
              displayContent: m.displayContent,
              docs: safeDocs,
              images: safeImages,
              image: safeImage,
              files: safeFiles,
              model: m.model,
              engine: m.engine,
              slot: m.slot,
              sources: m.sources,
              stats: m.stats,
              isDeepResearch: !!m.isDeepResearch,
              latency: m.latency,
              timestamp: m.timestamp
            };
          })
        }));
        localStorage.setItem('zoz_router_sessions_v1', JSON.stringify(lightweight));
      } catch (quotaErr) {
        // QUOTA PENUH: kunci ASLI masih berisi mirror lama yang UTUH — jangan ditimpa
        // (dulu ditimpa versi headers-only sehingga isi pesan hilang permanen padahal
        // byte-nya masih ada). Alih-alih itu:
        //   (i)  tulis backup terpisah 'zoz_router_sessions_v1_lite' (headers 20 sesi
        //        terakhir saja) — kunci asli tak tersentuh,
        //   (ii) set penanda agar save berikutnya melewati mirror penuh (IDB + server
        //        tetap jalan), lalu coba lagi 5 menit kemudian,
        //   (iii) console.warn sekali saja.
        if (!localStorageMirrorWarned) {
          localStorageMirrorWarned = true;
          console.warn('localStorage quota exceeded — mirror asli dipertahankan, backup lite dibuat:', quotaErr.message);
        }
        localStorageMirrorBroken = true;
        try {
          const headersOnly = STATE.sessions
            .slice()
            .sort((a, b) => String(b.updatedAt || '').localeCompare(String(a.updatedAt || '')))
            .slice(0, 20)
            .map(s => ({
              id: s.id,
              title: s.title,
              mode: s.mode,
              isPinned: !!s.isPinned,
              createdAt: s.createdAt,
              updatedAt: s.updatedAt,
              _isLazyDisk: !!s._isLazyDisk,
              messageCount: typeof s.messageCount === 'number' ? s.messageCount : (Array.isArray(s.messages) ? s.messages.length : 0),
              messages: []
            }));
          localStorage.setItem('zoz_router_sessions_v1_lite', JSON.stringify(headersOnly));
        } catch (innerErr) {
          console.warn('localStorage completely full, skipping lite sessions backup:', innerErr.message);
        }
        if (!localStorageMirrorRetryTimer) {
          localStorageMirrorRetryTimer = setTimeout(() => {
            localStorageMirrorRetryTimer = null;
            localStorageMirrorBroken = false;
            savePersistedState();
          }, 5 * 60 * 1000);
        }
      }
      BioEndocrine.secreteDopamine(0.8, 'Sinkronisasi status persisten sukses');
    } catch (err) {
      console.error('Error saving persisted state:', err);
      BioEndocrine.secreteStress(15, 'Gagal menyimpan status persisten: ' + (err.message || 'Storage error'));
    }
  }

  // ==================== TOAST NOTIFICATIONS ====================
  function showToast(message, type = 'info') {
    if (!els.toastContainer) return;
    // Bersihkan notifikasi lama agar tidak menumpuk memenuhi layar
    els.toastContainer.innerHTML = '';
    const toast = document.createElement('div');
    toast.className = `toast ${type}`;
    const icon = type === 'error' ? 'fa-triangle-exclamation' : 'fa-circle-check';
    toast.innerHTML = `<i class="fa-solid ${icon}"></i> <span>${escapeHtml(message)}</span>`;
    toast.onclick = () => toast.remove();
    els.toastContainer.appendChild(toast);
    setTimeout(() => {
      toast.style.opacity = '0';
      toast.style.transform = 'translateY(-10px)';
      setTimeout(() => toast.remove(), 250);
    }, 1500);
  }

  // ==================== BROWSER DESKTOP/MOBILE NOTIFICATIONS ====================
  function requestNotificationPermission() {
    if ('Notification' in window && Notification.permission === 'default') {
      try {
        Notification.requestPermission().catch(() => {});
      } catch (_) {}
    }
  }

  function notifyAiCompletion(title, textBody) {
    if (document.hidden && 'Notification' in window && Notification.permission === 'granted') {
      try {
        const cleanText = safeAssistantText(textBody).replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
        const snippet = cleanText.slice(0, 140) + (cleanText.length > 140 ? '...' : '');
        const notif = new Notification(title || '🤖 Zoz Router AI', {
          body: snippet || 'Jawaban AI telah selesai diproses.',
          icon: 'data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><circle cx="50" cy="50" r="45" fill="%2300F0FF"/><text x="50" y="66" font-size="46" font-weight="bold" text-anchor="middle" fill="%2308090D">Z</text></svg>'
        });
        notif.onclick = () => {
          try { window.focus(); } catch (_) {}
          notif.close();
        };
      } catch (_) {}
    }
  }

  // ==================== UTILS ====================
  function escapeHtml(str) {
    if (str === null || str === undefined) return '';
    const s = String(str);
    return s.replace(/[&<>'"]/g, tag => ({
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      "'": '&#39;',
      '"': '&quot;'
    }[tag] || tag));
  }

  function generateId() {
    return 'ses_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 6);
  }

  function sanitizeHtmlSafe(dirtyHtml) {
    if (!dirtyHtml || typeof dirtyHtml !== 'string') return '';
    if (window.DOMPurify) {
      return DOMPurify.sanitize(dirtyHtml, {
        ADD_TAGS: ['details', 'summary'],
        ADD_ATTR: ['target', 'rel', 'open'],
        FORBID_TAGS: ['script', 'iframe', 'object', 'embed', 'form'],
        FORBID_ATTR: ['onerror', 'onload', 'onclick', 'onmouseover']
      });
    }
    // Fallback native sanitizer jika DOMPurify belum termuat atau offline
    return dirtyHtml
      .replace(/<script\b[\s\S]*?<\/script>/gi, '')
      .replace(/<iframe\b[\s\S]*?<\/iframe>/gi, '')
      .replace(/<object\b[\s\S]*?<\/object>/gi, '')
      .replace(/<embed\b[\s\S]*?<\/embed>/gi, '')
      .replace(/<form\b[\s\S]*?<\/form>/gi, '')
      .replace(/\bon\w+\s*=\s*(?:'[^']*'|"[^"]*"|[^\s>]+)/gi, '');
  }

  // ==================== DETERMINISTIC REASONING & WEB SYNTHESIS PROCESSORS ====================
  function splitReasoningAndContent(rawText) {
    if (TEXT_SAFETY) return TEXT_SAFETY.splitReasoningAndContent(rawText);
    if (typeof rawText !== 'string' || !rawText) return { reasoning: '', content: '', isThinking: false };
    const open = rawText.toLowerCase().indexOf('<think>');
    if (open < 0) return { reasoning: '', content: rawText, isThinking: false };
    let content = rawText.slice(0, open);
    const close = rawText.toLowerCase().indexOf('</think>', open + 7);
    if (close < 0) return { reasoning: rawText.slice(open + 7), content, isThinking: true };
    content += rawText.slice(close + 8);
    return { reasoning: rawText.slice(open + 7, close), content: content.trim(), isThinking: false };
  }

  function synthesizeAutonomousWebSummary(rawToolResponsesText, sources) {
    if (!rawToolResponsesText && (!sources || sources.length === 0)) {
      return 'Penelusuran data web telah selesai dilaksanakan.';
    }
    const lines = (rawToolResponsesText || '').split('\n')
      .map(l => l.trim())
      .filter(l => l && !l.startsWith('[HASIL PENGUMPULAN') && !l.startsWith('Sumber:'));
    
    const summaryPoints = lines.slice(0, 8);
    let summary = '### 🌐 Ringkasan Hasil Penelusuran Web Terkini\n\n';
    if (summaryPoints.length > 0) {
      summary += summaryPoints.map(p => `- ${p}`).join('\n') + '\n\n';
    } else {
      summary += 'Informasi dan fakta terkait topik berhasil dikumpulkan secara langsung dari web.\n\n';
    }
    if (sources && sources.length > 0) {
      summary += `*Tersedia ${sources.length} tautan sumber referensi di bawah yang dapat Anda telusuri.*`;
    }
    return summary.trim();
  }

  function fastSanitizeHtml(dirtyHtml) {
    if (!dirtyHtml || typeof dirtyHtml !== 'string') return '';
    return dirtyHtml
      .replace(/<script\b[\s\S]*?<\/script>/gi, '')
      .replace(/<iframe\b[\s\S]*?<\/iframe>/gi, '')
      .replace(/<object\b[\s\S]*?<\/object>/gi, '')
      .replace(/<embed\b[\s\S]*?<\/embed>/gi, '')
      .replace(/<form\b[\s\S]*?<\/form>/gi, '')
      .replace(/\bon\w+\s*=\s*(?:'[^']*'|"[^"]*"|[^\s>]+)/gi, '');
  }

  function renderMarkdown(rawText, isStreaming = false) {
    if (!rawText) return '';
    
    // Pisahkan blok pemikiran AI (<think>) dan konten jawaban utama secara deterministik (tanpa regex rentan)
    const parsedBlocks = splitReasoningAndContent(rawText);
    
    // Reasoning dihapus dari proyeksi tampilan; hanya konten eksplisit di luar
    // kanal/tag reasoning yang boleh dirender. Jika provider tidak mengirim
    // jawaban eksplisit, output sengaja tetap kosong (fail closed).
    let contentHtml = '';
    if (parsedBlocks.content) {
      // Selama streaming, lewati reflowShreddedProse agar CPU hemat daya
      const displayContent = isStreaming ? parsedBlocks.content : reflowShreddedProse(parsedBlocks.content);
      if (window.marked) {
        try {
          contentHtml = marked.parse(displayContent);
        } catch (err) {
          console.warn('[renderMarkdown] Error parsing markdown, fallback to escaped text:', err);
          contentHtml = escapeHtml(displayContent).replace(/\n/g, '<br>');
        }
      } else {
        contentHtml = escapeHtml(displayContent).replace(/\n/g, '<br>');
      }
    }

    // Selama streaming berjalan cepat, gunakan fast regex sanitizer untuk mencegah beban 100% CPU.
    // Saat stream selesai (finish), full DOMPurify dijalankan secara komprehensif.
    const sanitized = isStreaming ? fastSanitizeHtml(contentHtml) : sanitizeHtmlSafe(contentHtml);

    // Pastikan seluruh tautan eksternal (http/https) membuka di tab baru agar tidak memutus sesi obrolan
    let result = sanitized.replace(/<a\b([^>]*?href=["']https?:\/\/[^"']+["'][^>]*)>/gi, (match, attrs) => {
      const cleanAttrs = attrs.replace(/\s*(?:target|rel)=["'][^"']*["']/gi, '');
      return `<a${cleanAttrs} target="_blank" rel="noopener noreferrer">`;
    });

    // Otomatis pasang loading="lazy" dan decoding="async" pada seluruh gambar agar hemat RAM & decode di latar belakang
    result = result.replace(/<img\b([^>]*?)>/gi, (match, attrs) => {
      let updated = attrs;
      if (!/\bloading=/i.test(updated)) updated += ' loading="lazy"';
      if (!/\bdecoding=/i.test(updated)) updated += ' decoding="async"';
      return `<img${updated}>`;
    });

    return result;
  }

  // Init opsi marked SEKALI di module scope (marked.min.js dimuat sebelum app.js di index.html).
  // Dulu setOptions dipanggil di dalam renderMarkdown → opsi di-set ulang pada SETIAP render,
  // menambah overhead saat streaming 60fps tanpa perubahan hasil sama sekali.
  if (window.marked) {
    marked.setOptions({
      // Single newlines in prose are soft-wrapped, not hard breaks. This keeps
      // answers with model-inserted line wraps as readable paragraphs while
      // Markdown blank lines/lists/code retain their structure.
      breaks: false,
      gfm: true
    });
  }


