  function generatePdfDocPreviewHtml(fileName, parsedBody) {
    return `<!DOCTYPE html>
<html lang="id">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <style>
    body {
      background: #0b0f19;
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
      margin: 0;
      padding: 24px 12px;
      display: flex;
      justify-content: center;
      color: #334155;
    }
    .pdf-sheet {
      background: #ffffff;
      width: 100%;
      max-width: 800px;
      min-height: 1100px;
      padding: 60px 52px;
      box-sizing: border-box;
      box-shadow: 0 12px 36px rgba(0,0,0,0.6);
      border-radius: 4px;
      line-height: 1.6;
      font-size: 14.5px;
    }
    .pdf-header-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: #fef2f2;
      color: #dc2626;
      padding: 6px 12px;
      border-radius: 4px;
      font-size: 12px;
      font-weight: 700;
      margin-bottom: 24px;
      border: 1px solid #fecaca;
    }
    h1, h2, h3, h4 { color: #0f172a; font-weight: 700; line-height: 1.3; }
    h1 { font-size: 24px; border-bottom: 2px solid #ef4444; padding-bottom: 8px; margin-top: 10px; }
    h2 { font-size: 18px; color: #1e3a8a; margin-top: 26px; }
    h3 { font-size: 15px; margin-top: 18px; }
    p { margin: 12px 0; color: #334155; }
    ul, ol { padding-left: 24px; margin: 12px 0; }
    li { margin-bottom: 6px; }
    pre { background: #f8fafc; border: 1px solid #e2e8f0; border-left: 4px solid #ef4444; padding: 12px; border-radius: 4px; font-family: 'Consolas', monospace; font-size: 12.5px; }
    code { font-family: 'Consolas', monospace; background: #f1f5f9; padding: 2px 4px; border-radius: 3px; font-size: 12.5px; }
    hr { border: none; border-top: 1px solid #e2e8f0; margin: 26px 0; }
    @media (max-width: 600px) {
      body { padding: 8px; }
      .pdf-sheet { padding: 24px 18px; }
    }
  </style>
</head>
<body>
  <div class="pdf-sheet">
    <div class="pdf-header-badge">📑 Pratinjau Dokumen Adobe PDF (.pdf) • ${escapeHtml(fileName || 'Dokumen')}</div>
    ${parsedBody}
  </div>
</body>
</html>`;
  }

  function generateMermaidDocPreviewHtml(fileName, svgHtml) {
    return `<!DOCTYPE html>
<html lang="id">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <style>
    html, body {
      background: #090d16;
      color: #e6edf3;
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
      margin: 0;
      padding: 0;
      width: 100%;
      height: 100%;
      box-sizing: border-box;
      overflow: auto;
    }
    .mermaid-sheet {
      width: 100%;
      min-height: 100%;
      padding: 20px 16px;
      box-sizing: border-box;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
    }
    .mermaid-header-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: rgba(0, 240, 255, 0.12);
      color: #00f0ff;
      padding: 6px 14px;
      border-radius: 6px;
      font-size: 13px;
      font-weight: 700;
      margin-bottom: 16px;
      border: 1px solid rgba(0, 240, 255, 0.35);
      letter-spacing: 0.5px;
    }
    .mermaid-svg-container {
      width: 100%;
      flex: 1;
      display: flex;
      justify-content: center;
      align-items: center;
      overflow: auto;
      padding: 8px 0;
    }
    .mermaid-svg-container svg {
      max-width: 100%;
      height: auto;
      max-height: 84vh;
      display: block;
      filter: drop-shadow(0 8px 32px rgba(0, 0, 0, 0.5));
    }
    @media (max-width: 600px) {
      .mermaid-sheet { padding: 12px 6px; }
      .mermaid-header-badge { font-size: 11px; padding: 4px 10px; margin-bottom: 10px; }
      .mermaid-svg-container svg { max-height: 88vh; }
    }
  </style>
</head>
<body>
  <div class="mermaid-sheet">
    <div class="mermaid-header-badge">📊 Pratinjau Diagram Visual • ${escapeHtml(fileName || 'Diagram')}</div>
    <div class="mermaid-svg-container">
      ${svgHtml}
    </div>
  </div>
</body>
</html>`;
  }

  function sanitizeTitle(str) {
    return String(str || '')
      .replace(/<[^>]+>/g, '')
      .replace(/[^\w\s-]/g, '')
      .trim()
      .replace(/\s+/g, '_')
      .slice(0, 50);
  }

  function extractSmartDiagramTitle(code, preElement = null) {
    if (!code) return 'diagram';

    // 1. Cek heading markdown terdekat sebelum elemen diagram di DOM
    if (preElement && preElement.parentElement) {
      let prev = preElement.previousElementSibling;
      let attempts = 0;
      while (prev && attempts < 5) {
        if (prev.matches('h1, h2, h3, h4, h5, h6, strong, b, .markdown-heading')) {
          const hText = (prev.textContent || '').replace(/[#*`_~]/g, '').trim();
          if (hText.length >= 3 && hText.length <= 60) return sanitizeTitle(hText);
        }
        prev = prev.previousElementSibling;
        attempts++;
      }
    }

    // 2. Cek frontmatter title: --- title: "..." ---
    const fmMatch = code.match(/^---\s*[\r\n]+(?:[\s\S]*?\n)?title:\s*["']?([^"'\r\n]+)["']?/i);
    if (fmMatch && fmMatch[1] && fmMatch[1].trim().length >= 3) {
      return sanitizeTitle(fmMatch[1]);
    }

    // 3. Cek direktif title atau accTitle: title: "..."
    const titleMatch = code.match(/^(?:accTitle|title)[:\s]+["']?([^"'\r\n]+)["']?/im);
    if (titleMatch && titleMatch[1] && titleMatch[1].trim().length >= 3) {
      return sanitizeTitle(titleMatch[1]);
    }

    // 4. Cek judul subgraph pertama: subgraph Enc["<b>ENCODER STACK</b>"]
    const subMatch = code.match(/subgraph\s+[a-zA-Z0-9_-]+\s*\["([^"\r\n]+)"\]/i);
    if (subMatch && subMatch[1]) {
      const cleanSub = subMatch[1].replace(/<[^>]+>/g, '').trim();
      if (cleanSub.length >= 3) return sanitizeTitle(cleanSub);
    }

    // 5. Cek label node pertama yang bermakna
    const nodeMatch = code.match(/[a-zA-Z0-9_-]+\s*\["([^"\r\n]+)"\]/);
    if (nodeMatch && nodeMatch[1]) {
      const cleanNode = nodeMatch[1].replace(/<[^>]+>/g, '').replace(/\\n/g, ' ').trim();
      if (cleanNode.length >= 3 && cleanNode.length <= 40) return sanitizeTitle(cleanNode);
    }

    // 6. Jenis diagram fallback
    const firstLine = code.trim().split('\n')[0].toLowerCase();
    if (firstLine.includes('sequencediagram')) return 'sequence_diagram';
    if (firstLine.includes('classdiagram')) return 'class_diagram';
    if (firstLine.includes('statediagram')) return 'state_diagram';
    if (firstLine.includes('erdiagram')) return 'er_diagram';
    if (firstLine.includes('flowchart') || firstLine.includes('graph')) return 'diagram_alur';
    if (firstLine.includes('mindmap')) return 'mindmap_diagram';
    return 'diagram_visual';
  }

  function generateUniqueDiagramFilename(code, preElement = null, ext = 'jpeg') {
    const base = extractSmartDiagramTitle(code, preElement);
    const now = new Date();
    const dateStr = now.getFullYear().toString() +
      String(now.getMonth() + 1).padStart(2, '0') +
      String(now.getDate()).padStart(2, '0');
    const timeStr = String(now.getHours()).padStart(2, '0') +
      String(now.getMinutes()).padStart(2, '0') +
      String(now.getSeconds()).padStart(2, '0');
    return `${base}_${dateStr}_${timeStr}.${ext}`;
  }

  let mermaidDiagramCounter = 0;

  function renderInteractiveMermaidCard(preElement, rawCode) {
    if (!preElement || !rawCode) return;
    if (preElement.dataset.mermaidRendered === 'true') return;
    preElement.dataset.mermaidRendered = 'true';

    const cleanCode = getCleanMermaidCode(rawCode);
    mermaidDiagramCounter++;
    const cardId = 'mermaidCard_' + mermaidDiagramCounter + '_' + Math.random().toString(36).substring(2, 7);
    const diagramId = 'mermaidSvg_' + mermaidDiagramCounter + '_' + Math.random().toString(36).substring(2, 7);

    const smartBaseTitle = extractSmartDiagramTitle(cleanCode, preElement);
    let diagramTitle = smartBaseTitle.replace(/_/g, ' ');
    if (diagramTitle.length > 40) diagramTitle = diagramTitle.slice(0, 40) + '...';

    const card = document.createElement('div');
    card.className = 'mermaid-diagram-card';
    card.id = cardId;

    const toolbar = document.createElement('div');
    toolbar.className = 'mermaid-toolbar';
    toolbar.innerHTML = `
      <div class="mermaid-title">
        <i class="fa-solid fa-diagram-project"></i>
        <span>${escapeHtml(diagramTitle)}</span>
      </div>
      <div class="mermaid-actions">
        <button class="mermaid-tool-btn mermaid-fullscreen-btn" data-action="fullscreen" title="Layar Penuh (Full Screen)"><i class="fa-solid fa-expand"></i> <span>Layar Penuh</span></button>
        <button class="mermaid-tool-btn" data-action="toggle-code" title="Lihat Sumber Mermaid"><i class="fa-solid fa-code"></i></button>
        <button class="mermaid-tool-btn" data-action="copy-code" title="Salin Kode Mermaid"><i class="fa-solid fa-clipboard"></i> <span>Salin</span></button>
        <div class="mermaid-dropdown-wrap">
          <button class="mermaid-tool-btn mermaid-download-toggle-btn" data-action="toggle-download-menu" title="Unduh Diagram (Pilih Format)"><i class="fa-solid fa-download"></i> <span>Unduh</span> <i class="fa-solid fa-chevron-down" style="font-size:0.65em; margin-left:3px;"></i></button>
          <div class="mermaid-dropdown-menu" style="display:none;">
            <button type="button" class="mermaid-download-item" data-action="download-svg">
              <i class="fa-solid fa-bezier-curve" style="color:var(--neon-cyan);"></i>
              <div class="menu-desc-text">
                <span class="fmt-title">Vektor SVG (.svg)</span>
                <span class="fmt-sub">Resolusi tajam tak terbatas, format vektor</span>
              </div>
            </button>
            <button type="button" class="mermaid-download-item" data-action="download-jpeg">
              <i class="fa-solid fa-file-image" style="color:var(--neon-amber);"></i>
              <div class="menu-desc-text">
                <span class="fmt-title">Gambar JPEG (.jpeg)</span>
                <span class="fmt-sub">Gambar raster HD, siap dibagikan ke mana saja</span>
              </div>
            </button>
          </div>
        </div>
        <button class="mermaid-tool-btn" data-action="zoom-out" title="Perkecil (-)"><i class="fa-solid fa-minus"></i></button>
        <span class="mermaid-zoom-level">100%</span>
        <button class="mermaid-tool-btn" data-action="zoom-in" title="Perbesar (+)"><i class="fa-solid fa-plus"></i></button>
        <button class="mermaid-tool-btn" data-action="zoom-reset" title="Reset Zoom (100%)"><i class="fa-solid fa-compress"></i></button>
      </div>
    `;

    const viewport = document.createElement('div');
    viewport.className = 'mermaid-viewport';

    const stage = document.createElement('div');
    stage.className = 'mermaid-svg-stage';
    stage.innerHTML = '<div style="padding:24px; color:var(--text-muted); font-size:12px; display:flex; align-items:center; gap:8px;"><i class="fa-solid fa-circle-notch fa-spin"></i> Merender visual diagram...</div>';

    viewport.appendChild(stage);

    const codeView = document.createElement('div');
    codeView.className = 'mermaid-code-view';
    codeView.style.display = 'none';
    const codePre = document.createElement('pre');
    codePre.style.margin = '0';
    codePre.style.borderRadius = '0';
    const codeInner = document.createElement('code');
    codeInner.className = 'language-mermaid';
    codeInner.textContent = cleanCode;
    codePre.appendChild(codeInner);
    codeView.appendChild(codePre);

    card.appendChild(toolbar);
    card.appendChild(viewport);
    card.appendChild(codeView);

    preElement.parentNode.replaceChild(card, preElement);

    let zoomLevel = 1.0;
    const zoomLabel = toolbar.querySelector('.mermaid-zoom-level');

    function applyZoom(newZoom) {
      zoomLevel = Math.max(0.4, Math.min(3.0, newZoom));
      stage.style.transform = `scale(${zoomLevel})`;
      if (zoomLabel) {
        zoomLabel.textContent = Math.round(zoomLevel * 100) + '%';
      }
    }

    let isPanning = false;
    let startX = 0;
    let startY = 0;
    let scrollLeft = 0;
    let scrollTop = 0;

    viewport.addEventListener('mousedown', (e) => {
      if (e.target.closest('.mermaid-toolbar') || e.target.closest('.mermaid-tool-btn')) return;
      isPanning = true;
      viewport.classList.add('panning');
      startX = e.pageX - viewport.offsetLeft;
      startY = e.pageY - viewport.offsetTop;
      scrollLeft = viewport.scrollLeft;
      scrollTop = viewport.scrollTop;
    });

    window.addEventListener('mouseup', () => {
      if (isPanning) {
        isPanning = false;
        viewport.classList.remove('panning');
      }
    });

    viewport.addEventListener('mousemove', (e) => {
      if (!isPanning) return;
      e.preventDefault();
      const x = e.pageX - viewport.offsetLeft;
      const y = e.pageY - viewport.offsetTop;
      viewport.scrollLeft = scrollLeft - (x - startX);
      viewport.scrollTop = scrollTop - (y - startY);
    });

    viewport.addEventListener('touchstart', (e) => {
      if (e.touches.length === 1) {
        isPanning = true;
        startX = e.touches[0].pageX - viewport.offsetLeft;
        startY = e.touches[0].pageY - viewport.offsetTop;
        scrollLeft = viewport.scrollLeft;
        scrollTop = viewport.scrollTop;
      }
    }, { passive: true });

    viewport.addEventListener('touchmove', (e) => {
      if (isPanning && e.touches.length === 1) {
        const x = e.touches[0].pageX - viewport.offsetLeft;
        const y = e.touches[0].pageY - viewport.offsetTop;
        viewport.scrollLeft = scrollLeft - (x - startX);
        viewport.scrollTop = scrollTop - (y - startY);
      }
    }, { passive: true });

    viewport.addEventListener('touchend', () => {
      isPanning = false;
    });

    viewport.addEventListener('dblclick', (e) => {
      if (e.target.closest('.mermaid-toolbar') || e.target.closest('.mermaid-tool-btn')) return;
      const fsBtn = toolbar.querySelector('[data-action="fullscreen"]');
      if (fsBtn) fsBtn.click();
    });

    const escMermaidFullscreen = (e) => {
      if (e.key === 'Escape' && card.classList.contains('mermaid-fullscreen')) {
        const fsBtn = toolbar.querySelector('[data-action="fullscreen"]');
        if (fsBtn) fsBtn.click();
      }
    };
    window.addEventListener('keydown', escMermaidFullscreen);

    toolbar.addEventListener('click', async (e) => {
      const btn = e.target.closest('.mermaid-tool-btn, .mermaid-download-item');
      if (!btn) return;
      e.stopPropagation();
      const action = btn.dataset.action;

      if (action === 'fullscreen') {
        const isFs = card.classList.toggle('mermaid-fullscreen');
        const parentRow = card.closest('.message-row');
        if (parentRow) parentRow.classList.toggle('has-mermaid-fullscreen', isFs);
        const parentBubble = card.closest('.message-bubble');
        if (parentBubble) parentBubble.classList.toggle('has-mermaid-fullscreen', isFs);
        const fsIcon = btn.querySelector('i');
        const fsText = btn.querySelector('span');
        if (isFs) {
          if (fsIcon) fsIcon.className = 'fa-solid fa-compress';
          if (fsText) fsText.textContent = 'Kecilkan';
          btn.title = 'Keluar Layar Penuh (Esc)';
          document.body.classList.add('mermaid-has-fullscreen');
          applyZoom(1.0);
        } else {
          if (fsIcon) fsIcon.className = 'fa-solid fa-expand';
          if (fsText) fsText.textContent = 'Layar Penuh';
          btn.title = 'Layar Penuh (Full Screen)';
          document.body.classList.remove('mermaid-has-fullscreen');
        }
      } else if (action === 'zoom-in') {
        applyZoom(zoomLevel + 0.15);
      } else if (action === 'zoom-out') {
        applyZoom(zoomLevel - 0.15);
      } else if (action === 'zoom-reset') {
        applyZoom(1.0);
        viewport.scrollLeft = Math.max(0, (stage.scrollWidth - viewport.clientWidth) / 2);
        viewport.scrollTop = 0;
      } else if (action === 'toggle-code') {
        const isCodeVisible = codeView.style.display !== 'none';
        if (isCodeVisible) {
          codeView.style.display = 'none';
          viewport.style.display = 'flex';
          btn.classList.remove('active');
          btn.title = 'Lihat Sumber Mermaid';
        } else {
          codeView.style.display = 'block';
          viewport.style.display = 'none';
          btn.classList.add('active');
          btn.title = 'Lihat Diagram Visual';
          if (window.hljs) {
            try { hljs.highlightElement(codeInner); } catch (_) {}
          }
        }
      } else if (action === 'copy-code') {
        copyTextToClipboard(cleanCode, () => {
          showToast('Kode sumber diagram Mermaid berhasil disalin!');
          AudioEngine.snap();
        });
      } else if (action === 'toggle-download-menu') {
        const menu = toolbar.querySelector('.mermaid-dropdown-menu');
        if (menu) {
          const isVisible = menu.style.display !== 'none';
          document.querySelectorAll('.mermaid-dropdown-menu').forEach(m => m.style.display = 'none');
          menu.style.display = isVisible ? 'none' : 'flex';
        }
      } else if (action === 'download-svg') {
        const menu = toolbar.querySelector('.mermaid-dropdown-menu');
        if (menu) menu.style.display = 'none';
        const svgEl = stage.querySelector('svg');
        if (!svgEl) {
          showToast('Diagram belum siap diunduh.', 'warning');
          return;
        }
        try {
          const svgData = new XMLSerializer().serializeToString(svgEl);
          const svgBlob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
          const svgUrl = URL.createObjectURL(svgBlob);
          const downloadLink = document.createElement('a');
          downloadLink.href = svgUrl;
          const finalSvgName = generateUniqueDiagramFilename(cleanCode, card, 'svg');
          downloadLink.download = finalSvgName;
          document.body.appendChild(downloadLink);
          downloadLink.click();
          downloadLink.remove();
          setTimeout(() => URL.revokeObjectURL(svgUrl), 2000);
          showToast(`Diagram SVG (${finalSvgName}) berhasil diunduh!`);
          AudioEngine.success();
        } catch (err) {
          showToast('Gagal mengunduh SVG: ' + err.message, 'error');
        }
      } else if (action === 'download-jpeg') {
        const menu = toolbar.querySelector('.mermaid-dropdown-menu');
        if (menu) menu.style.display = 'none';
        const svgEl = stage.querySelector('svg');
        if (!svgEl) {
          showToast('Diagram belum siap diunduh.', 'warning');
          return;
        }
        try {
          showToast('⚙ Merasterisasi gambar JPEG resolusi tinggi...', 'info');
          const jpegBlob = await convertSvgToJpegBlob(svgEl, { mermaidCode: cleanCode });
          const jpegUrl = URL.createObjectURL(jpegBlob);
          const downloadLink = document.createElement('a');
          downloadLink.href = jpegUrl;
          const finalJpegName = generateUniqueDiagramFilename(cleanCode, card, 'jpeg');
          downloadLink.download = finalJpegName;
          document.body.appendChild(downloadLink);
          downloadLink.click();
          downloadLink.remove();
          setTimeout(() => URL.revokeObjectURL(jpegUrl), 2000);
          showToast(`Diagram JPEG (${finalJpegName}) berhasil diunduh!`, 'success');
          AudioEngine.success();
        } catch (err) {
          showToast('Gagal mengunduh JPEG: ' + err.message, 'error');
        }
      }
    });

    function tryRenderSvg(retries = 8) {
      if (typeof window.mermaid !== 'undefined' && typeof window.mermaid.render === 'function') {
        try {
          initMermaidEngine();
          window.mermaid.render(diagramId, cleanCode).then((result) => {
            if (result && result.svg) {
              stage.innerHTML = result.svg;
              const svgNode = stage.querySelector('svg');
              if (svgNode) {
                svgNode.style.maxWidth = '100%';
                svgNode.style.height = 'auto';
                svgNode.style.display = 'block';
              }
              setTimeout(() => {
                viewport.scrollLeft = Math.max(0, (stage.scrollWidth - viewport.clientWidth) / 2);
              }, 50);
            }
          }).catch((renderErr) => {
            console.warn('Percobaan render diagram pertama gagal, mencoba pembersih sekunder:', renderErr);
            const aggressiveCode = getAggressiveMermaidCleaner(cleanCode);
            if (aggressiveCode && aggressiveCode !== cleanCode) {
              window.mermaid.render(diagramId + '_clean', aggressiveCode).then((res2) => {
                if (res2 && res2.svg) {
                  stage.innerHTML = res2.svg;
                  const svgNode = stage.querySelector('svg');
                  if (svgNode) {
                    svgNode.style.maxWidth = '100%';
                    svgNode.style.height = 'auto';
                    svgNode.style.display = 'block';
                  }
                  setTimeout(() => {
                    viewport.scrollLeft = Math.max(0, (stage.scrollWidth - viewport.clientWidth) / 2);
                  }, 50);
                  return;
                }
                showDiagramError();
              }).catch(() => {
                showDiagramError();
              });
            } else {
              showDiagramError();
            }
          });

          function showDiagramError() {
            stage.innerHTML = `
              <div class="mermaid-render-error">
                <i class="fa-solid fa-triangle-exclamation"></i>
                <div>
                  <strong>Visualisasi Diagram:</strong> Sintaks Mermaid memerlukan penyesuaian.
                  <div style="font-size:11px; margin-top:4px; opacity:0.85;">Klik tombol &lt;/&gt; di toolbar atas untuk melihat atau menyalin kode sumber diagram.</div>
                  <div style="margin-top:10px; display:flex; gap:8px; flex-wrap:wrap;">
                    <button type="button" class="mermaid-err-copy-btn" style="background:rgba(255,255,255,0.08); border:1px solid rgba(255,255,255,0.2); color:#f8fafc; border-radius:6px; padding:5px 12px; font-size:11px; font-weight:600; cursor:pointer; display:inline-flex; align-items:center; gap:6px;">
                      <i class="fa-solid fa-clipboard"></i> Salin Teks / Sumber
                    </button>
                    <button type="button" class="mermaid-err-view-btn" style="background:rgba(255,255,255,0.08); border:1px solid rgba(255,255,255,0.2); color:#f8fafc; border-radius:6px; padding:5px 12px; font-size:11px; font-weight:600; cursor:pointer; display:inline-flex; align-items:center; gap:6px;">
                      <i class="fa-solid fa-code"></i> Tampilkan Sebagai Kode/Teks
                    </button>
                  </div>
                </div>
              </div>
            `;
            const copyBtn = stage.querySelector('.mermaid-err-copy-btn');
            if (copyBtn) {
              copyBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                copyTextToClipboard(cleanCode, () => {
                  copyBtn.innerHTML = '<i class="fa-solid fa-check" style="color:var(--neon-teal);"></i> <span style="color:var(--neon-teal);">Disalin!</span>';
                  showToast('Teks sumber berhasil disalin!');
                  AudioEngine.snap();
                  setTimeout(() => {
                    copyBtn.innerHTML = '<i class="fa-solid fa-clipboard"></i> Salin Teks / Sumber';
                  }, 2000);
                });
              });
            }
            const viewBtn = stage.querySelector('.mermaid-err-view-btn');
            if (viewBtn) {
              viewBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                codeView.style.display = 'block';
                viewport.style.display = 'none';
                const codeBtn = toolbar.querySelector('[data-action="toggle-code"]');
                if (codeBtn) {
                  codeBtn.classList.add('active');
                  codeBtn.title = 'Lihat Diagram Visual';
                }
                if (window.hljs) {
                  try { hljs.highlightElement(codeInner); } catch (_) {}
                }
              });
            }
          }
        } catch (callErr) {
          console.warn('Mermaid render exception:', callErr);
          stage.innerHTML = `
            <div class="mermaid-render-error">
              <i class="fa-solid fa-circle-exclamation"></i>
              <div>Gagal memproses diagram visual. Klik &lt;/&gt; untuk melihat kode.</div>
            </div>
          `;
        }
      } else if (retries > 0) {
        setTimeout(() => tryRenderSvg(retries - 1), 180);
      } else {
        stage.innerHTML = `
          <div class="mermaid-render-error">
            <i class="fa-solid fa-circle-notch fa-spin"></i>
            <div>Memuat modul visual diagram... Klik &lt;/&gt; untuk melihat kode sumber.</div>
          </div>
        `;
      }
    }

    tryRenderSvg();
  }

  // ==================== UNIVERSAL CODE BLOCK ENHANCER (Syntax & Copy Button) ====================
  function enhanceCodeBlocks(container = document) {
    if (!container) return;
    
    // Process all PRE elements within container
    const preElements = container.querySelectorAll('pre');
    preElements.forEach(pre => {
      // Avoid duplicate headers or already rendered mermaid cards
      if (pre.querySelector('.code-header') || pre.closest('.mermaid-diagram-card') || pre.dataset.mermaidRendered === 'true') return;

      const codeBlock = pre.querySelector('code');
      let lang = 'CODE';
      let rawText = '';

      if (codeBlock) {
        rawText = (codeBlock.textContent || codeBlock.innerText || '').trim();
        const langMatch = codeBlock.className.match(/language-([a-zA-Z0-9_\-#+]+)/);
        if (langMatch && langMatch[1]) {
          lang = langMatch[1].toUpperCase();
        }
      } else {
        rawText = (pre.textContent || pre.innerText || '').trim();
      }

      // Pisahkan secara tegas antara Diagram Mermaid vs Kode Pemrograman / Teks Biasa yang siap disalin
      let isMermaid = false;
      let cleanCode = '';

      if (lang === 'MERMAID' || lang === 'MMD') {
        // Blok secara eksplisit dideklarasikan sebagai diagram Mermaid (```mermaid / ```mmd)
        isMermaid = true;
        cleanCode = getCleanMermaidCode(rawText);
      } else if (!NON_DIAGRAM_LANGUAGES.has(lang)) {
        // Blok tanpa bahasa (lang === 'CODE') HANYA dijadikan diagram jika memenuhi sintaks otentik Mermaid
        if (!pre.dataset.mermaidRendered && isAuthenticMermaidSyntax(rawText)) {
          isMermaid = true;
          cleanCode = getCleanMermaidCode(rawText);
        }
      }

      if (isMermaid && cleanCode) {
        renderInteractiveMermaidCard(pre, cleanCode);
        return;
      }

      // Highlight syntax if hljs is present (HANYA untuk kode non-Mermaid)
      if (codeBlock && window.hljs && !codeBlock.dataset.highlighted) {
        try {
          hljs.highlightElement(codeBlock);
          codeBlock.dataset.highlighted = 'true';
        } catch (e) {}
      }

      // Create code header bar with Copy Button
      const header = document.createElement('div');
      header.className = 'code-header';
      header.innerHTML = `
        <span class="code-lang-label"><i class="fa-solid fa-code"></i> ${escapeHtml(lang)}</span>
        <button class="code-copy-btn" title="Salin seluruh kode">
          <i class="fa-solid fa-clipboard"></i>
          <span class="copy-text">Salin Kode</span>
        </button>
      `;

      const copyBtn = header.querySelector('.code-copy-btn');
      copyBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        let codeText = '';
        if (codeBlock) {
          codeText = codeBlock.innerText || codeBlock.textContent || '';
        } else {
          const clone = pre.cloneNode(true);
          const oldHeader = clone.querySelector('.code-header');
          if (oldHeader) oldHeader.remove();
          codeText = clone.innerText || clone.textContent || '';
        }
        
        const setCopiedState = () => {
          copyBtn.innerHTML = '<i class="fa-solid fa-check" style="color:var(--neon-teal);"></i> <span class="copy-text" style="color:var(--neon-teal);">Disalin!</span>';
          copyBtn.classList.add('copied');
          showToast(`Kode ${lang} berhasil disalin ke clipboard!`);
          AudioEngine.snap();
          setTimeout(() => {
            copyBtn.innerHTML = '<i class="fa-solid fa-clipboard"></i> <span class="copy-text">Salin Kode</span>';
            copyBtn.classList.remove('copied');
          }, 2000);
        };

        copyTextToClipboard(codeText, setCopiedState);
      });

      pre.insertBefore(header, pre.firstChild);
    });
  }

  // ==================== UNIVERSAL CHAT IMAGE ENHANCER (Lightbox & Zoom) ====================
  function enhanceChatImages(container = document) {
    if (!container) return;
    const images = container.querySelectorAll('.msg-text-content img, .message-bubble img');
    images.forEach(img => {
      if (img.classList.contains('chat-zoomable-img') || img.classList.contains('image-result-img')) return;
      img.classList.add('chat-zoomable-img');
      img.loading = 'lazy';
      img.decoding = 'async';
      img.style.cursor = 'zoom-in';
      img.style.maxWidth = '100%';
      img.style.borderRadius = 'var(--radius-md, 8px)';
      img.style.display = 'block';
      img.style.marginTop = '8px';
      img.style.marginBottom = '8px';
      img.addEventListener('click', (e) => {
        e.stopPropagation();
        if (ImageLightbox && typeof ImageLightbox.open === 'function') {
          ImageLightbox.open([img.src], 0);
        }
      });
    });
  }

  function fallbackCopyText(text, onSuccess) {
    const textarea = document.createElement('textarea');
    textarea.value = text;
    textarea.style.position = 'fixed';
    textarea.style.top = '0';
    textarea.style.left = '0';
    textarea.style.width = '2em';
    textarea.style.height = '2em';
    textarea.style.padding = '0';
    textarea.style.border = 'none';
    textarea.style.outline = 'none';
    textarea.style.boxShadow = 'none';
    textarea.style.background = 'transparent';
    textarea.setAttribute('readonly', '');
    document.body.appendChild(textarea);
    try {
      textarea.focus();
      textarea.select();
      textarea.setSelectionRange(0, textarea.value.length);
      const successful = document.execCommand('copy');
      if (successful && onSuccess) {
        onSuccess();
      } else if (!successful) {
        showToast('Gagal menyalin teks ke clipboard.', 'error');
      }
    } catch (err) {
      showToast('Gagal menyalin teks ke clipboard.', 'error');
    } finally {
      textarea.remove();
    }
  }

  function copyTextToClipboard(text, onSuccess, successMsg = 'Teks disalin ke clipboard!') {
    const handleSuccess = () => {
      if (typeof onSuccess === 'function') {
        onSuccess();
      } else if (successMsg) {
        showToast(successMsg);
        AudioEngine.click();
      }
    };

    if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
      navigator.clipboard.writeText(text).then(handleSuccess).catch(() => {
        fallbackCopyText(text, handleSuccess);
      });
    } else {
      fallbackCopyText(text, handleSuccess);
    }
  }

    // ==================== SMART SCROLL STATE ====================
    let userScrolledUp = false;
    let isAutoScrolling = false;

    // ==================== HIGH-PERFORMANCE 60FPS STREAM BUFFER RENDERER ====================
  function hideTaskBlocksForDisplay(text) {
    if (!text || text.indexOf('<<<ZOZ_TASKS') === -1) return text;
    const out = [];
    let skipping = false;
    text.split('\n').forEach((line) => {
      const t = line.trim();
      if (!skipping) {
        if (t.indexOf('<<<ZOZ_TASKS') === 0) { skipping = true; return; }
        out.push(line);
        return;
      }
      if (t.indexOf('<<<END_ZOZ_TASKS') === 0) skipping = false;
    });
    return out.join('\n');
  }

  // Sembunyikan blok ZOZ_FILE, ZOZ_EDIT, ZOZ_MODIFY, ZOZ_DELETE, & ZOZ_TASKS dari tampilan sementara
  // saat streaming, supaya kode mentah tidak membajak gelembung obrolan.
  function hideFileBlocksForDisplay(text) {
    if (!text) return text;
    let processed = text;
    if (processed.indexOf('<<<ZOZ_TASKS') !== -1) {
      processed = hideTaskBlocksForDisplay(processed);
    }
    const hasFileMarkers = processed.indexOf('<<<ZOZ_FILE') !== -1 ||
                           processed.indexOf('<<<ZOZ_EDIT') !== -1 ||
                           processed.indexOf('<<<ZOZ_MODIFY') !== -1 ||
                           processed.indexOf('<<<ZOZ_DELETE') !== -1;
    if (!hasFileMarkers) return processed;

    const out = [];
    let skipping = false;
    processed.split('\n').forEach((line) => {
      const t = line.trim();
      if (!skipping) {
        if (t.indexOf('<<<ZOZ_FILE') === 0 || t.indexOf('<<<ZOZ_EDIT') === 0 || t.indexOf('<<<ZOZ_MODIFY') === 0) {
          skipping = true;
          return;
        }
        if (t.indexOf('<<<ZOZ_DELETE') === 0) {
          return; // single line directive
        }
        out.push(line);
        return;
      }
      // Masih di dalam blok file: buang sampai penanda tutup (atau sampai stream berakhir)
      if (t.indexOf('<<<END_ZOZ_FILE') === 0 || t.indexOf('<<<END_ZOZ_EDIT') === 0 || t.indexOf('<<<END_ZOZ_MODIFY') === 0) {
        skipping = false;
      }
    });
    return out.join('\n');
  }

  // Teks dari model reasoning varian :free sering "robek" per-token (satu KATA
  // per baris sehingga output tertampil vertikal berantakan). Sambung baris
  // PROSA berurutan menjadi satu baris mengalir — baris struktural (heading,
  // list, blockquote, tabel) dan isi BLOK KODE (di antara ```) dibiarkan utuh.
  function reflowShreddedProse(text) {
    return TEXT_SAFETY ? TEXT_SAFETY.reflowShreddedProse(text) : text;
  }

  class StreamBufferRenderer {
    constructor(bubbleElement, onScrollCallback, prefixHtml = '') {
      this.el = bubbleElement;
      this.onScroll = onScrollCallback;
      this.prefixHtml = prefixHtml;
      this.text = '';
      this.renderTimer = null; // handle setTimeout render terjadwal (coalesced)
      this.lastRenderTime = 0;
      this.isDone = false;
      this.isLoopTerminated = false;
    }

    setPrefixHtml(prefix) {
      this.prefixHtml = prefix || '';
    }

    appendReasoning(_reasoningDelta) {
      // Fail closed: kanal reasoning sengaja tidak disimpan/render di transkrip.
    }

    detectRepetitionLoop() {
      if (!this.text || this.text.length < 32) return false;
      const tail = this.text.slice(-320);

      // 1. Single character repetition: e.g. '&&&&&&&&&&&&&&&&&&&&' (>= 18 kali beruntun)
      const singleCharMatch = /(.)\1{17,}$/.exec(tail);
      if (singleCharMatch) {
        const char = singleCharMatch[1];
        const isWhitespace = /\s/.test(char);
        if (!isWhitespace || singleCharMatch[0].length >= 35) {
          const excessLen = singleCharMatch[0].length - 3;
          if (excessLen > 0) {
            this.text = this.text.slice(0, -excessLen);
          }
          return true;
        }
      }

      // 2. Multi-character pattern repetition: pola berulang (2 s.d. 30 karakter)
      for (let L = 2; L <= 30; L++) {
        if (tail.length < L * 5) continue;
        const pattern = tail.slice(-L);
        let count = 0;
        let pos = tail.length;
        while (pos >= L && tail.slice(pos - L, pos) === pattern) {
          count++;
          pos -= L;
        }
        const minRepeats = L <= 3 ? 8 : (L <= 10 ? 6 : 4);
        if (count >= minRepeats) {
          const excessRepeats = count - 2;
          if (excessRepeats > 0) {
            this.text = this.text.slice(0, -(excessRepeats * L));
          }
          return true;
        }
      }
      return false;
    }

    append(delta) {
      if (delta === null || delta === undefined) return;
      if (this.isLoopTerminated || this.isDone) return;
      const str = String(delta);
      if (!str) return;
      this.text += str;

      if (this.detectRepetitionLoop()) {
        this.isLoopTerminated = true;
        this.scheduleRender();
        return;
      }

      if (this.isDone) return;
      this.scheduleRender();
    }

    // SELALU jadwalkan render — TIDAK PERNAH render sinkron dari dalam loop baca SSE.
    // Coalesced/trailing: selama ada timer, append berikutnya tidak membuat timer baru
    // (paling banyak satu render per interval adaptif), dan timer selalu menyusul
    // append terakhir sehingga state final tidak pernah terlewat.
    scheduleRender() {
      if (this.renderTimer !== null) return;
      const isMobile = typeof window !== 'undefined' && window.innerWidth <= 768;
      const minInterval = isMobile ? 120 : 75;
      const interval = Math.min(220, Math.max(minInterval, Math.floor(this.text.length / 120)));
      const delay = Math.max(0, this.lastRenderTime + interval - performance.now());
      this.renderTimer = setTimeout(() => {
        this.renderTimer = null;
        this.lastRenderTime = performance.now();
        this.render();
      }, delay);
    }

    render() {
      if (!this.el) return;
      this.el.innerHTML = (this.prefixHtml || '') + renderMarkdown(hideFileBlocksForDisplay(this.text), true) + '<span class="typing-cursor"></span>';
      if (this.onScroll && !userScrolledUp) this.onScroll();
    }

    finish(opts = {}) {
      // opts.render === false → batalkan timer dan kembalikan teks jawaban,
      // TANPA menyentuh DOM (jalur completion merender sendiri di bawahnya).
      const shouldRender = opts.render !== false;
      this.isDone = true;
      if (this.renderTimer !== null) {
        clearTimeout(this.renderTimer);
        this.renderTimer = null;
      }
      if (shouldRender && this.el) {
        this.el.innerHTML = (this.prefixHtml || '') + renderMarkdown(hideFileBlocksForDisplay(this.text), false);
        enhanceCodeBlocks(this.el);
      }
      if (this.onScroll && !userScrolledUp) this.onScroll();
      return this.text;
    }

    flush() {
      return this.finish();
    }

    getFullText() {
      return this.text;
    }
  }

  // ==================== SMART SCROLL & CONTINUATION MANAGER ====================

  function isChatAtBottom(element = els.chatViewport, threshold = 25) {
    if (!element) return true;
    return (element.scrollHeight - element.scrollTop - element.clientHeight) <= threshold;
  }

  let scrollBottomBtnHideTimeout = null;

  function toggleScrollBottomBtn(show) {
    if (!els.scrollBottomBtn) return;
    if (scrollBottomBtnHideTimeout) {
      clearTimeout(scrollBottomBtnHideTimeout);
      scrollBottomBtnHideTimeout = null;
    }

    if (show) {
      els.scrollBottomBtn.style.display = 'flex';
      requestAnimationFrame(() => {
        els.scrollBottomBtn?.classList.add('visible');
      });
    } else {
      els.scrollBottomBtn.classList.remove('visible');
      scrollBottomBtnHideTimeout = setTimeout(() => {
        if (!els.scrollBottomBtn?.classList.contains('visible')) {
          els.scrollBottomBtn.style.display = 'none';
        }
      }, 300);
    }
  }

  function smartScrollChatToBottom(force = false) {
    if (!els.chatViewport) return;
    if (force) {
      userScrolledUp = false;
      toggleScrollBottomBtn(false);
    }
    if (userScrolledUp && !force) return;

    isAutoScrolling = true;
    els.chatViewport.scrollTop = els.chatViewport.scrollHeight;
    requestAnimationFrame(() => {
      isAutoScrolling = false;
    });
  }

  function setupSmartScrolling() {
    if (!els.chatViewport) return;

    let touchStartY = 0;
    let touchStartTime = 0;
    let pullHoldTimer = null;
    let pullFadeTimeout = null;
    let autoHideRevealedTimer = null;
    let wheelTimer = null;
    let wheelHoldTimer = null;
    let wheelAccumDelta = 0;
    let isScrollBtnVisible = false;
    // Dwell delay: tombol gulir-bawah hanya muncul setelah pengguna MENAHAN posisi
    // menggulir ke atas selama beberapa saat (bukan langsung reaktif saat melewati ambang).
    let scrollBtnDwellTimer = null;
    const SCROLL_BTN_DWELL_MS = 700;

    function showPullLoading() {
      if (!els.pullUpNewChatWrapper) return;
      const hasActiveMessages = STATE.currentSessionId && els.messagesList && els.messagesList.children.length > 0;
      if (!hasActiveMessages || STATE.isGenerating) return;

      if (pullFadeTimeout) {
        clearTimeout(pullFadeTimeout);
        pullFadeTimeout = null;
      }

      els.pullUpNewChatWrapper.style.display = 'flex';
      els.pullUpNewChatWrapper.classList.remove('revealed');
      requestAnimationFrame(() => {
        els.pullUpNewChatWrapper.classList.add('visible');
      });
    }

    function revealPullNewChatBtn() {
      if (!els.pullUpNewChatWrapper) return;
      const hasActiveMessages = STATE.currentSessionId && els.messagesList && els.messagesList.children.length > 0;
      if (!hasActiveMessages || STATE.isGenerating) return;

      if (pullFadeTimeout) {
        clearTimeout(pullFadeTimeout);
        pullFadeTimeout = null;
      }
      if (pullHoldTimer) {
        clearTimeout(pullHoldTimer);
        pullHoldTimer = null;
      }
      if (wheelHoldTimer) {
        clearTimeout(wheelHoldTimer);
        wheelHoldTimer = null;
      }
      wheelAccumDelta = 0;

      els.pullUpNewChatWrapper.style.display = 'flex';
      els.pullUpNewChatWrapper.classList.add('visible');
      els.pullUpNewChatWrapper.classList.add('revealed');
      AudioEngine.snap();

      // Auto dismiss after 8s if user leaves button untouched without clicking or scrolling
      if (autoHideRevealedTimer) clearTimeout(autoHideRevealedTimer);
      autoHideRevealedTimer = setTimeout(() => {
        if (els.pullUpNewChatWrapper?.classList.contains('revealed')) {
          hidePullWrapper(false, true);
        }
      }, 8000);
    }

    function hidePullWrapper(instant = false, reboundToBottom = true) {
      if (!els.pullUpNewChatWrapper) return;
      if (pullHoldTimer) {
        clearTimeout(pullHoldTimer);
        pullHoldTimer = null;
      }
      if (wheelHoldTimer) {
        clearTimeout(wheelHoldTimer);
        wheelHoldTimer = null;
      }
      if (autoHideRevealedTimer) {
        clearTimeout(autoHideRevealedTimer);
        autoHideRevealedTimer = null;
      }
      wheelAccumDelta = 0;

      if (instant) {
        els.pullUpNewChatWrapper.classList.remove('visible', 'revealed');
        els.pullUpNewChatWrapper.style.display = 'none';
        return;
      }

      els.pullUpNewChatWrapper.classList.remove('visible');
      if (pullFadeTimeout) clearTimeout(pullFadeTimeout);
      pullFadeTimeout = setTimeout(() => {
        if (!els.pullUpNewChatWrapper.classList.contains('visible')) {
          els.pullUpNewChatWrapper.classList.remove('revealed');
          els.pullUpNewChatWrapper.style.display = 'none';
          if (reboundToBottom && els.chatViewport && isChatAtBottom(els.chatViewport, 60)) {
            els.chatViewport.scrollTo({ top: els.chatViewport.scrollHeight, behavior: 'smooth' });
          }
        }
      }, 160);
    }

    // Pull-up New Chat button click handler
    els.pullUpNewChatBtn?.addEventListener('click', (e) => {
      e.stopPropagation();
      createNewSession();
      hidePullWrapper(true, false);
      AudioEngine.click();
    });

    const handleScrollEvent = (el = els.chatViewport) => {
      if (!el || isAutoScrolling) return;

      const scrollHeight = el.scrollHeight;
      const scrollTop = el.scrollTop;
      const clientHeight = el.clientHeight;
      const distFromBottom = Math.max(0, scrollHeight - scrollTop - clientHeight);

      // Ambang batas kemunculan tombol gulir (Scroll to Bottom Button Threshold):
      // Sesuai instruksi Kaisar Zozi: tombol tidak boleh muncul terlalu cepat saat pengguna hanya
      // menggulir sedikit (misal 50-200px dari dasar). Tombol HANYA muncul jika pengguna menggulir
      // jauh lebih tinggi ke atas (misal di bagian tengah output jawaban atau di percakapan-percakapan lama sebelumnya).
      // Ambang batas: minimal 380px atau 45% dari tinggi viewport obrolan.
      const showThreshold = Math.max(380, Math.round(clientHeight * 0.45));
      const hideThreshold = 80; // Sembunyi halus saat pengguna sudah dekat kembali ke bawah

      // Atur userScrolledUp untuk menjaga agar streaming tidak menyentak viewport jika pengguna sedang membaca
      userScrolledUp = distFromBottom > 70;

      if (distFromBottom >= showThreshold) {
        // Tampil HANYA setelah posisi menggulir ke atas ditahan stabil selama
        // SCROLL_BTN_DWELL_MS. Jika pengguna kembali ke dasar sebelum dwell selesai,
        // timer dibatalkan sehingga tombol tidak pernah muncul (anti-reaktif).
        if (!isScrollBtnVisible && !scrollBtnDwellTimer) {
          scrollBtnDwellTimer = setTimeout(() => {
            scrollBtnDwellTimer = null;
            const el = els.chatViewport;
            if (!el) return;
            const stillAway = (el.scrollHeight - el.scrollTop - el.clientHeight) >= showThreshold;
            if (stillAway && !isScrollBtnVisible) {
              isScrollBtnVisible = true;
              toggleScrollBottomBtn(true);
            }
          }, SCROLL_BTN_DWELL_MS);
        }
        hidePullWrapper(true, false);
      } else if (distFromBottom <= hideThreshold) {
        if (scrollBtnDwellTimer) {
          clearTimeout(scrollBtnDwellTimer);
          scrollBtnDwellTimer = null;
        }
        if (isScrollBtnVisible) {
          isScrollBtnVisible = false;
          toggleScrollBottomBtn(false);
        }
      }
    };

    let scrollRafId = null;
    els.chatViewport?.addEventListener('scroll', () => {
      if (scrollRafId) return;
      scrollRafId = requestAnimationFrame(() => {
        scrollRafId = null;
        handleScrollEvent(els.chatViewport);
      });
    }, { passive: true });
    
    // User touch start, move, and end on mobile devices (ChatGPT Elastic Pull & Hold)
    els.chatViewport?.addEventListener('touchstart', (e) => {
      if (e.touches && e.touches[0]) {
        touchStartY = e.touches[0].clientY;
        touchStartTime = Date.now();
        if (pullHoldTimer) {
          clearTimeout(pullHoldTimer);
          pullHoldTimer = null;
        }
      }
    }, { passive: true });

    els.chatViewport?.addEventListener('touchmove', (e) => {
      if (e.touches && e.touches[0]) {
        const deltaY = touchStartY - e.touches[0].clientY; // positive = pulling past bottom
        const atBottom = isChatAtBottom(els.chatViewport, 45);

        if (deltaY < -10 || (!atBottom && deltaY < 0)) {
          // Scrolling up into previous messages: sembunyikan pull wrapper, handleScrollEvent yang akan mengecek threshold
          hidePullWrapper(true, false);
        } else if (atBottom && deltaY > 12) {
          userScrolledUp = false;
          if (isScrollBtnVisible) {
            isScrollBtnVisible = false;
            toggleScrollBottomBtn(false);
          }

          if (!els.pullUpNewChatWrapper?.classList.contains('revealed')) {
            showPullLoading();

            // Arm hold timer as soon as user pulls past bottom.
            // Dwell ditahan lebih lama agar tombol tidak muncul karena tarikan sesaat.
            if (!pullHoldTimer) {
              const holdDuration = deltaY >= 60 ? 550 : 750;
              pullHoldTimer = setTimeout(() => {
                revealPullNewChatBtn();
                pullHoldTimer = null;
              }, holdDuration);
            }
          }
        }
      }
    }, { passive: true });

    els.chatViewport?.addEventListener('touchend', () => {
      if (pullHoldTimer) {
        clearTimeout(pullHoldTimer);
        pullHoldTimer = null;
      }
      // If user revealed button -> keep it visible for interaction
      // If user did not hold long enough to reveal button -> elastic rebound back to chat output
      if (!els.pullUpNewChatWrapper?.classList.contains('revealed')) {
        hidePullWrapper(false, true);
      }
    }, { passive: true });

    // Desktop wheel: track scroll-and-hold at bottom to reveal New Chat button
    els.chatViewport?.addEventListener('wheel', (e) => {
      if (e.deltaY < 0) {
        // Scrolling up into past messages: sembunyikan pull wrapper, handleScrollEvent yang akan mengecek threshold
        hidePullWrapper(true, false);
      } else if (e.deltaY > 0) {
        const atBottom = isChatAtBottom(els.chatViewport, 45);
        if (atBottom) {
          userScrolledUp = false;
          if (isScrollBtnVisible) {
            isScrollBtnVisible = false;
            toggleScrollBottomBtn(false);
          }

          if (!els.pullUpNewChatWrapper?.classList.contains('revealed')) {
            showPullLoading();
            wheelAccumDelta += Math.abs(e.deltaY);

            // User scrolling down at bottom and holding or repeated wheeling.
            // Dwell ditahan: putaran roda sesaat TIDAK langsung membuka tombol —
            // pengguna harus menahan/menggulir terus selama ~650ms.
            if (!wheelHoldTimer) {
              wheelHoldTimer = setTimeout(() => {
                revealPullNewChatBtn();
                wheelHoldTimer = null;
              }, 650);
            }

            // Quick energetic wheel gesture threshold (dinaikkan dari 70 → 400:
            // butuh beberapa putaran roda berturut-turut, bukan satu sentakan).
            if (wheelAccumDelta >= 400) {
              if (wheelHoldTimer) clearTimeout(wheelHoldTimer);
              wheelHoldTimer = null;
              revealPullNewChatBtn();
            }

            // If user only gave a tiny accidental wheel tick and stopped, rebound after 450ms
            if (wheelTimer) clearTimeout(wheelTimer);
            wheelTimer = setTimeout(() => {
              wheelAccumDelta = 0;
              if (!els.pullUpNewChatWrapper?.classList.contains('revealed')) {
                hidePullWrapper(false, true);
              }
            }, 450);
          }
        }
      }
    }, { passive: true });

    els.scrollBottomBtn?.addEventListener('click', () => {
      if (els.chatViewport) els.chatViewport.scrollTo({ top: els.chatViewport.scrollHeight, behavior: 'smooth' });
      userScrolledUp = false;
      isScrollBtnVisible = false;
      toggleScrollBottomBtn(false);
      AudioEngine.click();
    });
  }

  // ==================== TRUNCATED RESPONSE / NEMOTRON CONTINUATION HELPERS ====================
  function isOutputTruncated(text, finishReason = null) {
    if (finishReason === 'length') return true;
    if (!text) return false;
    const parsed = splitReasoningAndContent(text);
    if (parsed.reasoning && !parsed.content) return true;
    if (text.length < 50) return false;
    const trimmed = text.trim();
    // Check for unclosed markdown code blocks (odd count of ```)
    const backtickCount = (trimmed.match(/```/g) || []).length;
    if (backtickCount % 2 !== 0) return true;
    // Check for trailing unfinished punctuation
    const unfinishedPunctuation = [':', ',', ';', '-', '(', '[', '{'];
    if (unfinishedPunctuation.some(p => trimmed.endsWith(p))) return true;
    // Check for mid-sentence trailing conjunction words (using word boundary to avoid false positives like Medan, Sudan, wayang, waspada)
    const unfinishedWords = ['dan', 'atau', 'dengan', 'yang', 'untuk', 'pada', 'adalah', 'karena', 'namun', 'tetapi', 'serta'];
    if (unfinishedWords.some(w => new RegExp(`\\b${w}$`, 'i').test(trimmed))) return true;
    return false;
  }

  function attachContinuationButton(container, session, assistantRow, modelName, engine, previousText) {
    if (!container) return;
    container.querySelector('.continue-response-btn')?.remove();

    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'continue-response-btn';
    btn.innerHTML = '<i class="fa-solid fa-forward-step"></i> <span>Lanjutkan Jawaban (Output Terpotong)</span>';

    btn.addEventListener('click', async (e) => {
      e.stopPropagation();
      // H2: TOLAK saat masih ada stream berjalan. Handler ini membuat AbortController
      // BARU yang menimpa controller milik stream aktif — akibatnya tombol Stop jadi
      // mati untuk stream lama dan beberapa generasi bisa berjalan paralel
      // (jawaban tercampur di session.messages). Tombol dibiarkan ada agar bisa
      // diklik lagi setelah generasi selesai.
      if (STATE.isGenerating || STATE.isSending) {
        showToast('Masih ada respons yang sedang dihasilkan — tunggu selesai atau tekan Stop dulu.', 'info');
        return;
      }
      btn.remove();
      const bubbleText = assistantRow.querySelector('.msg-text-content');
      let continuePrompt = "Lanjutkan penjelasan/kode secara persis mulai dari kata/kalimat terakhir yang terpotong. JANGAN mengulang teks dari awal, langsung teruskan kelanjutannya.";
      const parsedPrev = splitReasoningAndContent(previousText);
      if (parsedPrev.reasoning && !parsedPrev.content) {
        continuePrompt = "Lanjutkan dengan memberikan jawaban final secara langsung dan lengkap berdasarkan proses pemikiran yang telah Anda rumuskan di atas. Langsung berikan jawaban tanpa mengulang proses pemikiran.";
      }

      bubbleText.innerHTML = renderMarkdown(previousText) + '<span class="typing-cursor"></span>';
      setGeneratingState(true);
      STATE.abortController = new AbortController();

      try {
        let appendedText = '';
        const ep = normalizeEndpoint(STATE.settings.ollamaEndpoint);
        const hasCustomExternalEndpoint = Boolean(STATE.settings.ollamaApiKey && !ep.includes('ollama.com') && !ep.includes('127.0.0.1') && !ep.includes('localhost'));
        if (engine === 'openrouter' || !hasCustomExternalEndpoint) {
          appendedText = await streamContinuationOpenRouter(session, modelName, continuePrompt, bubbleText, previousText);
        } else {
          try {
            appendedText = await streamContinuationOllama(session, modelName, continuePrompt, bubbleText, previousText);
          } catch (ollamaContErr) {
            console.warn('[streamContinuation] Ollama gagal, failover otomatis ke OpenRouter Cloud:', ollamaContErr?.message);
            appendedText = await streamContinuationOpenRouter(session, modelName, continuePrompt, bubbleText, previousText);
          }
        }

        const needsNewline = previousText.endsWith('\n') || /[\.\!\?\:\;]\s*$/.test(previousText) || /```\w*$/.test(previousText);
        const needsSpace = !needsNewline && !previousText.endsWith(' ') && !appendedText.startsWith(' ') && !appendedText.startsWith('\n');
        const separator = needsNewline ? '\n' : (needsSpace ? ' ' : '');
        const merged = safeAssistantText((safeAssistantText(previousText) + separator + appendedText).trim());
        bubbleText.innerHTML = renderMarkdown(merged);
        enhanceCodeBlocks(bubbleText);
        
        let targetMsg = null;
        if (Array.isArray(session.messages)) {
          for (let i = session.messages.length - 1; i >= 0; i--) {
            const msg = session.messages[i];
            const msgContent = (msg && typeof msg.content === 'string') ? msg.content : '';
            if (msg && msg.role === 'assistant' && (msgContent === previousText || msgContent.startsWith(previousText.substring(0, 50)))) {
              targetMsg = msg;
              break;
            }
          }
        }
        if (targetMsg) {
          targetMsg.content = safeAssistantText(merged);
        } else {
          const lastMsg = (session.messages && session.messages.length > 0) ? session.messages[session.messages.length - 1] : null;
          if (lastMsg && lastMsg.role === 'assistant') {
            lastMsg.content = safeAssistantText(merged);
          }
        }
        assistantRow.dataset.fullContent = safeAssistantText(merged);
        session.updatedAt = new Date().toISOString();
        savePersistedState();
        renderChatHistory(els.searchHistoryInput?.value || '');

        if (isOutputTruncated(merged)) {
          attachContinuationButton(container, session, assistantRow, modelName, engine, merged);
        }
      } catch (err) {
        showToast('Gagal melanjutkan output: ' + err.message, 'error');
      } finally {
        setGeneratingState(false);
      }
    });

    container.appendChild(btn);
  }

  async function streamContinuationOpenRouter(session, modelName, promptInstruction, bubbleText, currentFullText) {
    const effectiveModel = (modelName && modelName.includes('/'))
      ? modelName
      : (mapOllamaModelToOpenRouter(modelName) || 'openrouter/free');

    const candidateModels = [
      effectiveModel,
      ...LIVE_FREE_OPENROUTER_FALLBACKS
    ].filter(Boolean).filter((m, idx, arr) => arr.indexOf(m) === idx && !DEACTIVATED_OR_BROKEN_OPENROUTER_MODELS.has(m));

    const tryDirectFirst = IS_GITHUB_PAGES;
    const routesToTry = tryDirectFirst ? ['direct', 'proxy'] : ['proxy', 'direct'];

    let res = null;
    let lastErrDetail = '';

    for (let c = 0; c < candidateModels.length; c++) {
      const curModel = candidateModels[c];
      const supportsSystem = doesModelSupportSystemRole(curModel);
      const messagesPayload = [];
      if (STATE.settings.systemPrompt && supportsSystem) {
        messagesPayload.push({ role: 'system', content: STATE.settings.systemPrompt });
      }
      session.messages.forEach(m => messagesPayload.push({
        role: m.role,
        content: m.role === 'assistant' ? safeAssistantText(m.content || '') : (m.content || '')
      }));
      const userInstruction = (!supportsSystem && STATE.settings.systemPrompt)
        ? `[Instruksi Sistem: ${STATE.settings.systemPrompt}]\n\n${promptInstruction}`
        : promptInstruction;
      messagesPayload.push({ role: 'user', content: userInstruction });

      const isLiquid = Boolean(curModel && (curModel.includes('liquid') || curModel.includes('lfm-')));
      const isReasoning = Boolean(curModel && (curModel.includes('/o1') || curModel.includes('/o3')));

      const basePayload = {
        model: curModel,
        messages: messagesPayload,
        stream: true,
        provider: { allow_fallbacks: true }
      };
      if (!isReasoning) {
        basePayload.temperature = parseFloat(STATE.settings.temperature) || 0.7;
      }
      if (!isLiquid && !isReasoning) {
        basePayload.top_p = parseFloat(STATE.settings.topP) || 0.9;
      }

      for (const routeType of routesToTry) {
        if (STATE.abortController?.signal?.aborted) break;
        const isDirect = routeType === 'direct';
        const endpoint = isDirect ? 'https://openrouter.ai/api/v1/chat/completions' : '/api/openrouter/chat';
        const headers = { 'Content-Type': 'application/json' };
        if (STATE.settings.openRouterKey) {
          headers['Authorization'] = `Bearer ${STATE.settings.openRouterKey}`;
        }
        if (isDirect) {
          headers['HTTP-Referer'] = location.origin || 'https://zozi0999.github.io/zoz_router';
          headers['X-Title'] = 'ZOZ Router Continuation';
        }

        const body = {
          ...basePayload,
          ...(isDirect ? {} : {
            sessionId: session?.id || null,
            userId: STATE.userId || null,
            apiKey: STATE.settings.openRouterKey || undefined
          })
        };

        try {
          const attemptRes = await fetch(endpoint, {
            method: 'POST',
            headers,
            body: JSON.stringify(body),
            signal: STATE.abortController?.signal
          });
          if (routeType === 'proxy' && attemptRes.status === 404) {
            continue;
          }
          if (attemptRes.ok) {
            res = attemptRes;
            break;
          }
          let attemptErr = `HTTP ${attemptRes.status}`;
          try {
            const errJson = await attemptRes.json();
            if (errJson && errJson.error) {
              attemptErr = typeof errJson.error === 'object' ? (errJson.error.message || JSON.stringify(errJson.error)) : errJson.error;
            }
          } catch (_) {}
          lastErrDetail = attemptErr;
          if (attemptRes.status === 401 || attemptRes.status === 403 || attemptRes.status === 402) {
            break;
          }
        } catch (err) {
          if (STATE.abortController?.signal?.aborted) throw err;
          lastErrDetail = err.message || String(err);
          continue;
        }
      }

      if (res && res.ok) break;
      if (c < candidateModels.length - 1) {
        console.warn(`[streamContinuationOpenRouter] Failover dari ${curModel} ke ${candidateModels[c + 1]}:`, lastErrDetail);
      }
    }

    if (!res || !res.ok) throw new Error(lastErrDetail || 'Gagal melanjutkan streaming OpenRouter');

    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buf = '';
    let appended = '';

    // Renderer coalesced: mengganti renderMarkdown sinkron per token (O(n²)) dengan
    // StreamBufferRenderer. Teks sebelumnya di-seed ke renderer; chunk PERTAMA saja
    // yang membawa separator (identik dengan logika lama), sisanya append polos.
    const renderer = new StreamBufferRenderer(bubbleText, () => smartScrollChatToBottom(false));
    renderer.text = currentFullText;
    let seedSep = null;
    const appendContinuationChunk = (delta) => {
      if (seedSep === null) {
        const needsNl = currentFullText.endsWith('\n') || /[\.\!\?\:\;]\s*$/.test(currentFullText) || /```\w*$/.test(currentFullText);
        const needsSp = !needsNl && !currentFullText.endsWith(' ') && !delta.startsWith(' ') && !delta.startsWith('\n');
        seedSep = needsNl ? '\n' : (needsSp ? ' ' : '');
        renderer.append(seedSep + delta);
      } else {
        renderer.append(delta);
      }
    };

    // Reasoning delta tidak pernah masuk buffer/render/persist. Tetap proses
    // contentDelta pada event yang sama — beberapa provider mengirim keduanya.
    const feedContinuationDelta = (contentDelta, _reasoningDelta) => {
      if (!contentDelta) return;
      appended += contentDelta;
      appendContinuationChunk(contentDelta);
    };

    while (true) {
      const { done, value } = await reader.read();
      if (done) {
        buf += decoder.decode();
        break;
      }
      buf += decoder.decode(value, { stream: true });
      const lines = buf.split('\n');
      buf = lines.pop();

      for (const line of lines) {
        const trimmed = line.trim();
        if (!trimmed || !trimmed.startsWith('data:')) continue;
        const jsonStr = trimmed.replace(/^data:\s*/, '');
        if (jsonStr === '[DONE]') break;
        try {
          const parsed = JSON.parse(jsonStr);
          const cReasoning = parsed.choices?.[0]?.delta?.reasoning
            || parsed.choices?.[0]?.delta?.reasoning_content
            || parsed.choices?.[0]?.delta?.thought
            || '';
          feedContinuationDelta(parsed.choices?.[0]?.delta?.content, cReasoning);
        } catch (e) {}
      }
    }

    if (buf && buf.trim() && buf.trim().startsWith('data:')) {
      const jsonStr = buf.trim().replace(/^data:\s*/, '');
      if (jsonStr !== '[DONE]') {
        try {
          const parsed = JSON.parse(jsonStr);
          const cReasoning = parsed.choices?.[0]?.delta?.reasoning
            || parsed.choices?.[0]?.delta?.reasoning_content
            || parsed.choices?.[0]?.delta?.thought
            || '';
          feedContinuationDelta(parsed.choices?.[0]?.delta?.content, cReasoning);
        } catch (e) {}
      }
    }
    // render:false → batalkan timer & kembalikan teks saja. Pemanggil
    // (handler Lanjutkan) merender merged text-nya sendiri tepat setelah ini,
    // jadi render + hljs di sini hanya akan membuang-buang siklus.
    renderer.finish({ render: false });
    return appended;
  }

  async function streamContinuationOllama(session, modelName, promptInstruction, bubbleText, currentFullText) {
    const ep = normalizeEndpoint(STATE.settings.ollamaEndpoint);
    const headers = { 'Content-Type': 'application/json' };
    if (STATE.settings.ollamaApiKey) {
      headers['Authorization'] = `Bearer ${STATE.settings.ollamaApiKey}`;
      headers['x-ollama-key'] = STATE.settings.ollamaApiKey;
    }
    if (STATE.settings.openRouterKey) {
      headers['x-openrouter-key'] = STATE.settings.openRouterKey;
    }

    const messagesPayload = [];
    if (STATE.settings.systemPrompt) {
      messagesPayload.push({ role: 'system', content: STATE.settings.systemPrompt });
    }
    session.messages.forEach(m => messagesPayload.push({
      role: m.role,
      content: m.role === 'assistant' ? safeAssistantText(m.content || '') : (m.content || '')
    }));
    messagesPayload.push({ role: 'user', content: promptInstruction });

    const chatUrl = IS_GITHUB_PAGES ? resolveEndpointUrl(ep, 'api/chat') : '/api/ollama/chat';
    const res = await fetch(chatUrl, {
      method: 'POST',
      headers,
      body: JSON.stringify({
        model: modelName,
        messages: messagesPayload,
        stream: true,
        options: {
          temperature: parseFloat(STATE.settings.temperature)
        },
        endpoint: ep,
        ...(STATE.settings.ollamaApiKey ? { apiKey: STATE.settings.ollamaApiKey } : {}),
        ...(STATE.settings.openRouterKey ? { openRouterKey: STATE.settings.openRouterKey } : {})
      }),
      signal: STATE.abortController?.signal
    });

    if (!res.ok) throw new Error(`HTTP ${res.status}`);

    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buf = '';
    let appended = '';

    // Renderer coalesced: mengganti renderMarkdown sinkron per token (O(n²)) dengan
    // StreamBufferRenderer. Teks sebelumnya di-seed ke renderer; chunk PERTAMA saja
    // yang membawa separator (identik dengan logika lama), sisanya append polos.
    const renderer = new StreamBufferRenderer(bubbleText, () => smartScrollChatToBottom(false));
    renderer.text = currentFullText;
    let seedSep = null;
    const appendContinuationChunk = (delta) => {
      if (seedSep === null) {
        const needsNl = currentFullText.endsWith('\n') || /[\.\!\?\:\;]\s*$/.test(currentFullText) || /```\w*$/.test(currentFullText);
        const needsSp = !needsNl && !currentFullText.endsWith(' ') && !delta.startsWith(' ') && !delta.startsWith('\n');
        seedSep = needsNl ? '\n' : (needsSp ? ' ' : '');
        renderer.append(seedSep + delta);
      } else {
        renderer.append(delta);
      }
    };

    while (true) {
      const { done, value } = await reader.read();
      if (done) {
        buf += decoder.decode();
        break;
      }
      buf += decoder.decode(value, { stream: true });
      const lines = buf.split('\n');
      buf = lines.pop();

      for (const line of lines) {
        if (!line.trim()) continue;
        try {
          const parsed = JSON.parse(line);
          const chunk = parsed.message?.content || parsed.response || '';
          if (chunk) {
            appended += chunk;
            appendContinuationChunk(chunk);
          }
        } catch (e) {}
      }
    }

    if (buf && buf.trim()) {
      try {
        const parsed = JSON.parse(buf.trim());
        const chunk = parsed.message?.content || parsed.response || '';
        if (chunk) {
          appended += chunk;
          appendContinuationChunk(chunk);
        }
      } catch (e) {}
    }
    // render:false → batalkan timer & kembalikan teks saja. Pemanggil
    // (handler Lanjutkan) merender merged text-nya sendiri tepat setelah ini,
    // jadi render + hljs di sini hanya akan membuang-buang siklus.
    renderer.finish({ render: false });
    return appended;
  }

  // ==================== SESSIONS & CHAT MANAGEMENT ====================
  function createNewSession(initialTitle = 'Obrolan Baru', targetMode = STATE.mode) {
    if (activeChatPollTimer) {
      clearInterval(activeChatPollTimer);
      activeChatPollTimer = null;
    }
    if (STATE.isGenerating) {
      stopGeneration();
    }
    STATE.currentSessionId = null;
    safeSessionStorage.removeItem('zoz_active_session_id');
    try { localStorage.removeItem('zoz_last_active_session_id'); } catch (_) {}
    STATE.isImageGenMode = false;
    clearPhotoEdit(); // sesi baru — kartu referensi foto tidak boleh ikut pindah
    updateImageGenModeUI();
    STATE.isMusicGenMode = false;
    if (typeof updateMusicGenModeUI === 'function') updateMusicGenModeUI();
    clearResearchTargetUrls();
    STATE.attachedDocs = [];
    clearAttachedImages();
    if (els.docFileInput) els.docFileInput.value = '';
    renderAttachmentPreviews();
    renderChatHistory();
    renderCurrentSession();
    AudioEngine.click();
    if (window.innerWidth <= 768 && els.sidebar?.classList.contains('open')) {
      els.sidebar.classList.remove('open');
      els.sidebarBackdrop?.classList.remove('show');
      // M15: pop entri {modal:'sidebar'} yang dipush saat sidebar dibuka — tanpa ini
      // entri jadi yatim: tombol Back hardware ditelan, atau Back berikutnya
      // memunculkan sidebar ghost & menutup modal yang sedang terbuka.
      if (history.state?.modal === 'sidebar') history.back();
    }
  }

  function getActiveSession(targetMode = STATE.mode) {
    if (STATE.currentSessionId) {
      const found = STATE.sessions.find(s => s.id === STATE.currentSessionId);
      if (found) return found;
    }

    // Return or create active working session
    const newSession = {
      id: generateId(),
      userId: STATE.userId,
      title: 'Obrolan Baru',
      mode: targetMode,
      messages: [],
      createdAt: new Date().toISOString()
    };
    STATE.sessions.unshift(newSession);
    STATE.currentSessionId = newSession.id;
    safeSessionStorage.setItem('zoz_active_session_id', newSession.id);
    try { localStorage.setItem('zoz_last_active_session_id', newSession.id); } catch (_) {}
    savePersistedState();
    return newSession;
  }

  // Lookup sesi eksplisit tanpa sisi-efek (tidak membuat sesi baru) — dipakai alur
  // kirim yang menangkap id sesi SEBELUM await agar pesan tidak salah sasaran.
  function getSessionById(id) {
    if (!id) return null;
    return STATE.sessions.find(s => s.id === id) || null;
  }

  // M9: token per-pemanggilan — klik sesi terAKHIR yang menang, terlepas dari urutan
  // selesai await-nya (dulu "last-resolved-wins": sidebar bisa menyorot sesi A
  // padahal pengguna memilih B, dan input terasosiasi ke sesi yang salah).
  let sessionSwitchToken = 0;
  async function switchSession(sessionId) {
    if (STATE.isGenerating || STATE.isSending) {
      showToast('Harap tunggu atau hentikan generasi respons saat ini.', 'error');
      return;
    }
    const targetSession = STATE.sessions.find(s => s.id === sessionId);
    if (!targetSession) return;
    const switchToken = ++sessionSwitchToken;

    if (activeChatPollTimer) {
      clearInterval(activeChatPollTimer);
      activeChatPollTimer = null;
    }

    // Sinkronkan pesan dari disk storage jika targetSession lazy-loaded ATAU jika disk memiliki pembaruan latar belakang
    try {
      const fullSess = await DeviceStorage.getSession(sessionId);
      if (fullSess && Array.isArray(fullSess.messages)) {
        const diskLen = fullSess.messages.length;
        const memLen = targetSession.messages ? targetSession.messages.length : 0;
        const diskLast = fullSess.messages[diskLen - 1];
        const memLast = targetSession.messages ? targetSession.messages[memLen - 1] : null;

        if (targetSession._isLazyDisk || diskLen > memLen || (diskLast && memLast && diskLast.content !== memLast.content && ((diskLast.content || '').length > (memLast.content || '').length || diskLast.backgroundCompleted))) {
          targetSession.messages = fullSess.messages;
          delete targetSession._isLazyDisk;
          await ChatDB.saveSession(targetSession);
        }
      }
    } catch (e) {
      console.warn('Gagal memuat detail sesi dari storage:', e);
    }

    // M9: pengguna sudah memilih sesi LAIN selama await di atas → batalkan hasil basi ini
    if (switchToken !== sessionSwitchToken) return;

    // If session has different mode, switch tab
    if (targetSession.mode && targetSession.mode !== STATE.mode) {
      const safeMode = ['ollama', 'openrouter', 'auto'].includes(targetSession.mode) ? targetSession.mode : 'ollama';
      STATE.mode = safeMode;
      els.modeTabs.forEach(tab => {
        tab.classList.toggle('active', tab.dataset.mode === STATE.mode);
      });
      updateModeLayout(STATE.mode);
    }

    STATE.currentSessionId = sessionId;
    safeSessionStorage.setItem('zoz_active_session_id', sessionId);
    try { localStorage.setItem('zoz_last_active_session_id', sessionId); } catch (_) {}
    STATE.isImageGenMode = false;
    clearPhotoEdit(); // pindah sesi — kartu referensi foto tidak boleh ikut pindah
    updateImageGenModeUI();
    STATE.isMusicGenMode = false;
    if (typeof updateMusicGenModeUI === 'function') updateMusicGenModeUI();
    // Sinkronkan URL target riset sesuai sesi yang dituju
    if (Array.isArray(targetSession.researchTargetUrls)) {
      STATE.researchTargetUrls = [...targetSession.researchTargetUrls];
    } else {
      STATE.researchTargetUrls = [];
    }
    renderResearchUrlChips();
    STATE.attachedDocs = [];
    clearAttachedImages();
    if (els.docFileInput) els.docFileInput.value = '';
    renderAttachmentPreviews();
    savePersistedState();
    renderChatHistory();
    renderCurrentSession();
    updateModelUI();
    AudioEngine.click();

    if (window.innerWidth <= 768 && els.sidebar?.classList.contains('open')) {
      els.sidebar.classList.remove('open');
      els.sidebarBackdrop?.classList.remove('show');
      // M15: sama seperti createNewSession — buang entri history sidebar yatim.
      if (history.state?.modal === 'sidebar') history.back();
    }

    // Periksa apakah sesi tujuan memiliki tugas aktif atau selesai di background
    checkBackgroundChatTasksSync();
  }

  let activeHistoryDropdown = null;

  function closeAllHistoryDropdowns() {
    if (activeHistoryDropdown) {
      activeHistoryDropdown.remove();
      activeHistoryDropdown = null;
    }
    document.querySelectorAll('.history-item.menu-open').forEach(el => el.classList.remove('menu-open'));
  }

  // Global listeners for dropdown dismissal
  document.addEventListener('click', (e) => {
    if (!e.target.closest('.history-dropdown-menu') && !e.target.closest('.history-menu-btn')) {
      closeAllHistoryDropdowns();
    }
  });

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') closeAllHistoryDropdowns();
  });

  async function deleteSession(sessionId, e) {
    if (e) e.stopPropagation();
    const target = STATE.sessions.find(s => s.id === sessionId);
    if (!target) return;

    // H5: konfirmasi SEBELUM penghapusan permanen — dulu satu klik tak sengaja
    // (menu "Hapus" bersebelahan dengan Export/Rename) langsung menghapus sesi
    // beserta seluruh pesan dari IndexedDB tanpa undo, padahal hapus massal dan
    // hapus playlist keduanya memakai confirm().
    if (!confirm(`Hapus percakapan "${target.title || 'Obrolan Baru'}"?\n\nSeluruh pesan di dalamnya akan dihapus PERMANEN dan tidak bisa dikembalikan.`)) {
      return;
    }

    // Abort active in-flight generation if deleting the current generating session
    if (STATE.isGenerating && STATE.currentSessionId === sessionId) {
      stopGeneration();
    }

    // Hentikan tugas background chat/riset aktif di server agar tidak membangkitkan zombi sesi
    if (sessionId) {
      try {
        fetch('/api/chat/stop', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-User-ID': STATE.userId
          },
          body: JSON.stringify({ sessionId, userId: STATE.userId })
        }).catch(() => {});
      } catch (_) {}
    }

    STATE.sessions = STATE.sessions.filter(s => s.id !== sessionId);
    await DeviceStorage.deleteSession(sessionId);

    if (STATE.currentSessionId === sessionId) {
      STATE.currentSessionId = null;
      safeSessionStorage.removeItem('zoz_active_session_id');
      try { localStorage.removeItem('zoz_last_active_session_id'); } catch (_) {}
    } else {
      try {
        if (localStorage.getItem('zoz_last_active_session_id') === sessionId) {
          localStorage.removeItem('zoz_last_active_session_id');
        }
      } catch (_) {}
    }

    // Immediate: penghapusan sesi tak boleh tertunda debounce — kalau tab ditutup
    // sebelum timer 700ms, mirror lama masih menyimpan sesi yang sudah dihapus.
    savePersistedState({ immediate: true });
    renderChatHistory();
    renderCurrentSession();
    AudioEngine.click();
  }

  function renameSessionPrompt(sessionId, titleSpanElement) {
    const session = STATE.sessions.find(s => s.id === sessionId);
    if (!session || !titleSpanElement) return;

    const currentTitle = session.title || 'Obrolan Baru';
    
    // Create inline editor input
    const input = document.createElement('input');
    input.type = 'text';
    input.className = 'history-rename-input';
    input.value = currentTitle;
    
    let isSaved = false;
    const finishRename = async () => {
      if (isSaved) return;
      isSaved = true;
      const newTitle = input.value.trim() || currentTitle;
      session.title = newTitle;
      if (titleSpanElement.parentNode) {
        titleSpanElement.innerText = newTitle;
        titleSpanElement.title = newTitle;
        if (input.parentNode) input.replaceWith(titleSpanElement);
      }
      await DeviceStorage.renameSession(sessionId, newTitle);
      savePersistedState();
      showToast(`Nama percakapan diubah menjadi "${newTitle}"`);
      AudioEngine.click();
    };

    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        input.blur();
      } else if (e.key === 'Escape') {
        e.preventDefault();
        isSaved = true;
        if (input.parentNode) input.replaceWith(titleSpanElement);
      }
    });

    input.addEventListener('blur', finishRename, { once: true });
    
    titleSpanElement.replaceWith(input);
    input.focus();
    input.select();
  }

  async function exportSessionData(sessionId) {
    const session = STATE.sessions.find(s => s.id === sessionId);
    if (!session) return;
    await promptExportConfirmation(session);
  }

  function getSessionTimestamp(s) {
    if (!s) return 0;
    if (s.updatedAt) {
      const t = new Date(s.updatedAt).getTime();
      if (!isNaN(t)) return t;
    }
    if (s.messages && s.messages.length > 0) {
      let lastMsg = null;
      if (s.messages.length > 0) {
        lastMsg = s.messages[s.messages.length - 1];
      }
      if (lastMsg && lastMsg.timestamp) {
        const t = new Date(lastMsg.timestamp).getTime();
        if (!isNaN(t)) return t;
      }
    }
    if (s.createdAt) {
      const t = new Date(s.createdAt).getTime();
      if (!isNaN(t)) return t;
    }
    return 0;
  }

  async function togglePinSession(sessionId) {
    const session = STATE.sessions.find(s => s.id === sessionId);
    if (!session) return;
    session.isPinned = !session.isPinned;
    session.updatedAt = new Date().toISOString();
    
    if (session._isLazyDisk && (!session.messages || session.messages.length === 0)) {
      await DeviceStorage.updateSessionMetadata(sessionId, { isPinned: session.isPinned, updatedAt: session.updatedAt });
    } else {
      await DeviceStorage.saveSession(session);
    }
    savePersistedState();
    renderChatHistory();
    showToast(session.isPinned ? '📌 Percakapan disematkan di paling atas' : 'Percakapan dilepas dari sematan');
    AudioEngine.click();
  }

  function getSessionTimeGroup(session) {
    if (session.isPinned) return 'Pinned';
    const ts = getSessionTimestamp(session);
    if (!ts || isNaN(ts)) return '30 Hari Terakhir';
    const now = new Date();
    const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
    const startOfYesterday = startOfToday - 86400000;
    const startOf7Days = startOfToday - (6 * 86400000);
    const startOf30Days = startOfToday - (29 * 86400000);

    if (ts >= startOfToday) return 'Hari Ini';
    if (ts >= startOfYesterday) return 'Kemarin';
    if (ts >= startOf7Days) return '7 Hari Terakhir';
    if (ts >= startOf30Days) return '30 Hari Terakhir';
    return 'Lebih Lama';
  }

  function enterHistorySelectMode(initialSessionId = null) {
    STATE.historySelectMode = true;
    STATE.selectedSessionIds.clear();
    if (initialSessionId) {
      STATE.selectedSessionIds.add(initialSessionId);
    }
    updateHistorySelectUI();
    renderChatHistory(els.searchHistoryInput?.value || '');
    AudioEngine.click();
  }

  function exitHistorySelectMode() {
    STATE.historySelectMode = false;
    STATE.selectedSessionIds.clear();
    updateHistorySelectUI();
    renderChatHistory(els.searchHistoryInput?.value || '');
    AudioEngine.click();
  }

  function updateHistorySelectUI() {
    if (STATE.historySelectMode) {
      if (els.searchHistoryBox) els.searchHistoryBox.style.display = 'none';
      if (els.historySelectTopBar) els.historySelectTopBar.style.display = 'flex';
      if (els.sidebarNormalFooter) els.sidebarNormalFooter.style.display = 'none';
      if (els.historySelectBottomBar) els.historySelectBottomBar.style.display = 'flex';

      const count = STATE.selectedSessionIds.size;
      const countStr = count === 1 ? '1 chat selected' : (count === 0 ? 'Pilih percakapan' : `${count} chats selected`);
      if (els.historySelectCountText) els.historySelectCountText.innerText = countStr;

      const selectedSessions = STATE.sessions.filter(s => STATE.selectedSessionIds.has(s.id));
      const allPinned = selectedSessions.length > 0 && selectedSessions.every(s => s.isPinned);
      if (els.pinSelectedText) {
        els.pinSelectedText.innerText = allPinned ? 'Unpin' : 'Pin';
      }
      if (els.btnPinSelectedHistory) {
        const pinIcon = els.btnPinSelectedHistory.querySelector('i');
        if (pinIcon) pinIcon.style.transform = allPinned ? 'rotate(45deg)' : 'none';
      }
    } else {
      if (els.searchHistoryBox) els.searchHistoryBox.style.display = '';
      if (els.historySelectTopBar) els.historySelectTopBar.style.display = 'none';
      if (els.sidebarNormalFooter) els.sidebarNormalFooter.style.display = '';
      if (els.historySelectBottomBar) els.historySelectBottomBar.style.display = 'none';
    }
  }

  function toggleSessionSelection(sessionId) {
    if (STATE.selectedSessionIds.has(sessionId)) {
      STATE.selectedSessionIds.delete(sessionId);
    } else {
      STATE.selectedSessionIds.add(sessionId);
    }
    updateHistorySelectUI();
    const item = els.chatHistoryList?.querySelector(`.history-item[data-id="${sessionId}"]`);
    if (item) {
      const isSelected = STATE.selectedSessionIds.has(sessionId);
      item.classList.toggle('is-selected', isSelected);
      const circle = item.querySelector('.history-select-circle');
      if (circle) {
        circle.className = `history-select-circle ${isSelected ? 'selected' : ''}`;
        circle.innerHTML = `<i class="${isSelected ? 'fa-solid fa-circle-check' : 'fa-regular fa-circle'}"></i>`;
      }
    }
    AudioEngine.click();
  }

  function toggleSelectAllHistory() {
    const q = els.searchHistoryInput?.value?.toLowerCase()?.trim() || '';
    const validSessions = STATE.sessions.filter(s => {
      const hasMsg = s._isLazyDisk 
        ? ((typeof s.messageCount === 'number' && s.messageCount > 0) || (Array.isArray(s.messages) && s.messages.length > 0))
        : (Array.isArray(s.messages) && s.messages.length > 0);
      if (!hasMsg) return false;
      return !q || (s.title || '').toLowerCase().includes(q) || (s.mode && s.mode.toLowerCase().includes(q));
    });

    const allSelected = validSessions.length > 0 && validSessions.every(s => STATE.selectedSessionIds.has(s.id));
    if (allSelected) {
      STATE.selectedSessionIds.clear();
    } else {
      validSessions.forEach(s => STATE.selectedSessionIds.add(s.id));
    }
    updateHistorySelectUI();
    renderChatHistory(q);
    AudioEngine.click();
  }

  async function pinOrUnpinSelectedHistory() {
    if (STATE.selectedSessionIds.size === 0) {
      showToast('Pilih percakapan yang ingin di-pin / unpin terlebih dahulu');
      return;
    }
    const selectedSessions = STATE.sessions.filter(s => STATE.selectedSessionIds.has(s.id));
    const allPinned = selectedSessions.every(s => s.isPinned);
    const targetPin = !allPinned;

    for (const session of selectedSessions) {
      session.isPinned = targetPin;
      session.updatedAt = new Date().toISOString();
      if (session._isLazyDisk && (!session.messages || session.messages.length === 0)) {
        await DeviceStorage.updateSessionMetadata(session.id, { isPinned: session.isPinned, updatedAt: session.updatedAt });
      } else {
        await DeviceStorage.saveSession(session);
      }
    }

    savePersistedState();
    exitHistorySelectMode();
    showToast(targetPin ? `📌 ${selectedSessions.length} percakapan disematkan ke atas` : `${selectedSessions.length} percakapan dilepas dari sematan`, 'success');
    AudioEngine.click();
  }

  async function deleteSelectedHistory() {
    if (STATE.selectedSessionIds.size === 0) {
      showToast('Pilih percakapan yang ingin dihapus terlebih dahulu');
      return;
    }
    const count = STATE.selectedSessionIds.size;
    if (!confirm(`Hapus ${count} percakapan yang dipilih secara permanen?\n\nSeluruh pesan di dalamnya akan dihapus dan tidak bisa dikembalikan.`)) {
      return;
    }

    const idsToDelete = Array.from(STATE.selectedSessionIds);
    let activeDeleted = false;

    for (const sessionId of idsToDelete) {
      if (STATE.isGenerating && STATE.currentSessionId === sessionId) {
        stopGeneration();
      }
      if (STATE.currentSessionId === sessionId) {
        activeDeleted = true;
      }
      const idx = STATE.sessions.findIndex(s => s.id === sessionId);
      if (idx !== -1) {
        STATE.sessions.splice(idx, 1);
      }
      await DeviceStorage.deleteSession(sessionId);
    }

    if (activeDeleted) {
      if (STATE.sessions.length > 0) {
        STATE.currentSessionId = STATE.sessions[0].id;
        safeSessionStorage.setItem('zoz_active_session_id', STATE.currentSessionId);
        try { localStorage.setItem('zoz_last_active_session_id', STATE.currentSessionId); } catch (_) {}
      } else {
        createNewSession();
      }
    }

    savePersistedState({ immediate: true });
    exitHistorySelectMode();
    if (activeDeleted && STATE.currentSessionId) {
      switchSession(STATE.currentSessionId);
    }
    showToast(`🗑️ ${count} percakapan berhasil dihapus`, 'success');
    AudioEngine.click();
  }

  function renderChatHistory(filterQuery = '') {
    if (!els.chatHistoryList) return;
    els.chatHistoryList.innerHTML = '';
    const q = filterQuery.toLowerCase().trim();
    
    // Unified list of all sessions across engines (including lazy-loaded disk sessions)
    const validSessions = STATE.sessions.filter(s => {
      if (s._isLazyDisk) {
        return (typeof s.messageCount === 'number' && s.messageCount > 0) || (Array.isArray(s.messages) && s.messages.length > 0);
      }
      return Array.isArray(s.messages) && s.messages.length > 0;
    });
    const filtered = validSessions.filter(s => !q || (s.title || '').toLowerCase().includes(q) || (s.mode && s.mode.toLowerCase().includes(q)));

    // Sort strictly: Pinned sessions first, then most recently active descending
    filtered.sort((a, b) => {
      const aPinned = !!a.isPinned;
      const bPinned = !!b.isPinned;
      if (aPinned && !bPinned) return -1;
      if (!aPinned && bPinned) return 1;
      return getSessionTimestamp(b) - getSessionTimestamp(a);
    });

    // Update history header label
    const historyHeader = $('.history-label');
    if (historyHeader) {
      historyHeader.innerText = 'RIWAYAT PERCAKAPAN';
    }

    if (filtered.length === 0) {
      if (q) {
        els.chatHistoryList.innerHTML = `
          <div style="font-size:0.75rem; color:var(--text-dim); text-align:center; padding:18px 8px; line-height:1.4;">
            <i class="fa-solid fa-magnifying-glass" style="font-size:1.1rem; opacity:0.4; margin-bottom:6px; display:block;"></i>
            Tidak ada percakapan yang cocok dengan "<span style="color:var(--text-main); font-weight:600;">${escapeHtml(filterQuery)}</span>"
          </div>`;
      } else {
        els.chatHistoryList.innerHTML = `<div style="font-size:0.75rem; color:var(--text-dim); text-align:center; padding:16px 8px;">Belum ada riwayat percakapan<br><span style="font-size:0.68rem; opacity:0.7;">Ketik prompt di bawah untuk memulai.</span></div>`;
      }
      return;
    }

    // Grouping by time categories (DeepSeek style: Pinned, Hari Ini, Kemarin, 7 Hari Terakhir, etc.)
    const groups = {};
    const groupOrder = ['Pinned', 'Hari Ini', 'Kemarin', '7 Hari Terakhir', '30 Hari Terakhir', 'Lebih Lama'];
    groupOrder.forEach(g => { groups[g] = []; });

    filtered.forEach(session => {
      const g = getSessionTimeGroup(session);
      if (!groups[g]) groups[g] = [];
      groups[g].push(session);
    });

    groupOrder.forEach(groupName => {
      const groupSessions = groups[groupName];
      if (!groupSessions || groupSessions.length === 0) return;

      const groupHeader = document.createElement('div');
      groupHeader.className = 'history-group-title';
      groupHeader.innerText = groupName;
      els.chatHistoryList.appendChild(groupHeader);

      groupSessions.forEach(session => {
        const item = document.createElement('div');
        const inSelect = STATE.historySelectMode;
        const isSelected = STATE.selectedSessionIds.has(session.id);

        item.className = `history-item ${session.id === STATE.currentSessionId ? 'active' : ''} ${session.isPinned ? 'is-pinned' : ''} ${inSelect ? 'in-select-mode' : ''} ${isSelected ? 'is-selected' : ''}`;
        item.dataset.id = session.id;
        item.tabIndex = 0;
        
        let modeIcon = 'fa-server';
        let modeColor = 'var(--neon-cyan)';
        let modeTag = 'Ollama';
        if (session.mode === 'openrouter') {
          modeIcon = 'fa-bolt';
          modeColor = 'var(--neon-amber)';
          modeTag = 'OpenRouter';
        } else if (session.mode === 'auto') {
          modeIcon = 'fa-route';
          modeColor = 'var(--neon-teal)';
          modeTag = 'Auto';
        }

        const selectCircleHtml = inSelect ? `
          <div class="history-select-circle ${isSelected ? 'selected' : ''}" title="${isSelected ? 'Batal Pilih' : 'Pilih'}">
            <i class="${isSelected ? 'fa-solid fa-circle-check' : 'fa-regular fa-circle'}"></i>
          </div>
        ` : '';

        item.innerHTML = `
          ${selectCircleHtml}
          <div class="history-title-wrap">
            ${session.isPinned ? '<i class="fa-solid fa-thumbtack history-pin-icon" title="Disematkan di Atas"></i>' : ''}
            <i class="fa-solid ${modeIcon}" style="color:${modeColor}; font-size:0.8rem;" title="Engine: ${modeTag}"></i>
            <span class="history-title" title="${escapeHtml(session.title)}">${escapeHtml(session.title)}</span>
          </div>
          ${!inSelect ? `
            <div class="history-item-actions">
              <button class="history-menu-btn" title="Opsi Percakapan (Sematkan / Ganti Nama / Hapus)" aria-label="Opsi Percakapan">
                <i class="fa-solid fa-ellipsis-vertical"></i>
              </button>
            </div>
          ` : ''}
        `;

        if (inSelect) {
          item.addEventListener('click', () => {
            toggleSessionSelection(session.id);
          });
          els.chatHistoryList.appendChild(item);
          return;
        }

        const titleSpan = item.querySelector('.history-title');
        const menuBtn = item.querySelector('.history-menu-btn');

        // Double-click on title to rename
        titleSpan.addEventListener('dblclick', (e) => {
          e.stopPropagation();
          renameSessionPrompt(session.id, titleSpan);
        });

        // Switch session on item click
        item.addEventListener('click', (e) => {
          if (e.target.closest('.history-menu-btn') || e.target.closest('.history-dropdown-menu') || e.target.closest('.history-rename-input')) {
            return;
          }
          closeAllHistoryDropdowns();
          switchSession(session.id);
        });

        // 3-Dots Menu Click Trigger
        menuBtn.addEventListener('click', (e) => {
          e.stopPropagation();
          const isOpen = item.classList.contains('menu-open');
          closeAllHistoryDropdowns();

          if (isOpen) return;

          item.classList.add('menu-open');
          const dropdown = document.createElement('div');
          dropdown.className = 'history-dropdown-menu';
          dropdown.innerHTML = `
            <button class="history-dropdown-item select-opt">
              <i class="fa-solid fa-list-check"></i>
              <span>Pilih Percakapan</span>
            </button>
            <button class="history-dropdown-item pin-opt">
              <i class="fa-solid fa-thumbtack" style="${session.isPinned ? 'color:var(--neon-cyan); transform:rotate(45deg);' : ''}"></i>
              <span>${session.isPinned ? 'Lepas Sematan' : 'Sematkan di Atas'}</span>
            </button>
            <button class="history-dropdown-item rename-opt">
              <i class="fa-solid fa-pen-to-square"></i>
              <span>Ganti Nama</span>
            </button>
            <button class="history-dropdown-item export-opt">
              <i class="fa-solid fa-file-arrow-down"></i>
              <span>Unduh Chat (.md)</span>
            </button>
            <button class="history-dropdown-item delete-item delete-opt">
              <i class="fa-solid fa-trash-can"></i>
              <span>Hapus Percakapan</span>
            </button>
          `;

          dropdown.querySelector('.select-opt').addEventListener('click', (ev) => {
            ev.stopPropagation();
            closeAllHistoryDropdowns();
            enterHistorySelectMode(session.id);
          });

          dropdown.querySelector('.pin-opt').addEventListener('click', (ev) => {
            ev.stopPropagation();
            closeAllHistoryDropdowns();
            togglePinSession(session.id);
          });

          dropdown.querySelector('.rename-opt').addEventListener('click', (ev) => {
            ev.stopPropagation();
            closeAllHistoryDropdowns();
            renameSessionPrompt(session.id, titleSpan);
          });

          dropdown.querySelector('.export-opt').addEventListener('click', (ev) => {
            ev.stopPropagation();
            closeAllHistoryDropdowns();
            exportSessionData(session.id);
          });

          dropdown.querySelector('.delete-opt').addEventListener('click', (ev) => {
            ev.stopPropagation();
            closeAllHistoryDropdowns();
            deleteSession(session.id);
          });

          document.body.appendChild(dropdown);
          const anchor = e.currentTarget.getBoundingClientRect();
          dropdown.style.position = 'fixed';
          dropdown.style.zIndex = '1200';
          dropdown.style.right = '0px';
          dropdown.style.top = '0px';
          const menuW = dropdown.offsetWidth;
          const menuH = dropdown.offsetHeight;
          let menuTop = anchor.bottom + 4;
          if (menuTop + menuH > window.innerHeight - 8) {
            menuTop = Math.max(8, anchor.top - menuH - 4);
          }
          let menuRight = Math.max(8, window.innerWidth - anchor.right);
          if (menuRight + menuW > window.innerWidth - 8) {
            menuRight = Math.max(8, window.innerWidth - menuW - 8);
          }
          dropdown.style.top = menuTop + 'px';
          dropdown.style.right = menuRight + 'px';
          activeHistoryDropdown = dropdown;
          AudioEngine.click();
        });

        els.chatHistoryList.appendChild(item);
      });
    });
  }

  function renderCurrentSession(forceScroll = true) {
    const prevScrollTop = els.chatViewport ? els.chatViewport.scrollTop : 0;
    const wasScrolledUp = userScrolledUp;

    // If no session is actively selected -> Land on TAMPILAN UTAMA (Welcome Hero)!
    if (!STATE.currentSessionId) {
      if (els.welcomeHero) els.welcomeHero.style.display = 'flex';
      if (els.messagesList) els.messagesList.innerHTML = '';
      if (els.pullUpNewChatWrapper) {
        els.pullUpNewChatWrapper.classList.remove('visible');
        els.pullUpNewChatWrapper.style.display = 'none';
      }
      smartScrollChatToBottom(forceScroll);
      return;
    }

    const session = STATE.sessions.find(s => s.id === STATE.currentSessionId);
    if (!session) {
      if (els.welcomeHero) els.welcomeHero.style.display = 'flex';
      if (els.messagesList) els.messagesList.innerHTML = '';
      if (els.pullUpNewChatWrapper) {
        els.pullUpNewChatWrapper.classList.remove('visible');
        els.pullUpNewChatWrapper.style.display = 'none';
      }
      smartScrollChatToBottom(forceScroll);
      return;
    }

    // Tangani sesi lazy-disk secara mulus tanpa membuat Welcome Hero berkedip (flicker)
    if (session._isLazyDisk && (!session.messages || session.messages.length === 0)) {
      if (els.welcomeHero) els.welcomeHero.style.display = 'none';
      if (els.pullUpNewChatWrapper) {
        els.pullUpNewChatWrapper.classList.remove('visible');
        els.pullUpNewChatWrapper.style.display = 'none';
      }
      if (els.messagesList) {
        els.messagesList.innerHTML = `
          <div style="display:flex; flex-direction:column; align-items:center; justify-content:center; padding:60px 20px; color:var(--text-dim); gap:12px;">
            <i class="fa-solid fa-circle-notch fa-spin" style="font-size:1.8rem; color:var(--neon-cyan);"></i>
            <span style="font-size:0.85rem; font-weight:500;">Memuat pesan percakapan...</span>
          </div>
        `;
      }
      if (!session._isHydrating) {
        session._isHydrating = true;
        DeviceStorage.getSession(session.id).then(full => {
          session._isHydrating = false;
          if (full && Array.isArray(full.messages)) {
            session.messages = full.messages;
            delete session._isLazyDisk;
            ChatDB.saveSession(session);
            if (STATE.currentSessionId === session.id) {
              renderCurrentSession(forceScroll);
            }
          }
        }).catch(err => {
          session._isHydrating = false;
          console.warn('Notice hydrating session:', err);
        });
      }
      smartScrollChatToBottom(forceScroll);
      return;
    }

    if (!session.messages || session.messages.length === 0) {
      if (els.welcomeHero) els.welcomeHero.style.display = 'flex';
      if (els.messagesList) els.messagesList.innerHTML = '';
      if (els.pullUpNewChatWrapper) {
        els.pullUpNewChatWrapper.classList.remove('visible');
        els.pullUpNewChatWrapper.style.display = 'none';
      }
      smartScrollChatToBottom(forceScroll);
      return;
    }

    if (els.welcomeHero) els.welcomeHero.style.display = 'none';
    if (els.messagesList) els.messagesList.innerHTML = '';
    if (els.pullUpNewChatWrapper) {
      els.pullUpNewChatWrapper.classList.remove('visible');
      els.pullUpNewChatWrapper.style.display = 'none';
    }
    session.messages.forEach((msg, idx) => {
      if (msg.type === 'image_generation' || msg.isImageGen) {
        renderSavedImageMessage(msg, idx);
        return;
      }
      let textToDisplay = (msg.role === 'user' && typeof msg.displayContent === 'string') ? msg.displayContent : (msg.content || '');
      const imagesToDisplay = msg.images || (msg.image ? [msg.image] : null);
      if (imagesToDisplay && imagesToDisplay.length > 0 && /^📷 \[\d+ Foto Lampiran\]$/.test(textToDisplay.trim())) {
        textToDisplay = '';
      }
      if (msg.role === 'user' && msg.docs && Array.isArray(msg.docs) && msg.docs.length > 0) {
        if (/^\[File:\s*[^\]]+\]$/i.test(textToDisplay.trim())) {
          textToDisplay = '';
        } else if (/\[File:\s*[^\]]+\]/i.test(textToDisplay)) {
          textToDisplay = textToDisplay.replace(/\s*\[File:\s*[^\]]+\]/gi, '').trim();
        }
      }
      appendMessageElement(msg.role, textToDisplay, imagesToDisplay, msg.model, msg.stats, idx, msg.sources, msg.docs, msg.isDeepResearch, msg.latency, msg.timestamp || session.updatedAt || session.createdAt, msg);
    });

    enhanceCodeBlocks(els.messagesList);
    if (!forceScroll && wasScrolledUp && els.chatViewport) {
      userScrolledUp = true;
      els.chatViewport.scrollTop = prevScrollTop;
    } else {
      smartScrollChatToBottom(forceScroll);
    }
  }

  function createGeneratedImageCardHtml(item) {
    const imgUrl = item.url || item.imageUrl || item.localUrl || '';
    const prompt = item.prompt || '';
    const model = item.model || 'Flux.1 Schnell';
    const duration = item.duration || item.stats?.duration || '3.5';
    const width = item.width || 1024;
    const height = item.height || 1024;
    const seed = item.seed || '';

    return `
      <div class="image-result-card" data-prompt="${escapeHtml(prompt)}" data-img-url="${escapeHtml(imgUrl)}" data-model="${escapeHtml(model)}" tabindex="0">
        <div class="image-result-display-wrap" title="Klik untuk membuka layar penuh (Lightbox)">
          <img src="${escapeHtml(imgUrl)}" alt="${escapeHtml(prompt)}" class="image-result-img chat-zoomable-img" loading="lazy" decoding="async">
          <div class="image-result-overlay">
            <button class="image-action-btn btn-open-lightbox" title="Buka Layar Penuh">
              <i class="fa-solid fa-expand"></i>
            </button>
            <button class="image-action-btn btn-download-img" title="Unduh HD PNG">
              <i class="fa-solid fa-download"></i>
            </button>
          </div>
        </div>
        <div class="image-result-footer">
          <div class="image-meta-badges">
            <span class="image-meta-badge model-badge"><i class="fa-solid fa-wand-magic-sparkles"></i> ${escapeHtml(model)}</span>
            <span class="image-meta-badge"><i class="fa-solid fa-vector-square"></i> ${width}×${height}</span>
            <span class="image-meta-badge latency-badge"><i class="fa-solid fa-bolt"></i> ${duration}s</span>
            ${seed ? `<span class="image-meta-badge"><i class="fa-solid fa-hashtag"></i> ${seed}</span>` : ''}
          </div>
          <div class="image-gen-prompt-quote" title="${escapeHtml(prompt)}">
            "${escapeHtml(prompt)}"
          </div>
          <div class="image-actions-bar">
            <button class="btn btn-xs btn-primary btn-image-action btn-regen-img">
              <i class="fa-solid fa-rotate-right"></i> Buat Variasi Baru
            </button>
            <button class="btn btn-xs btn-outline btn-image-action btn-copy-prompt">
              <i class="fa-solid fa-copy"></i> Salin Prompt
            </button>
            <button class="btn btn-xs btn-outline btn-image-action btn-download-direct">
              <i class="fa-solid fa-download"></i> Unduh Gambar
            </button>
          </div>
        </div>
      </div>
    `;
  }

  async function triggerImageDownload(url, promptText) {
    showToast('Mengunduh gambar HD...', 'info');
    const cleanName = (promptText || 'ai_image').toLowerCase().replace(/[^a-z0-9]+/g, '_').substring(0, 30);
    const fileName = `zoz_${cleanName}_${Date.now()}.png`;
    try {
      if (url.startsWith('data:')) {
        const a = document.createElement('a');
        a.href = url;
        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        setTimeout(() => a.remove(), 500);
        return;
      }
      const resp = await fetch(url, { mode: 'cors' });
      const blob = await resp.blob();
      const blobUrl = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = blobUrl;
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      setTimeout(() => {
        a.remove();
        URL.revokeObjectURL(blobUrl);
      }, 3000);
    } catch (err) {
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName;
      a.target = '_blank';
      document.body.appendChild(a);
      a.click();
      setTimeout(() => a.remove(), 500);
    }
  }

  function attachImageCardListeners(row, promptText, imageUrl, cardModel = null, refImage = null) {
    const card = row.querySelector('.image-result-card');
    if (!card) return;

    // Lightbox on image click or fullscreen button
    const imgWrap = card.querySelector('.image-result-display-wrap');
    const openLbBtn = card.querySelector('.btn-open-lightbox');
    const triggerLightbox = (e) => {
      e.stopPropagation();
      ImageLightbox.open([imageUrl], 0);
    };
    imgWrap?.addEventListener('click', triggerLightbox);
    openLbBtn?.addEventListener('click', triggerLightbox);

    // Download HD Image
    const dlBtns = card.querySelectorAll('.btn-download-img, .btn-download-direct');
    dlBtns.forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        triggerImageDownload(imageUrl, promptText);
      });
    });

    // Copy Prompt
    const copyBtns = [card.querySelector('.btn-copy-prompt'), row.querySelector('.copy-prompt-btn')].filter(Boolean);
    copyBtns.forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        copyTextToClipboard(promptText || '');
        showToast('Prompt gambar berhasil disalin!', 'success');
      });
    });

    // Regenerate variation (mempertahankan foto referensi Img2Img bila ada)
    const regenBtn = card.querySelector('.btn-regen-img');
    regenBtn?.addEventListener('click', (e) => {
      e.stopPropagation();
      const currentSession = getActiveSession();
      if (currentSession) {
        const effectiveRefImage = refImage || (STATE.photoEditImage || null);
        runImageGeneration(currentSession, promptText, cardModel || STATE.settings.imageModel, effectiveRefImage);
      }
    });
  }

  function renderSavedImageMessage(msg, idx = -1) {
    const row = document.createElement('div');
    row.className = 'message-row assistant';
    row.dataset.index = idx;

    const avatarIcon = '<i class="fa-solid fa-microchip-ai"></i>';
    const cardHtml = createGeneratedImageCardHtml(msg);

    row.innerHTML = `
      <div class="message-avatar">${avatarIcon}</div>
      <div class="message-content-box">
        <div class="message-meta">
          <strong>AI Image Studio</strong>
          <span class="meta-model-badge">${escapeHtml(msg.model || 'Flux.1')}</span>
          ${msg.stats?.duration ? `<span>⏱️ ${msg.stats.duration}s</span>` : ''}
        </div>
        <div class="message-bubble" style="background:transparent; border:none; padding:0;">
          ${cardHtml}
        </div>
        <div class="message-actions-bar">
          <button class="msg-action-btn copy-prompt-btn" title="Salin Prompt"><i class="fa-solid fa-copy"></i> Salin Prompt</button>
        </div>
      </div>
    `;

    attachImageCardListeners(row, msg.prompt, msg.imageUrl || msg.url, msg.model, msg.referenceImage || null);
    els.messagesList.appendChild(row);
  }

  function appendMessageElement(role, content, image = null, model = '', stats = null, index = -1, sources = null, docs = null, isDeepResearch = false, latency = null, timestamp = null, extraMeta = null) {
    const row = document.createElement('div');
    row.className = `message-row ${role}`;
    row.dataset.index = index;
    const currentSess = STATE.sessions.find(s => s.id === STATE.currentSessionId);
    const resolvedTimestamp = timestamp || (typeof index === 'number' && index >= 0 && currentSess?.messages?.[index]?.timestamp) || currentSess?.updatedAt || currentSess?.createdAt || null;
    if (resolvedTimestamp) {
      row.dataset.reportDate = resolvedTimestamp;
    }
    if (content) {
      row.dataset.fullContent = role === 'assistant' ? safeAssistantText(content) : content;
    }

    const avatarIcon = role === 'user' ? '<i class="fa-solid fa-user-ninja"></i>' : '<i class="fa-solid fa-microchip-ai"></i>';
    const roleLabel = role === 'user' ? 'Anda' : 'Zoz AI';

    const imgList = Array.isArray(image) ? image.filter(Boolean) : (image ? [image] : []);
    let imageGalleryHtml = '';
    if (imgList.length > 0) {
      const gridClass = imgList.length === 1 ? 'grid-1' : (imgList.length === 2 ? 'grid-2' : 'grid-multi');
      imageGalleryHtml = `
        <div class="attached-images-gallery ${gridClass}">
          ${imgList.map((src, imgIdx) => `
            <div class="chat-img-thumb-wrap" data-img-idx="${imgIdx}" title="Klik untuk melihat foto layar penuh" tabindex="0">
              <img src="${escapeHtml(src)}" alt="Foto ${imgIdx + 1}" class="chat-zoomable-img" loading="lazy" decoding="async">
              <div class="chat-img-overlay">
                <i class="fa-solid fa-expand"></i>
              </div>
            </div>
          `).join('')}
        </div>
      `;
    }

    let docsHtml = '';
    if (docs && Array.isArray(docs) && docs.length > 0 && role === 'user') {
      docsHtml = `
        <div class="attached-docs-badge-row">
          ${docs.map(d => {
            const isWebDoc = Boolean(d.isWeb || (d.name && d.name.startsWith('[Web:')) || d.url);
            let targetUrl = d.url;
            if (!targetUrl && isWebDoc && typeof d.content === 'string') {
              const urlMatch = d.content.match(/Sumber URL:\s*(https?:\/\/[^\s\n]+)/i);
              if (urlMatch) targetUrl = urlMatch[1];
            }
            const iconClass = isWebDoc ? 'fa-solid fa-globe' : 'fa-solid fa-file-lines';
            const iconColor = isWebDoc ? 'color: var(--neon-cyan);' : '';
            if (isWebDoc && targetUrl) {
              return `
                <a href="${escapeHtml(targetUrl)}" target="_blank" rel="noopener noreferrer" class="msg-doc-badge msg-doc-web-link" title="Buka tautan website: ${escapeHtml(targetUrl)}">
                  <i class="${iconClass}" style="${iconColor}"></i>
                  <span class="msg-doc-name" title="${escapeHtml(d.name)}">${escapeHtml(d.name)}</span>
                  <span class="msg-doc-size">${escapeHtml(d.size || '')}</span>
                  <i class="fa-solid fa-arrow-up-right-from-square" style="font-size:0.65rem; opacity:0.75; margin-left:2px;"></i>
                </a>
              `;
            }
            return `
              <div class="msg-doc-badge" data-doc-name="${escapeHtml(d.name || '')}" title="Klik untuk membuka & membaca file lampiran">
                <i class="${iconClass}" style="${iconColor}"></i>
                <span class="msg-doc-name" title="${escapeHtml(d.name)}">${escapeHtml(d.name)}</span>
                <span class="msg-doc-size">${escapeHtml(d.size || '')}</span>
              </div>
            `;
          }).join('')}
        </div>
      `;
    }

    const isActuallyDeepResearch = Boolean(
      isDeepResearch ||
      (role === 'assistant' && typeof content === 'string' && (
        /#\s*(?:📑|🔬)?\s*(?:laporan\s*)?deep\s*research/i.test(content) ||
        content.includes('Lead Auditor & Corrector') ||
        (content.includes('DEEP RESEARCH') && /##\s*1\.\s*.*(?:rangkuman|pendahuluan|ringkasan|komprehensif)/i.test(content)) ||
        /##\s*1\.\s*.*(?:pendahuluan\s*&\s*ringkasan\s*komprehensif|ringkasan\s*eksekutif)/i.test(content)
      ))
    );

    let statsHtml = '';
    if (isActuallyDeepResearch && role === 'assistant') {
      statsHtml = `
        <span class="meta-badge engine-badge"><i class="fa-solid fa-microscope" style="color:var(--neon-amber);"></i> DEEP RESEARCH</span>
        <span class="meta-badge model-badge">${escapeHtml(model || 'Zoz AI')}</span>
        ${latency ? `<span class="meta-badge latency-badge"><i class="fa-solid fa-bolt"></i> ${escapeHtml(latency)}s</span>` : ''}
        ${sources && sources.length > 0 ? `<span class="meta-badge sources-badge"><i class="fa-solid fa-globe"></i> ${sources.length} Sumber</span>` : ''}
      `;
    } else if (stats && role === 'assistant') {
      statsHtml = `
        <span class="meta-model-badge">${escapeHtml(model)}</span>
        <span>⏱️ ${stats.duration}s</span>
        <span>⚡ ${stats.tps} tps</span>
      `;
    } else if (model && role === 'assistant') {
      statsHtml = `<span class="meta-model-badge">${escapeHtml(model)}</span>`;
    }

    let safeContent = role === 'assistant' ? safeAssistantText(content || '') : (content || '');
    if (role === 'user' && docs && Array.isArray(docs) && docs.length > 0 && typeof safeContent === 'string') {
      if (/^\[File:\s*[^\]]+\]$/i.test(safeContent.trim())) {
        safeContent = '';
      } else if (/\[File:\s*[^\]]+\]/i.test(safeContent)) {
        safeContent = safeContent.replace(/\s*\[File:\s*[^\]]+\]/gi, '').trim();
      }
    }
    const hasText = Boolean(safeContent && String(safeContent).trim().length > 0);
    let renderedBody = '';
    if (isActuallyDeepResearch && role === 'assistant' && hasText) {
      const msgObj = (typeof index === 'number' && index >= 0 && currentSess?.messages?.[index]) ? currentSess.messages[index] : null;
      renderedBody = buildDeepResearchSummaryCardHtml(safeContent, model, sources, resolvedTimestamp || timestamp, msgObj?.chatSummary || '');
    } else {
      renderedBody = role === 'assistant' ? renderMarkdown(safeContent) : escapeHtml(safeContent).replace(/\n/g, '<br>');
    }
    const textDisplayStyle = (!hasText && role === 'user') ? 'style="display:none;"' : '';

    let assistantGeneratedImagesHtml = '';
    if (role === 'assistant' && imgList.length > 0) {
      assistantGeneratedImagesHtml = `
        <div class="chat-generated-images-grid" style="margin-top: 10px; display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 10px;">
          ${imgList.map(src => createGeneratedImageCardHtml({
            url: src,
            imageUrl: src,
            prompt: content || 'Karya Visual AI',
            model: model || 'Zoz AI',
            duration: stats?.duration || '1.5'
          })).join('')}
        </div>
      `;
    }

    let assistantMediaHtml = '';
    const safeMeta = (extraMeta && typeof extraMeta === 'object') ? extraMeta : {};
    const audioUrl = safeMeta.audioUrl || safeMeta.url || (typeof content === 'string' && (content.match(/\[(?:Putar\s*\/\s*Unduh\s*Audio|Dengar\s*Audio)\]\((https?:\/\/[^\s\)]+|\/uploads\/[^\s\)]+)\)/i) || content.match(/\((https?:\/\/[^\s\)]+\.mp3|\/uploads\/[^\s\)]+\.mp3)\)/i))?.[1]);
    const videoUrl = safeMeta.videoUrl || (safeMeta.type === 'video_generation' && safeMeta.url) || (typeof content === 'string' && (content.match(/\[(?:Tonton\s*\/\s*Unduh\s*Video|Lihat\s*Video)\]\((https?:\/\/[^\s\)]+|\/uploads\/[^\s\)]+)\)/i) || content.match(/\((https?:\/\/[^\s\)]+\.mp4|\/uploads\/[^\s\)]+\.mp4)\)/i))?.[1]);

    if (role === 'assistant' && audioUrl && (safeMeta.isMusicGen || safeMeta.type === 'music_generation' || /\.mp3(?:$|\?)/i.test(audioUrl) || /Audio/i.test(content || ''))) {
      if (typeof buildCyberAudioPlayerCardHtml === 'function') {
        assistantMediaHtml += buildCyberAudioPlayerCardHtml({
          url: audioUrl,
          audioUrl: audioUrl,
          title: safeMeta.title || 'Singularity Cyber Audio',
          genre: safeMeta.genre || 'Cyberpunk',
          bpm: safeMeta.bpm || null,
          duration: safeMeta.duration || 15,
          prompt: safeMeta.prompt || content,
          aiComposed: Boolean(safeMeta.aiComposed),
          aiSummary: safeMeta.aiSummary || ''
        });
      }
    }

    if (role === 'assistant' && videoUrl && (safeMeta.isVideoGen || safeMeta.type === 'video_generation' || /\.mp4(?:$|\?)/i.test(videoUrl) || /Video/i.test(content || ''))) {
      if (typeof buildCyberVideoPlayerCardHtml === 'function') {
        assistantMediaHtml += buildCyberVideoPlayerCardHtml({
          url: videoUrl,
          videoUrl: videoUrl,
          title: safeMeta.title || 'Cinematic Video Motion',
          style: safeMeta.style || 'Cinematic Motion',
          duration: safeMeta.duration || 5,
          prompt: safeMeta.prompt || content
        });
      }
    }

    let sourcesHtml = '';
    if (sources && Array.isArray(sources) && sources.length > 0 && role === 'assistant' && !isActuallyDeepResearch) {
      sourcesHtml = buildSourcesSectionHtml(sources, true);
    }

    const metaContent = (isActuallyDeepResearch && role === 'assistant')
      ? statsHtml
      : `<strong>${roleLabel}</strong> ${statsHtml}`;

    row.innerHTML = `
      <div class="message-avatar">${avatarIcon}</div>
      <div class="message-content-box">
        <div class="message-meta">
          ${metaContent}
        </div>
        <div class="message-bubble">
          ${role === 'user' ? imageGalleryHtml : ''}
          ${docsHtml}
          <div class="msg-text-content" ${textDisplayStyle}>${renderedBody}</div>
          ${role === 'assistant' ? assistantGeneratedImagesHtml : ''}
          ${role === 'assistant' ? assistantMediaHtml : ''}
          ${sourcesHtml}
        </div>
        <div class="message-actions-bar">
          ${role === 'user' ? '<button class="msg-action-btn edit-msg-btn" title="Edit & Kirim Ulang Prompt"><i class="fa-solid fa-pen-to-square"></i> Edit</button>' : ''}
          <button class="msg-action-btn copy-msg-btn" title="Salin Pesan"><i class="fa-solid fa-copy"></i> Salin</button>
        </div>
      </div>
    `;

    // Attach Deep Research Card Actions (Full Report Modal & Quick Exports)
    if (isActuallyDeepResearch && role === 'assistant' && hasText) {
      attachDeepResearchCardEvents(row, content, model, sources, null);
    }

    // Attach image card listeners for assistant generated visual cards
    if (role === 'assistant' && imgList.length > 0) {
      attachImageCardListeners(row, content || '', imgList[0]);
    }

    // Attach audio & video listeners
    if (role === 'assistant') {
      try {
        if (typeof attachAudioPlayerListeners === 'function') attachAudioPlayerListeners(row);
        if (typeof attachVideoPlayerListeners === 'function') attachVideoPlayerListeners(row);
      } catch (mediaListenerErr) {
        console.warn('Media player listener init notice:', mediaListenerErr);
      }
    }

    // Attach Lightbox click triggers to images in user attachment bubble
    if (imgList.length > 0 && role === 'user') {
      row.querySelectorAll('.chat-img-thumb-wrap').forEach((thumb) => {
        thumb.addEventListener('click', (e) => {
          e.stopPropagation();
          const clickedIdx = parseInt(thumb.dataset.imgIdx, 10) || 0;
          ImageLightbox.open(imgList, clickedIdx);
        });
      });
    }

    // Enhance any inline markdown images
    enhanceChatImages(row);

    // Attach click triggers to document badges in user attachment bubble (view-only inspection)
    if (docs && docs.length > 0 && role === 'user') {
      row.querySelectorAll('.msg-doc-badge:not(.msg-doc-web-link)').forEach((badgeEl, bIdx) => {
        badgeEl.style.cursor = 'pointer';
        badgeEl.addEventListener('click', (e) => {
          e.stopPropagation();
          const targetDoc = (docs && docs[bIdx]) ? docs[bIdx] : null;
          if (!targetDoc) return;
          let docContent = targetDoc.rawContent || targetDoc.content || '';
          if (!docContent && typeof content === 'string') {
            const safeName = (targetDoc.name || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const docRegex = new RegExp(`--- \\[LAMPIRAN DOKUMEN:\\s*${safeName}[^\\n]*\\] ---\\r?\\n([\\s\\S]*?)\\r?\\n--- \\[AKHIR DOKUMEN:`, 'i');
            const match = content.match(docRegex);
            if (match && match[1]) {
              docContent = match[1];
            }
          }
          openDocPreviewModal({
            name: targetDoc.name,
            size: targetDoc.size,
            content: docContent,
            rawContent: docContent,
            isAutoConvertedMarkdown: targetDoc.isAutoConvertedMarkdown || true
          }, -1);
        });
      });
    }


    // Edit Prompt Button Handler (for User messages)
    if (role === 'user') {
      const editBtn = row.querySelector('.edit-msg-btn');
      const bubble = row.querySelector('.message-bubble');
      const textContainer = row.querySelector('.msg-text-content');
      const actionsBar = row.querySelector('.message-actions-bar');

      editBtn?.addEventListener('click', () => {
        if (STATE.isGenerating) {
          showToast('Harap tunggu atau hentikan generasi AI saat ini sebelum mengedit.', 'error');
          return;
        }
        if (!bubble || !textContainer) return;
        if (bubble.querySelector('.inline-edit-box')) return;

        // Create inline editor
        let originalContent = content;
        if (role === 'user' && docs && Array.isArray(docs) && docs.length > 0 && typeof originalContent === 'string') {
          if (/^\[File:\s*[^\]]+\]$/i.test(originalContent.trim())) {
            const sessMsg = (index >= 0 && currentSess?.messages?.[index]) ? currentSess.messages[index] : null;
            if (sessMsg && typeof sessMsg.content === 'string') {
              const trailingPrompt = sessMsg.content.replace(/^[\s\S]*--- \[AKHIR DOKUMEN:[^\]]*\] ---\s*/i, '').trim();
              if (trailingPrompt && !/^Tolong pelajari, analisis, dan jelaskan/i.test(trailingPrompt)) {
                originalContent = trailingPrompt;
              } else {
                originalContent = '';
              }
            } else {
              originalContent = '';
            }
          } else if (/\[File:\s*[^\]]+\]/i.test(originalContent)) {
            originalContent = originalContent.replace(/\s*\[File:\s*[^\]]+\]/gi, '').trim();
          }
        }
        textContainer.style.display = 'none';
        if (actionsBar) actionsBar.style.display = 'none';

        const editorBox = document.createElement('div');
        editorBox.className = 'inline-edit-box';
        editorBox.style.cssText = 'display:flex; flex-direction:column; gap:8px; width:100%; min-width:280px; margin-top:4px;';
        editorBox.innerHTML = `
          <textarea class="inline-edit-textarea" style="width:100%; min-height:75px; background:var(--bg-core); border:1px solid var(--neon-cyan); border-radius:6px; color:var(--text-main); padding:8px 10px; font-family:var(--font-main); font-size:0.9rem; line-height:1.5; resize:vertical; outline:none; box-shadow:0 0 12px rgba(0,240,255,0.25);">${escapeHtml(originalContent)}</textarea>
          <div style="display:flex; justify-content:flex-end; gap:8px;">
            <button class="btn btn-sm btn-secondary cancel-edit-btn" style="padding:4px 10px; font-size:0.75rem;">Batal</button>
            <button class="btn btn-sm btn-primary save-edit-btn" style="padding:4px 12px; font-size:0.75rem;"><i class="fa-solid fa-paper-plane"></i> Simpan & Kirim Ulang</button>
          </div>
        `;

        bubble.appendChild(editorBox);
        const textarea = editorBox.querySelector('.inline-edit-textarea');
        if (textarea) {
          textarea.focus();
          textarea.setSelectionRange(textarea.value.length, textarea.value.length);
        }

        // Cancel
        editorBox.querySelector('.cancel-edit-btn')?.addEventListener('click', () => {
          editorBox.remove();
          if (textContainer) textContainer.style.display = 'block';
          if (actionsBar) actionsBar.style.display = 'flex';
          AudioEngine.click();
        });

        // Save & Resend
        const doSaveAndResend = () => {
          // M5: cek KEDUA guard SAAT tombol ditekan (bukan hanya saat editor dibuka).
          // Saat masih ada await awal di handleSendPrompt (scrape URL / hydrate sesi),
          // isSending=true tetapi isGenerating=false — dulu riwayat sudah dipotong
          // lebih dulu lalu kirim dibatalkan diam-diam oleh guard → pesan hilang.
          if (STATE.isGenerating || STATE.isSending) {
            showToast('Masih ada pengiriman yang diproses — tunggu selesai dulu sebelum mengedit & mengirim ulang.', 'error');
            return;
          }
          const newText = textarea ? textarea.value.trim() : '';
          if (!newText && (!imgList || imgList.length === 0) && (!docs || docs.length === 0)) {
            showToast('Prompt tidak boleh kosong.', 'error');
            return;
          }

          const session = getActiveSession();
          // Find index of this message in session (matching either raw content or displayContent)
          let msgIdx = index;
          if (msgIdx < 0 || msgIdx >= session.messages.length) {
            msgIdx = session.messages.findIndex(m => m.role === 'user' && (m.content === originalContent || m.displayContent === originalContent || m.content === content || m.displayContent === content));
          }

          const targetUserMsg = (msgIdx >= 0 && msgIdx < session.messages.length) ? session.messages[msgIdx] : null;

          // Preserve / restore attached documents with their full text content
          let restoredDocs = (docs && Array.isArray(docs)) ? [...docs] : [];
          if (restoredDocs.length > 0 && targetUserMsg) {
            restoredDocs = restoredDocs.map(d => {
              if (d && typeof d.content === 'string' && d.content.trim().length > 0) {
                return d;
              }
              // Check if targetUserMsg.docs has content
              if (Array.isArray(targetUserMsg.docs)) {
                const foundDoc = targetUserMsg.docs.find(td => td && td.name === d.name && typeof td.content === 'string' && td.content.trim().length > 0);
                if (foundDoc) return { ...d, content: foundDoc.content };
              }
              // Extract content from targetUserMsg.content
              if (targetUserMsg.content && typeof targetUserMsg.content === 'string') {
                const safeName = (d.name || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                const docRegex = new RegExp(`--- \\[LAMPIRAN DOKUMEN:\\s*${safeName}[^\\n]*\\] ---\\r?\\n([\\s\\S]*?)\\r?\\n--- \\[AKHIR DOKUMEN:`, 'i');
                const match = targetUserMsg.content.match(docRegex);
                if (match && match[1]) {
                  return { ...d, content: match[1] };
                }
              }
              return d;
            });
          }

          if (msgIdx >= 0) {
            // Truncate history from this message onward
            session.messages = session.messages.slice(0, msgIdx);
          }

          editorBox.remove();
          savePersistedState();
          
          // Re-render UI up to the truncated point
          renderCurrentSession();

          // Set prompt input and send
          if (els.promptInput) els.promptInput.value = newText;
          if (imgList && imgList.length > 0) {
            STATE.attachedImages = [...imgList];
            renderAttachmentPreviews();
          }
          if (restoredDocs && Array.isArray(restoredDocs) && restoredDocs.length > 0) {
            STATE.attachedDocs = [...restoredDocs];
            renderAttachmentPreviews();
          }
          if (STATE.isPromptHidden) {
            togglePromptVisibility(false);
          }
          handleSendPrompt().catch((err) => {
            console.error('Edit-and-resend gagal:', err);
            showToast('Gagal mengirim pesan: ' + (err && err.message ? err.message : err), 'error');
          });
        };

        editorBox.querySelector('.save-edit-btn')?.addEventListener('click', doSaveAndResend);
        textarea?.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
            e.preventDefault();
            doSaveAndResend();
          }
        });
      });
    }

    // Universal Code block enhancement & Copy button
    enhanceCodeBlocks(row);

    // Message copy button
    row.querySelector('.copy-msg-btn')?.addEventListener('click', () => {
      let rawText = row.dataset.fullContent || content || row.querySelector('.msg-text-content')?.innerText || '';
      if (role === 'user' && !rawText && docs && docs.length > 0) {
        rawText = docs.map(d => `[Dokumen: ${d.name || 'lampiran'}]`).join('\n');
      }
      const textToCopy = role === 'assistant' ? safeAssistantText(rawText) : rawText;
      copyTextToClipboard(textToCopy, null, 'Pesan disalin ke clipboard!');
    });

    els.messagesList?.appendChild(row);
    if (hasText) {
      renderYouTubeCardsForMessage(row, content);
    }
    // Kartu file buatan AI juga dirender saat pesan dimuat ulang dari riwayat (msg.files)
    renderMessageFiles(row, extraMeta && extraMeta.files);
    return row;
  }

  // ==================== DOCUMENT & FILE ATTACHMENT HANDLER ====================
  async function extractFileContent(file) {
    if (!file) return '';
    const ext = (file.name.split('.').pop() || '').toLowerCase();
    
    // Safety guard: Jika berkas gambar lolos ke fungsi ini, cegah pembacaan teks mentah
    if (isImageFile(file)) {
      return `[File gambar "${file.name}" dialihkan secara visual ke galeri foto.]`;
    }

    // Safety guard: Berkas biner non-dokumen yang tidak boleh dibaca sebagai teks
    const binaryExtensions = [
      'exe', 'dll', 'so', 'bin', 'iso', 'img', 'dmg', 'apk', 'zip', 'rar', '7z', 'tar', 'gz', 'bz2', 'xz',
      'mp3', 'wav', 'ogg', 'm4a', 'flac', 'mp4', 'mkv', 'avi', 'mov', 'webm', 'wmv', 'flv'
    ];
    if (binaryExtensions.includes(ext)) {
      return `[File biner "${file.name}" tidak dapat dibaca sebagai dokumen teks. Harap gunakan format teks (PDF, DOCX, TXT, MD, JSON, CSV, Kode).]`;
    }

    // 1. PDF Documents (Extract text per page safely via PDF.js)
    if (ext === 'pdf' || file.type === 'application/pdf') {
      try {
        if (!window.pdfjsLib) {
          return `[Pustaka pembaca PDF (pdf.js) belum termuat atau diblokir peramban. Tidak dapat membaca file "${file.name}".]`;
        }
        pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
        const arrayBuffer = await file.arrayBuffer();
        const loadingTask = pdfjsLib.getDocument({ data: new Uint8Array(arrayBuffer) });
        const pdf = await loadingTask.promise;
        let fullText = '';
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          const pageText = textContent.items.map(item => item.str).join(' ');
          if (pageText.trim()) {
            fullText += `[Halaman ${i}]\n${pageText.trim()}\n\n`;
          }
        }
        if (!fullText.trim()) {
          return `[Dokumen PDF "${file.name}" tidak berisi lapisan teks digital / merupakan pindaian gambar.]`;
        }
        return fullText.trim();
      } catch (pdfErr) {
        console.warn('PDF.js parse error:', pdfErr);
        return `[Gagal mengekstrak teks dari PDF "${file.name}": ${pdfErr.message}]`;
      }
    }

    // 2. DOCX Documents (Extract text safely via JSZip & DOMParser)
    if (ext === 'docx' || file.type === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document') {
      try {
        if (!window.JSZip) {
          return Promise.resolve(`[Pustaka pembaca DOCX (JSZip) belum termuat atau diblokir peramban. Tidak dapat membaca file "${file.name}".]`);
        }
        const arrayBuffer = await file.arrayBuffer();
        let zip;
        try {
          zip = await JSZip.loadAsync(arrayBuffer);
        } catch (zipErr) {
          console.warn('JSZip loadAsync error:', zipErr);
          return `[File DOCX "${file.name}" corrupt atau bukan arsip ZIP valid: ${zipErr.message}]`;
        }
        const docXml = zip.file('word/document.xml');
        if (docXml) {
          const xmlText = await docXml.async('text');
          const parser = new DOMParser();
          const xmlDoc = parser.parseFromString(xmlText, 'application/xml');
          const paragraphs = xmlDoc.getElementsByTagName('w:p');
          const lines = [];
          for (let i = 0; i < paragraphs.length; i++) {
            const texts = paragraphs[i].getElementsByTagName('w:t');
            let pText = '';
            for (let j = 0; j < texts.length; j++) {
              pText += texts[j].textContent;
            }
            if (pText.trim()) lines.push(pText.trim());
          }
          if (lines.length > 0) return lines.join('\n');
        }
        return `[Dokumen DOCX "${file.name}" kosong atau tidak memiliki teks yang terbaca.]`;
      } catch (docxErr) {
        console.warn('DOCX parse error:', docxErr);
        return `[Gagal mengekstrak teks dari DOCX "${file.name}": ${docxErr.message}]`;
      }
    }

    // 3. Plain Text, Code, CSV, Markdown, JSON, YAML, etc.
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        let text = e.target.result || '';
        // Check for binary character density: if text contains excessive null bytes, it's an unsupported binary file
        let nullByteCount = 0;
        const sampleLimit = Math.min(text.length, 1000);
        for (let i = 0; i < sampleLimit; i++) {
          if (text.charCodeAt(i) === 0) nullByteCount++;
        }
        if (nullByteCount > 5) {
          return resolve(`[File "${file.name}" terdeteksi sebagai berkas biner mentah dan tidak dapat diekstrak sebagai teks.]`);
        }
        // Sanitize: strip dangerous unprintable ASCII binary characters while preserving text and newlines
        text = text.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F-\x9F]/g, '');
        resolve(text);
      };
      reader.onerror = () => resolve(`[Gagal membaca isi file: ${file.name}]`);
      reader.readAsText(file);
    });
  }

  async function handleDocUpload(e) {
    const files = Array.from(e.target.files || []);
    if (!files || files.length === 0) return;

    let addedDocsCount = 0;
    let addedImagesCount = 0;

    for (const file of files) {
      if (!file || typeof file.size !== 'number' || file.size <= 0) continue;
      // 1. Cek cerdas: Jika user memilih foto/gambar melalui menu Dokumen
      if (isImageFile(file)) {
        const ok = await processSingleImageFile(file);
        if (ok) addedImagesCount++;
        continue;
      }

      const sizeStr = (file.size < 1024) 
        ? `${file.size} B` 
        : (file.size < 1024 * 1024) 
          ? `${(file.size / 1024).toFixed(1)} KB` 
          : `${(file.size / (1024 * 1024)).toFixed(1)} MB`;

      const content = await extractFileContent(file);

      STATE.attachedDocs.push({
        name: file.name,
        size: sizeStr,
        content: content
      });
      addedDocsCount++;
    }

    if (els.docFileInput) els.docFileInput.value = '';
    renderAttachmentPreviews();
    if (addedDocsCount > 0 || addedImagesCount > 0) {
      AudioEngine.click();
    }
  }

  function removeAttachedDoc(idx) {
    if (idx >= 0 && idx < STATE.attachedDocs.length) {
      STATE.attachedDocs.splice(idx, 1);
      renderAttachmentPreviews();
      AudioEngine.click();
    }
  }

  // ==================== AUTO MARKDOWN FILE CONVERTER (CLAUDE & GROK AI STYLE) ====================
  let activePreviewDocIndex = -1;
  let activeAIFile = null; // file yang sedang dibuka di AI File Studio

  function detectDocumentTypeAndExt(text) {
    if (!text || typeof text !== 'string') return { ext: 'md', lang: 'markdown', label: 'Dokumen', customName: 'dokumen-lampiran.md' };
    const trimmed = text.trim();

    // 1. Cek judul Markdown (# Judul)
    const mdHeaderMatch = trimmed.match(/^#+\s+([^\n\r]{2,40})/);
    if (mdHeaderMatch) {
      const slug = mdHeaderMatch[1].trim().replace(/[^a-zA-Z0-9_\-\s]/g, '').replace(/\s+/g, '-').toLowerCase();
      if (slug.length >= 3 && !/^(?:function|class|def|import|const|var|let)\b/i.test(slug)) {
        return { ext: 'md', lang: 'markdown', label: slug, customName: `${slug}.md` };
      }
    }

    // 2. HTML / XML / JSX
    if (/<(?:!doctype\s+html|html|head|body|div|section|table|script|template)\b/i.test(trimmed)) {
      return { ext: 'html.md', lang: 'html', label: 'HTML Snippet', customName: 'webpage.html.md' };
    }

    // 3. JSON
    if ((trimmed.startsWith('{') && trimmed.endsWith('}')) || (trimmed.startsWith('[') && trimmed.endsWith(']'))) {
      try {
        JSON.parse(trimmed);
        return { ext: 'json.md', lang: 'json', label: 'Data JSON', customName: 'data.json.md' };
      } catch (_) {}
    }

    // 4. SQL
    if (/\b(?:SELECT\s+[\s\S]*?\s+FROM|INSERT\s+INTO|CREATE\s+TABLE|ALTER\s+TABLE|DROP\s+TABLE|UPDATE\s+[\s\S]*?\s+SET)\b/i.test(trimmed)) {
      return { ext: 'sql.md', lang: 'sql', label: 'Query SQL', customName: 'query.sql.md' };
    }

    // 5. Python
    if (/\b(?:def\s+[a-zA-Z_]\w*\s*\(|import\s+[a-zA-Z_]|from\s+[a-zA-Z_].*import|if\s+__name__\s*==\s*['"]__main__['"]|elif\s+|print\s*\()/i.test(trimmed)) {
      return { ext: 'py.md', lang: 'python', label: 'Python Script', customName: 'script.py.md' };
    }

    // 6. JavaScript / TypeScript
    if (/\b(?:const\s+[a-zA-Z_]|let\s+[a-zA-Z_]|var\s+[a-zA-Z_]|function\s+[a-zA-Z_]|import\s+.*from|export\s+(?:default|const|function)|console\.log\(|async\s+function|=>)/i.test(trimmed)) {
      if (/\b(?:interface\s+[A-Z]|type\s+[A-Z]|:\s*(?:string|number|boolean|any)\b)/.test(trimmed)) {
        return { ext: 'ts.md', lang: 'typescript', label: 'TypeScript Code', customName: 'code.ts.md' };
      }
      return { ext: 'js.md', lang: 'javascript', label: 'JavaScript Code', customName: 'script.js.md' };
    }

    // 7. PHP
    if (/<\?php|\b(?:echo\s+\$|\$this->)/i.test(trimmed)) {
      return { ext: 'php.md', lang: 'php', label: 'PHP Script', customName: 'script.php.md' };
    }

    // 8. C / C++ / C# / Java / Rust / Go
    if (/#include\s+[<"]|\bnamespace\s+\w+|\busing\s+System;|\bpublic\s+class\s+\w+|\bfn\s+main\b|\bpackage\s+main\b/i.test(trimmed)) {
      return { ext: 'code.md', lang: 'c', label: 'Source Code', customName: 'source-code.md' };
    }

    // 9. CSS / Styles
    if (
      /\b(?:display|margin|padding|border|color|background|font|width|height|position|align|flex|grid|transform|opacity|z-index)\s*:/i.test(trimmed) ||
      /[a-zA-Z0-9_\-#.:>\s,]+\s*\{\s*[^}]*\}/.test(trimmed) ||
      /(?:@media|@keyframes|\.[\w\-]+|#[\w\-]+)\s*\{/i.test(trimmed) ||
      /[a-zA-Z0-9_\-#.]+\s*\{\s*[\w\-]+\s*:[^;]+;/i.test(trimmed)
    ) {
      return { ext: 'css.md', lang: 'css', label: 'Styles CSS', customName: 'styles.css.md' };
    }

    // 10. Log / Trace
    if (/\b(?:\[(?:INFO|ERROR|WARN|DEBUG)\]|Traceback\s+\(most\s+recent\s+call\s+last\)|Exception in thread|FATAL:)\b/i.test(trimmed)) {
      return { ext: 'log.md', lang: 'log', label: 'System Log', customName: 'system-log.md' };
    }

    // 11. Heuristik baris pertama jika artikel/laporan
    const firstLine = trimmed.split('\n')[0].replace(/[^a-zA-Z0-9_\-\s]/g, '').trim();
    if (firstLine.length >= 4 && firstLine.length <= 30 && !/^(?:function|class|def|import|const|var|let|if|for|while)\b/i.test(firstLine)) {
      const slug = firstLine.replace(/\s+/g, '-').toLowerCase();
      return { ext: 'md', lang: 'markdown', label: 'Dokumen', customName: `${slug}.md` };
    }

    return { ext: 'md', lang: 'markdown', label: 'Dokumen Teks', customName: 'dokumen-lampiran.md' };
  }

  function countPromptWords(text) {
    if (!text || typeof text !== 'string') return 0;
    const trimmed = text.trim();
    if (!trimmed) return 0;
    const words = trimmed.match(/\S+/g);
    return words ? words.length : 0;
  }

  function shouldAutoConvertAsDocument(text) {
    if (!text || typeof text !== 'string') return false;
    const trimmed = text.trim();
    if (!trimmed) return false;

    // Mandat Kaisar Zozi: Minimal 500 KATA sebelum memicu notifikasi konversi ke markdown!
    // Teks di bawah 500 kata (misal 50, 100, 200, 400 kata) dibiarkan tetap di kolom prompt tanpa notifikasi.
    const wordCount = countPromptWords(trimmed);

    // Memicu notifikasi hanya jika mencapai minimal 500 kata (atau teks masif >= 4000 karakter)
    if (wordCount >= 500 || trimmed.length >= 4000) {
      return true;
    }

    return false;
  }

  function convertTextToMarkdownDoc(rawText, userGivenName = '') {
    if (!rawText || typeof rawText !== 'string' || !rawText.trim()) return null;
    const cleanText = rawText.trim();
    const typeInfo = detectDocumentTypeAndExt(cleanText);

    let baseName = userGivenName || typeInfo.customName;
    if (!baseName) {
      if (typeInfo.lang !== 'markdown') {
        baseName = `code-snippet.${typeInfo.ext}`;
      } else {
        baseName = `dokumen-lampiran.md`;
      }
    }

    // Unik nama file
    const existingNames = (STATE.attachedDocs || []).map(d => (d.name || '').toLowerCase());
    let finalName = baseName;
    let counter = 1;
    while (existingNames.includes(finalName.toLowerCase())) {
      const dotIdx = baseName.lastIndexOf('.');
      if (dotIdx > 0) {
        finalName = `${baseName.substring(0, dotIdx)}-${counter}${baseName.substring(dotIdx)}`;
      } else {
        finalName = `${baseName}-${counter}`;
      }
      counter++;
    }

    let formattedContent = cleanText;
    if (typeInfo.lang !== 'markdown' && !cleanText.startsWith('```')) {
      formattedContent = `\`\`\`${typeInfo.lang}\n${cleanText}\n\`\`\``;
    }

    let bytes = 0;
    try {
      bytes = new Blob([formattedContent]).size;
    } catch (_) {
      bytes = formattedContent.length;
    }
    const sizeStr = bytes < 1024 
      ? `${bytes} B` 
      : bytes < 1024 * 1024 
        ? `${(bytes / 1024).toFixed(1)} KB` 
        : `${(bytes / (1024 * 1024)).toFixed(1)} MB`;

    const charCount = cleanText.length;
    const lineCount = cleanText.split('\n').length;

    return {
      name: finalName,
      size: `${sizeStr} • ${lineCount} baris`,
      content: formattedContent,
      rawContent: cleanText,
      lang: typeInfo.lang,
      charCount,
      lineCount,
      isAutoConvertedMarkdown: true
    };
  }

  // Helper universal untuk mengekstrak instruksi prompt terpisah dari badan dokumen lampiran
  function extractPromptAndDocContent(incomingText, existingPrompt = '') {
    if (!incomingText || typeof incomingText !== 'string') {
      return { docBody: '', promptInstruction: (existingPrompt || '').trim() };
    }
    const cleanText = incomingText.trim();
    if (!cleanText) {
      return { docBody: '', promptInstruction: (existingPrompt || '').trim() };
    }

    let docBody = cleanText;
    let extractedInstruction = '';

    // Regex pengenal instruksi / prompt (Indonesia & Inggris)
    const INSTRUCTION_KEYWORD_RE = /(?:tolong|mohon|silakan|coba|bantu|jelaskan|analisis|analisa|evaluasi|tinjau|baca|ringkas|rangkum|simpulkan|review|perbaiki|fix|cek|buatkan|kenapa|mengapa|gimana|bagaimana|bagaimanakah|apa(?:kah)?|artikan|terjemahkan|explain|analyze|review|summarize|read|fix|help|check|please|how|what|why|where|could you|can you)\b/i;

    // 1. Deteksi blok kode markdown terisolasi (```lang ... ```)
    const codeFenceMatch = cleanText.match(/^([\s\S]*?)(```[a-zA-Z0-9_-]*\s*\n[\s\S]*?\n```)([\s\S]*)$/);
    if (codeFenceMatch) {
      const prefix = codeFenceMatch[1].trim();
      const codeFence = codeFenceMatch[2].trim();
      const suffix = codeFenceMatch[3].trim();
      // Bila blok kode cukup substansial (>= 15 baris atau >= 250 karakter)
      if (codeFence.length >= 250 || codeFence.split('\n').length >= 15) {
        docBody = codeFence;
        const outerParts = [prefix, suffix].filter(Boolean);
        if (outerParts.length > 0) {
          extractedInstruction = outerParts.join('\n\n').trim();
        }
      }
    }

    // 2. Jika belum terurai: Deteksi instruksi di AWAL teks
    if (!extractedInstruction && docBody === cleanText) {
      const lines = cleanText.split('\n');
      if (lines.length >= 3) {
        // Cek 1-5 baris pertama sebelum baris kosong (\n\n) atau divider (---, ===)
        for (let i = 0; i < Math.min(lines.length - 2, 6); i++) {
          const candidateLines = lines.slice(0, i + 1);
          const candidateText = candidateLines.map(l => l.trim()).join(' ').trim();
          const nextLine = lines[i + 1].trim();
          const separatorHit = (nextLine === '' || /^[-=_*]{3,}$/.test(nextLine));

          if (candidateText.length <= 400 && (
            (separatorHit && (INSTRUCTION_KEYWORD_RE.test(candidateText) || candidateText.endsWith(':') || candidateText.endsWith('?'))) ||
            (!separatorHit && (candidateText.endsWith(':') || candidateText.endsWith('?')) && INSTRUCTION_KEYWORD_RE.test(candidateText))
          )) {
            let bodyStartIdx = i + 1;
            while (bodyStartIdx < lines.length && (lines[bodyStartIdx].trim() === '' || /^[-=_*]{3,}$/.test(lines[bodyStartIdx].trim()))) {
              bodyStartIdx++;
            }
            if (bodyStartIdx < lines.length) {
              const remainingBody = lines.slice(bodyStartIdx).join('\n').trim();
              if (remainingBody.length >= 200 || remainingBody.split('\n').length >= 10) {
                extractedInstruction = candidateLines.join('\n').trim();
                docBody = remainingBody;
                break;
              }
            }
          }
        }

        // Fallback baris pertama instruksi pendek (<= 160 karakter)
        if (!extractedInstruction && lines.length >= 2) {
          const firstLine = lines[0].trim();
          if (firstLine.length <= 160 && (INSTRUCTION_KEYWORD_RE.test(firstLine) || firstLine.endsWith(':') || firstLine.endsWith('?'))) {
            let bodyStartIdx = 1;
            while (bodyStartIdx < lines.length && lines[bodyStartIdx].trim() === '') {
              bodyStartIdx++;
            }
            const remainingBody = lines.slice(bodyStartIdx).join('\n').trim();
            if (remainingBody.length >= 200 || remainingBody.split('\n').length >= 10) {
              extractedInstruction = firstLine;
              docBody = remainingBody;
            }
          }
        }
      }
    }

    // 3. Deteksi instruksi di AKHIR teks (sangat lazim: user menempel kodingan/laporan, lalu menulis pertanyaan di bawah)
    if (!extractedInstruction && docBody === cleanText) {
      const lines = cleanText.split('\n');
      if (lines.length >= 3) {
        for (let i = lines.length - 1; i >= Math.max(lines.length - 6, 2); i--) {
          const candidateLines = lines.slice(i);
          const candidateText = candidateLines.map(l => l.trim()).join(' ').trim();
          const prevLine = lines[i - 1].trim();
          const separatorHit = (prevLine === '' || /^[-=_*]{3,}$/.test(prevLine));

          if (candidateText.length <= 400 && (
            (separatorHit && (INSTRUCTION_KEYWORD_RE.test(candidateText) || candidateText.endsWith('?') || candidateText.endsWith(':'))) ||
            candidateText.endsWith('?') ||
            (candidateLines.length <= 2 && INSTRUCTION_KEYWORD_RE.test(candidateText))
          )) {
            let bodyEndIdx = i - 1;
            while (bodyEndIdx >= 0 && (lines[bodyEndIdx].trim() === '' || /^[-=_*]{3,}$/.test(lines[bodyEndIdx].trim()))) {
              bodyEndIdx--;
            }
            if (bodyEndIdx >= 0) {
              const remainingBody = lines.slice(0, bodyEndIdx + 1).join('\n').trim();
              if (remainingBody.length >= 200 || remainingBody.split('\n').length >= 10) {
                extractedInstruction = candidateLines.join('\n').trim();
                docBody = remainingBody;
                break;
              }
            }
          }
        }
      }
    }

    // 4. Gabungkan instruksi dengan existingPrompt jika ada (misal teks sebelum paste di kolom prompt)
    const cleanExisting = (existingPrompt || '').trim();
    let finalPromptInstruction = '';
    if (cleanExisting && extractedInstruction) {
      finalPromptInstruction = `${cleanExisting}\n\n${extractedInstruction}`.trim();
    } else {
      finalPromptInstruction = cleanExisting || extractedInstruction || '';
    }

    return {
      docBody: docBody || cleanText,
      promptInstruction: finalPromptInstruction
    };
  }

  function tryAutoConvertInputToDoc(incomingText, existingPrompt = '') {
    if (!incomingText || typeof incomingText !== 'string') return false;
    const trimmed = incomingText.trim();
    if (!shouldAutoConvertAsDocument(trimmed)) return false;

    const { docBody, promptInstruction } = extractPromptAndDocContent(trimmed, existingPrompt);
    const doc = convertTextToMarkdownDoc(docBody);
    if (!doc) return false;

    STATE.attachedDocs.push(doc);
    renderAttachmentPreviews();
    AudioEngine.success();

    if (navigator.vibrate) {
      try { navigator.vibrate(40); } catch (_) {}
    }

    if (els.promptInput) {
      els.promptInput.value = promptInstruction;
      autoResizeTextarea(els.promptInput);
      els.promptInput.focus();
    }
    if (els.autoConvertDocRow) {
      els.autoConvertDocRow.style.display = 'none';
    }
    hideComposerFoldPromptCard();

    showToast(`📄 Teks panjang otomatis dikonversi ke file markdown [${doc.name}]! Kolom prompt tetap bersih.`, 'info');
    return true;
  }

  let pendingFoldText = '';
  let pendingFoldInstruction = '';
  let pendingFoldRawIncoming = '';
  let pendingFoldDismissedHash = '';
  let pendingFoldPastedDirectly = false;

  function hideComposerFoldPromptCard() {
    if (els.composerFoldPromptCard) {
      els.composerFoldPromptCard.style.display = 'none';
    }
  }

  function checkAndShowPromptFoldPrompt(incomingText, forceModal = false, fromPaste = false, existingPrompt = '') {
    if (!incomingText || typeof incomingText !== 'string') {
      hideComposerFoldPromptCard();
      return false;
    }
    const trimmed = incomingText.trim();
    if (!shouldAutoConvertAsDocument(trimmed)) {
      hideComposerFoldPromptCard();
      return false;
    }

    // Jika user sudah mencentang opsi selalu otomatis konversi
    const alwaysAutoFold = localStorage.getItem('zoz_always_auto_fold_prompt') === 'true';
    if (alwaysAutoFold) {
      hideComposerFoldPromptCard();
      return tryAutoConvertInputToDoc(trimmed, existingPrompt);
    }

    const textHash = `${trimmed.length}_${trimmed.substring(0, 50)}`;
    if (!forceModal && pendingFoldDismissedHash === textHash) {
      return false;
    }

    const { docBody, promptInstruction } = extractPromptAndDocContent(trimmed, existingPrompt);
    const typeInfo = detectDocumentTypeAndExt(docBody);
    const fileName = typeInfo.customName || `code-snippet.${typeInfo.ext}`;
    const wordCount = countPromptWords(docBody);
    const lineCount = docBody.split('\n').length;
    const charCount = docBody.length;

    pendingFoldText = docBody;
    pendingFoldInstruction = promptInstruction;
    pendingFoldRawIncoming = incomingText;
    pendingFoldPastedDirectly = fromPaste;

    // Tampilkan Floating Card di atas composer
    if (els.composerFoldPromptCard) {
      if (els.foldCardTitle) {
        els.foldCardTitle.textContent = `${typeInfo.label || 'Teks Panjang / Kodingan'} Terdeteksi (${fileName})`;
      }
      if (els.foldCardSubtitle) {
        els.foldCardSubtitle.textContent = `${wordCount.toLocaleString('id-ID')} kata • ${lineCount} baris (${charCount.toLocaleString('id-ID')} karakter) • Ubah ke file markdown agar prompt bersih?`;
      }
      els.composerFoldPromptCard.style.display = 'flex';
    }

    // Jika forceModal (misal saat paste kodingan besar)
    if (forceModal && els.promptFoldConfirmModal) {
      if (els.foldModalFileName) {
        els.foldModalFileName.textContent = fileName;
      }
      if (els.foldModalSnippet) {
        els.foldModalSnippet.textContent = docBody.length > 500 ? docBody.substring(0, 500) + '\n\n... (teks dipotong untuk preview)' : docBody;
      }
      if (els.foldModalMeta) {
        els.foldModalMeta.innerHTML = `<i class="fa-solid fa-align-left"></i> ${wordCount.toLocaleString('id-ID')} kata &bull; ${lineCount} baris &bull; ${charCount.toLocaleString('id-ID')} karakter`;
      }
      if (els.chkAutoFoldAlways) {
        els.chkAutoFoldAlways.checked = false;
      }
      openModal('promptFoldConfirmModal');
    }

    return true;
  }

  function executeConfirmedPromptFold() {
    if (!pendingFoldText) {
      hideComposerFoldPromptCard();
      closeModal('promptFoldConfirmModal');
      return;
    }

    if (els.chkAutoFoldAlways && els.chkAutoFoldAlways.checked) {
      try {
        localStorage.setItem('zoz_always_auto_fold_prompt', 'true');
      } catch (_) {}
    }

    const doc = convertTextToMarkdownDoc(pendingFoldText);
    if (doc) {
      STATE.attachedDocs.push(doc);
      renderAttachmentPreviews();
      AudioEngine.success();

      if (navigator.vibrate) {
        try { navigator.vibrate(40); } catch (_) {}
      }

      if (els.promptInput) {
        els.promptInput.value = pendingFoldInstruction || '';
        autoResizeTextarea(els.promptInput);
        els.promptInput.focus();
      }

      showToast(`📄 Berhasil! Teks diubah ke file markdown [${doc.name}]. Kolom prompt bersih.`, 'info');
    }

    hideComposerFoldPromptCard();
    if (els.autoConvertDocRow) {
      els.autoConvertDocRow.style.display = 'none';
    }
    closeModal('promptFoldConfirmModal');
    pendingFoldText = '';
    pendingFoldInstruction = '';
    pendingFoldRawIncoming = '';
    pendingFoldPastedDirectly = false;
  }

  function dismissPromptFold(insertIntoPromptIfPasted = false) {
    if (pendingFoldText) {
      pendingFoldDismissedHash = `${pendingFoldText.length}_${pendingFoldText.substring(0, 50)}`;
    }

    if (insertIntoPromptIfPasted && pendingFoldPastedDirectly && els.promptInput) {
      const incomingToRestore = pendingFoldRawIncoming || pendingFoldText;
      if (incomingToRestore) {
        const currentVal = els.promptInput.value;
        els.promptInput.value = currentVal ? `${currentVal}\n${incomingToRestore}` : incomingToRestore;
        autoResizeTextarea(els.promptInput);
        els.promptInput.focus();
      }
    }

    hideComposerFoldPromptCard();
    closeModal('promptFoldConfirmModal');
    pendingFoldText = '';
    pendingFoldInstruction = '';
    pendingFoldRawIncoming = '';
    pendingFoldPastedDirectly = false;
  }

  function openDocPreviewModal(doc, idx = -1) {
    if (!doc) return;
    activePreviewDocIndex = idx;
    if (els.docPreviewModalTitle) {
      const isMdCode = Boolean(doc.isAutoConvertedMarkdown || (doc.name && /\.(?:md|markdown|js|ts|py|html|css|json|sql|sh)$/i.test(doc.name)));
      els.docPreviewModalTitle.innerHTML = `<i class="${isMdCode ? 'fa-solid fa-file-code' : 'fa-solid fa-file-lines'}"></i> ${escapeHtml(doc.name)}`;
    }
    if (els.docPreviewMetaName) {
      els.docPreviewMetaName.innerHTML = `<i class="fa-solid fa-file"></i> ${escapeHtml(doc.name)}`;
    }
    if (els.docPreviewMetaSize) {
      els.docPreviewMetaSize.innerHTML = `<i class="fa-solid fa-weight-scale"></i> ${escapeHtml(doc.size || '')}`;
    }
    if (els.docPreviewMetaLines) {
      const raw = doc.rawContent || doc.content || '';
      const lines = raw.split('\n').length;
      const chars = raw.length;
      els.docPreviewMetaLines.innerHTML = `<i class="fa-solid fa-align-left"></i> ${lines} baris (${chars.toLocaleString('id-ID')} karakter)`;
    }
    if (els.docPreviewContent) {
      els.docPreviewContent.textContent = doc.rawContent || doc.content || '';
    }
    if (els.revertDocToPromptBtn) {
      els.revertDocToPromptBtn.style.display = (idx >= 0) ? 'inline-flex' : 'none';
    }
    if (els.deleteDocFromModalBtn) {
      els.deleteDocFromModalBtn.style.display = (idx >= 0) ? 'inline-flex' : 'none';
    }
    openModal('docPreviewModal');
  }

  // ==================== AI FILE STUDIO (preview langsung + kode + unduh) ====================
  // Format keluaran yang diminta ke AI ketika pengguna minta sebuah berkas:
  //   <<<ZOZ_FILE name="index.html" mime="text/html" lang="html">
  //   ...isi file apa adanya...
  //   <<<END_ZOZ_FILE>>>
  const TICK3 = String.fromCharCode(96).repeat(3);

  function getFileStudioDirective() {
    return `### INSTRUKSI SISTEM: AI FILE STUDIO & DIAGRAM VISUAL OTONOM

1. PEMBUATAN & PENGEDITAN BERKAS / DOKUMEN:
Saat pengguna meminta sebuah berkas — website, script (.bat/.py/.sh/.ps1), konfigurasi, dokumen, atau diagram:
<<<ZOZ_FILE name="Nama_Berkas_Spesifik.ekstensi" mime="tipe/mime" lang="bahasa">
isi lengkap file, siap pakai, tanpa potongan
<<<END_ZOZ_FILE>>>

ATURAN WAJIB PENAMAAN BERKAS (AI HARUS MENENTUKAN NAMA SPESIFIK & DESKRIPTIF):
- AI HARUS menentukan nama berkas yang spesifik, relevan, dan sangat deskriptif sesuai topik/isi yang diminta pengguna!
- Untuk Diagram Visual: Gunakan ekstensi .svg seperti "Alur_Verifikasi_Email.svg", "Arsitektur_Logika_AI_Agent.svg", "Arsitektur_Sistem.svg", "ERD_Database_Toko.svg". DILARANG KERAS menggunakan ekstensi .mermaid atau nama generik seperti "file.svg" atau "diagram.svg"!
- Untuk Dokumen Word/PDF: Gunakan "Panduan_Implementasi_API.docx", "Laporan_Analisis_Sistem.pdf", "Rencana_Proyek_2026.docx". DILARANG KERAS menggunakan nama generik seperti "file.docx", "file.pdf", "Dokumen.docx"!
- Jangan gunakan spasi pada nama file, gunakan underscore (_) atau dash (-).

KEMAMPUAN DOKUMEN OTONOM (PDF & WORD .DOCX):
- Jika pengguna meminta berkas Word (.docx) atau PDF (.pdf), gunakan:
  <<<ZOZ_FILE name="Nama_Dokumen_Spesifik.docx" mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document" lang="markdown">>>
  atau
  <<<ZOZ_FILE name="Nama_Dokumen_Spesifik.pdf" mime="application/pdf" lang="markdown">>>
- Tulis isinya dalam format Markdown terstruktur yang rapi (judul #, ##, ###, bullet points -, bold **teks**, tabel, pemisah ---).
- Mesin ZOZ Document Compiler akan secara otomatis mengompilasi teks Markdown ini menjadi berkas biner murni .docx (Office Open XML) atau .pdf (Adobe Acrobat) yang valid dan siap langsung dibuka di Microsoft Word / Acrobat Reader di laptop maupun HP pengguna!

2. PEMBUATAN DIAGRAM VISUAL INTERAKTIF (.SVG) (STANDAR KUALITAS CLAUDE AI - BERSIH, RAPI & MUDAH DIBACA):
- Saat pengguna meminta diagram alur (flowchart), alur logika, urutan proses (sequence diagram), struktur kelas, ERD, mindmap, atau arsitektur sistem:
- AI membungkusnya dalam blok ZOZ_FILE berekstensi .svg:
<<<ZOZ_FILE name="Alur_Kerja_AI_Agent.svg" mime="image/svg+xml" lang="mermaid">
flowchart TD
    A["<b>Input Pengguna</b><br/>Tujuan atau perintah"] --> B["<b>LLM (Otak Agen)</b><br/>Menalar dan merencanakan"]
    B <--> C["<b>Memori</b><br/>Pendek dan panjang"]
    B --> D["<b>Pemilihan Alat</b><br/>Pencarian, kode, API"]
    D --> E["<b>Observasi</b><br/>Hasil dari alat"]
    E -->|jika selesai| F["<b>Jawaban Akhir</b><br/>Solusi terverifikasi"]
    E -.->|ulangi| B

    classDef default fill:#111827,stroke:#38bdf8,stroke-width:1.5px,color:#f8fafc;
    classDef brain fill:#1e1b4b,stroke:#818cf8,stroke-width:2px,color:#e0e7ff;
    classDef action fill:#2d1515,stroke:#fb923c,stroke-width:1.5px,color:#ffedd5;
    class B,C brain;
    class D,E action;
<<<END_ZOZ_FILE>>>

PRINSIP WAJIB DIAGRAM RAPI, BERSIH & JELAS (TIDAK BERANTAKAN):
1. Fokus & Terarah (KISS Principle): Batasi diagram pada 4 - 8 kotak alur inti paling esensial. JANGAN membuat diagram laba-laba raksasa dengan puluhan kotak kecil bertumpuk yang membuat garis panah saling bertabrakan atau teks kekecilan.
2. Format Kotak 2-Baris Elegan:
   - Baris 1: Judul Komponen tebal: <b>Judul Utama</b>
   - Baris 2: Deskripsi peran singkat: <br/>Peran atau tindakan singkat
   - Selalu apit teks label kotak dengan tanda kutip dua: ["<b>...</b><br/>..."]
3. Arah Alur Linier & Rapi: Gunakan "flowchart TD" (vertikal atas ke bawah). Tempatkan cabang pendukung (seperti Memori) di sisi samping node terkait, dan garis perulangan (loopback) berupa panah putus-putus rapi di sisi samping (-.->|ulangi|).
4. Palet Warna Harmonis & Elegan: Gunakan classDef lembut sesuai peran (misal: Indigo untuk pemrosesan/otak, Amber untuk aksi/tool, Cyan untuk input/output). JANGAN gunakan warna neon keras atau warna-warni acak yang menyilaukan mata.
5. Uraian Penjelasan Terstruktur Pasca-Diagram:
   Setelah blok diagram, WAJIB berikan pengantar dan uraian bernomor yang ramah, mendalam, dan terstruktur mengenai fungsi tiap komponen (seperti format penjelasan Claude AI).

Aturan wajib:
- name : nama file final yang deskriptif dan spesifik berakhiran .svg / .docx / .pdf / .html / .js / dsb.
- Isi berkas HARUS lengkap, valid, dan langsung bisa dijalankan/dibuka — bukan pseudocode atau potongan.
- Jangan menyalin ulang kode diagram di luar blok penanda, cukup berikan teks penjelasan yang informatif.`;
  }

  // Deteksi niat pengguna meminta pembuatan atau pengeditan/modifikasi file (Bahasa Indonesia + Inggris)
  function isFileGenerationRequest(text) {
    if (!text || typeof text !== 'string') return false;
    const t = text.toLowerCase();
    const wants = /\b(?:buatkan|buat|bikin|bikinkan|tolong buat|generate|create|write|tulis|simpan sebagai|unduh|download|export|ekspor|saya butuh file|saya minta file|butuh file|perlukan file|bikinkan file|edit|mengedit|mengdit|modifikasi|memodifikasi|ubah|mengubah|perbarui|memperbarui|update|revisi|merevisi|perbaiki|memperbaiki|tambahkan ke|tambah|ganti)\b/i.test(t);
    const target = /\b(?:file|berkas|dokumen|script|skrip|kode program|program|website|situs|halaman web|landing|aplikasi|utilitas|tool|bot|konfigurasi|template|lampiran|readme|kodenya|skripnya|filenya|dokumennya|diagram|flowchart|alur|arsitektur visual)\b|\.(?:html?|css|js|ts|py|bat|ps1|sh|sql|json|csv|xml|ya?ml|md|txt|docx|pdf|xlsx|ipynb|svg)\b/i.test(t);
    // Jika direktori lokal aktif dan pengguna menyebut nama berkas yang ada di direktori
    const workspaceMatch = STATE.localWorkspace.enabled && (STATE.localWorkspace.files || []).some(f => {
      const baseName = f.name.replace(/\.[^/.]+$/, '').toLowerCase();
      return t.includes(f.name.toLowerCase()) || (baseName.length >= 3 && t.includes(baseName));
    });
    return (wants && target) || (wants && workspaceMatch);
  }

  function formatFileSize(bytes) {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
  }

  function guessMimeFromName(name) {
    const ext = (String(name).split('.').pop() || '').toLowerCase();
    const map = { html: 'text/html', htm: 'text/html', css: 'text/css', js: 'text/javascript', mjs: 'text/javascript', jsx: 'text/plain', ts: 'text/plain', py: 'text/x-python', bat: 'application/bat', cmd: 'application/bat', ps1: 'text/plain', sh: 'application/x-sh', bash: 'application/x-sh', json: 'application/json', yaml: 'text/yaml', yml: 'text/yaml', xml: 'application/xml', sql: 'text/plain', csv: 'text/csv', md: 'text/markdown', markdown: 'text/markdown', txt: 'text/plain', log: 'text/plain', php: 'text/x-php', java: 'text/plain', c: 'text/plain', cpp: 'text/plain', go: 'text/plain', toml: 'text/plain', ini: 'text/plain', conf: 'text/plain', svg: 'image/svg+xml', mermaid: 'image/svg+xml', mmd: 'image/svg+xml', docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', pdf: 'application/pdf' };
    return map[ext] || 'text/plain';
  }

  function guessLangFromName(name) {
    const ext = (String(name).split('.').pop() || '').toLowerCase();
    const map = { html: 'html', htm: 'html', css: 'css', js: 'javascript', mjs: 'javascript', jsx: 'javascript', ts: 'typescript', py: 'python', bat: 'batch', ps1: 'powershell', sh: 'shell', bash: 'shell', json: 'json', yaml: 'yaml', yml: 'yaml', xml: 'xml', sql: 'sql', md: 'markdown', markdown: 'markdown', php: 'php', java: 'java', c: 'c', cpp: 'cpp', go: 'go', csv: 'csv', txt: 'text', svg: 'mermaid', mermaid: 'mermaid', mmd: 'mermaid', docx: 'markdown', pdf: 'markdown' };
    return map[ext] || (ext || 'text');
  }

  function guessFileNameFromLang(lang, body = '') {
    const cleanLang = String(lang || '').toLowerCase().trim();
    const isMermaid = cleanLang === 'mermaid' || cleanLang === 'mmd' || (cleanLang === 'svg' && isAuthenticMermaidSyntax(body));

    if (isMermaid) {
      return generateUniqueDiagramFilename(body, null, 'svg');
    }

    if (cleanLang === 'docx' || cleanLang === 'pdf' || cleanLang === 'md' || cleanLang === 'markdown') {
      const hMatch = String(body || '').match(/^#\s+([^\r\n]+)/m);
      if (hMatch && hMatch[1]) {
        const cleanH = sanitizeTitle(hMatch[1]);
        const ext = cleanLang === 'docx' ? 'docx' : (cleanLang === 'pdf' ? 'pdf' : 'md');
        if (cleanH.length >= 3) return `${cleanH}.${ext}`;
      }
    }

    const map = {
      html: 'index.html', css: 'styles.css', javascript: 'script.js', js: 'script.js',
      typescript: 'main.ts', ts: 'main.ts', python: 'main.py', py: 'main.py',
      bash: 'run.sh', sh: 'run.sh', shell: 'run.sh', batch: 'run.bat', bat: 'run.bat',
      powershell: 'script.ps1', ps1: 'script.ps1', json: 'data.json', yaml: 'config.yaml',
      yml: 'config.yaml', xml: 'data.xml', sql: 'query.sql', php: 'index.php',
      java: 'Main.java', c: 'main.c', cpp: 'main.cpp', go: 'main.go', csv: 'data.csv',
      markdown: 'README.md', md: 'README.md', text: 'catatan.txt', txt: 'catatan.txt',
      docx: 'Dokumen_Laporan.docx', pdf: 'Dokumen_Laporan.pdf',
      svg: 'Diagram_Alur_Sistem.svg', mermaid: 'Diagram_Alur_Sistem.svg'
    };
    return map[cleanLang] || ('berkas_' + Date.now().toString(36).slice(-4) + '.' + (cleanLang || 'txt'));
  }

  function sanitizeSmartFileName(name, lang, content) {
    let cleanName = String(name || '').trim();

    // Pastikan berkas diagram menggunakan ekstensi .svg, bukan .mermaid atau .mmd
    if (/\.(?:mermaid|mmd)$/i.test(cleanName)) {
      cleanName = cleanName.replace(/\.(?:mermaid|mmd)$/i, '.svg');
    }

    const cleanLang = String(lang || '').toLowerCase().trim();
    // Berkas HANYA dianggap diagram jika bahasa eksplisit mermaid/mmd atau berkas .svg dengan sintaks Mermaid otentik
    const isMermaid = cleanLang === 'mermaid' || cleanLang === 'mmd' ||
      (cleanName.toLowerCase().endsWith('.svg') && isAuthenticMermaidSyntax(content));

    if (isMermaid && !cleanName.toLowerCase().endsWith('.svg')) {
      cleanName = cleanName.replace(/\.[a-z0-9]+$/i, '') + '.svg';
    }

    const lower = cleanName.toLowerCase();
    const isGeneric = !cleanName ||
      lower === 'file.svg' || lower === 'diagram.svg' || lower === 'chart.svg' || lower === 'untitled.svg' ||
      lower === 'diagram_alur_sistem.svg' || lower === 'diagram_alur_logika.svg' || lower === 'arsitektur_sistem.svg' ||
      lower === 'file.mermaid' || lower === 'diagram.mermaid' || lower === 'chart.mermaid' || lower === 'untitled.mermaid' ||
      lower === 'file.docx' || lower === 'dokumen.docx' || lower === 'document.docx' || lower === 'dokumen_laporan.docx' ||
      lower === 'file.pdf' || lower === 'dokumen.pdf' || lower === 'document.pdf' || lower === 'dokumen_laporan.pdf' ||
      lower === 'file.txt' || lower === 'untitled.txt' || lower === 'catatan.txt' || lower === 'readme.md';

    if (isGeneric) {
      const ext = lower.split('.').pop() || lang || (isMermaid ? 'svg' : 'txt');
      cleanName = guessFileNameFromLang(ext, content);
    }
    return cleanName || 'berkas.svg';
  }

  function getFileIconClass(name) {
    const ext = (String(name || '').split('.').pop() || '').toLowerCase();
    const map = {
      html: 'fa-brands fa-html5', htm: 'fa-brands fa-html5',
      css: 'fa-brands fa-css3-alt', js: 'fa-brands fa-js', mjs: 'fa-brands fa-js', jsx: 'fa-brands fa-react',
      ts: 'fa-solid fa-code', py: 'fa-brands fa-python',
      bat: 'fa-solid fa-terminal', cmd: 'fa-solid fa-terminal', ps1: 'fa-solid fa-terminal',
      sh: 'fa-solid fa-terminal', bash: 'fa-solid fa-terminal',
      json: 'fa-solid fa-braces', yaml: 'fa-solid fa-gears', yml: 'fa-solid fa-gears',
      xml: 'fa-solid fa-code', sql: 'fa-solid fa-database',
      md: 'fa-brands fa-markdown', markdown: 'fa-brands fa-markdown',
      txt: 'fa-solid fa-file-lines', log: 'fa-solid fa-file-lines', csv: 'fa-solid fa-table',
      php: 'fa-brands fa-php', java: 'fa-brands fa-java', go: 'fa-solid fa-microchip',
      docx: 'fa-solid fa-file-word', pdf: 'fa-solid fa-file-pdf',
      svg: 'fa-solid fa-diagram-project', mermaid: 'fa-solid fa-diagram-project', mmd: 'fa-solid fa-diagram-project'
    };
    return map[ext] || 'fa-solid fa-file-code';
  }

  function buildAIFile(name, mime, lang, content, desc) {
    const cleanName = sanitizeSmartFileName(name, lang, content);
    let bytes = 0;
    try { bytes = new Blob([content]).size; } catch (_) { bytes = String(content).length; }
    const lineCount = String(content).split('\n').length;
    return {
      name: cleanName,
      mime: mime || guessMimeFromName(cleanName),
      lang: lang || guessLangFromName(cleanName),
      content: String(content),
      // M1: TANPA rawContent duplikat — dulu string yang sama disimpan dua kali
      // (content + rawContent) dan mirror localStorage ikut mem-serialize keduanya →
      // payload AI File membengkak 2× dan kuota ~5MB 'zoz_router_sessions_v1' mudah
      // pecah (fallback-nya menulis messages: [] → badan pesan hilang dari mirror).
      // Semua pembaca memakai `file.rawContent || file.content` sehingga aman.
      byteSize: bytes,
      lineCount: lineCount,
      size: formatFileSize(bytes) + ' • ' + lineCount + ' baris',
      desc: desc || '',
      isGeneratedByAI: true
    };
  }

  function renderAttachmentPreviews() {
    if (!els.attachmentPreviewBar) return;
    const hasImages = STATE.attachedImages && STATE.attachedImages.length > 0;
    const hasDocs = STATE.attachedDocs && STATE.attachedDocs.length > 0;

    if (!hasImages && !hasDocs) {
      els.attachmentPreviewBar.style.display = 'none';
      return;
    }

    els.attachmentPreviewBar.style.display = 'flex';

    // Clear existing preview cards & chips
    els.attachmentPreviewBar.querySelectorAll('.preview-card, .doc-preview-chip').forEach(c => c.remove());

    // Append Image Preview Cards
    if (hasImages) {
      STATE.attachedImages.forEach((imgSrc, idx) => {
        const card = document.createElement('div');
        card.className = 'preview-card';
        card.title = 'Klik untuk melihat foto layar penuh';
        card.innerHTML = `
          <img src="${escapeHtml(imgSrc)}" alt="Lampiran Foto ${idx + 1}" loading="lazy" decoding="async">
          <button class="remove-attachment-btn" data-img-idx="${idx}" title="Hapus Foto"><i class="fa-solid fa-xmark"></i></button>
        `;
        card.querySelector('img').addEventListener('click', (e) => {
          e.stopPropagation();
          ImageLightbox.open(STATE.attachedImages, idx);
        });
        card.querySelector('.remove-attachment-btn').addEventListener('click', (e) => {
          e.stopPropagation();
          removeAttachedImage(idx);
        });
        els.attachmentPreviewBar.appendChild(card);
      });
    }

    // Append Doc Chips
    if (hasDocs) {
      STATE.attachedDocs.forEach((doc, idx) => {
        const isMarkdownOrCode = Boolean(doc.isAutoConvertedMarkdown || (doc.name && /\.(?:md|markdown|js|ts|py|html|css|json|sql|sh|txt)$/i.test(doc.name)));
        const iconClass = isMarkdownOrCode ? 'fa-solid fa-file-code' : 'fa-solid fa-file-lines';
        const chip = document.createElement('div');
        chip.className = 'doc-preview-chip';
        chip.title = 'Klik untuk pratinjau isi dokumen atau kode';
        chip.style.cursor = 'pointer';
        chip.innerHTML = `
          <i class="${iconClass} doc-icon"></i>
          <span class="doc-name" title="${escapeHtml(doc.name)}">${escapeHtml(doc.name)}</span>
          <span class="doc-size">(${escapeHtml(doc.size)})</span>
          <button class="remove-doc-btn" data-idx="${idx}" title="Hapus file"><i class="fa-solid fa-xmark"></i></button>
        `;
        chip.addEventListener('click', (e) => {
          if (e.target.closest('.remove-doc-btn')) return;
          openDocPreviewModal(doc, idx);
        });
        chip.querySelector('.remove-doc-btn').addEventListener('click', (e) => {
          e.stopPropagation();
          removeAttachedDoc(idx);
        });
        els.attachmentPreviewBar.appendChild(chip);
      });
    }
  }

  function isPreviewableDoc(file) {
    if (!file) return false;
    const name = String(file.name || '').toLowerCase();
    const mime = String(file.mime || '').toLowerCase();
    if (mime.includes('text/html') || mime.includes('application/pdf') || mime.includes('wordprocessingml') || mime.includes('text/markdown') || mime.includes('mermaid')) return true;
    const ext = name.split('.').pop() || '';
    return ['html', 'htm', 'xhtml', 'svg', 'docx', 'pdf', 'md', 'markdown', 'txt', 'mermaid', 'mmd'].includes(ext);
  }

  function isPreviewableHtmlFile(file) {
    return isPreviewableDoc(file);
  }

  function setAIFileStudioTab(tab) {
    const isPreview = tab === 'preview';
    if (els.aiFileStudioPreviewPane) els.aiFileStudioPreviewPane.classList.toggle('hidden', !isPreview);
    if (els.aiFileStudioCode) els.aiFileStudioCode.classList.toggle('active', !isPreview);
    if (els.aiFileStudioTabs) {
      els.aiFileStudioTabs.querySelectorAll('.ai-file-tab').forEach((b) => {
        b.classList.toggle('active', b.dataset.tab === tab);
      });
    }
  }

  function openAIFileStudio(file) {
    if (!file) return;
    if (file.name && /\.(?:mermaid|mmd)$/i.test(file.name)) {
      file.name = file.name.replace(/\.(?:mermaid|mmd)$/i, '.svg');
    }
    activeAIFile = file;
    if (els.aiFileStudioTitle) {
      els.aiFileStudioTitle.innerHTML = `<i class="fa-solid fa-wand-magic-sparkles"></i> ${escapeHtml(file.name)}`;
    }
    if (els.aiFileStudioMeta) {
      els.aiFileStudioMeta.textContent = file.name + ' • ' + (file.size || '') + (file.desc ? ' — ' + file.desc : '');
    }

    const previewable = isPreviewableDoc(file);
    const ext = (file.name || '').split('.').pop().toLowerCase();
    const rawContent = file.rawContent || file.content || '';
    const isDocx = ext === 'docx';
    const isPdf = ext === 'pdf';
    const isMarkdown = ext === 'md' || ext === 'markdown';
    const isHtml = ext === 'html' || ext === 'htm' || ext === 'xhtml';
    const isMermaid = ext === 'mermaid' || ext === 'mmd' || file.lang === 'mermaid' || file.lang === 'mmd' ||
      (ext === 'svg' && !rawContent.trim().startsWith('<svg') && !rawContent.trim().startsWith('<?xml') && isAuthenticMermaidSyntax(rawContent));
    const isPureSvg = ext === 'svg' && !isMermaid;
    const isDiagram = isDiagramFile(file);

    if (els.aiFileStudioDownloadCaret) {
      els.aiFileStudioDownloadCaret.style.display = isDiagram ? 'inline-block' : 'none';
    }
    if (els.aiFileStudioDownloadMenu) {
      els.aiFileStudioDownloadMenu.style.display = 'none';
    }
    if (els.aiFileStudioDownloadText) {
      els.aiFileStudioDownloadText.textContent = isDiagram ? 'Unduh Diagram' : 'Unduh File';
    }

    setAIFileStudioTab(previewable ? 'preview' : 'code');

    if (els.aiFileStudioCode) {
      els.aiFileStudioCode.textContent = rawContent;
      try {
        if (window.hljs && els.aiFileStudioCode.removeAttribute) {
          els.aiFileStudioCode.removeAttribute('data-highlighted');
          window.hljs.highlightElement(els.aiFileStudioCode);
        }
      } catch (_) {}
    }
    if (els.aiFileStudioFrame) {
      if (isMermaid) {
        els.aiFileStudioFrame.removeAttribute('src');
        const cleanMermaid = getCleanMermaidCode(rawContent);
        const tempId = 'aiStudioMermaid_' + Math.random().toString(36).substr(2, 6);
        if (typeof window.mermaid !== 'undefined' && typeof window.mermaid.render === 'function') {
          try {
            initMermaidEngine();
            window.mermaid.render(tempId, cleanMermaid).then(res => {
              if (res && res.svg) {
                file.svgContent = res.svg;
                els.aiFileStudioFrame.srcdoc = generateMermaidDocPreviewHtml(file.name, res.svg);
              }
            }).catch(async (err) => {
              console.warn('Percobaan pertama render mermaid gagal, mencoba pembersih sekunder:', err);
              try {
                const cleanSecondary = getAggressiveMermaidCleaner(cleanMermaid);
                const res2 = await window.mermaid.render(tempId + '_sec', cleanSecondary);
                if (res2 && res2.svg) {
                  file.svgContent = res2.svg;
                  els.aiFileStudioFrame.srcdoc = generateMermaidDocPreviewHtml(file.name, res2.svg);
                  return;
                }
              } catch (_) {}

              console.warn('Gagal merender diagram di file studio:', err);
              els.aiFileStudioFrame.srcdoc = generateMermaidDocPreviewHtml(file.name, `
                <div style="color:#f87171; background:rgba(239,68,68,0.1); border:1px solid rgba(239,68,68,0.3); padding:16px; border-radius:6px; font-size:13px; text-align:center;">
                  ⚠️ Diagram memerlukan penyesuaian sintaks untuk dirender secara visual.<br>
                  <small style="color:#94a3b8; margin-top:8px; display:inline-block;">Buka tab "Kode Sumber" untuk melihat dan mengedit kode diagram Mermaid.</small>
                </div>
              `);
            });
          } catch (err) {
            els.aiFileStudioFrame.srcdoc = generateMermaidDocPreviewHtml(file.name, `
              <div style="color:#f87171; padding:16px; text-align:center;">
                ⚠️ Mesin visualisasi Mermaid belum siap. Silakan lihat tab Kode Sumber.
              </div>
            `);
          }
        } else {
          els.aiFileStudioFrame.srcdoc = generateMermaidDocPreviewHtml(file.name, `
            <div style="color:#f87171; padding:16px; text-align:center;">
              ⚠️ Mesin visualisasi Mermaid belum termuat. Silakan lihat tab Kode Sumber.
            </div>
          `);
        }
      } else if (isPureSvg) {
        els.aiFileStudioFrame.removeAttribute('src');
        els.aiFileStudioFrame.srcdoc = generateMermaidDocPreviewHtml(file.name, rawContent);
      } else if (isDocx || isMarkdown) {
        const parsedBody = (window.marked && window.marked.parse) ? window.marked.parse(rawContent) : escapeHtml(rawContent);
        els.aiFileStudioFrame.removeAttribute('src');
        els.aiFileStudioFrame.srcdoc = generateWordDocPreviewHtml(file.name, parsedBody);
      } else if (isPdf) {
        const parsedBody = (window.marked && window.marked.parse) ? window.marked.parse(rawContent) : escapeHtml(rawContent);
        els.aiFileStudioFrame.removeAttribute('src');
        els.aiFileStudioFrame.srcdoc = generatePdfDocPreviewHtml(file.name, parsedBody);
      } else if (isHtml) {
        els.aiFileStudioFrame.removeAttribute('src');
        els.aiFileStudioFrame.srcdoc = rawContent;
      } else {
        els.aiFileStudioFrame.removeAttribute('src');
        els.aiFileStudioFrame.srcdoc = '';
      }
    }
    if (els.aiFileStudioPlaceholder) {
      els.aiFileStudioPlaceholder.classList.toggle('show', !previewable);
    }

    const existingFile = findWorkspaceFile(file.name) || file.existingFile;
    const isWorkspace = Boolean(STATE.localWorkspace.enabled) && Boolean(existingFile || file.isEdit);
    if (els.aiFileStudioSaveDiskBtn) {
      if (isWorkspace) {
        els.aiFileStudioSaveDiskBtn.style.display = 'inline-flex';
        els.aiFileStudioSaveDiskBtn.innerHTML = (file.isEdit || existingFile)
          ? '<i class="fa-solid fa-floppy-disk"></i> Simpan Langsung ke Direktori'
          : '<i class="fa-solid fa-folder-plus"></i> Simpan ke Direktori Lokal';
      } else {
        els.aiFileStudioSaveDiskBtn.style.display = 'none';
      }
    }

    openModal('aiFileStudioModal');
  }

  function isDiagramFile(file) {
    if (!file) return false;
    const n = (file.name || '').toLowerCase();
    const raw = file.rawContent || file.content || '';
    const l = (file.lang || '').toLowerCase();
    if (n.endsWith('.mermaid') || n.endsWith('.mmd') || l === 'mermaid' || l === 'mmd') return true;
    if (n.endsWith('.svg') || file.mime === 'image/svg+xml') {
      if (raw.trim().startsWith('<svg') || raw.trim().startsWith('<?xml')) return false; // Pure vector SVG
      return isAuthenticMermaidSyntax(raw);
    }
    return false;
  }

  async function convertSvgToJpegBlob(svgInput, options = {}) {
    let svgStr = typeof svgInput === 'string' ? svgInput : new XMLSerializer().serializeToString(svgInput);
    const rawMermaidCode = options.mermaidCode || null;

    // Render untainted SVG dengan htmlLabels: false jika kode mermaid tersedia (mencegah foreignObject tainted canvas)
    if (typeof window.mermaid !== 'undefined' && typeof window.mermaid.render === 'function') {
      try {
        if (rawMermaidCode) {
          window.mermaid.initialize({
            startOnLoad: false,
            theme: 'dark',
            securityLevel: 'loose',
            fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif',
            themeVariables: {
              fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif',
              fontSize: '14px',
              primaryTextColor: '#f8fafc',
              textColor: '#f8fafc'
            },
            flowchart: {
              htmlLabels: false,
              useMaxWidth: false,
              curve: 'basis',
              nodeSpacing: 50,
              rankSpacing: 55,
              padding: 24
            },
            sequence: {
              useMaxWidth: false,
              actorFontSize: 14,
              noteFontSize: 13,
              messageFontSize: 13
            }
          });
          const cleanDiagram = getCleanMermaidCodeForRaster(rawMermaidCode);
          const rasterRes = await window.mermaid.render('raster_jpeg_' + Date.now(), cleanDiagram);
          if (rasterRes && rasterRes.svg) {
            svgStr = rasterRes.svg;
          }
          initMermaidEngine();
        }
      } catch (mErr) {
        console.warn('Gagal merender SVG htmlLabels:false, menggunakan pembersih fallback:', mErr);
        try { initMermaidEngine(); } catch (_) {}
      }
    }

    // Safety sanitize fallback: Jika SVG masih memiliki <foreignObject>, konversi ke elemen teks SVG murni multiline yang terpusat
    if (svgStr.includes('<foreignObject')) {
      svgStr = svgStr.replace(/<foreignObject\b([^>]*)>([\s\S]*?)<\/foreignObject>/gi, (m, attrs, body) => {
        const xMatch = attrs.match(/x=["']([^"']*)["']/i);
        const yMatch = attrs.match(/y=["']([^"']*)["']/i);
        const wMatch = attrs.match(/width=["']([^"']*)["']/i);
        const hMatch = attrs.match(/height=["']([^"']*)["']/i);
        const x = xMatch ? parseFloat(xMatch[1]) : 0;
        const y = yMatch ? parseFloat(yMatch[1]) : 0;
        const w = wMatch ? parseFloat(wMatch[1]) : 120;
        const h = hMatch ? parseFloat(hMatch[1]) : 40;

        let cleanText = body
          .replace(/<br\s*\/?>/gi, '\n')
          .replace(/<\/p>|<\/div>/gi, '\n')
          .replace(/<[^>]+>/g, '')
          .replace(/&gt;/g, '>')
          .replace(/&lt;/g, '<')
          .replace(/&amp;/g, '&')
          .replace(/&quot;/g, '"')
          .replace(/&#39;/g, "'")
          .trim();

        const lines = cleanText.split('\n').map(l => l.trim()).filter(Boolean);
        if (lines.length === 0) return '';

        const centerX = x + (w / 2);
        const startY = y + (h / 2) - ((lines.length - 1) * 8) + 4;
        const tspans = lines.map((line, idx) => {
          const dy = idx === 0 ? '0' : '16';
          const weight = idx === 0 ? 'font-weight="600"' : '';
          return `<tspan x="${centerX}" dy="${dy}" ${weight}>${escapeHtml(line)}</tspan>`;
        }).join('');

        return `<text x="${centerX}" y="${startY}" fill="#e2e8f0" font-size="13" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" text-anchor="middle">${tspans}</text>`;
      });
    }

    // Post-sanitize SVG: hilangkan artefak kode HTML mentah atau entitas lolos dalam elemen teks/tspan SVG
    svgStr = svgStr
      .replace(/&lt;b&gt;/gi, '')
      .replace(/&lt;\/b&gt;/gi, '')
      .replace(/&lt;br\s*\/?&gt;/gi, ' ')
      .replace(/&lt;\/?(?:strong|i|em|u|span|font)(?:\s+[^>]*)?&gt;/gi, '')
      .replace(/<b\b[^>]*>/gi, '')
      .replace(/<\/b>/gi, '')
      .replace(/<br\s*\/?>/gi, ' ')
      .replace(/<\/?(?:strong|i|em|u|span|font)(?:\s+[^>]*)?>/gi, '')
      .replace(/&amp;amp;/g, '&amp;');

    // Suntikkan font keluarga sistem universal agar rendering canvas Image() konsisten di desktop dan mobile
    const fontInject = '<style>text, tspan, .node text, .cluster text, .edgeLabel { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif !important; }</style>';
    svgStr = svgStr.replace(/<svg\b([^>]*)>/i, '$&' + fontInject);

    // Dimensions
    let width = options.width || 0;
    let height = options.height || 0;
    const viewBoxMatch = svgStr.match(/viewBox=["']([0-9.\s-]+)["']/i);
    if (viewBoxMatch && viewBoxMatch[1]) {
      const parts = viewBoxMatch[1].trim().split(/[\s,]+/).map(Number);
      if (parts.length === 4 && parts[2] > 0 && parts[3] > 0) {
        width = parts[2];
        height = parts[3];
      }
    }
    if (!width || !height) {
      const wMatch = svgStr.match(/width=["']([0-9.]+)(?:px)?["']/i);
      const hMatch = svgStr.match(/height=["']([0-9.]+)(?:px)?["']/i);
      if (wMatch && wMatch[1]) width = parseFloat(wMatch[1]);
      if (hMatch && hMatch[1]) height = parseFloat(hMatch[1]);
    }
    if (!width || !height || isNaN(width) || isNaN(height)) {
      width = 900;
      height = 650;
    }

    const padding = 32;
    const totalWidth = width + (padding * 2);
    const totalHeight = height + (padding * 2);

    if (!svgStr.includes('xmlns=')) {
      svgStr = svgStr.replace('<svg', '<svg xmlns="http://www.w3.org/2000/svg"');
    }
    svgStr = svgStr.replace(/<svg\b([^>]*)>/i, (m, attrs) => {
      let cleanAttrs = attrs
        .replace(/\bwidth=["'][^"']*["']/gi, '')
        .replace(/\bheight=["'][^"']*["']/gi, '')
        .replace(/\bstyle=["'][^"']*max-width:[^;"']*(?:;)?/gi, 'style="');
      return `<svg width="${width}" height="${height}" ${cleanAttrs}>`;
    });

    const svgDataUrl = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svgStr);

    return new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => {
        try {
          const scale = options.scale || 2;
          const canvas = document.createElement('canvas');
          canvas.width = Math.round(totalWidth * scale);
          canvas.height = Math.round(totalHeight * scale);
          const ctx = canvas.getContext('2d');

          ctx.fillStyle = options.backgroundColor || '#0a0f1d';
          ctx.fillRect(0, 0, canvas.width, canvas.height);

          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'high';
          ctx.drawImage(img, padding * scale, padding * scale, width * scale, height * scale);

          canvas.toBlob((blob) => {
            if (blob) {
              resolve(blob);
            } else {
              reject(new Error('Gagal merender kanvas ke JPEG'));
            }
          }, 'image/jpeg', options.quality || 0.95);
        } catch (e) {
          reject(e);
        }
      };
      img.onerror = () => reject(new Error('Gagal memuat gambar SVG untuk konversi JPEG'));
      img.src = svgDataUrl;
    });
  }

  async function downloadAIFile(file, format = 'svg') {
    if (!file) return;
    try {
      const fileNameLower = (file.name || '').toLowerCase();
      const rawText = file.rawContent || file.content || '';
      let blob;

      const isDiagram = isDiagramFile(file);

      if (fileNameLower.endsWith('.docx')) {
        showToast('⚙ Mengompilasi dokumen Word (.docx)...', 'info');
        blob = await compileMarkdownToDocxBlob(rawText, file.name);
      } else if (fileNameLower.endsWith('.pdf')) {
        showToast('⚙ Mengompilasi dokumen PDF (.pdf)...', 'info');
        blob = await compileMarkdownToPdfBlob(rawText, file.name);
      } else if (isDiagram) {
        let svgText = file.svgContent || '';
        if (!svgText && (rawText.includes('<svg') || rawText.trim().startsWith('<svg'))) {
          svgText = rawText;
        } else if (!svgText && typeof window.mermaid !== 'undefined' && typeof window.mermaid.render === 'function') {
          const cleanCode = getCleanMermaidCode(rawText);
          const tempId = 'downloadSvg_' + Date.now();
          try {
            initMermaidEngine();
            const res = await window.mermaid.render(tempId, cleanCode);
            if (res && res.svg) svgText = res.svg;
          } catch (mErr) {
            console.warn('Gagal render mermaid saat unduh, mencoba pembersih sekunder:', mErr);
            try {
              const res2 = await window.mermaid.render(tempId + '_sec', getAggressiveMermaidCleaner(cleanCode));
              if (res2 && res2.svg) svgText = res2.svg;
            } catch (_) {}
          }
        }
        if (!svgText) {
          svgText = `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 600" width="100%" height="100%">
  <rect width="100%" height="100%" fill="#0d1117"/>
  <text x="24" y="44" fill="#38bdf8" font-family="monospace" font-size="16" font-weight="bold">${escapeHtml(file.name || 'Diagram_Visual.svg')}</text>
  <foreignObject x="24" y="64" width="852" height="512">
    <pre xmlns="http://www.w3.org/1999/xhtml" style="color:#e2e8f0; font-family:monospace; font-size:12px; white-space:pre-wrap; word-break:break-word; margin:0;">${escapeHtml(rawText)}</pre>
  </foreignObject>
</svg>`;
        }

        if (format === 'jpeg' || format === 'jpg') {
          showToast('⚙ Merasterisasi gambar JPEG resolusi tinggi...', 'info');
          blob = await convertSvgToJpegBlob(svgText, { mermaidCode: rawText });
        } else {
          showToast('⚙ Mengompilasi gambar vektor SVG...', 'info');
          blob = new Blob([svgText], { type: 'image/svg+xml;charset=utf-8' });
        }
      } else {
        blob = new Blob([file.content || ''], { type: (String(file.mime || 'text/plain')) + ';charset=utf-8' });
      }

      let safeFileName = (file.name || 'berkas.txt').replace(/[/\\?%*:|"<>]/g, '_').trim() || 'berkas.txt';
      const lowerName = safeFileName.toLowerCase();
      if (isDiagram) {
        if (lowerName.startsWith('berkas') || lowerName.startsWith('diagram') || lowerName.includes('alur_sistem') || lowerName.includes('alur_logika') || lowerName.includes('arsitektur_sistem')) {
          safeFileName = generateUniqueDiagramFilename(rawText, null, (format === 'jpeg' || format === 'jpg') ? 'jpeg' : 'svg');
        } else {
          if (format === 'jpeg' || format === 'jpg') {
            safeFileName = safeFileName.replace(/\.(?:svg|mermaid|mmd|txt)$/i, '') + '.jpeg';
          } else if (!safeFileName.toLowerCase().endsWith('.svg')) {
            safeFileName = safeFileName.replace(/\.(?:mermaid|mmd|txt)$/i, '') + '.svg';
          }
        }
      } else if (lowerName.startsWith('dokumen_laporan') || lowerName.startsWith('berkas_') || lowerName.startsWith('catatan') || lowerName === 'readme.md') {
        const hMatch = String(rawText || '').match(/^#\s+([^\r\n]+)/m);
        if (hMatch && hMatch[1]) {
          const cleanH = sanitizeTitle(hMatch[1]);
          const ext = safeFileName.split('.').pop() || 'txt';
          if (cleanH.length >= 3) safeFileName = `${cleanH}.${ext}`;
        }
      }

      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = safeFileName;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => { try { URL.revokeObjectURL(url); } catch (_) {} }, 4000);
      const formatLabel = (format === 'jpeg' || format === 'jpg') ? 'JPEG' : (isDiagram ? 'SVG' : 'berkas');
      showToast(`⬇ Berkas ${safeFileName} (${formatLabel}) berhasil diunduh.`, 'success');
      AudioEngine.click();
    } catch (err) {
      showToast('Gagal mengunduh berkas: ' + (err && err.message ? err.message : err), 'error');
    }
  }

  // Ekstrak file buatan / editan AI dari teks respons -> { files, rawBlocks }
  function extractGeneratedFiles(text, allowFallback) {
    const out = { files: [], rawBlocks: [] };
    if (!text || typeof text !== 'string') return out;
    const lines = text.split('\n');

    // --- Format utama: blok penanda ZOZ_FILE, ZOZ_EDIT, atau ZOZ_MODIFY ---
    let idx = 0;
    while (idx < lines.length) {
      const header = lines[idx].trim();
      const isFileHeader = header.indexOf('<<<ZOZ_FILE') === 0 ||
                           header.indexOf('<<<ZOZ_EDIT') === 0 ||
                           header.indexOf('<<<ZOZ_MODIFY') === 0;
      if (!isFileHeader) { idx++; continue; }
      let end = -1;
      for (let j = idx + 1; j < lines.length; j++) {
        const curLine = lines[j].trim();
        if (curLine.indexOf('<<<END_ZOZ_FILE') === 0 ||
            curLine.indexOf('<<<END_ZOZ_EDIT') === 0 ||
            curLine.indexOf('<<<END_ZOZ_MODIFY') === 0) {
          end = j;
          break;
        }
      }
      if (end < 0) { idx++; continue; }

      const nameMatch = header.match(/(?:name|file|path)=["']?([^"'\s>]+)["']?/i);
      const mimeMatch = header.match(/mime=["']?([^"'\s>]+)["']?/i);
      const langMatch = header.match(/lang=["']?([^"'\s>]+)["']?/i);
      const descMatch = header.match(/desc=["']([^"']*)["']/i);
      const content = lines.slice(idx + 1, end).join('\n');

      const rawFileName = nameMatch ? nameMatch[1] : 'file.txt';
      const isExplicitEdit = header.indexOf('<<<ZOZ_EDIT') === 0 || header.indexOf('<<<ZOZ_MODIFY') === 0;
      const matchedWorkspaceFile = findWorkspaceFile(rawFileName);
      const isWorkspaceEdit = isExplicitEdit || Boolean(matchedWorkspaceFile);

      const resolvedFileName = matchedWorkspaceFile ? matchedWorkspaceFile.name : rawFileName;
      const resolvedFilePath = matchedWorkspaceFile ? (matchedWorkspaceFile.path || matchedWorkspaceFile.name) : rawFileName;

      const fileObj = buildAIFile(
        resolvedFileName,
        mimeMatch ? mimeMatch[1] : '',
        langMatch ? langMatch[1] : '',
        content,
        descMatch ? descMatch[1] : (isWorkspaceEdit ? 'Modifikasi berkas direktori' : '')
      );
      fileObj.isEdit = isWorkspaceEdit;
      fileObj.path = resolvedFilePath;
      if (matchedWorkspaceFile) {
        fileObj.existingFile = matchedWorkspaceFile;
      }
      out.files.push(fileObj);
      out.rawBlocks.push(lines.slice(idx, end + 1).join('\n'));
      idx = end + 1;
    }

    // --- Fallback: blok kode besar saat pengguna meminta file/website tapi AI
    //     tidak memakai penanda (umum terjadi pada model kecil/tanpa tool call) ---
    if (allowFallback && out.files.length === 0) {
      for (let i = 0; i < lines.length; i++) {
        const t = lines[i].trim();
        if (t.length < 4 || t.slice(0, 3) !== TICK3) continue;
        const langTag = t.slice(3).trim().toLowerCase();
        if (!langTag || langTag === TICK3) continue;
        let end = -1;
        for (let j = i + 1; j < lines.length; j++) {
          if (lines[j].trim() === TICK3) { end = j; break; }
        }
        if (end <= i) continue;
        const body = lines.slice(i + 1, end).join('\n');
        if (body.length < 300) continue;
        out.files.push(buildAIFile(guessFileNameFromLang(langTag, body), '', langTag, body, ''));
        out.rawBlocks.push(lines.slice(i, end + 1).join('\n'));
        break;
      }
    }

    return out;
  }

  // Hapus blok file dari teks respons agar tampilan gelembung tetap rapi
  // Khusus diagram Mermaid: pertahankan sebagai blok ```mermaid``` agar langsung dirender visual di obrolan chat!
  function stripGeneratedFileBlocks(text, rawBlocks) {
    let out = String(text);
    if (Array.isArray(rawBlocks)) {
      rawBlocks.forEach((b) => {
        if (!b) return;

        // Ekstrak header blok ZOZ_FILE untuk mengetahui nama berkas dan bahasanya secara akurat
        const headerMatch = b.match(/<<<ZOZ_FILE\s+name=["']?([^"'\s>]+)["']?(?:\s+mime=["']?([^"'\s>]+)["']?)?(?:\s+lang=["']?([^"'\s>]+)["']?)?/i);
        const fileName = (headerMatch && headerMatch[1]) ? headerMatch[1].toLowerCase() : '';
        const fileLang = (headerMatch && headerMatch[3]) ? headerMatch[3].toLowerCase() : '';

        const lines = b.split('\n');
        const innerLines = [];
        let started = false;
        for (let i = 0; i < lines.length; i++) {
          const line = lines[i];
          const t = line.trim();
          if (!started) {
            if (t.startsWith('<<<ZOZ_FILE') || t.startsWith('<<<ZOZ_EDIT') || t.startsWith('<<<ZOZ_MODIFY')) {
              started = true;
            }
            continue;
          }
          if (t.startsWith('<<<END_ZOZ_FILE') || t.startsWith('<<<END_ZOZ_EDIT') || t.startsWith('<<<END_ZOZ_MODIFY')) {
            break;
          }
          innerLines.push(line);
        }
        const innerContent = innerLines.join('\n');

        // Berkas dianggap Diagram Mermaid HANYA jika secara eksplisit ditandai mermaid atau berekstensi .svg/.mermaid dengan sintaks otentik
        const isDiagram = fileLang === 'mermaid' || fileLang === 'mmd' ||
                          fileName.endsWith('.mermaid') || fileName.endsWith('.mmd') ||
                          (fileName.endsWith('.svg') && isAuthenticMermaidSyntax(innerContent));

        if (isDiagram) {
          const cleanDiagram = getCleanMermaidCode(innerContent);
          out = out.split(b).join(`\n\n\`\`\`mermaid\n${cleanDiagram}\n\`\`\`\n\n`);
        } else {
          // File kode/dokumen non-diagram dihilangkan dari teks gelembung karena sudah memiliki kartu di AI File Studio
          out = out.split(b).join('');
        }
      });
    }
    const kept = out.split('\n').filter((line) => {
      const t = line.trim();
      return t.indexOf('<<<ZOZ_FILE') !== 0 && t.indexOf('<<<END_ZOZ_FILE') !== 0 &&
             t.indexOf('<<<ZOZ_EDIT') !== 0 && t.indexOf('<<<END_ZOZ_EDIT') !== 0 &&
             t.indexOf('<<<ZOZ_MODIFY') !== 0 && t.indexOf('<<<END_ZOZ_MODIFY') !== 0 &&
             t.indexOf('<<<ZOZ_DELETE') !== 0;
    });
    const cleaned = [];
    let prevEmpty = false;
    kept.forEach((line) => {
      const isEmpty = line.trim() === '';
      if (isEmpty && prevEmpty) return;
      cleaned.push(line);
      prevEmpty = isEmpty;
    });
    return cleaned.join('\n').trim();
  }

  // Ekstrak berkas yang diminta dihapus oleh AI (<<<ZOZ_DELETE name="..." ...>>>)
  function extractDeletedFiles(text) {
    const deleted = [];
    if (!text || typeof text !== 'string') return deleted;
    const regex = /<<<ZOZ_DELETE\s+(?:name|path|file)=["']?([^"'\s>]+)["']?\s*(?:\/?>|>>>)/gi;
    let match;
    while ((match = regex.exec(text)) !== null) {
      if (match[1]) deleted.push(match[1].trim());
    }
    return deleted;
  }

  function stripDeletedFileBlocks(text) {
    if (!text || typeof text !== 'string') return text;
    return text.replace(/<<<ZOZ_DELETE\s+[^>]+>>>/gi, '').trim();
  }

  // Sanitasi teks parsial (jalur Abort / Koneksi Terputus): ekstrak blok ZOZ_FILE
  // yang sudah UTUH menjadi kartu file, lalu buang sisa marker/blok yang belum selesai
  // agar tidak ada kode mentah yang bocor ke gelembung maupun riwayat.
  function sanitizePartialResponseWithFiles(text) {
    const ex = extractGeneratedFiles(String(text || ''), false);
    let out = ex.files.length > 0 ? stripGeneratedFileBlocks(text, ex.rawBlocks) : String(text || '');
    out = hideFileBlocksForDisplay(out);
    out = safeAssistantText(out);
    return { text: out, files: ex.files };
  }

  // ==================== WORKSPACE AUTO-SAVE & APPROVAL PIPELINE ====================
  async function processAiGeneratedWorkspaceFiles(generatedFiles) {
    if (!Array.isArray(generatedFiles) || generatedFiles.length === 0) return;
    // Mode direktori lokal HANYA aktif jika pengguna memang mengaktifkannya secara eksplisit
    const hasWorkspace = Boolean(STATE.localWorkspace.enabled && STATE.localWorkspace.aiCanWrite !== false);
    if (!hasWorkspace) return;

    const requireApproval = STATE.localWorkspace.requireApproval !== false;
    for (const gf of generatedFiles) {
      let matchedWorkspaceFile = findWorkspaceFile(gf.name) || gf.existingFile;
      if (!matchedWorkspaceFile && ServerWorkspaceAPI && ServerWorkspaceAPI.isAvailable) {
        try {
          const serverContent = await ServerWorkspaceAPI.readFile(gf.name);
          if (serverContent !== null) {
            matchedWorkspaceFile = {
              name: gf.name,
              path: gf.name,
              size: serverContent.length,
              content: serverContent
            };
            if (!Array.isArray(STATE.localWorkspace.files)) STATE.localWorkspace.files = [];
            STATE.localWorkspace.files.push(matchedWorkspaceFile);
          }
        } catch (_) {}
      }

      const isEdit = Boolean(gf.isEdit || matchedWorkspaceFile);
      if (matchedWorkspaceFile) {
        gf.name = matchedWorkspaceFile.name;
        gf.path = matchedWorkspaceFile.path || matchedWorkspaceFile.name;
        gf.isEdit = true;
      }

      if (requireApproval) {
        if (!STATE.localWorkspace.pendingChanges) STATE.localWorkspace.pendingChanges = {};

        // Selesaikan semua subtask AI sebelumnya yang tertinggal in_progress
        (STATE.taskTracker.tasks || []).forEach(t => {
          if (t.status === 'in_progress') {
            t.status = 'completed';
            t.activeForm = 'Selesai';
          }
        });

        let matchedTask = (STATE.taskTracker.tasks || []).find(t =>
          (t.status === 'waiting_approval' || t.status === 'pending' || t.status === 'in_progress') &&
          (t.subject.toLowerCase().includes('simpan') || t.subject.toLowerCase().includes('save') || t.subject.toLowerCase().includes('tulis') || t.subject.toLowerCase().includes('modifikasi') || t.subject.toLowerCase().includes('edit') || t.subject.toLowerCase().includes(gf.name.toLowerCase()))
        );

        const approvalTaskId = matchedTask ? matchedTask.id : ('task-approval-' + Date.now() + '-' + Math.random().toString(36).substr(2, 4));

        if (matchedTask) {
          matchedTask.status = 'waiting_approval';
          matchedTask.activeForm = 'Menunggu Izin Pengguna...';
          matchedTask.fileName = gf.name;
          if (isEdit) {
            matchedTask.subject = `Izin modifikasi berkas "${gf.name}" di direktori lokal`;
          }
        } else {
          if (!Array.isArray(STATE.taskTracker.tasks)) STATE.taskTracker.tasks = [];
          STATE.taskTracker.tasks.push({
            id: approvalTaskId,
            subject: isEdit ? `Izin modifikasi berkas "${gf.name}" di direktori lokal` : `Izin simpan perubahan berkas "${gf.name}" ke direktori lokal`,
            status: 'waiting_approval',
            activeForm: 'Menunggu Izin Pengguna...',
            fileName: gf.name
          });
        }

        STATE.taskTracker.visible = true;
        renderTaskTrackerUI();

        STATE.localWorkspace.pendingChanges[gf.name] = {
          name: gf.name,
          path: gf.path || gf.name,
          content: gf.rawContent || gf.content || '',
          desc: gf.desc || '',
          author: 'ai',
          isEdit: isEdit,
          note: gf.desc || (isEdit ? 'Dimodifikasi oleh AI' : 'Dibuat oleh AI'),
          taskId: approvalTaskId,
          timestamp: Date.now()
        };

        gf.pendingApproval = true;
        showToast(isEdit ? `⚠️ AI meminta izin Anda untuk memodifikasi "${gf.name}" di direktori lokal` : `⚠️ AI meminta izin Anda untuk menyimpan "${gf.name}" ke direktori lokal`, 'info');
      } else {
        await createWorkspaceDocument(gf.name, gf.rawContent || gf.content || '', {
          silent: false,
          author: 'ai',
          note: gf.desc || (isEdit ? 'Dimodifikasi oleh AI' : 'Dibuat oleh AI'),
          isEdit: isEdit
        });
      }
    }
  }

  // Kartu file di dalam gelembung obrolan (dipanggil saat render live & riwayat)
  function renderMessageFiles(row, files) {
    if (!row || !Array.isArray(files) || files.length === 0) return;
    const bubble = (row.classList && row.classList.contains('message-bubble'))
      ? row
      : row.querySelector('.message-bubble');
    // Render visual diagram inline di dalam gelembung pesan jika ada file diagram Mermaid dan belum dirender
    const diagramFile = files.find(f => {
      const n = (f.name || '').toLowerCase();
      const raw = f.rawContent || f.content || '';
      const l = (f.lang || '').toLowerCase();
      return n.endsWith('.mermaid') || n.endsWith('.mmd') || l === 'mermaid' || l === 'mmd' ||
        (n.endsWith('.svg') && !raw.trim().startsWith('<svg') && !raw.trim().startsWith('<?xml') && isAuthenticMermaidSyntax(raw));
    });

    if (diagramFile) {
      const msgTextEl = bubble.querySelector('.msg-text-content');
      const alreadyHasDiagram = bubble.querySelector('.mermaid-diagram-card');
      if (!alreadyHasDiagram && msgTextEl) {
        const diagramHolder = document.createElement('div');
        diagramHolder.className = 'inline-mermaid-chat-container';
        const preEl = document.createElement('pre');
        const codeEl = document.createElement('code');
        codeEl.className = 'language-mermaid';
        codeEl.textContent = diagramFile.rawContent || diagramFile.content || '';
        preEl.appendChild(codeEl);
        diagramHolder.appendChild(preEl);
        msgTextEl.insertBefore(diagramHolder, msgTextEl.firstChild);
        enhanceCodeBlocks(diagramHolder);
      }
    }

    if (bubble.querySelector('.msg-file-cards-wrap')) return;

    const wrap = document.createElement('div');
    wrap.className = 'msg-file-cards-wrap';
    files.forEach((file) => {
      if (file && file.name && /\.(?:mermaid|mmd)$/i.test(file.name)) {
        file.name = file.name.replace(/\.(?:mermaid|mmd)$/i, '.svg');
      }
      const card = document.createElement('div');
      card.className = 'ai-file-card';
      card._aiFile = file;

      const existingFile = STATE.localWorkspace.enabled ? (findWorkspaceFile(file.name) || file.existingFile) : null;
      const isWorkspace = Boolean(STATE.localWorkspace.enabled) && Boolean(existingFile || file.isEdit);
      const isPending = Boolean(STATE.localWorkspace.enabled) && Boolean(file.pendingApproval || (STATE.localWorkspace.pendingChanges && (STATE.localWorkspace.pendingChanges[file.name] || STATE.localWorkspace.pendingChanges[file.path])));
      const isEdit = Boolean(file.isEdit || existingFile);

      let workspaceBadge = '';
      if (isPending) {
        workspaceBadge = isEdit
          ? '<span class="file-workspace-tag file-approval-pending-tag"><i class="fa-solid fa-pen-to-square"></i> Modifikasi Direktori: Menunggu Izin</span>'
          : '<span class="file-workspace-tag file-approval-pending-tag"><i class="fa-solid fa-shield-halved"></i> Berkas Baru: Menunggu Izin</span>';
      } else if (isWorkspace) {
        workspaceBadge = isEdit
          ? '<span class="file-workspace-tag file-edited-tag"><i class="fa-solid fa-folder-check"></i> Berkas Direktori Telah Diperbarui</span>'
          : '<span class="file-workspace-tag"><i class="fa-solid fa-folder-check"></i> Direktori Lokal</span>';
      }

      // TOMBOL UNDUH SELALU ADA DI SEMUA KONDISI AGAR PENGGUNA BISA MENGUNDUH KAPAN SAJA
      const isFileDiagram = isDiagramFile(file);
      let downloadButtonsHtml = '';
      if (isFileDiagram) {
        downloadButtonsHtml =
          '  <button class="ai-file-btn download download-svg" type="button" data-act="download-svg" title="Unduh gambar vektor SVG (.svg)"><i class="fa-solid fa-bezier-curve"></i> SVG</button>' +
          '  <button class="ai-file-btn download download-jpeg" type="button" data-act="download-jpeg" title="Unduh gambar foto JPEG (.jpeg)"><i class="fa-solid fa-image"></i> JPEG</button>';
      } else {
        downloadButtonsHtml =
          '  <button class="ai-file-btn download" type="button" data-act="download"><i class="fa-solid fa-download"></i> Unduh</button>';
      }

      let actionsHtml = '';
      if (isPending) {
        actionsHtml =
          '  <button class="ai-file-btn allow-pending" type="button" data-act="allow-pending" data-name="' + escapeHtml(file.name) + '"><i class="fa-solid fa-check"></i> ' + (isEdit ? 'Konfirmasi & Tulis' : 'Konfirmasi & Simpan') + '</button>' +
          '  <button class="ai-file-btn reject-pending" type="button" data-act="reject-pending" data-name="' + escapeHtml(file.name) + '"><i class="fa-solid fa-xmark"></i> Tolak</button>' +
          '  <button class="ai-file-btn preview" type="button" data-act="preview"><i class="fa-solid fa-eye"></i> Pratinjau</button>' +
          downloadButtonsHtml;
      } else if (isWorkspace) {
        actionsHtml =
          '  <button class="ai-file-btn preview" type="button" data-act="preview"><i class="fa-solid fa-eye"></i> Pratinjau</button>' +
          '  <button class="ai-file-btn open-workspace-doc" type="button" data-act="open-workspace-doc" data-name="' + escapeHtml(file.name) + '"><i class="fa-solid fa-folder-open"></i> Buka di Direktori</button>' +
          downloadButtonsHtml;
      } else {
        actionsHtml =
          '  <button class="ai-file-btn preview" type="button" data-act="preview"><i class="fa-solid fa-eye"></i> Pratinjau</button>' +
          downloadButtonsHtml;
      }

      card.innerHTML =
        '<div class="ai-file-icon"><i class="' + getFileIconClass(file.name) + '"></i></div>' +
        '<div class="ai-file-info">' +
        '  <div class="ai-file-name" title="' + escapeHtml(file.name) + '">' + escapeHtml(file.name) + ' ' + workspaceBadge + '</div>' +
        '  <div class="ai-file-meta">' + escapeHtml(file.size || '') + (isEdit ? ' • Modifikasi Berkas' : '') + '</div>' +
        (file.desc ? '  <div class="ai-file-desc" title="' + escapeHtml(file.desc) + '">' + escapeHtml(file.desc) + '</div>' : '') +
        '</div>' +
        '<div class="ai-file-actions">' + actionsHtml + '</div>';
      wrap.appendChild(card);
    });
    bubble.appendChild(wrap);
  }

  const REPUTABLE_TECH_DOMAINS = new Set([
    'reuters.com', 'bloomberg.com', 'axios.com', 'apnews.com', 'wsj.com',
    'techcrunch.com', 'theverge.com', 'wired.com', 'arstechnica.com', 'venturebeat.com',
    'engadget.com', 'zdnet.com', 'tomshardware.com', 'anandtech.com',
    'openai.com', 'anthropic.com', 'deepmind.google', 'ai.meta.com', 'blog.google',
    'microsoft.com', 'nvidia.com', 'huggingface.co', 'github.com',
    'arxiv.org', 'nature.com', 'science.org', 'technologyreview.com',
    'mit.edu', 'stanford.edu', 'bbc.com', 'cnbc.com', 'ft.com'
  ]);

  // ==================== AUTONOMOUS AI WEB SEARCH SKILL ENGINE ====================
  function synthesizeAutonomousSearchQuery(session, rawPrompt) {
    if (!rawPrompt) return '';
    const cleanPrompt = rawPrompt.trim();

    // Indonesian & English filler / stop-words
    const fillerWords = [
      'bagaimana', 'apa', 'apakah', 'kenapa', 'mengapa', 'tolong', 'coba', 'carikan', 'cari', 'jelaskan',
      'sebutkan', 'berikan', 'tampilkan', 'info', 'informasi', 'data', 'terbaru', 'terupdate', 'terkini',
      'hari ini', 'saat ini', 'sekarang', 'menurutmu', 'menurut anda', 'tentang', 'mengenai', 'bisa', 'dong',
      'kan', 'sih', 'ya', 'bro', 'min', 'how', 'what', 'why', 'tell', 'me', 'about', 'latest', 'news', 'update'
    ];

    const words = cleanPrompt.toLowerCase().replace(/[^a-z0-9\s]/gi, ' ').split(/\s+/).filter(Boolean);
    const nonFillerWords = words.filter(w => !fillerWords.includes(w) && w.length > 1);

    // Scan recent session history to extract subject context
    let contextSubject = '';
    if (session && Array.isArray(session.messages) && session.messages.length > 0) {
      // Look at the last 4 messages in reverse
      const recentMsgs = session.messages.slice(-4).reverse();
      for (const msg of recentMsgs) {
        const text = msg.content || '';
        // Extract capitalized terms, quotes, code blocks, technology names, product names
        const matches = text.match(/([A-Z][a-zA-Z0-9_\-\.\+]+(?:\s+[A-Z0-9][a-zA-Z0-9_\-\.\+]+){0,5})/g);
        if (matches && matches.length > 0) {
          const filteredMatches = matches.filter(m => !['Anda', 'AI', 'Zoz', 'Router', 'Ollama', 'OpenRouter', 'Google', 'HTTP', 'JSON'].includes(m) && m.length > 2);
          if (filteredMatches.length > 0) {
            contextSubject = filteredMatches[0];
            break;
          }
        }
        // If no capitalized match, check backticks or bold text
        const codeMatch = text.match(/`([^`]+)`|\*\*([^*]+)\*\*/);
        if (codeMatch) {
          contextSubject = codeMatch[1] || codeMatch[2];
          break;
        }
      }
    }

    // Formulate the optimal targeted query without hardcoded year noise or topic poisoning
    let finalQuery = '';
    const isAnaphoricFollowUp = nonFillerWords.length <= 2 || /\b(itu|tersebut|dia|ini|nya|it|they|them|this|that)\b/i.test(cleanPrompt);
    if (isAnaphoricFollowUp && contextSubject && !cleanPrompt.toLowerCase().includes(contextSubject.toLowerCase())) {
      const intentKeywords = nonFillerWords.length > 0 ? nonFillerWords.join(' ') : 'data spesifikasi update';
      finalQuery = `${contextSubject} ${intentKeywords}`;
    } else {
      finalQuery = `${cleanPrompt}`;
    }

    return finalQuery.replace(/\s+/g, ' ').trim();
  }

  async function getWebSearchContext(query, session = null, hudElement = null, forceRun = false) {
    if (!query || !query.trim()) return null;
    if (STATE.searchMode === 'autonomous' && !forceRun) {
      // Mode Autonomous Web Explorer menggunakan eksekusi tool dinamis on-demand oleh AI tanpa Serper API!
      return null;
    }
    const smartQuery = session ? synthesizeAutonomousSearchQuery(session, query) : query.trim();
    // Key Serper HANYA dikirim bila user benar-benar mengaturnya; tanpa key kita
    // langsung jatuh ke proxy backend (yang memakai key env milik server).
    const serperKey = (STATE.settings.serperApiKey || '').trim() || null;

    if (hudElement) {
      hudElement.innerHTML = `
        <div class="web-search-hud">
          <i class="fa-solid fa-satellite-dish fa-spin" style="color:var(--neon-cyan);"></i>
          <span><strong>AI Search Skill:</strong> Menganalisis konteks & mencari <em>"${escapeHtml(smartQuery)}"</em>...</span>
        </div>
      `;
    }

    const makeSearchSignal = (timeoutMs = 6500) => {
      const timeoutSig = AbortSignal.timeout(timeoutMs);
      if (typeof STATE !== 'undefined' && STATE?.abortController?.signal) {
        return (typeof AbortSignal.any === 'function')
          ? AbortSignal.any([timeoutSig, STATE.abortController.signal])
          : (STATE.abortController.signal || timeoutSig);
      }
      return timeoutSig;
    };

    try {
      let data = null;

      // 1. Direct browser fetch to Serper API (hanya jika user punya key sendiri)
      const isDomestic = isExplicitDomesticIndoQuery(smartQuery) || isExplicitDomesticIndoQuery(query);
      const globalQuery = (!isDomestic ? translateIndoQueryToGlobalEnglish(smartQuery) : smartQuery) || smartQuery;

      if (serperKey) {
        try {
          const directRes = await fetch('https://google.serper.dev/search', {
            method: 'POST',
            headers: {
              'X-API-KEY': serperKey,
              'Content-Type': 'application/json'
            },
            body: JSON.stringify({
              q: globalQuery,
              num: 10,
              gl: isDomestic ? 'id' : 'us', // Prioritaskan domain Indonesia HANYA jika eksplisit domestik
              hl: isDomestic ? 'id' : 'en'
            }),
            signal: makeSearchSignal(6500)
          });
          if (directRes.ok) {
            data = await directRes.json();
          }
        } catch (errDirect) {
          console.warn('Direct Serper fetch failed, trying proxy...', errDirect);
        }
      }

      // 2. Fallback to proxy /api/web-search if direct fetch failed
      if (!data) {
        const proxyHeaders = { 'Content-Type': 'application/json' };
        if (serperKey) proxyHeaders['x-serper-key'] = serperKey;
        const proxyRes = await fetch('/api/web-search', {
          method: 'POST',
          headers: proxyHeaders,
          body: JSON.stringify(serperKey ? { query: globalQuery, apiKey: serperKey, num: 10 } : { query: globalQuery, num: 10 }),
          signal: makeSearchSignal(7000)
        }).catch(() => null);
        if (proxyRes && proxyRes.ok) {
          data = await proxyRes.json();
        }
      }

      // 3. Fallback ke Zero-API Autonomous Search (/api/tools/search-web) jika Serper gagal atau tanpa hasil
      if (!data || (!data.organic?.length && !data.results?.length && !data.knowledgeGraph && !data.answerBox)) {
        try {
          const autoRes = await fetch('/api/tools/search-web', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ query: globalQuery, originalQuery: smartQuery, maxResults: 10 }),
            signal: makeSearchSignal(7500)
          }).catch(() => null);
          if (autoRes && autoRes.ok) {
            const autoData = await autoRes.json().catch(() => null);
            if (autoData && Array.isArray(autoData.results) && autoData.results.length > 0) {
              data = {
                organic: autoData.results.map(r => ({
                  title: r.title,
                  link: r.url,
                  snippet: r.snippet,
                  date: r.pubDate
                }))
              };
            }
          }
        } catch (_) {}
      }

      if (!data) return null;

      const sources = [];
      let factsBlock = '';

      // Knowledge graph
      if (data.knowledgeGraph) {
        const kg = data.knowledgeGraph;
        const kgText = `${kg.title || ''} (${kg.type || 'Fakta Ringkas'}): ${kg.description || ''}`;
        factsBlock += `\n[KNOWLEDGE GRAPH]: ${kgText}\n`;
        const kgUrl = kg.website || kg.descriptionUrl;
        if (kgUrl) {
          sources.push({
            title: kg.title || 'Knowledge Graph Fact',
            url: kgUrl,
            snippet: kg.description || '',
            domain: kgUrl.replace(/^https?:\/\//i, '').split('/')[0]
          });
        }
      }

      // Answer Box
      if (data.answerBox) {
        const ab = data.answerBox;
        const abText = ab.answer || ab.snippet || ab.title || '';
        factsBlock += `\n[JAWABAN UTAMA GOOGLE]: ${abText}\n`;
        if (ab.link) {
          sources.push({
            title: ab.title || 'Jawaban Teratas',
            url: ab.link,
            snippet: abText,
            domain: ab.link.replace(/^https?:\/\//i, '').split('/')[0]
          });
        }
      }

      // Organic search results: utamakan data.results yang sudah difilter backend, fallback ke data.organic
      const rawList = (Array.isArray(data.results) && data.results.length > 0)
        ? data.results
        : (Array.isArray(data.organic) ? data.organic : []);

      const cleanOrganicList = [];
      const seenOrganicUrls = new Set();
      for (const item of rawList) {
        const link = item.link || item.url || '';
        if (!link) continue;
        const normUrl = link.trim().toLowerCase().replace(/\/$/, '');
        const normTitle = (item.title || '').trim().toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, '');

        if (!isDomestic) {
          const isSpam = /\b(pluang|riaugreen|inforiau|riaupos|tribunnews|detik|kompas|liputan6|suara|merdeka|sindonews|viva|inews|kumparan|jpnn|kapanlagi|idntimes)\b/i.test(normUrl) || /\b(pluang|riaugreen)\b/i.test(item.domain || '');
          if (isSpam) continue;
        }
        if (normTitle.includes('listofapplecodenames') && !query.toLowerCase().includes('apple')) continue;
        if (normTitle.includes('jalanbesar') && !query.toLowerCase().includes('jalan')) continue;
        if (seenOrganicUrls.has(normUrl)) continue;
        seenOrganicUrls.add(normUrl);

        let domain = item.domain || '';
        try { domain = new URL(link).hostname.replace(/^www\./, ''); } catch (_) {}

        cleanOrganicList.push({
          title: item.title || `Sumber ${cleanOrganicList.length + 1}`,
          url: link,
          snippet: item.snippet || '',
          date: item.date || item.pubDate || null,
          domain,
          timestamp: item.timestamp || (item.date ? (Date.parse(item.date) || Date.now()) : Date.now())
        });
      }

      cleanOrganicList.sort((a, b) => {
        const aRep = REPUTABLE_TECH_DOMAINS.has(a.domain) ? 1 : 0;
        const bRep = REPUTABLE_TECH_DOMAINS.has(b.domain) ? 1 : 0;
        if (aRep !== bRep) return bRep - aRep;
        return (b.timestamp || 0) - (a.timestamp || 0);
      });

      let organicBlock = '';
      if (cleanOrganicList.length > 0) {
        cleanOrganicList.slice(0, 8).forEach((item, idx) => {
          const title = item.title;
          const link = item.url;
          const snippet = item.snippet;
          const date = item.date ? ` (Dipublikasikan: ${item.date})` : '';

          organicBlock += `\n${idx + 1}. **[${title}](${link})**${date}\n   ${snippet}\n`;
          
          if (link && !sources.some(s => s.url === link)) {
            sources.push({
              title,
              url: link,
              snippet,
              date: item.date || null,
              domain: item.domain
            });
          }
        });
      }

      if (!factsBlock && !organicBlock) return null;

      const currentTime = new Date().toLocaleString('id-ID', { dateStyle: 'full', timeStyle: 'short' });
      const systemPromptContext = `[DATA PENCARIAN GOOGLE REAL-TIME - SERPER ENGINE (AI SEARCH SKILL)]
Query Kontekstual yang Dirumuskan AI: "${smartQuery}"
Pertanyaan Pengguna: "${query}"
Waktu Pencarian: ${currentTime}
${factsBlock}
=== TEMUAN SITUS WEB TERATAS ===
${organicBlock}
[PANDUAN UNTUK ASISTEN AI]:
- Anda adalah AI yang telah mengaktifkan kemampuan Search Skill untuk mencari data Google secara otonom berdasarkan konteks obrolan.
- Hubungkan data real-time di atas dengan konteks riwayat percakapan sebelumnya dan jawab dengan akurat, mutakhir, faktual, dan komprehensif.
- FOKUS DAN RELEVANSI TINGGI: Jawablah pertanyaan pengguna secara langsung, relevan, dan terarah. Jika pengguna bertanya tentang berita atau model AI terbaru, utamakan perkembangan model AI utama terkemuka dunia (OpenAI GPT/o-series, Claude, Gemini, Meta Llama, DeepSeek, Mistral, xAI, dll.). Dilarang mengalihkan fokus ke ringkasan pergerakan saham finansial sampingan atau platform lokal kecil yang tidak relevan.
- ANTI-HALUSINASI KETAT: Dilarang keras mengarang berita, kemitraan fiktif (seperti konsorsium gabungan palsu antar raksasa teknologi), atau tanggal rilis imajiner. Hanya gunakan fakta nyata yang tercantum di hasil pencarian web di atas.
- Wajib sertakan referensi tautan markdown [Nama Sumber](URL) jika merujuk fakta spesifik.`;

      return {
        systemPromptContext,
        sources,
        query: smartQuery
      };
    } catch (e) {
      console.error('Serper Web Search Engine error:', e);
      return null;
    }
  }

