  // ==================== UNIVERSAL YOUTUBE OEMBED & CUSTOM VIDEO PLAYER ENGINE ====================
  const YOUTUBE_URL_REGEX_CLIENT = /(?:https?:\/\/)?(?:www\.|m\.|music\.)?(?:youtube\.com\/(?:watch\?(?:.*&)?v=|shorts\/|live\/|embed\/|v\/)|youtu\.be\/|(?:yewtu\.be|piped\.video|[a-z0-9.-]+\.invidious\.[a-z]+)\/(?:watch\?(?:.*&)?v=|embed\/))([a-zA-Z0-9_-]{11})(?:[^\s]*)?/gi;
  const clientYouTubeCache = new Map();

  function extractYouTubeVideoIdsClient(text) {
    if (!text || typeof text !== 'string') return [];
    const ids = [];
    const patterns = [
      /(?:https?:\/\/)?(?:www\.|m\.|music\.)?(?:youtube\.com\/(?:watch\?(?:.*&)?v=|shorts\/|live\/|embed\/|v\/)|youtu\.be\/|(?:yewtu\.be|piped\.video)\/(?:watch\?(?:.*&)?v=|embed\/))([a-zA-Z0-9_-]{11})/gi,
      /[?&]v=([a-zA-Z0-9_-]{11})/gi,
      /(?:https?:\/\/)?(?:[a-z0-9.-]+\/)?(?:watch\?v=|embed\/|shorts\/)([a-zA-Z0-9_-]{11})/gi
    ];
    for (const re of patterns) {
      let match;
      while ((match = re.exec(text)) !== null) {
        const id = match[1];
        if (id && id.length === 11 && !ids.includes(id)) {
          ids.push(id);
        }
      }
    }
    return ids;
  }

  function extractDirectVideoUrlsClient(text) {
    if (!text || typeof text !== 'string') return [];
    const urls = [];
    const re = /https?:\/\/[^\s<>"'`]+?\.(?:mp4|webm|ogv|mov)(?:\?[^\s<>"'`]*)?/gi;
    let match;
    while ((match = re.exec(text)) !== null) {
      let u = match[0].replace(/[.,;:!?)]+$/, '');
      if (u && !urls.includes(u)) {
        urls.push(u);
      }
    }
    return urls;
  }

  async function fetchYouTubeInfoClient(rawUrlOrId) {
    if (!rawUrlOrId || typeof rawUrlOrId !== 'string') return null;
    const clean = rawUrlOrId.trim();
    let videoId = null;
    let canonicalUrl = '';

    if (/^[a-zA-Z0-9_-]{11}$/.test(clean)) {
      videoId = clean;
      canonicalUrl = `https://www.youtube.com/watch?v=${videoId}`;
    } else {
      const match = clean.match(/(?:watch\?(?:.*&)?v=|shorts\/|live\/|embed\/|youtu\.be\/)([a-zA-Z0-9_-]{11})/i);
      if (match && match[1]) {
        videoId = match[1];
        canonicalUrl = `https://www.youtube.com/watch?v=${videoId}`;
      } else {
        canonicalUrl = clean;
      }
    }

    const cacheKey = videoId || canonicalUrl;
    if (clientYouTubeCache.has(cacheKey)) {
      return clientYouTubeCache.get(cacheKey);
    }

    let result = null;

    // 1. Try local server endpoint first if not github pages
    if (!IS_GITHUB_PAGES) {
      try {
        const resp = await fetch(`/api/youtube-info?url=${encodeURIComponent(canonicalUrl)}`, {
          signal: AbortSignal.timeout(8000)
        });
        if (resp.ok) {
          result = await resp.json();
        }
      } catch (err) {
        console.warn('Backend YouTube info fetch failed, trying direct oEmbed fallback:', err?.message || err);
      }
    }

    // 2. Fallback to direct YouTube oEmbed API
    if (!result || !result.success) {
      try {
        const directUrl = `https://www.youtube.com/oembed?url=${encodeURIComponent(canonicalUrl)}&format=json`;
        const resp = await fetch(directUrl, {
          signal: AbortSignal.timeout(8000)
        });
        if (resp.ok) {
          const parsed = await resp.json();
          result = {
            success: true,
            videoId,
            url: canonicalUrl,
            title: parsed.title || 'Tanpa Judul',
            channel: parsed.author_name || 'Kreator YouTube',
            channel_url: parsed.author_url || '',
            thumbnail: parsed.thumbnail_url || (videoId ? `https://i.ytimg.com/vi/${videoId}/hqdefault.jpg` : ''),
            type: parsed.type || 'video',
            provider: parsed.provider_name || 'YouTube'
          };
        }
      } catch (directErr) {
        console.warn('Direct YouTube oEmbed fetch error:', directErr?.message || directErr);
      }
    }

    // Fallback default info if fetch blocked
    if (!result || !result.success) {
      result = {
        success: false,
        videoId,
        url: canonicalUrl,
        title: videoId ? `Video YouTube (${videoId})` : 'Video YouTube',
        channel: 'YouTube',
        channel_url: '',
        thumbnail: videoId ? `https://i.ytimg.com/vi/${videoId}/hqdefault.jpg` : '',
        type: 'video'
      };
    }

    // Hanya cache hasil sukses: kegagalan oEmbed bersifat sementara (mis. rate
    // limit) dan tidak boleh menempel sehingga kartu video hilang permanen.
    if (result && result.success) {
      clientYouTubeCache.set(cacheKey, result);
    }
    return result;
  }

  async function getYouTubeGroundingContext(promptText, hudElement = null) {
    if (!promptText || typeof promptText !== 'string') return null;
    const ids = extractYouTubeVideoIdsClient(promptText);
    if (ids.length === 0) return null;

    if (hudElement && ids.length > 0) {
      hudElement.innerHTML = `
        <div class="web-search-hud">
          <i class="fa-brands fa-youtube" style="color:#ff0033; font-size:1.1rem;"></i>
          <span><strong>Video Grounding:</strong> Mengambil metadata ${ids.length} video via oEmbed...</span>
        </div>
      `;
    }

    const videoInfos = await Promise.all(ids.map(id => fetchYouTubeInfoClient(id)));
    const validVideos = videoInfos.filter(v => v && v.success && v.title);

    if (validVideos.length === 0) return null;

    const blocks = validVideos.map((v, idx) => {
      return `[DATA TERVERIFIKASI VIDEO YOUTUBE #${idx + 1}]
- URL: ${v.url}
- Judul Video: "${v.title}"
- Nama Channel / Pembuat: "${v.channel}" (${v.channel_url || 'N/A'})
- Thumbnail: ${v.thumbnail}
- Status Transkrip: Tidak tersedia dalam metadata oEmbed.
(Informasi resmi ini diambil secara real-time via YouTube oEmbed)`;
    }).join('\n\n');

    const groundingContext = `### DATA METADATA RESMI VIDEO (VERIFIED GROUNDING):
${blocks}

### PANDUAN INTEGRITAS & ANTI-HALUSINASI UNTUK ASISTEN AI:
1. Informasi di atas adalah metadata resmi terverifikasi real-time via video grounding.
2. BATASAN DATA: Data di atas HANYA memuat judul dan nama channel/kreator/URL, dan TIDAK MEMUAT transkrip/rekaman isi suara video lengkap kecuali disediakan pengguna.
3. DILARANG BERHALUSINASI: Dilarang mengarang atau mereka-reka isi dialog atau kesimpulan detail dari video di atas semata-mata berdasarkan judulnya.
4. JAWABAN JUJUR: Jika pengguna meminta "Rangkum isi video ini" atau "Apa kesimpulan video ini?", jelaskan fakta judul dan kreator/tautannya, lalu sampaikan secara transparan kepada pengguna jika transkrip penuh percakapan di dalam video belum disertakan.`;

    return {
      groundingContext,
      videos: validVideos
    };
  }

