  const GLOBAL_SEARCH_STOPWORDS = /\b(apa|apakah|siapa|siapakah|bagaimana|bagaimanakah|gimana|gimanakah|mengapa|kenapa|kapan|dimana|ke mana|di mana|dari mana|mana|berapa|seperti|kayak|yang|dan|atau|tetapi|namun|dengan|untuk|bagi|pada|di|ke|dari|tentang|mengenai|soal|terkait|adalah|ialah|yaitu|yakni|merupakan|bisa|dapat|tolong|coba|carikan|cari|bantu|tampilkan|berikan|sebutkan|jelaskan|paparkan|terangkan|ceritakan|nya|kah|lah|saja|pun|dong|sih|kok|deh|ya|kan|ada|sudah|telah|sedang|lagi|akan|pernah|kalian|kamu|anda|kita|saya|nih|tuh|lho|loh|kira|kira-kira)\b/gi;

  function translateIndoQueryToGlobalEnglish(rawQuery) {
    if (!rawQuery || typeof rawQuery !== 'string') return '';
    const trimmed = rawQuery.trim();
    if (!trimmed) return '';

    // 1. Jika query eksplisit meminta data domestik Indonesia, jangan diterjemahkan ke kueri global
    if (isExplicitDomesticIndoQuery(trimmed)) {
      return trimmed;
    }

    // 2. Jika tidak ada kata bahasa Indonesia sama sekali, pertahankan kueri asli
    if (!hasIndonesianWords(trimmed)) {
      return trimmed;
    }

    let translated = trimmed;

    // 3. Ganti frasa majemuk terlebih dahulu
    for (const [regex, replacement] of GLOBAL_SEARCH_PHRASE_DICT) {
      translated = translated.replace(regex, replacement);
    }

    // 4. Ganti kata-kata individual
    for (const [regex, replacement] of GLOBAL_SEARCH_WORD_DICT) {
      translated = translated.replace(regex, replacement);
    }

    // 5. Bersihkan stopwords / partikel bahasa Indonesia
    translated = translated.replace(GLOBAL_SEARCH_STOPWORDS, ' ');

    // 6. Normalisasi spasi dan tanda baca
    translated = translated
      .replace(/[^\p{L}\p{N}\s\.\-]/gu, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    // 7. Deduplikasi kata berturut-turut yang identik
    const words = translated.split(/\s+/).filter(Boolean);
    const dedupedWords = [];
    for (const w of words) {
      const last = dedupedWords[dedupedWords.length - 1];
      if (!last || last.toLowerCase() !== w.toLowerCase()) {
        dedupedWords.push(w);
      }
    }
    const result = dedupedWords.join(' ').trim();

    return result.length >= 2 ? result : trimmed;
  }

  function deriveBroadSearchQueries(rawQuery, contextText = '') {
    if (!rawQuery || typeof rawQuery !== 'string') {
      return { primary: '', tech: '', news: '', recentNews: '', recentNewsId: '', weeklyNews: '', core: '' };
    }

    // Bersihkan karakter berlebih / HTML
    let cleanQuery = rawQuery
      .replace(/<[^>]+>/g, ' ')
      .replace(/[^\p{L}\p{N}\s\.\-]/gu, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    // Bersihkan kata pengisi percakapan umum tanpa merusak topik inti
    const fillerWords = [
      'tolong', 'carikan', 'cari', 'bantu', 'apakah', 'bisakah', 'coba',
      'search', 'find', 'please'
    ];
    let coreQuery = cleanQuery;
    fillerWords.forEach(w => {
      coreQuery = coreQuery.replace(new RegExp(`\\b${w}\\b`, 'gi'), ' ');
    });
    coreQuery = coreQuery.replace(/\s+/g, ' ').trim();
    if (coreQuery.length < 2) coreQuery = cleanQuery;

    const isDomestic = isExplicitDomesticIndoQuery(cleanQuery) || isExplicitDomesticIndoQuery(contextText);
    const hasNewsWord = /\b(news|berita)\b/i.test(coreQuery);
    const hasLatestWord = /\b(latest|terbaru|terkini)\b/i.test(coreQuery);
    const newsSuffix = hasNewsWord ? '' : ' news';
    const latestSuffix = hasLatestWord ? '' : ' latest';

    return {
      primary: cleanQuery,
      core: coreQuery,
      news: `${coreQuery}${newsSuffix}`.replace(/\s+/g, ' ').trim(),
      recentNews: isDomestic ? `${coreQuery} berita terbaru` : `${coreQuery}${latestSuffix}${newsSuffix}`.replace(/\s+/g, ' ').trim(),
      recentNewsId: isDomestic ? `${coreQuery} berita terkini` : `${coreQuery} breaking news`,
      weeklyNews: `${coreQuery} updates`,
      tech: coreQuery.replace(/\b(major|news|headlines|breaking)\b/gi, ' ').replace(/\s+/g, ' ').trim() || coreQuery
    };
  }

  // ==================== PENCARIAN VIDEO YOUTUBE (CLIENT) ====================
  // Dipakai tool `search_youtube`: endpoint lokal dulu, fallback lintas-origin
  // (GitHub Pages / endpoint gagal) lewat proxy publik CORS-bebas.
  function ytClientText(node) {
    if (!node) return '';
    if (typeof node.simpleText === 'string') return node.simpleText;
    if (Array.isArray(node.runs)) return node.runs.map((r) => (r && r.text) || '').join('');
    if (typeof node.content === 'string') return node.content;
    return '';
  }

  function ytClientExtractJson(source, marker) {
    if (!source || typeof source !== 'string') return null;
    const idx = source.indexOf(marker);
    if (idx === -1) return null;
    const start = source.indexOf('{', idx + marker.length);
    if (start === -1) return null;
    let depth = 0, inStr = false, esc = false;
    for (let i = start; i < source.length; i++) {
      const c = source[i];
      if (esc) { esc = false; continue; }
      if (c === '\\') { esc = true; continue; }
      if (c === '"') { inStr = !inStr; continue; }
      if (inStr) continue;
      if (c === '{') depth++;
      else if (c === '}') { depth--; if (depth === 0) return source.slice(start, i + 1); }
    }
    return null;
  }

  function ytClientDurationSeconds(text) {
    if (!text || typeof text !== 'string') return 0;
    const parts = text.split(':').map((p) => parseInt(p, 10));
    if (parts.some((n) => Number.isNaN(n))) return 0;
    return parts.reduce((acc, n) => acc * 60 + n, 0);
  }

  function ytClientMapVideoRenderer(vr) {
    if (!vr || !vr.videoId) return null;
    const title = ytClientText(vr.title);
    if (!title) return null;
    const ownerRuns = vr.ownerText && vr.ownerText.runs;
    const ownerNav = ownerRuns && ownerRuns[0] && ownerRuns[0].navigationEndpoint && ownerRuns[0].navigationEndpoint.browseEndpoint;
    const channelPath = ownerNav && ownerNav.canonicalBaseUrl;
    const durationText = ytClientText(vr.lengthText);
    return {
      videoId: vr.videoId,
      title,
      channel: ytClientText(vr.ownerText || vr.longBylineText) || '',
      channelUrl: channelPath ? `https://www.youtube.com${channelPath}` : '',
      durationText,
      durationSeconds: ytClientDurationSeconds(durationText),
      viewText: ytClientText(vr.viewCountText) || ytClientText(vr.shortViewCountText),
      publishedText: ytClientText(vr.publishedTimeText),
      description: ytClientText(vr.descriptionSnippet).slice(0, 260),
      url: `https://www.youtube.com/watch?v=${vr.videoId}`,
      thumbnail: `https://i.ytimg.com/vi/${vr.videoId}/hqdefault.jpg`,
      source: 'YouTube Search'
    };
  }

  function ytClientCollect(node, out, limit) {
    if (!node || typeof node !== 'object' || out.length >= limit) return;
    if (Array.isArray(node)) {
      for (const item of node) { ytClientCollect(item, out, limit); if (out.length >= limit) return; }
      return;
    }
    if (node.videoRenderer) {
      const m = ytClientMapVideoRenderer(node.videoRenderer);
      if (m && !out.some((v) => v.videoId === m.videoId)) out.push(m);
      if (out.length >= limit) return;
    }
    if (node.lockupViewModel && node.lockupViewModel.contentId && String(node.lockupViewModel.contentType || '').toUpperCase().includes('VIDEO')) {
      const lv = node.lockupViewModel;
      const meta = (lv.metadata && lv.metadata.lockupMetadataViewModel) || {};
      const title = (meta.title && meta.title.content) || '';
      if (title && !out.some((v) => v.videoId === lv.contentId)) {
        out.push({
          videoId: lv.contentId,
          title,
          channel: '',
          channelUrl: '',
          durationText: '',
          durationSeconds: 0,
          viewText: (meta.metadata && meta.metadata.content) || '',
          publishedText: '',
          description: '',
          url: `https://www.youtube.com/watch?v=${lv.contentId}`,
          thumbnail: `https://i.ytimg.com/vi/${lv.contentId}/hqdefault.jpg`,
          source: 'YouTube Search'
        });
      }
      if (out.length >= limit) return;
    }
    for (const key of Object.keys(node)) { ytClientCollect(node[key], out, limit); if (out.length >= limit) return; }
  }

  function ytClientParseHtml(html, limit) {
    const jsonStr = ytClientExtractJson(html, 'ytInitialData');
    if (!jsonStr) return [];
    try {
      const out = [];
      ytClientCollect(JSON.parse(jsonStr), out, limit);
      return out;
    } catch (_) {
      return [];
    }
  }

  async function searchYouTubeClient(query, maxResults = 6) {
    const q = String(query || '').trim();
    const limit = Math.max(1, Math.min(10, parseInt(maxResults, 10) || 6));
    const payload = { success: false, query: q, count: 0, results: [], error: 'Pencarian video YouTube tidak tersedia saat ini.' };

    const abortSignals = [AbortSignal.timeout(10000)];
    if (typeof STATE !== 'undefined' && STATE && STATE.abortController && STATE.abortController.signal) {
      abortSignals.push(STATE.abortController.signal);
    }
    const combinedSignal = (typeof AbortSignal.any === 'function')
      ? AbortSignal.any(abortSignals)
      : (STATE?.abortController?.signal || abortSignals[0]);

    // 1) Endpoint lokal (server.js / Vercel / worker)
    if (!IS_GITHUB_PAGES) {
      try {
        const resp = await fetch('/api/youtube-search', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ query: q, limit }),
          signal: combinedSignal
        });
        if (resp.ok) {
          const data = await resp.json();
          if (data && Array.isArray(data.results)) {
            payload.success = data.success !== false && data.results.length > 0;
            payload.results = data.results;
            payload.count = data.results.length;
            payload.error = payload.success ? undefined : (data.error || payload.error);
            return payload;
          }
        }
      } catch (_) {
        // lanjut ke fallback
      }
    }

    // 2) Fallback lintas-origin lewat proxy publik (untuk GitHub Pages / endpoint gagal)
    try {
      const target = `https://www.youtube.com/results?search_query=${encodeURIComponent(q)}&hl=en&gl=US`;
      const proxyUrl = `https://api.allorigins.win/raw?url=${encodeURIComponent(target)}`;
      const resp2 = await fetch(proxyUrl, { signal: combinedSignal });
      if (resp2.ok) {
        const rawText = await resp2.text();
        // Cek jika response adalah JSON (misal Invidious / Piped / custom REST API)
        try {
          const parsed = JSON.parse(rawText);
          const out = [];
          const items = Array.isArray(parsed) ? parsed : (parsed.items || parsed.results || []);
          if (Array.isArray(items)) {
            for (const item of items) {
              if (out.length >= limit) break;
              if (item.videoId || item.title || item.url) {
                out.push({
                  title: item.title || 'Video',
                  url: item.videoId ? `https://www.youtube.com/watch?v=${item.videoId}` : (item.url || ''),
                  videoId: item.videoId || '',
                  channel: item.author || item.uploaderName || item.channel || '',
                  duration: item.lengthSeconds ? `${Math.floor(item.lengthSeconds / 60)}:${String(item.lengthSeconds % 60).padStart(2, '0')}` : (item.duration || ''),
                  views: item.viewCountText || (item.views ? `${item.views} views` : ''),
                  description: item.description || ''
                });
              }
            }
          }
          if (out.length > 0) {
            payload.success = true;
            payload.results = out;
            payload.count = out.length;
            payload.error = undefined;
            return payload;
          }
        } catch (_) {}

        const results = ytClientParseHtml(rawText, limit);
        payload.success = results.length > 0;
        payload.results = results;
        payload.count = results.length;
        payload.error = payload.success ? undefined : payload.error;
        return payload;
      }
    } catch (_) {
      // diamkan; payload kesalahan sudah siap
    }
    return payload;
  }

  // ==================== LOCAL BROWSER MEMORY PERSISTENCE (CLIENT-SIDE FALLBACK) ====================
  function getLocalBrowserMemories() {
    try {
      const raw = localStorage.getItem('zoz_local_memories');
      return raw ? JSON.parse(raw) : [];
    } catch (_) {
      return [];
    }
  }

  function saveLocalBrowserMemory(topic, content) {
    try {
      const list = getLocalBrowserMemories();
      const existingIdx = list.findIndex(m => m.topic === topic && m.content === content);
      if (existingIdx !== -1) {
        list[existingIdx].timestamp = Date.now();
      } else {
        list.unshift({ topic, content, timestamp: Date.now() });
        if (list.length > 200) list.pop();
      }
      localStorage.setItem('zoz_local_memories', JSON.stringify(list));
      return true;
    } catch (_) {
      return false;
    }
  }

  function searchLocalBrowserMemories(query, limit = 5) {
    const list = getLocalBrowserMemories();
    const qTerms = String(query || '').toLowerCase().replace(/[^\p{L}\p{N}_]/gu, ' ').trim().split(/\s+/).filter(Boolean);
    if (qTerms.length === 0) return [];
    const scored = [];
    for (const m of list) {
      const topLower = String(m.topic || '').toLowerCase();
      const conLower = String(m.content || '').toLowerCase();
      let score = 0;
      for (const t of qTerms) {
        if (topLower.includes(t)) score += 3;
        if (conLower.includes(t)) score += 1;
      }
      if (score > 0) scored.push({ m, score });
    }
    scored.sort((a, b) => b.score - a.score);
    return scored.map(item => item.m).slice(0, limit);
  }

  // ==================== AUTONOMOUS TOOL RESPONSE CACHE ====================
  // Cache in-memory berbatas waktu (TTL 10 menit) untuk mencegah pemanggilan berulang
  // pada query pencarian atau URL ekstraksi yang sama, menghemat kuota dan memangkas latensi ke 0ms.
  const AUTONOMOUS_TOOL_CACHE = new Map();
  const TOOL_CACHE_TTL_MS = 10 * 60 * 1000;

  async function executeAutonomousWebTool(rawToolName, rawArgs, promptContext = '', session = null) {
    if (STATE.abortController?.signal?.aborted) {
      const abortErr = new Error('The operation was aborted');
      abortErr.name = 'AbortError';
      throw abortErr;
    }
    const toolName = normalizeToolName(rawToolName) || rawToolName;
    const makeToolSignal = (timeoutMs = 8000) => {
      const timeoutSig = AbortSignal.timeout(timeoutMs);
      if (typeof STATE !== 'undefined' && STATE?.abortController?.signal) {
        return (typeof AbortSignal.any === 'function')
          ? AbortSignal.any([timeoutSig, STATE.abortController.signal])
          : (STATE.abortController.signal || timeoutSig);
      }
      return timeoutSig;
    };
    try {
      let args = {};
      if (typeof rawArgs === 'string') {
        const trimmed = rawArgs.trim();
        try {
          args = JSON.parse(trimmed);
        } catch (_) {
          // If string is raw text (not JSON), use it directly
          if (toolName === 'browse_web_page' || toolName === 'extract_web') {
            args = { url: trimmed };
          } else if (toolName === 'execute_python_code') {
            args = { code: trimmed };
          } else if (toolName === 'save_memory') {
            args = { topic: 'catatan', content: trimmed };
          } else {
            // search_web & search_youtube & search_memory memakai query
            args = { query: trimmed };
          }
        }
      } else if (rawArgs && typeof rawArgs === 'object') {
        args = rawArgs;
      }

      // Unpack nested parameters if model wrapped them in arguments/parameters/input
      if (args && typeof args === 'object') {
        if (args.arguments && typeof args.arguments === 'object') args = args.arguments;
        else if (args.parameters && typeof args.parameters === 'object') args = args.parameters;
        else if (args.input && typeof args.input === 'object') args = args.input;
      }

      // Bangun cacheKey kanonikal: satukan alias tool & parameter esensial
      let canonicalTool = toolName;
      let canonicalArg = '';
      if (toolName === 'search_web') {
        canonicalTool = 'search_web';
        canonicalArg = String(args.query || args.q || args.keyword || args.search || args.topic || args.text || args.cari || args.kata_kunci || (typeof args === 'string' ? args : '') || promptContext || '').trim().toLowerCase();
      } else if (toolName === 'search_youtube') {
        canonicalTool = 'search_youtube';
        const q = String(args.query || args.q || args.keyword || args.search || args.topic || args.title || args.text || args.cari || args.kata_kunci || args.judul || (typeof args === 'string' ? args : '') || promptContext || '').trim().toLowerCase();
        const max = Math.max(1, Math.min(10, parseInt(args.max_results || args.maxResults || args.limit, 10) || 6));
        canonicalArg = `${q}:${max}`;
      } else if (toolName === 'browse_web_page' || toolName === 'extract_web') {
        canonicalTool = 'browse_web_page';
        let u = String(args.url || args.target || args.link || args.href || args.targetUrl || args.tautan || args.alamat || (typeof args === 'string' ? args : '')).trim().toLowerCase();
        if (u && !/^https?:\/\//i.test(u)) u = 'https://' + u;
        canonicalArg = u.replace(/\/+$/, '');
      } else if (toolName === 'save_memory') {
        canonicalTool = 'save_memory';
        const top = String(args.topic || args.title || args.key || args.subject || args.kategori || args.topik || '').trim().toLowerCase();
        const cnt = String(args.content || args.value || args.text || args.fact || args.note || args.catatan || args.info || args.data || args.isi || args.konten || (typeof args === 'string' ? args : '')).trim();
        canonicalArg = `${top}:${cnt.slice(0, 60)}`;
      } else if (toolName === 'search_memory') {
        canonicalTool = 'search_memory';
        const q = String(args.query || args.q || args.search || args.keyword || args.topic || args.text || args.cari || args.kata_kunci || (typeof args === 'string' ? args : '') || promptContext || '').trim().toLowerCase();
        const lim = Math.max(1, Math.min(15, parseInt(args.limit || args.max_results || 5, 10) || 5));
        canonicalArg = `${q}:${lim}`;
      } else if (toolName === 'execute_python_code') {
        canonicalTool = 'execute_python_code';
        canonicalArg = String(args.code || args.script || args.python || (typeof args === 'string' ? args : '')).trim();
      } else {
        canonicalArg = JSON.stringify(args);
      }

      const cacheKey = `${canonicalTool}:${canonicalArg}`;
      const cachedEntry = AUTONOMOUS_TOOL_CACHE.get(cacheKey);
      if (cachedEntry) {
        if (cachedEntry.expiresAt > Date.now()) {
          return cachedEntry.data;
        } else {
          AUTONOMOUS_TOOL_CACHE.delete(cacheKey);
        }
      }

      const cacheAndReturn = (data) => {
        if (data && data.text && !data.text.startsWith('Error:') && canonicalArg) {
          AUTONOMOUS_TOOL_CACHE.set(cacheKey, {
            data,
            expiresAt: Date.now() + TOOL_CACHE_TTL_MS
          });
          if (AUTONOMOUS_TOOL_CACHE.size > 120) {
            const now = Date.now();
            for (const [k, v] of AUTONOMOUS_TOOL_CACHE.entries()) {
              if (v.expiresAt <= now) AUTONOMOUS_TOOL_CACHE.delete(k);
            }
            if (AUTONOMOUS_TOOL_CACHE.size > 120) {
              const oldestKey = AUTONOMOUS_TOOL_CACHE.keys().next().value;
              if (oldestKey) AUTONOMOUS_TOOL_CACHE.delete(oldestKey);
            }
          }
        }
        return data;
      };
      
      if (['search_youtube', 'youtube_search', 'cari_youtube', 'search_yt', 'youtube'].includes(toolName)) {
        let query = args.query || args.q || args.keyword || args.search || args.topic || args.title || args.text || args.cari || args.kata_kunci || args.judul || (typeof args === 'string' ? args : '');
        if (!query || !String(query).trim()) {
          query = promptContext || 'video populer hari ini';
        }
        query = String(query).trim();
        const maxResults = Math.max(1, Math.min(10, parseInt(args.max_results || args.maxResults || args.limit, 10) || 6));

        const data = await searchYouTubeClient(query, maxResults);
        const list = (data && Array.isArray(data.results)) ? data.results : [];
        if (list.length === 0) {
          return {
            text: `Hasil pencarian video YouTube untuk "${query}": tidak ditemukan video. Coba kata kunci alternatif yang lebih spesifik.`,
            sources: [],
            videoIds: [],
            success: false
          };
        }

        let output = `HASIL PENCARIAN VIDEO YOUTUBE UNTUK "${query}":\n`;
        output += `Ditemukan ${list.length} video relevan:\n`;
        list.forEach((v, idx) => {
          output += `\n[${idx + 1}] ${v.title}\n`;
          output += `URL: ${v.url}\n`;
          if (v.channel) output += `Channel: ${v.channel}\n`;
          if (v.durationText) output += `Durasi: ${v.durationText}\n`;
          if (v.viewText) output += `Tayangan: ${v.viewText}\n`;
          if (v.publishedText) output += `Dipublikasikan: ${v.publishedText}\n`;
          if (v.description) output += `Deskripsi: ${v.description}\n`;
        });
        output += `\nCatatan: video di atas dapat diputar langsung di dalam percakapan. Sertakan tautan video yang Anda rekomendasikan (format markdown [Judul](URL)) di dalam jawaban akhir.`;

        return cacheAndReturn({
          text: output,
          sources: list.map((v) => ({
            title: v.title,
            url: v.url,
            domain: 'youtube.com',
            snippet: `${v.channel ? `Video YouTube oleh ${v.channel}: ` : 'Video YouTube: '}${(v.description || v.title || '').slice(0, 160)}`
          })),
          videoIds: list.map((v) => v.videoId).filter(Boolean),
          success: true
        });
      }

      if (['search_web', 'web_search', 'search'].includes(toolName)) {
        let query = args.query || args.q || args.keyword || args.search || args.topic || args.text || args.cari || args.kata_kunci || (typeof args === 'string' ? args : '');
        if (!query || !query.trim()) {
          query = promptContext || 'berita dan informasi terkini';
        }
        
        let effectiveContext = promptContext || '';
        if (!effectiveContext && session?.messages?.length > 0) {
          effectiveContext = session.messages.slice(-3).map(m => m.content || '').join(' ');
        }

        const serperApiKey = (STATE.settings?.serperApiKey || '').trim() || null;
        const cleanDateQuery = stripDateNoise(query.trim());
        const isDomestic = isExplicitDomesticIndoQuery(query.trim()) || isExplicitDomesticIndoQuery(effectiveContext);
        const englishQuery = translateIndoQueryToGlobalEnglish(query.trim());

        const queriesToSearch = [];
        if (!isDomestic && englishQuery && englishQuery.toLowerCase() !== query.trim().toLowerCase()) {
          queriesToSearch.push(englishQuery);
        }
        queriesToSearch.push(query.trim());
        if (cleanDateQuery && cleanDateQuery.length >= 3 && !queriesToSearch.some(q => q.toLowerCase() === cleanDateQuery.toLowerCase())) {
          queriesToSearch.push(cleanDateQuery);
        }

        let results = [];
        const seenUrls = new Set();
        const seenTitles = new Set();

        const addCandidate = (item) => {
          if (!item || !item.url || !item.title) return;
          const normUrl = item.url.trim().toLowerCase().replace(/\/$/, '');
          const normTitle = item.title.trim().toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, '');

          // Filter domain spam, aggregator regional berita clickbait, dan bot finansial yang tidak relevan untuk kueri global
          if (!isDomestic) {
            const isSpamOrClickbait = /\b(pluang|riaugreen|inforiau|riaupos|tribunnews|detik|kompas|liputan6|suara|merdeka|sindonews|viva|inews|kumparan|jpnn|kapanlagi|idntimes)\b/i.test(normUrl) || /\b(pluang|riaugreen)\b/i.test(item.domain || '');
            if (isSpamOrClickbait) return;
          }

          // Filter Wikipedia HANYA jika sudah ada cukup sumber web/berita non-Wikipedia (>= 3)
          if (normUrl.includes('wikipedia.org') || normTitle.includes('wikipedia') || (item.domain && item.domain.includes('wikipedia.org'))) {
            if (results.length >= 3) return;
          }

          // Filter out irrelevant codename or disambiguation entries
          if (normTitle.includes('listofapplecodenames') && !query.toLowerCase().includes('apple')) return;
          if (normTitle.includes('jalanbesar') && !query.toLowerCase().includes('jalan')) return;

          if (seenUrls.has(normUrl)) return;
          seenUrls.add(normUrl);
          results.push(item);
        };

        // 1. Prioritas Utama: Google Serper API Langsung dari Browser (CORS Open, Super Cepat < 300ms, Akurat 100% untuk topik apa pun)
        if (serperApiKey) {
          try {
            for (const q of queriesToSearch) {
              if (results.length >= 10) break;
              const sRes = await fetch('https://google.serper.dev/search', {
                method: 'POST',
                headers: {
                  'X-API-KEY': serperApiKey,
                  'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                  q: q,
                  num: 15,
                  gl: isDomestic ? 'id' : 'us', // Prioritaskan domain/region Indonesia HANYA jika kueri eksplisit domestik
                  hl: isDomestic ? 'id' : 'en'  // Global Language Ranking default
                }),
                signal: makeToolSignal(6500)
              });
              if (sRes.ok) {
                const sData = await sRes.json();
                if (sData.answerBox) {
                  const abTitle = sData.answerBox.title || 'Jawaban Teratas Google';
                  const abLink = sData.answerBox.link || 'https://google.com';
                  let abDomain = 'google.com';
                  try { abDomain = new URL(abLink).hostname.replace(/^www\./, ''); } catch (_) {}
                  addCandidate({
                    title: abTitle,
                    url: abLink,
                    domain: abDomain,
                    snippet: `[Google AnswerBox] ${sData.answerBox.answer || sData.answerBox.snippet || ''}`,
                    sourceProvider: `Google AnswerBox (${abDomain})`,
                    timestamp: Date.now(),
                    pubDate: 'Terkini'
                  });
                }
                if (sData.knowledgeGraph) {
                  const kgTitle = sData.knowledgeGraph.title || 'Knowledge Graph';
                  const kgLink = sData.knowledgeGraph.website || sData.knowledgeGraph.descriptionUrl || 'https://google.com';
                  let kgDomain = 'google.com';
                  try { kgDomain = new URL(kgLink).hostname.replace(/^www\./, ''); } catch (_) {}
                  addCandidate({
                    title: `${kgTitle} (${sData.knowledgeGraph.type || 'Fakta'})`,
                    url: kgLink,
                    domain: kgDomain,
                    snippet: `[Knowledge Graph] ${sData.knowledgeGraph.description || ''}`,
                    sourceProvider: `Google KG (${kgDomain})`,
                    timestamp: Date.now(),
                    pubDate: 'Terkini'
                  });
                }
                if (Array.isArray(sData.organic)) {
                  sData.organic.forEach((it, idx) => {
                    const u = it.link || it.url || '';
                    if (!u) return;
                    let dName = 'web';
                    try { dName = new URL(u).hostname.replace(/^www\./, ''); } catch (_) {}
                    addCandidate({
                      title: it.title || `Hasil ${idx + 1}`,
                      url: u,
                      domain: dName,
                      snippet: it.snippet || '',
                      sourceProvider: `Google (${dName})`,
                      timestamp: it.date ? (Date.parse(it.date) || Date.now()) : Date.now(),
                      pubDate: it.date || 'Terkini'
                    });
                  });
                }
              }
            }
          } catch (_) {}
        }

        // 2. Prioritas Kedua: Coba endpoint backend lokal/tunnel jika hasil < 3
        if (results.length < 3) {
          try {
            const targetBackendQuery = (!isDomestic && englishQuery) ? englishQuery : (cleanDateQuery || query.trim());
            const res = await fetch('/api/tools/search-web', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ query: targetBackendQuery, originalQuery: query.trim(), context: effectiveContext, maxResults: 15 }),
              signal: makeToolSignal(7000)
            });
            if (res.ok) {
              const data = await res.json();
              if (Array.isArray(data.results)) {
                data.results.forEach(addCandidate);
              }
            }
          } catch (_) {}
        }

        // 3. Fallback jika kueri pendek/kontekstual (seperti "Di youtube ada video nya") dan hasil < 2
        if (results.length < 2 && effectiveContext && effectiveContext.trim().length > 5) {
          try {
            const baseContextQ = (!isDomestic && englishQuery) ? englishQuery : query.trim();
            const enrichedQ = `${baseContextQ} ${effectiveContext.replace(/\b(user|assistant|system)\b/gi, ' ').slice(-100).trim()}`.replace(/\s+/g, ' ').trim();
            if (serperApiKey && enrichedQ.length > baseContextQ.length) {
              const sRes = await fetch('https://google.serper.dev/search', {
                method: 'POST',
                headers: { 'X-API-KEY': serperApiKey, 'Content-Type': 'application/json' },
                body: JSON.stringify({ q: enrichedQ, num: 8, gl: isDomestic ? 'id' : 'us', hl: isDomestic ? 'id' : 'en' }),
                signal: makeToolSignal(6500)
              });
              if (sRes.ok) {
                const sData = await sRes.json();
                if (Array.isArray(sData.organic)) {
                  sData.organic.forEach((it, idx) => {
                    const u = it.link || it.url || '';
                    if (!u) return;
                    let dName = 'web';
                    try { dName = new URL(u).hostname.replace(/^www\./, ''); } catch (_) {}
                    addCandidate({
                      title: it.title || `Hasil ${idx + 1}`,
                      url: u,
                      domain: dName,
                      snippet: it.snippet || '',
                      sourceProvider: `Google (${dName})`,
                      timestamp: Date.now(),
                      pubDate: it.date || 'Terkini'
                    });
                  });
                }
              }
            }
          } catch (_) {}
        }

        // 4. Multi-Source Client-Side Aggregator (HackerNews, DuckDuckGo) jika hasil masih < 3
        if (results.length < 3) {
          try {
            const clientController = new AbortController();
            const clientTimeout = setTimeout(() => clientController.abort(), 6000);
            const clientSignal = clientController.signal;

            const primaryBroadSource = (!isDomestic && englishQuery) ? englishQuery : (cleanDateQuery || query.trim());
            const qPlan = deriveBroadSearchQueries(primaryBroadSource, effectiveContext);
            const techQ = qPlan.tech;
            const coreQ = qPlan.core;
            const combinedQueryStr = (query + ' ' + effectiveContext).toLowerCase();
            const isTechQuery = /\b(ai|llm|software|github|code|linux|python|developer|api|tech|crypto|bitcoin|model|chip|gpu|nvidia|programming|framework)\b/i.test(combinedQueryStr);
            const minHnTimestamp = Math.floor((Date.now() - 120 * 86400 * 1000) / 1000);
            const hnUrlTech = `https://hn.algolia.com/api/v1/search?query=${encodeURIComponent(techQ)}&tags=story&hitsPerPage=8&numericFilters=created_at_i%3E${minHnTimestamp}`;
            const ddgUrl = `https://api.duckduckgo.com/?q=${encodeURIComponent(coreQ)}&format=json&no_html=1&skip_disambig=1`;

            await Promise.allSettled([
              isTechQuery ? fetch(hnUrlTech, { signal: clientSignal }).then(r => r.ok ? r.json() : null).then(d => {
                if (d && Array.isArray(d.hits)) {
                  d.hits.slice(0, 6).forEach(h => {
                    const u = h.url || `https://news.ycombinator.com/item?id=${h.objectID}`;
                    let dName = 'news.ycombinator.com';
                    try { dName = new URL(u).hostname.replace(/^www\./, ''); } catch (_) {}
                    addCandidate({
                      title: h.title,
                      url: u,
                      domain: dName,
                      snippet: `[Tech Wire] ${h.title}`,
                      sourceProvider: 'HackerNews Wire',
                      timestamp: h.created_at_i ? h.created_at_i * 1000 : Date.now(),
                      pubDate: 'Terkini'
                    });
                  });
                }
              }).catch(() => {}) : Promise.resolve(),

              fetch(ddgUrl, { signal: clientSignal }).then(r => r.ok ? r.json() : null).then(d => {
                if (d) {
                  if (d.Heading && d.AbstractURL && !d.AbstractURL.includes('wikipedia.org')) {
                    let dName = 'duckduckgo.com';
                    try { dName = new URL(d.AbstractURL).hostname.replace(/^www\./, ''); } catch (_) {}
                    addCandidate({
                      title: d.Heading,
                      url: d.AbstractURL,
                      domain: dName,
                      snippet: (d.Abstract || d.Heading).replace(/<[^>]+>/g, ' ').slice(0, 180),
                      sourceProvider: 'DuckDuckGo Instant',
                      timestamp: 0,
                      pubDate: ''
                    });
                  }
                  if (Array.isArray(d.RelatedTopics)) {
                    d.RelatedTopics.slice(0, 3).forEach(rt => {
                      if (rt.FirstURL && rt.Text && !rt.FirstURL.includes('wikipedia.org')) {
                        let dName = 'duckduckgo.com';
                        try { dName = new URL(rt.FirstURL).hostname.replace(/^www\./, ''); } catch (_) {}
                        addCandidate({
                          title: rt.Text.slice(0, 60),
                          url: rt.FirstURL,
                          domain: dName,
                          snippet: rt.Text.replace(/<[^>]+>/g, ' ').slice(0, 180),
                          sourceProvider: 'DuckDuckGo Related',
                          timestamp: 0,
                          pubDate: ''
                        });
                      }
                    });
                  }
                }
              }).catch(() => {}),

              // Wikipedia Open CORS API Fallback (origin=* diizinkan di seluruh peramban)
              (async () => {
                const lang = isDomestic ? 'id' : 'en'; // Global Wikipedia (EN) atau Indonesia (ID) jika eksplisit domestik
                const wikiQuery = (!isDomestic && englishQuery) ? englishQuery : (cleanDateQuery || query.trim());
                const wikiUrl = `https://${lang}.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(wikiQuery)}&utf8=1&format=json&origin=*`;
                const wRes = await fetch(wikiUrl, { signal: clientSignal }).catch(() => null);
                if (wRes && wRes.ok) {
                  const wData = await wRes.json().catch(() => null);
                  if (wData?.query?.search && Array.isArray(wData.query.search)) {
                    wData.query.search.slice(0, 3).forEach(item => {
                      const pTitle = item.title || '';
                      const pUrl = `https://${lang}.wikipedia.org/wiki/${encodeURIComponent(pTitle.replace(/ /g, '_'))}`;
                      const cleanSnippet = (item.snippet || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
                      addCandidate({
                        title: pTitle,
                        url: pUrl,
                        domain: `${lang}.wikipedia.org`,
                        snippet: cleanSnippet || `Artikel ensiklopedia: ${pTitle}`,
                        sourceProvider: 'Wikipedia Global',
                        timestamp: Date.now(),
                        pubDate: 'Ensiklopedia'
                      });
                    });
                  }
                }
              })().catch(() => {})
            ]);
            clearTimeout(clientTimeout);
          } catch (_) {}
        }
        
        if (results.length === 0) {
          return { text: `Hasil pencarian untuk "${query}": Tidak ditemukan hasil spesifik. Coba gunakan kata kunci alternatif.`, sources: [], success: false };
        }

        results.sort((a, b) => {
          const aRep = REPUTABLE_TECH_DOMAINS.has(a.domain) ? 1 : 0;
          const bRep = REPUTABLE_TECH_DOMAINS.has(b.domain) ? 1 : 0;
          if (aRep !== bRep) return bRep - aRep;
          return (b.timestamp || 0) - (a.timestamp || 0);
        });
        
        let output = `HASIL PENCARIAN WEB MULTI-SUMBER UNTUK "${query}":\n`;
        output += `Ditemukan ${results.length} sumber informasi terverifikasi (Diurutkan dari publikasi paling mutakhir & aktual):\n`;
        results.forEach((item, idx) => {
          output += `\n[${idx + 1}] [${item.sourceProvider || 'Web'}] ${item.title}\nURL: ${item.url}\nSumber/Domain: ${item.domain}\nRingkasan: ${item.snippet}\n`;
        });
        return cacheAndReturn({ text: output, sources: results, success: true });
      }
      
      if (['browse_web_page', 'browse_web', 'browse_page', 'extract_web', 'read_url', 'scrape_url'].includes(toolName)) {
        let url = args.url || args.target || args.link || args.href || args.targetUrl || (typeof args === 'string' ? args : '');
        if (!url || !url.trim()) return { text: 'Error: Parameter `url` tidak boleh kosong.', sources: [], success: false };
        url = url.trim();
        if (!/^https?:\/\//i.test(url)) {
          url = 'https://' + url;
        }

        // Intersep khusus untuk URL YouTube agar mengembalikan metadata resmi video via oEmbed
        const ytIds = extractYouTubeVideoIdsClient(url);
        if (ytIds && ytIds.length > 0) {
          try {
            const ytInfo = await fetchYouTubeInfoClient(ytIds[0]);
            if (ytInfo && ytInfo.success && ytInfo.title) {
              return cacheAndReturn({
                text: `[INFORMASI TERVERIFIKASI VIDEO YOUTUBE]:\n- Judul: "${ytInfo.title}"\n- Channel / Pembuat: "${ytInfo.channel}" (${ytInfo.channel_url || 'N/A'})\n- URL: ${ytInfo.url}\n- Thumbnail: ${ytInfo.thumbnail}\n(Diambil secara real-time via YouTube oEmbed)`,
                sources: [{ title: ytInfo.title, url: ytInfo.url, domain: 'youtube.com', snippet: `Video YouTube oleh ${ytInfo.channel}: ${ytInfo.title}` }],
                videoIds: ytIds,
                success: true
              });
            }
          } catch (_) {}
        }
        
        if (!IS_GITHUB_PAGES) {
          try {
            // 1. Coba endpoint ekstraksi web resmi Zoz Router (/api/extract-web)
            try {
              const extRes = await fetch(`/api/extract-web?url=${encodeURIComponent(url)}&maxChars=8000`, {
                headers: { 'Accept': 'application/json' },
                signal: makeToolSignal(8000)
              });
              if (extRes.ok) {
                const extData = await extRes.json();
                if (extData && extData.success && extData.content && extData.content.length > 40) {
                  const docTitle = extData.title || (extractDomainSafe ? extractDomainSafe(url) : 'Halaman Web');
                  return cacheAndReturn({
                    text: `KONTEN HALAMAN WEB "${docTitle}" (${url}):\n\n${extData.content}`,
                    sources: [{ title: docTitle, url: url, domain: extData.domain || 'web', snippet: extData.content.substring(0, 160) }],
                    videoIds: Array.isArray(extData.videoIds) ? extData.videoIds : extractYouTubeVideoIdsClient(url),
                    success: true
                  });
                }
              }
            } catch (_) {}

            // 2. Fallback: coba endpoint /api/tools/browse-page
            const res = await fetch('/api/tools/browse-page', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ url: url, maxChars: 5000 }),
              signal: makeToolSignal(8000)
            });
            if (res.ok) {
              const data = await res.json();
              if (data && data.text && data.text.length > 50) {
                let output = `KONTEN HALAMAN WEB "${data.title || url}" (${url}):\n\n`;
                output += data.text || '(Konten teks bersih tidak ditemukan)';
                if (Array.isArray(data.links) && data.links.length > 0) {
                  output += '\n\nTautan Terkait Di Halaman:\n';
                  data.links.slice(0, 5).forEach(l => {
                    output += `- [${l.title}](${l.url})\n`;
                  });
                }
                const foundDomain = extractDomainSafe ? extractDomainSafe(url) : 'web';
                return cacheAndReturn({
                  text: output,
                  sources: [{ title: data.title || url, url: url, domain: foundDomain, snippet: (data.text || '').substring(0, 160) }],
                  videoIds: Array.isArray(data.videoIds) ? data.videoIds : extractYouTubeVideoIdsClient(url),
                  success: true
                });
              }
            }
          } catch (_) {}
        }

        // Client-side universal reader via Jina Reader (CORS open, converts any URL to clean markdown)
        try {
          const jinaRes = await fetch(`https://r.jina.ai/${encodeURI(url)}`, {
            signal: makeToolSignal(7500),
            headers: { 'Accept': 'text/plain' }
          });
          if (jinaRes.ok) {
            const markdown = await jinaRes.text();
            if (markdown && markdown.length > 80) {
              const cleanMarkdown = markdown.substring(0, 5000);
              const titleMatch = markdown.match(/^Title:\s*(.+)$/m) || markdown.match(/^#\s+(.+)$/m);
              const docTitle = titleMatch ? titleMatch[1].trim() : (extractDomainSafe ? extractDomainSafe(url) : 'Halaman Web');
              return cacheAndReturn({
                text: `KONTEN HALAMAN WEB "${docTitle}" (${url}):\n\n${cleanMarkdown}`,
                sources: [{ title: docTitle, url: url, domain: extractDomainSafe ? extractDomainSafe(url) : 'web', snippet: cleanMarkdown.substring(0, 160) }],
                videoIds: extractYouTubeVideoIdsClient(url),
                success: true
              });
            }
          }
        } catch (_) {}

        // Client-side fallback for Wikipedia URLs on GitHub Pages
        if (/wikipedia\.org\/wiki\//i.test(url)) {
          try {
            const pageTitleMatch = url.match(/\/wiki\/([^#\?]+)/);
            if (pageTitleMatch && pageTitleMatch[1]) {
              const pageTitle = decodeURIComponent(pageTitleMatch[1]);
              const langMatch = url.match(/https?:\/\/([a-z]+)\.wikipedia\.org/i);
              const lang = langMatch ? langMatch[1] : 'id';
              const restApiUrl = `https://${lang}.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(pageTitle)}`;
              const wikiRes = await fetch(restApiUrl, { signal: makeToolSignal(6000) });
              if (wikiRes.ok) {
                const wData = await wikiRes.json();
                const extract = wData.extract || wData.description || 'Halaman Wikipedia';
                return cacheAndReturn({
                  text: `KONTEN ARTIKEL WIKIPEDIA "${wData.title || pageTitle}" (${url}):\n\n${extract}`,
                  sources: [{ title: wData.title || pageTitle, url: url, domain: `${lang}.wikipedia.org`, snippet: extract.substring(0, 160) }],
                  success: true
                });
              }
            }
          } catch (_) {}
        }

        return { text: `Error: Tidak dapat membaca URL ${url} (Koneksi gagal atau halaman tidak dapat diakses). Saran: Coba gunakan search_web untuk mencari ringkasan/informasi alternatif tentang topik ini, atau beri tahu pengguna bahwa tautan tersebut tidak dapat dibuka.`, sources: [], success: false };
      }

      if (['save_memory', 'simpan_memori', 'store_memory'].includes(toolName)) {
        const content = String(args.content || args.value || args.text || args.fact || args.note || args.catatan || args.info || args.data || args.isi || args.konten || (typeof args === 'string' ? args : '')).trim();
        if (!content) {
          return { text: 'Error: Konten fakta/catatan memori tidak boleh kosong.', sources: [], success: false };
        }
        let topic = String(args.topic || args.title || args.key || args.subject || args.kategori || args.topik || '').trim();
        if (!topic) {
          topic = content.split(/\s+/).slice(0, 4).join('_').replace(/[^\p{L}\p{N}_]/gu, '').toLowerCase() || 'catatan';
        }

        // Simpan juga di browser storage sebagai fallback instan
        saveLocalBrowserMemory(topic, content);

        if (!IS_GITHUB_PAGES) {
          try {
            const res = await fetch('/api/memory/save', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json', 'X-User-ID': STATE.userId || 'default' },
              body: JSON.stringify({ topic, content, userId: STATE.userId || 'default' }),
              signal: makeToolSignal(6000)
            });
            if (res.ok) {
              const data = await res.json();
              return {
                text: `[MEMORI JANGKA PANJANG TERSIMPAN]: Berhasil menyimpan fakta ke dalam database lokal (SQLite FTS5):\n- Topik: "${topic}"\n- Konten: ${content}\n(Catatan: Informasi ini tersimpan secara permanen dan dapat dicari di sesi mana pun menggunakan tool \`search_memory\`).`,
                sources: [],
                success: true
              };
            }
          } catch (_) {}
        }

        return {
          text: `[MEMORI JANGKA PANJANG TERSIMPAN (BROWSER)]: Berhasil menyimpan fakta ke dalam memori browser lokal:\n- Topik: "${topic}"\n- Konten: ${content}\n(Catatan: Informasi ini tersimpan dan dapat dicari di sesi mana pun menggunakan tool \`search_memory\`).`,
          sources: [],
          success: true
        };
      }

      if (['search_memory', 'cari_memori', 'query_memory'].includes(toolName)) {
        let query = String(args.query || args.q || args.search || args.keyword || args.topic || args.text || args.cari || args.kata_kunci || (typeof args === 'string' ? args : '')).trim();
        if (!query) {
          query = promptContext || '';
        }
        if (!query) {
          return { text: 'Error: Parameter `query` pencarian memori tidak boleh kosong.', sources: [], success: false };
        }
        const limit = Math.max(1, Math.min(15, parseInt(args.limit || args.max_results || 5, 10) || 5));

        let serverMatches = [];
        if (!IS_GITHUB_PAGES) {
          try {
            const res = await fetch(`/api/memory/search?q=${encodeURIComponent(query)}&userId=${encodeURIComponent(STATE.userId || 'default')}&limit=${limit}`, {
              headers: { 'Accept': 'application/json', 'X-User-ID': STATE.userId || 'default' },
              signal: makeToolSignal(6000)
            });
            if (res.ok) {
              const data = await res.json();
              if (data && data.count > 0 && Array.isArray(data.results)) {
                serverMatches = data.results;
              }
            }
          } catch (_) {}
        }

        // Gabungkan dengan catatan di browser storage untuk mencegah data silo
        const localMatches = searchLocalBrowserMemories(query, limit);
        const combined = [...serverMatches];
        const seen = new Set(combined.map(r => `${String(r.topic || '').toLowerCase()}:::${String(r.content || '').toLowerCase()}`));
        for (const lm of localMatches) {
          const key = `${String(lm.topic || '').toLowerCase()}:::${String(lm.content || '').toLowerCase()}`;
          if (!seen.has(key)) {
            seen.add(key);
            combined.push(lm);
          }
        }

        if (combined.length > 0) {
          const selected = combined.slice(0, limit);
          const formatted = selected.map(m => `[${m.topic}] : ${m.content}`).join('\n\n');
          return {
            text: `[HASIL PENCARIAN MEMORI JANGKA PANJANG UNTUK "${query}"]:\n${formatted}`,
            sources: [],
            success: true
          };
        }

        return {
          text: `[HASIL PENCARIAN MEMORI JANGKA PANJANG UNTUK "${query}"]:\nTidak ada catatan memori masa lalu yang cocok dengan kata kunci tersebut.`,
          sources: [],
          success: true
        };
      }

      if (toolName === 'execute_python_code') {
        const code = String(args.code || args.script || args.python || (typeof args === 'string' ? args : '')).trim();
        if (!code) {
          return { text: 'Error: Parameter `code` tidak boleh kosong. Sertakan kode Python yang valid dengan perintah print() untuk melihat output.', sources: [], success: false };
        }

        if (!IS_GITHUB_PAGES) {
          try {
            const execSignal = (typeof AbortSignal.any === 'function' && STATE.abortController?.signal)
              ? AbortSignal.any([AbortSignal.timeout(12000), STATE.abortController.signal])
              : (STATE.abortController?.signal || AbortSignal.timeout(12000));
            const res = await fetch('/api/execute-code', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ code }),
              signal: execSignal
            });
            if (res.ok) {
              const data = await res.json();
              const outText = data.output || 'Kode berhasil dijalankan tanpa output.';
              return {
                text: `[HASIL EKSEKUSI PYTHON SUBPROCESS SANDBOX]:\n\`\`\`\n${outText}\n\`\`\``,
                sources: [],
                success: data.success !== false
              };
            } else {
              const errData = await res.json().catch(() => ({}));
              return {
                text: `Error eksekusi Python (${res.status}): ${errData.error || errData.output || 'Gagal menjalankan subprocess Python di server.'}`,
                sources: [],
                success: false
              };
            }
          } catch (err) {
            if (STATE.abortController?.signal?.aborted) {
              return {
                text: 'Eksekusi Python dihentikan oleh pengguna.',
                sources: [],
                success: false
              };
            }
          }
        }

        return {
          text: 'Error eksekusi: Tidak dapat menghubungi server lokal ZOZ Router. Pastikan server lokal aktif (`node server.js`) untuk mengeksekusi kode Python dalam subprocess sandbox.',
          sources: [],
          success: false
        };
      }
      
      return { text: `Error: Tool "${toolName}" tidak dikenal.`, sources: [], success: false };
    } catch (err) {
      if (err && (err.name === 'AbortError' || STATE.abortController?.signal?.aborted)) {
        throw err;
      }
      return { text: `Error menjalankan tool ${toolName}: ${err.message}`, sources: [], success: false };
    }
  }

  function extractBalancedJsonObjects(text) {
    if (!text || typeof text !== 'string') return [];
    const results = [];
    let startIndex = 0;
    while (startIndex < text.length) {
      const start = text.indexOf('{', startIndex);
      if (start === -1) break;

      let depth = 0;
      let inString = false;
      let escape = false;
      let end = -1;

      for (let i = start; i < text.length; i++) {
        const char = text[i];
        if (escape) {
          escape = false;
          continue;
        }
        if (char === '\\') {
          escape = true;
          continue;
        }
        if (char === '"') {
          inString = !inString;
          continue;
        }
        if (!inString) {
          if (char === '{') {
            depth++;
          } else if (char === '}') {
            depth--;
            if (depth === 0) {
              end = i;
              break;
            }
          }
        }
      }

      if (end !== -1) {
        const candidate = text.substring(start, end + 1);
        results.push({ json: candidate, start, end });
        startIndex = end + 1;
      } else {
        startIndex = start + 1;
      }
    }
    return results;
  }

  function scrubRawToolCallArtifacts(text) {
    if (!text || typeof text !== 'string') return '';
    const toolPattern = AUTONOMOUS_TOOL_NAMES.join('|');
    const invokeRegex = new RegExp(`<invoke\\s+name=["'](?:${toolPattern})["']>[\\s\\S]*?<\\/invoke>`, 'gi');
    const jsonCodeBlockRegex = new RegExp(`\`\`\`(?:tool_call|json)?\\s*\\{[\\s\\S]*?"(?:name|function|tool)"\\s*:\\s*"(?:${toolPattern})"[\\s\\S]*?\\}\\s*\`\`\``, 'gi');
    const callPreambleRegex = new RegExp(`(?:we will call|calling tool|memanggil tool|i will search|saya akan mencari)\\s+(?:${toolPattern})[\\s\\S]*?(?:\\.|\\n|$)`, 'gi');
    const funcCallRegex = new RegExp(`(?:${toolPattern})\\s*\\(\\s*\\{[\\s\\S]*?\\}\\s*\\)`, 'gi');
    const funcCallArgsRegex = new RegExp(`(?:${toolPattern})\\s*\\(\\s*(?:(?:query|url|q|code|topic|content|script|link|target|isi|kata_kunci|topik)\\s*[:=]\\s*)?(["'\`])[\\s\\S]*?\\1\\s*\\)`, 'gi');
    const funcCallTwoArgsRegex = /(?:save_memory|simpan_memori|store_memory)\s*\(\s*(?:[a-zA-Z_]+\s*[:=]\s*)?(["'`])[\s\S]*?\1\s*,\s*(?:[a-zA-Z_]+\s*[:=]\s*)?(["'`])[\s\S]*?\2\s*\)/gi;

    let cleaned = text
      .replace(/<(?:tool_call|function_call)>[\s\S]*?<\/(?:tool_call|function_call)>/gi, '')
      .replace(invokeRegex, '')
      .replace(/\[TOOL_CALLS\][\s\S]*?(?:\[\/TOOL_CALLS\]|(?=\n\n)|$)/gi, '')
      .replace(jsonCodeBlockRegex, '');

    // Hapus blok JSON seimbang yang merepresentasikan pemanggilan tool mentah
    const jsonBlocks = extractBalancedJsonObjects(cleaned);
    for (const block of jsonBlocks) {
      try {
        const p = JSON.parse(block.json);
        const name = p.name || p.function || p.tool;
        if (isKnownAutonomousTool(name)) {
          cleaned = cleaned.replace(block.json, '');
        }
      } catch (_) {}
    }

    // Bersihkan residu teks bocor seperti "We will call search_web for ..."
    cleaned = cleaned
      .replace(callPreambleRegex, '')
      .replace(funcCallRegex, '')
      .replace(funcCallArgsRegex, '')
      .replace(funcCallTwoArgsRegex, '')
      .trim();

    return cleaned;
  }

  function extractInlineToolCalls(text) {
    if (!text || typeof text !== 'string') return [];
    const calls = [];
    const seenIds = new Set();

    function addCall(toolName, rawArgs, rawTag) {
      const normalizedName = normalizeToolName(toolName);
      if (!normalizedName || !isKnownAutonomousTool(normalizedName)) return;

      let parsedArgs = rawArgs;
      if (typeof rawArgs === 'string') {
        const trimmed = rawArgs.trim();
        try {
          parsedArgs = JSON.parse(trimmed);
        } catch (_) {
          if (['browse_web_page', 'extract_web', 'read_url'].includes(normalizedName)) {
            parsedArgs = { url: trimmed };
          } else if (normalizedName === 'search_youtube') {
            parsedArgs = { query: trimmed };
          } else if (normalizedName === 'save_memory') {
            parsedArgs = { topic: 'catatan', content: trimmed };
          } else if (normalizedName === 'execute_python_code') {
            parsedArgs = { code: trimmed };
          } else {
            parsedArgs = { query: trimmed };
          }
        }
      } else if (!parsedArgs || typeof parsedArgs !== 'object') {
        parsedArgs = {};
      }

      // Normalisasi properti argumen
      if (['browse_web_page', 'extract_web', 'read_url'].includes(normalizedName)) {
        const urlVal = parsedArgs.url || parsedArgs.target || parsedArgs.link || parsedArgs.href || parsedArgs.targetUrl || parsedArgs.tautan || parsedArgs.alamat || '';
        parsedArgs = { url: String(urlVal).trim() };
      } else if (normalizedName === 'search_youtube') {
        const qVal = parsedArgs.query || parsedArgs.q || parsedArgs.keyword || parsedArgs.search || parsedArgs.cari || parsedArgs.kata_kunci || parsedArgs.judul || parsedArgs.title || '';
        parsedArgs = { query: String(qVal).trim(), max_results: parsedArgs.max_results || 6 };
      } else if (normalizedName === 'search_web') {
        const qVal = parsedArgs.query || parsedArgs.q || parsedArgs.keyword || parsedArgs.search || parsedArgs.topic || parsedArgs.cari || parsedArgs.kata_kunci || '';
        parsedArgs = { query: String(qVal).trim() };
      } else if (normalizedName === 'save_memory') {
        parsedArgs = {
          topic: String(parsedArgs.topic || parsedArgs.title || parsedArgs.key || parsedArgs.topik || 'catatan').trim(),
          content: String(parsedArgs.content || parsedArgs.value || parsedArgs.text || parsedArgs.isi || parsedArgs.konten || parsedArgs.catatan || '').trim()
        };
      } else if (normalizedName === 'search_memory') {
        const qVal = parsedArgs.query || parsedArgs.q || parsedArgs.keyword || parsedArgs.topic || parsedArgs.cari || parsedArgs.kata_kunci || '';
        parsedArgs = { query: String(qVal).trim() };
      } else if (normalizedName === 'execute_python_code') {
        const codeVal = parsedArgs.code || parsedArgs.script || parsedArgs.python || (typeof parsedArgs === 'string' ? parsedArgs : '');
        parsedArgs = { code: String(codeVal).trim() };
      }

      const serializedArgs = JSON.stringify(parsedArgs);
      const callKey = `${normalizedName}:${serializedArgs}`;
      if (!seenIds.has(callKey)) {
        seenIds.add(callKey);
        calls.push({
          id: `call_${Date.now()}_${calls.length}`,
          type: 'function',
          rawTag: rawTag || '',
          function: {
            name: normalizedName,
            arguments: serializedArgs
          }
        });
      }
    }

    // 1. Tag <tool_call>...</tool_call> and <function_call>...</function_call>
    const tagRegex = /<(?:tool_call|function_call)>\s*([\s\S]*?)\s*<\/(?:tool_call|function_call)>/gi;
    let tm;
    while ((tm = tagRegex.exec(text)) !== null) {
      try {
        const clean = tm[1].replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
        const p = JSON.parse(clean);
        const name = p.name || p.function || p.tool;
        const args = p.arguments ?? p.parameters ?? p.args ?? p.input ?? {};
        addCall(name, args, tm[0]);
      } catch (_) {}
    }

    // 2. Mistral format: [TOOL_CALLS] [{"name": "search_web", "arguments": ...}]
    const mistralRegex = /\[TOOL_CALLS\]\s*([\s\S]*?)(?:\[\/TOOL_CALLS\]|$)/gi;
    let mtm;
    while ((mtm = mistralRegex.exec(text)) !== null) {
      try {
        const block = mtm[1].trim();
        const parsed = JSON.parse(block);
        const items = Array.isArray(parsed) ? parsed : [parsed];
        items.forEach(it => {
          if (it && (it.name || it.function)) {
            addCall(it.name || it.function, it.arguments ?? it.parameters ?? it.args ?? {}, mtm[0]);
          }
        });
      } catch (_) {}
    }

    // 3. Anthropic XML format: <invoke name="search_web"><parameter name="query">...</parameter></invoke>
    const toolPattern = AUTONOMOUS_TOOL_NAMES.join('|');
    const invokeRegex = new RegExp(`<invoke\\s+name=["'](${toolPattern})["']>([\\s\\S]*?)<\\/invoke>`, 'gi');
    let ivm;
    while ((ivm = invokeRegex.exec(text)) !== null) {
      const name = ivm[1];
      const inner = ivm[2];
      const paramMatch = inner.match(/<parameter\s+name=["'](?:query|q|url|target|link|href|code|topic|content)["']>([\s\S]*?)<\/parameter>/i);
      const val = paramMatch ? paramMatch[1].trim() : inner.replace(/<[^>]+>/g, '').trim();
      if (val) {
        const isUrlTool = ['browse_web_page', 'browse_web', 'browse_page', 'extract_web', 'read_url', 'scrape_url'].includes(name.toLowerCase());
        const isCodeTool = ['execute_python_code', 'execute_code', 'run_code', 'python_code', 'run_python', 'python'].includes(name.toLowerCase());
        const isSaveMem = ['save_memory', 'simpan_memori', 'store_memory'].includes(name.toLowerCase());
        if (isUrlTool) addCall(name, { url: val }, ivm[0]);
        else if (isCodeTool) addCall(name, { code: val }, ivm[0]);
        else if (isSaveMem) addCall(name, { topic: 'catatan', content: val }, ivm[0]);
        else addCall(name, { query: val }, ivm[0]);
      }
    }

    // 4. Fenced codeblock ```json ... ``` or ```tool_call ... ```
    const codeBlockRegex = new RegExp(`\`\`\`(?:json|tool_call)?\\s*(\\{\\s*"(?:name|function|tool)"\\s*:\\s*"(?:${toolPattern})"[\\s\\S]*?\\})\\s*\`\`\``, 'gi');
    let cm;
    while ((cm = codeBlockRegex.exec(text)) !== null) {
      try {
        const p = JSON.parse(cm[1]);
        const name = p.name || p.function || p.tool;
        const args = p.arguments ?? p.parameters ?? p.args ?? p.input ?? {};
        addCall(name, args, cm[0]);
      } catch (_) {}
    }

    // Strip fenced code blocks dan inline code sebelum menjalankan regex teks biasa (5, 6, 7, 8)
    // agar kode pemrograman / tutorial yang menyebut search_web TIDAK PERNAH terintersepsi keliru sebagai tool hidup
    let textWithoutCode = text
      .replace(/```[\s\S]*?```/g, ' ')
      .replace(/`[^`\n]+`/g, ' ');

    const remainingProse = scrubRawToolCallArtifacts(textWithoutCode).trim();
    const isLongCompleteText = textWithoutCode.trim().length > 350 && remainingProse.length > 150;

    // 5. Raw balanced JSON objects anywhere in text (di luar blok kode)
    const jsonBlocks = extractBalancedJsonObjects(textWithoutCode);
    for (const block of jsonBlocks) {
      if (isLongCompleteText && block.start > 220) continue;
      try {
        const p = JSON.parse(block.json);
        const name = p.name || p.function || p.tool;
        if (isKnownAutonomousTool(name)) {
          const args = p.arguments ?? p.parameters ?? p.args ?? p.input ?? {};
          addCall(name, args, block.json);
        }
      } catch (_) {}
    }

    // 6. Function call with JSON argument: search_web({"query": "..."}) or browse_web_page({"url": "..."})
    const funcJsonRegex = /(search_web|web_search|search|browse_web_page|browse_web|browse_page|extract_web|read_url|scrape_url|search_youtube|youtube_search|cari_youtube|search_yt|youtube|save_memory|simpan_memori|search_memory|cari_memori|execute_python_code|execute_code|run_code|python_code|run_python|python)\s*\(\s*(\{[\s\S]*?\})\s*\)/gi;
    let fjm;
    while ((fjm = funcJsonRegex.exec(textWithoutCode)) !== null) {
      if (isLongCompleteText && fjm.index > 220) continue;
      const name = fjm[1];
      try {
        let cleanJson = fjm[2]
          .replace(/'/g, '"')
          .replace(/,\s*([}\]])/g, '$1');
        const p = JSON.parse(cleanJson);
        addCall(name, p, fjm[0]);
      } catch (_) {
        const extracted = {};
        const kvRegex = /["']?([a-zA-Z0-9_]+)["']?\s*:\s*(?:["']([^"']*)["']|(\d+(?:\.\d+)?)|(true|false)|null)/g;
        let km;
        while ((km = kvRegex.exec(fjm[2])) !== null) {
          const k = km[1];
          const v = km[2] !== undefined ? km[2] : (km[3] !== undefined ? Number(km[3]) : (km[4] !== undefined ? km[4] === 'true' : null));
          extracted[k] = v;
        }
        if (Object.keys(extracted).length > 0) {
          addCall(name, extracted, fjm[0]);
        }
      }
    }

    // 7a. Two-argument function call syntax: save_memory("topik", "konten fakta") or save_memory(topic="...", content="...")
    const funcTwoArgsRegex = /(save_memory|simpan_memori|store_memory)\s*\(\s*(?:([a-zA-Z_]+)\s*[:=]\s*)?(["'`])([\s\S]*?)\3\s*,\s*(?:([a-zA-Z_]+)\s*[:=]\s*)?(["'`])([\s\S]*?)\6\s*\)/gi;
    let ftm;
    while ((ftm = funcTwoArgsRegex.exec(textWithoutCode)) !== null) {
      if (isLongCompleteText && ftm.index > 220) continue;
      const name = ftm[1];
      const k1 = (ftm[2] || '').toLowerCase();
      const v1 = ftm[4].trim();
      const k2 = (ftm[5] || '').toLowerCase();
      const v2 = ftm[7].trim();
      let topicVal = v1;
      let contentVal = v2;
      if (['content', 'konten', 'isi', 'value', 'text', 'data'].includes(k1)) {
        contentVal = v1;
        topicVal = v2;
      }
      if (topicVal || contentVal) {
        addCall(name, { topic: topicVal || 'catatan', content: contentVal || topicVal }, ftm[0]);
        textWithoutCode = textWithoutCode.replace(ftm[0], ' '.repeat(ftm[0].length));
      }
    }

    // 7b. Single-argument function call syntax: search_web("query") or browse_web_page("url")
    // Jika teks sangat panjang (> 300 kata), hanya izinkan jika pemanggilan ada di awal teks (< 200 karakter)
    const funcRegex = new RegExp(`(${toolPattern})\\s*\\(\\s*(?:(?:query|url|q|link|target|code|topic|content|isi|kata_kunci|topik|script|cari|tautan|konten)\\s*[:=]\\s*)?(["'\`])([\\s\\S]*?)\\2\\s*\\)`, 'gi');
    let fm;
    while ((fm = funcRegex.exec(textWithoutCode)) !== null) {
      if (isLongCompleteText && fm.index > 220) continue;
      const name = fm[1];
      const val = fm[3].trim();
      if (val) {
        const normName = normalizeToolName(name);
        const isUrlTool = ['browse_web_page', 'extract_web'].includes(normName);
        const isCodeTool = ['execute_python_code', 'run_python', 'python'].includes(normName);
        const isSaveMem = normName === 'save_memory';
        if (isUrlTool) addCall(name, { url: val }, fm[0]);
        else if (isCodeTool) addCall(name, { code: val }, fm[0]);
        else if (isSaveMem) addCall(name, { topic: 'catatan', content: val }, fm[0]);
        else addCall(name, { query: val }, fm[0]);
      }
    }

    // 8. Conversational triggers: "We will call search_web for <query>"
    // Hanya picu jika berada di awal generasi (bukan teks penutup di akhir pesan panjang)
    const convRegex = new RegExp(`(?:we will call|calling tool|memanggil tool|i will search|saya akan mencari|menjelajahi|ekstrak)\\s+(${toolPattern})(?:\\s+(?:for|with|tentang|query|url|code|topic|isi|kata_kunci|topik|cari|tautan|:))?\\s*(["'\`])([^\\n]+?)\\2`, 'gi');
    let cvm;
    while ((cvm = convRegex.exec(textWithoutCode)) !== null) {
      if (isLongCompleteText && cvm.index > 220) continue;
      const name = cvm[1];
      const val = cvm[3].trim();
      if (val) {
        const normName = normalizeToolName(name);
        const isUrlTool = ['browse_web_page', 'extract_web'].includes(normName);
        const isCodeTool = normName === 'execute_python_code';
        const isSaveMem = normName === 'save_memory';
        if (isUrlTool) addCall(name, { url: val }, cvm[0]);
        else if (isCodeTool) addCall(name, { code: val }, cvm[0]);
        else if (isSaveMem) addCall(name, { topic: 'catatan', content: val }, cvm[0]);
        else addCall(name, { query: val }, cvm[0]);
      }
    }

    return calls;
  }

  function getAutonomousSystemDirective() {
    return `### INSTRUKSI SISTEM: KESADARAN PENGETAHUAN & PENGGUNAAN ALAT OTONOM (WEB, MEMORI & PYTHON)

1. KESADARAN BATASAN PENGETAHUAN (KNOWLEDGE CUTOFF):
- Anda adalah asisten AI yang sepenuhnya menyadari bahwa pengetahuan internal bawaan Anda memiliki batasan waktu (knowledge cutoff).
- Anda TIDAK MEMILIKI pengetahuan bawaan mengenai data real-time, berita mutakhir, peristiwa terkini, atau informasi spesifik dunia nyata saat ini dalam topik APA PUN (politik, ekonomi, pasar saham, olahraga, sains, hiburan, hukum, peristiwa global maupun lokal).
- Dilarang menebak atau mengarang spekulasi tentang peristiwa dunia nyata terkini tanpa mencari fakta aktual melalui alat pencarian web.

2. KEWAJIBAN MENGGUNAKAN TOOL YANG TEPAT (SINGLE RESPONSIBILITY & SEMANTIK):
- Gunakan alat yang sesuai dengan kebutuhan tugas secara eksplisit:
  a. search_web: Untuk mencari informasi terkini, artikel, berita, atau data umum dari internet global dunia.
     Format: search_web("kata kunci") atau {"name":"search_web","arguments":{"query":"kata kunci"}}
  b. browse_web_page / extract_web: Untuk membaca dan mengekstrak isi teks lengkap dari URL website spesifik.
     Format: browse_web_page("https://example.com/artikel") atau {"name":"browse_web_page","arguments":{"url":"https://example.com/artikel"}}
  c. save_memory: Untuk menyimpan preferensi penting pengguna, instruksi permanen, catatan fakta kunci, atau memori proyek jangka panjang ke dalam SQLite.
     Format: save_memory({"topic":"topik","content":"isi fakta"})
  d. search_memory: Untuk memanggil kembali catatan atau fakta masa lalu dari memori jangka panjang pengguna.
     Format: search_memory({"query":"kata kunci"})
  e. execute_python_code: Untuk melakukan kalkulasi matematika presisi tinggi, pemrosesan data, manipulasi string, atau simulasi logika dengan Python sandbox lokal. Wajib gunakan print() untuk melihat output.
     Format: execute_python_code({"code":"import math\\nprint(math.factorial(20))"})
- Jika pengguna melampirkan atau menyebutkan URL web dan meminta membacanya: WAJIB panggil browse_web_page!
- Jika pengguna menanyakan hal yang pernah dibahas di masa lalu atau preferensi yang pernah disimpan: WAJIB panggil search_memory!
- Jika pengguna meminta kalkulasi angka rumit, statistik, atau pembuktian kode: WAJIB panggil execute_python_code!
- HANYA jika pertanyaan pengguna berupa penjelasan konsep dasar teori, logika matematika sederhana, atau percakapan kasual yang sama sekali tidak membutuhkan fakta atau kalkulasi: Anda boleh langsung menjawab tanpa memanggil alat.

3. MANDAT PENCARIAN GLOBAL & KUERI BAHASA INGGRIS (GLOBAL SEARCH & ENGLISH QUERY MANDATE):
- Prioritas utama pencarian web adalah INDEKS GLOBAL DUNIA (World-Wide Web) dari sumber-sumber internasional bereputasi tinggi (misal: Reuters, Bloomberg, TechCrunch, The Verge, ArXiv, Nature, BBC, Wired, IEEE, GitHub, Wikipedia Global).
- WAJIB DALAM BAHASA INGGRIS: Untuk setiap pemanggilan alat \`search_web\`, Anda WAJIB merumuskan parameter \`query\` dalam BAHASA INGGRIS (English), TERLEPAS DARI BAHASA INPUT PENGGUNA (bahkan ketika pengguna bertanya dalam bahasa Indonesia penuh).
- Terjemahkan dan ringkas konsep, topik, atau pertanyaan pengguna ke dalam kata kunci pencarian bahasa Inggris yang tepat, padat, dan representatif:
  * Contoh Input Pengguna: "apa berita besar model ai terbaru?"
    -> Pemanggilan Tool: search_web({"query": "latest major AI models news breakthroughs"}) (BUKAN bahasa Indonesia!)
  * Contoh Input Pengguna: "siapa pemenang liga champions dan berita transfer sepak bola?"
    -> Pemanggilan Tool: search_web({"query": "champions league winners and latest football transfer news"})
  * Contoh Input Pengguna: "kondisi pasar saham dan harga emas dunia saat ini"
    -> Pemanggilan Tool: search_web({"query": "global stock market trends and gold prices today"})
  * Pengecualian Satu-satunya: HANYA jika pengguna secara EKSPLISIT menanyakan hal spesifik domestik lokal Indonesia (contoh: "jadwal imsakiyah Jakarta", "BMKG gempa Jawa Barat", "kurs rupiah BI"). Selain permintaan eksplisit domestik lokal tersebut, SEMUA kueri pencarian web WAJIB dalam bahasa Inggris global!

4. SINTESIS SETELAH EKSEKUSI ALAT & BAHASA JAWABAN:
- Meskipun pencarian web dilakukan dalam bahasa Inggris dari sumber-sumber global dunia, Anda WAJIB menyajikan dan menjawab kembali kepada pengguna dalam BAHASA INDONESIA (atau bahasa yang diminta pengguna) secara alami, lengkap, fasih, dan mendalam.
- FOKUS DAN RELEVANSI TINGGI: Jawablah pertanyaan pengguna secara langsung, relevan, dan terarah. Jika pengguna bertanya tentang model AI, fokuslah pada inovasi dan rilis model AI terkemuka (seperti OpenAI GPT/o-series, Claude, Gemini, Meta Llama, DeepSeek, Mistral, xAI). Jangan mengalihkan jawaban ke artikel finansial/saham sampingan atau blog regional yang tidak relevan.
- ANTI-HALUSINASI & FAKTUALITAS KETAT: Dilarang keras mengarang berita, melompat ke kesimpulan fiktif (seperti konsorsium gabungan palsu atau tanggal peluncuran imajiner). Hanya sintesiskan informasi yang benar-benar didukung oleh fakta web.
- Setelah sistem mengeksekusi alat dan menyediakan data kepada Anda, berikan jawaban akhir yang komprehensif, jelas, akurat, dan informatif.
- Wajib sertakan referensi tautan markdown [Nama Sumber](URL) jika merujuk fakta web spesifik.
- Jawab secara langsung tanpa penolakan kaku, tanpa basa-basi robotik, dan tanpa mencetak format pemanggilan tool lagi.`;
  }
  const AUTONOMOUS_SYSTEM_DIRECTIVE = getAutonomousSystemDirective();

  function getYouTubeToolDirective() {
    return `### INSTRUKSI SISTEM: TOOL PENCARIAN YOUTUBE (search_youtube)

Tool \`search_youtube\` aktif untuk mencari video resmi di YouTube.

1. KAPAN WAJIB DIPAKAI:
- Pengguna meminta mencarikan/menemukan/mencari/memutar/menonton sebuah video (YouTube, video tutorial, klip musik, podcast, vlog, review, dsb).
- Argumen \`query\` berisi kata kunci alami hasil ekstraksi dari permintaan pengguna (misal: "tutorial React JS untuk pemula").
- Argumen \`max_results\` opsional (1-10, default 6).

2. FORMAT PEMANGGILAN (dukung SEMUA model):
Format native/JSON:
  {"name":"search_youtube","arguments":{"query":"kata kunci","max_results":6}}
Format teks (untuk model tanpa function calling):
  search_youtube("kata kunci")
  atau: search_youtube({"query":"kata kunci"})

3. SETELAH SISTEM MENGEMBALIKAN HASIL:
- Jelaskan dan rekomendasikan video yang paling relevan secara jelas (judul, channel, durasi, jumlah tayangan).
- WAJIB menyertakan tautan video pilihan Anda secara langsung di dalam jawaban akhir dengan format markdown, misal [Judul Video](URL_VIDEO), agar kartu video dapat ditampilkan dan diputar langsung di dalam percakapan.
- Jangan mengarang data video; gunakan hanya hasil yang diberikan sistem.`;
  }

  function createAutonomousToolHudHtml(toolName, targetText, status = 'loading') {
    const norm = normalizeToolName(toolName);
    const isYouTube = norm === 'search_youtube';
    const isBrowse = norm === 'browse_web_page' || norm === 'extract_web';
    const isSaveMem = norm === 'save_memory';
    const isSearchMem = norm === 'search_memory';
    const isCode = norm === 'execute_python_code';

    // iconClass sudah memuat prefiks family-nya (fa-solid / fa-brands) agar tidak
    // bentrok dengan aturan font-family bila digabung dengan fa-solid.
    let iconClass = status === 'loading' ? 'fa-solid fa-magnifying-glass fa-spin' : 'fa-solid fa-circle-check';
    let title = 'PENCARIAN WEB LIVE (ZERO-API)';

    if (isYouTube) {
      title = 'PENCARIAN VIDEO YOUTUBE LIVE';
      iconClass = status === 'loading' ? 'fa-brands fa-youtube fa-spin' : 'fa-brands fa-youtube';
    } else if (isBrowse) {
      title = (norm === 'extract_web' || toolName === 'read_url') ? 'EKSTRAKSI KONTEN WEB' : 'PENJELAJAHAN HALAMAN WEB';
      iconClass = status === 'loading' ? 'fa-solid fa-compass fa-spin' : 'fa-solid fa-circle-check';
    } else if (isSaveMem) {
      title = 'PENYIMPANAN MEMORI JANGKA PANJANG (SQLITE FTS5)';
      iconClass = status === 'loading' ? 'fa-solid fa-floppy-disk fa-spin' : 'fa-solid fa-floppy-disk';
    } else if (isSearchMem) {
      title = 'PENCARIAN MEMORI JANGKA PANJANG (SQLITE FTS5)';
      iconClass = status === 'loading' ? 'fa-solid fa-brain fa-spin' : 'fa-solid fa-brain';
    } else if (isCode) {
      title = 'EKSEKUSI PYTHON SANDBOX (SUBPROCESS)';
      iconClass = status === 'loading' ? 'fa-brands fa-python fa-spin' : 'fa-brands fa-python';
    }

    let actionText = '';
    let subText = '';

    if (isYouTube) {
      actionText = status === 'loading' ? `Mencari video: "${escapeHtml(targetText)}"` : `Video ditemukan: "${escapeHtml(targetText)}"`;
      subText = status === 'loading' ? 'Menelusuri katalog video YouTube secara langsung...' : 'Daftar video siap diputar langsung di percakapan...';
    } else if (isBrowse) {
      actionText = status === 'loading' ? `Mengekstrak URL: "${escapeHtml(targetText)}"` : `Halaman selesai diekstrak: "${escapeHtml(targetText)}"`;
      subText = status === 'loading' ? 'Mengekstrak teks & konten halaman secara langsung...' : 'Konten halaman diserap & disintesis oleh AI...';
    } else if (isSaveMem) {
      actionText = status === 'loading' ? `Menyimpan memori: "${escapeHtml(targetText)}"` : `Memori tersimpan: "${escapeHtml(targetText)}"`;
      subText = status === 'loading' ? 'Merekam fakta ke database lokal SQLite FTS5...' : 'Fakta tersimpan permanen di memori lokal...';
    } else if (isSearchMem) {
      actionText = status === 'loading' ? `Mencari memori: "${escapeHtml(targetText)}"` : `Pencarian memori selesai: "${escapeHtml(targetText)}"`;
      subText = status === 'loading' ? 'Memindai riwayat memori lokal SQLite...' : 'Catatan masa lalu siap dicerna oleh AI...';
    } else if (isCode) {
      actionText = status === 'loading' ? `Menjalankan kode Python: "${escapeHtml(targetText)}"` : `Eksekusi kode selesai: "${escapeHtml(targetText)}"`;
      subText = status === 'loading' ? 'Menjalankan kalkulasi di sandbox subprocess lokal...' : 'Hasil keluaran terminal siap disintesis oleh AI...';
    } else {
      actionText = status === 'loading' ? `Mencari web: "${escapeHtml(targetText)}"` : `Pencarian selesai: "${escapeHtml(targetText)}"`;
      subText = status === 'loading' ? 'Mengumpulkan berita live & multi-sumber terkini...' : 'Data berita aktual diserap & disintesis oleh AI...';
    }

    return `
      <div class="autonomous-tool-hud${status === 'done' ? ' done' : ''}">
        <div class="autonomous-tool-icon-wrap">
          <i class="${iconClass}"></i>
        </div>
        <div class="autonomous-tool-content">
          <div class="autonomous-tool-title">
            <span>${title}</span>
            <span style="font-size:0.75rem; font-weight:normal; opacity:0.8;">[${escapeHtml(toolName)}]</span>
          </div>
          <div class="autonomous-tool-subtext">
            <strong>${actionText}</strong> &mdash; ${subText}
          </div>
        </div>
      </div>
    `;
  }

  function deduplicateSources(sources) {
    if (!Array.isArray(sources)) return [];
    const seen = new Set();
    const result = [];
    for (const s of sources) {
      if (!s || !s.url) continue;
      const norm = String(s.url).trim().toLowerCase();
      if (!seen.has(norm)) {
        seen.add(norm);
        result.push(s);
      }
    }
    return result;
  }

  // ==================== UNIVERSAL MODEL ERROR & WARNING HANDLER ====================
  function formatModelErrorMessage(engine, modelName, err, hasImage = false, hasWebSearch = false) {
    const rawMsg = (err && err.message) ? err.message : String(err || 'Unknown error');
    const msg = rawMsg.toLowerCase();
    const isMixedContentLocal = (location.protocol === 'https:' || IS_CLOUD_HOSTED) && (
      msg.includes('mixed_content') || 
      ((msg.includes('failed to fetch') || msg.includes('networkerror') || err?.name === 'TypeError') && engine === 'ollama')
    );
    const isCorsOrNetwork = (IS_GITHUB_PAGES || IS_CLOUD_HOSTED) && (msg.includes('failed to fetch') || msg.includes('networkerror') || err?.name === 'TypeError');
    const actualHasImage = Array.isArray(hasImage) ? hasImage.length > 0 : Boolean(hasImage);
    const isVisionUnsupported = actualHasImage && (
      msg.includes('image') || 
      msg.includes('vision') || 
      msg.includes('multimodal') || 
      msg.includes('does not support image') ||
      msg.includes('unsupported image') ||
      msg.includes('no endpoints found that support image')
    );
    const isAuthError = msg.includes('401') || msg.includes('unauthorized') || msg.includes('api key') || msg.includes('user not found');
    const isModelNotFound = msg.includes('404') || msg.includes('not found') || msg.includes('no endpoints') || msg.includes('does not exist');
    const isRateLimit = msg.includes('429') || msg.includes('rate limit') || msg.includes('quota') || msg.includes('credits') || msg.includes('free tier limit');
    const isContextLength = msg.includes('context length') || msg.includes('token limit') || msg.includes('maximum context');
    const isProviderReturnedError = msg.includes('provider returned error') || msg.includes('upstream error') || msg.includes('provider error') || msg.includes('provider rejected');

    let title = `Peringatan Model: ${escapeHtml(modelName)}`;
    let desc = escapeHtml(rawMsg);
    let advice = '';

    if (isMixedContentLocal && engine === 'ollama') {
      title = `Koneksi Ollama Cloud Dialihkan ke Jalur Cadangan`;
      desc = `Model cloud <code>${escapeHtml(modelName)}</code> sedang dialihkan ke jalur streaming Cloud AI yang aktif.`;
      advice = `💡 <strong>Solusi Cepat:</strong> Klik <strong>Coba Kirim Ulang</strong> atau pilih model resmi lainnya dari katalog Model Hub.`;
    } else if (isVisionUnsupported) {
      title = `Model ${escapeHtml(modelName)} Tidak Mendukung Input Gambar`;
      desc = `Model ini menolak pemrosesan gambar multimodal karena beroperasi dalam mode teks murni (text-only).`;
      advice = `💡 <strong>Saran:</strong> Beralihlah ke model multimodal aktif seperti <code>google/gemma-4-31b-it:free</code>, <code>google/gemini-2.5-flash</code>, <code>openai/gpt-4o</code>, atau kirim prompt Anda tanpa lampiran gambar.`;
    } else if (engine === 'openrouter' && (msg.includes('402') || msg.includes('insufficient') || msg.includes('payment required') || msg.includes('credit'))) {
      title = `Model Berbayar Memerlukan Saldo OpenRouter (HTTP 402)`;
      desc = `Model <code>${escapeHtml(modelName)}</code> adalah model cloud berbayar (paid tier) dan saldo kredit OpenRouter Anda belum mencukupi untuk memproses permintaan ini.`;
      advice = `💡 <strong>Solusi Cepat:</strong> Klik tombol <strong>Ganti ke Model Gratis &amp; Kirim Ulang</strong> di bawah untuk menggunakan model tanpa biaya, atau isi ulang kredit OpenRouter Anda di <code>openrouter.ai</code>.`;
    } else if (engine === 'openrouter' && (msg.includes('failed to fetch') || msg.includes('networkerror') || err?.name === 'TypeError')) {
      title = `Koneksi ke OpenRouter Terganggu / Terblokir Jaringan`;
      desc = `Koneksi browser ke API OpenRouter gagal dilakukan (${escapeHtml(rawMsg)}). Hal ini bisa disebabkan oleh kebijakan CORS, VPN, pemblokir iklan (adblocker), atau jaringan internet Anda.`;
      advice = `💡 <strong>Solusi Cepat:</strong> Coba klik <strong>Coba Kirim Ulang</strong> atau beralih ke model gratis stabil dengan klik <strong>Ganti ke Model Gratis &amp; Kirim Ulang</strong>.`;
    } else if (isProviderReturnedError) {
      title = `Penyedia Model OpenRouter Sedang Sibuk (Upstream Provider Error)`;
      desc = `Server penyedia pihak ketiga (upstream) untuk model <code>${escapeHtml(modelName)}</code> sedang mengalami antrean penuh atau gangguan sementara di OpenRouter.`;
      advice = `💡 <strong>Solusi Cepat:</strong> Coba beralih ke model free lain yang sedang aktif stabil seperti <code>openrouter/free</code> atau <code>nvidia/nemotron-3-super-120b-a12b:free</code>, atau klik <strong>Ganti ke Model Gratis &amp; Kirim Ulang</strong>.`;
    } else if (isCorsOrNetwork && engine === 'ollama') {
      title = `Jalur Cloud Sedang Menyinkronkan Model`;
      desc = `Koneksi ke endpoint cloud untuk model <code>${escapeHtml(modelName)}</code> mengalami kendala jaringan sementara (${escapeHtml(rawMsg)}).`;
      advice = `💡 <strong>Solusi Cepat:</strong> Klik <strong>Coba Kirim Ulang</strong> untuk menjalankan via jalur cloud tercepat.`;
    } else if (isAuthError) {
      title = `Autentikasi / API Key Diperlukan`;
      desc = `API Key untuk provider <strong>${engine === 'ollama' ? 'Ollama Cloud' : 'OpenRouter'}</strong> tidak valid, belum diisi, atau kadaluarsa.`;
      advice = `💡 <strong>Solusi:</strong> Buka menu <strong>Pengaturan (⚙️)</strong> dan periksa kembali API Key Anda.`;
    } else if (isRateLimit) {
      title = `Batas Kuota / Rate Limit Provider Tercapai`;
      desc = `Permintaan ditolak oleh server provider karena batas kuota sementara atau beban server sedang tinggi.`;
      advice = `💡 <strong>Solusi:</strong> Pilih model gratis lainnya dari katalog Model Hub atau tunggu beberapa detik sebelum mencoba kembali.`;
    } else if (isModelNotFound) {
      title = `Model Cloud Sedang Dialihkan ke Provider Alternatif`;
      desc = `ID Model <code>${escapeHtml(modelName)}</code> sedang dialihkan secara otomatis ke model cloud aktif yang setara di katalog Cloud Hub.`;
      advice = `💡 <strong>Solusi Cepat:</strong> Klik <strong>Coba Kirim Ulang</strong> atau pilih model resmi lainnya dari katalog Model Hub.`;
    } else if (isContextLength) {
      title = `Batas Panjang Konteks Terlampaui`;
      desc = `Jumlah teks prompt, dokumen, atau hasil pencarian web melebihi kapasitas context window model <code>${escapeHtml(modelName)}</code>.`;
      advice = `💡 <strong>Solusi:</strong> Ringkas teks prompt Anda atau gunakan model dengan context window besar seperti <code>kimi-k3</code> atau <code>google/gemini-2.0-flash-exp:free</code>.`;
    }

    return `
      <div style="background:rgba(255,170,0,0.08); border:1px solid rgba(255,170,0,0.35); border-radius:10px; padding:14px; margin-bottom:12px; line-height:1.5;">
        <div style="font-weight:700; color:var(--neon-amber); margin-bottom:6px; display:flex; align-items:center; gap:8px; font-size:0.9rem;">
          <i class="fa-solid fa-triangle-exclamation"></i> ${title}
        </div>
        <div style="font-size:0.83rem; color:var(--text-main); margin-bottom:8px;">
          ${desc}
        </div>
        ${advice ? `<div style="font-size:0.8rem; color:var(--text-secondary); background:rgba(0,0,0,0.3); padding:8px 10px; border-radius:6px; border-left:3px solid var(--neon-cyan);">${advice}</div>` : ''}
      </div>
    `;
  }

  // Universal Message Payload Normalizer & Alternating Role Enforcer
  function doesModelSupportSystemRole(modelName) {
    if (!modelName || typeof modelName !== 'string') return true;
    const lower = modelName.toLowerCase();
    // Model Gemma, Liquid LFM, Inkling, Dots, Ling, dll. menolak role "system" di sebagian besar provider OpenRouter
    if (
      lower.includes('gemma') || 
      lower.includes('mistral-tiny') ||
      lower.includes('lfm') ||
      lower.includes('liquid') ||
      lower.includes('inkling') ||
      lower.includes('dots-') ||
      lower.includes('ling-') ||
      lower.includes('apodex')
    ) {
      return false;
    }
    return true;
  }

  // Helper cerdas: Mengonversi path gambar lokal (/uploads/) menjadi Base64 Data URL di browser
  async function resolveImageToDataUrlSafe(img) {
    if (!img || typeof img !== 'string') return img;
    if (img.startsWith('data:image')) return img;
    if (img.startsWith('/uploads/') || img.includes('/uploads/')) {
      try {
        const resp = await fetch(img);
        if (resp.ok) {
          const blob = await resp.blob();
          return await new Promise((resolve) => {
            const reader = new FileReader();
            reader.onloadend = () => resolve(reader.result);
            reader.onerror = () => resolve(img);
            reader.readAsDataURL(blob);
          });
        }
      } catch (_) {}
    }
    return img;
  }

  function buildSanitizedMessagesPayload(sessionOrMessages, currentImages = [], engine = 'openrouter', systemContent = '', modelName = '') {
    const messagesPayload = [];
    const supportsSystem = doesModelSupportSystemRole(modelName);

    const rawList = Array.isArray(sessionOrMessages?.messages) ? sessionOrMessages.messages : (Array.isArray(sessionOrMessages) ? sessionOrMessages : []);
    const validList = [];

    rawList.forEach((m, idx) => {
      const isLatestTurn = (idx === rawList.length - 1);
      const mImgs = (isLatestTurn && Array.isArray(currentImages) && currentImages.length > 0)
        ? currentImages
        : (Array.isArray(m.images) && m.images.length > 0 ? m.images : (m.image ? [m.image] : []));

      const textContent = (m.content || '').trim();
      if (!textContent && mImgs.length === 0) {
        return; // skip blank message turns
      }

      validList.push({
        role: m.role || 'user',
        content: textContent || (mImgs.length > 0 ? 'Analisis gambar terlampir ini.' : '...'),
        images: mImgs
      });
    });

    if (validList.length === 0) {
      validList.push({ role: 'user', content: 'Halo', images: [] });
    }

    const activePersona = (STATE.settings.systemPrompt ? STATE.settings.systemPrompt.trim() : '');

    if (systemContent && systemContent.trim()) {
      if (supportsSystem) {
        messagesPayload.push({ role: 'system', content: systemContent.trim() });
      } else {
        // Untuk model yang tidak mendukung role system (misal: Gemma), lebur konteks sistem ke turn user pertama
        const firstUserMsg = validList.find(m => m.role === 'user');
        if (firstUserMsg) {
          firstUserMsg.content = `[Instruksi Sistem & Konteks:\n${systemContent.trim()}]\n\n${firstUserMsg.content}`;
        } else {
          validList.unshift({ role: 'user', content: `[Instruksi Sistem & Konteks:\n${systemContent.trim()}]`, images: [] });
        }
      }
    }

    // Penguat persona multi-turn & continuity: pastikan persona tidak luntur pada giliran obrolan lanjutan
    if (activePersona && validList.length > 1) {
      const lastUserMsg = [...validList].reverse().find(m => m.role === 'user');
      if (lastUserMsg && typeof lastUserMsg.content === 'string' && !lastUserMsg.content.includes('[Pengingat Persona:')) {
        const personaReminderText = activePersona.length > 800 ? activePersona.slice(0, 800) + '...' : activePersona;
        lastUserMsg.content = `[Pengingat Persona: Tetap adopsi identitas persona yang ditetapkan]:\n"${personaReminderText}"\n\n${lastUserMsg.content}`;
      }
    }

    // Merge consecutive messages with the same role to strictly enforce alternating roles
    const mergedList = [];
    for (const msg of validList) {
      if (mergedList.length > 0 && mergedList[mergedList.length - 1].role === msg.role) {
        const prev = mergedList[mergedList.length - 1];
        prev.content = `${prev.content}\n\n${msg.content}`.trim();
        if (msg.images && msg.images.length > 0) {
          prev.images = [...(prev.images || []), ...msg.images];
        }
      } else {
        mergedList.push({ ...msg });
      }
    }

    const lastIdx = mergedList.length - 1;
    mergedList.forEach((m, idx) => {
      const isLatestTurn = (idx === lastIdx);
      const imgs = m.images || [];

      if (engine === 'ollama') {
        const item = { role: m.role, content: m.role === 'assistant' ? safeAssistantText(m.content || '...') : (m.content || '...') };
        if (imgs.length > 0 && isLatestTurn) {
          const rawImages = [];
          imgs.forEach(img => {
            if (typeof img === 'string') {
              if (img.startsWith('data:image')) {
                const raw = String(img).replace(/^data:image\/[a-z0-9.+_-]+;base64,/i, '').replace(/[\r\n\s]/g, '');
                if (raw) rawImages.push(raw);
              } else if (/^[A-Za-z0-9+/=]+$/.test(img.trim()) && img.trim().length > 50) {
                rawImages.push(img.trim().replace(/[\r\n\s]/g, ''));
              }
            }
          });
          if (rawImages.length > 0) item.images = rawImages;
        }
        messagesPayload.push(item);
      } else {
        // OpenRouter / OpenAI format
        if (imgs.length > 0 && m.role === 'user') {
          if (isLatestTurn) {
            const contentParts = [
              { type: 'text', text: m.content || 'Jelaskan dan analisis gambar terlampir ini.' }
            ];
            imgs.forEach(img => {
              if (typeof img === 'string') {
                if (img.startsWith('data:image')) {
                  contentParts.push({ type: 'image_url', image_url: { url: img } });
                } else if (img.startsWith('http://') || img.startsWith('https://')) {
                  try {
                    const parsed = new URL(img);
                    const host = parsed.hostname.toLowerCase();
                    const isPrivate = host === 'localhost' || host === '127.0.0.1' || host === '::1' || host.startsWith('192.168.') || host.startsWith('10.') || host.endsWith('.local');
                    if (!isPrivate) {
                      contentParts.push({ type: 'image_url', image_url: { url: img } });
                    }
                  } catch (_) {
                    contentParts.push({ type: 'image_url', image_url: { url: img } });
                  }
                } else if (img.startsWith('/uploads/')) {
                  const host = window.location.hostname.toLowerCase();
                  const isPrivate = host === 'localhost' || host === '127.0.0.1' || host === '::1' || host.startsWith('192.168.') || host.startsWith('10.') || host.endsWith('.local');
                  if (!isPrivate && window.location.protocol === 'https:') {
                    const fullUrl = `${window.location.origin}${img}`;
                    contentParts.push({ type: 'image_url', image_url: { url: fullUrl } });
                  } else {
                    // Di localhost/intranet, biarkan path /uploads/ relatif agar proxy backend server.js mengonversinya ke Base64
                    contentParts.push({ type: 'image_url', image_url: { url: img } });
                  }
                }
              }
            });
            messagesPayload.push({ role: m.role, content: contentParts });
          } else {
            // Pada riwayat pesan lama, hindari pengiriman ulang data Base64 gambar agar payload tetap ringan (<100KB)
            const textSummary = m.content || '[Pengguna melampirkan gambar untuk dianalisis]';
            messagesPayload.push({ role: m.role, content: textSummary });
          }
        } else {
          const messageContent = m.content || '...';
          messagesPayload.push({
            role: m.role,
            content: m.role === 'assistant' ? safeAssistantText(messageContent) : messageContent
          });
        }
      }
    });

    return messagesPayload;
  }

  // --- OLLAMA STREAMING EXECUTION ---
  async function runOllamaStreaming(session, promptText, image, modelName, runOptions = {}) {
    // 100% Pure Cloud Architecture: Delegasikan eksekusi model Ollama ke Cloud Streaming
    const ep = normalizeEndpoint(STATE.settings.ollamaEndpoint);
    const hasCustomExternalEndpoint = Boolean(STATE.settings.ollamaApiKey && !ep.includes('ollama.com') && !ep.includes('127.0.0.1') && !ep.includes('localhost'));
    if (!hasCustomExternalEndpoint) {
      const targetCloudModel = modelName.includes('/')
        ? modelName
        : (mapOllamaModelToOpenRouter(modelName) || 'openrouter/free');
      return await runOpenRouterStreaming(session, promptText, image, targetCloudModel, {
        displayModel: modelName,
        engineLabel: 'Ollama Cloud',
        engineMode: 'ollama'
      });
    }

    setGeneratingState(true);
    STATE.abortController = new AbortController();

    const startTime = performance.now();
    let firstTokenTime = null;
    let tokenCount = 0;

    // Append initial assistant placeholder bubble
    const assistantRow = appendMessageElement('assistant', '', null, modelName);
    const bubbleText = assistantRow.querySelector('.msg-text-content');
    const metaBox = assistantRow.querySelector('.message-meta');
    bubbleText.innerHTML = '<span class="typing-cursor"></span>';
    smartScrollChatToBottom(true);

    let fullText = '';
    let webSources = null;
    let streamRenderer = null;
    let executedHudHtml = '';
    const foundYouTubeIds = []; // ID video hasil tool search_youtube (dipakai render kartu)
    const wantsFile = isFileGenerationRequest(promptText); // niat "buatkan file/website" untuk AI File Studio

    try {
      let personaPrompt = STATE.settings.systemPrompt ? STATE.settings.systemPrompt.trim() : '';
      const canRunAutonomous = Boolean(STATE.webSearchEnabled || STATE.searchMode === 'autonomous');
      let systemContent = '';
      if (personaPrompt) {
        systemContent = `### MANDAT PERSONA UTAMA (PRIORITAS TERTINGGI - IDENTITAS KARAKTER ANDA)\n[PENTING: Anda WAJIB mengadopsi persona dan gaya komunikasi berikut dalam SETIAP respon]:\n${personaPrompt}\n----------------------------------------`;
      }
      if (canRunAutonomous) {
        systemContent = systemContent ? `${systemContent}\n\n${getAutonomousSystemDirective()}` : getAutonomousSystemDirective();
      }
      // Tool video YouTube hanya diumumkan bila toggle "Cari Video YouTube" aktif
      // (agar model tidak memanggil tool yang tidak dikirim).
      if (STATE.isYouTubeSearchMode) {
        systemContent = systemContent
          ? `${systemContent}\n\n${getYouTubeToolDirective()}`
          : getYouTubeToolDirective();
      }

      // AI File Studio: selalu diumumkan agar model tahu format blok ZOZ_FILE
      // ketika pengguna meminta pembuatan file / website.
      systemContent = systemContent
        ? `${systemContent}\n\n${getFileStudioDirective()}`
        : getFileStudioDirective();

      // UNIVERSAL YOUTUBE METADATA GROUNDING FOR ALL MODELS
      try {
        const ytRes = await getYouTubeGroundingContext(promptText, bubbleText);
        if (ytRes && ytRes.groundingContext) {
          systemContent = `${systemContent}\n\n${ytRes.groundingContext}`;
          bubbleText.innerHTML = '<span class="typing-cursor"></span>';
        }
      } catch (ytErr) {
        console.warn('YouTube client grounding error:', ytErr);
      }

      // WEB SEARCH GROUNDING:
      // Aktif pada mode default search, atau sebagai fallback otomatis ketika mode autonomous search
      // berjalan pada model tanpa dukungan tools atau model gratis (agar tetap mendapat data internet terkini).
      const ep = normalizeEndpoint(STATE.settings.ollamaEndpoint);
      const hasCustomExternalEndpoint = Boolean(STATE.settings.ollamaApiKey && !ep.includes('ollama.com') && !ep.includes('127.0.0.1') && !ep.includes('localhost'));
      const effectiveCloudModel = mapOllamaModelToOpenRouter(modelName) || 'openrouter/free';
      const isCloudFree = effectiveCloudModel.includes(':free') || effectiveCloudModel.endsWith('/free') || effectiveCloudModel === 'openrouter/free';
      const needsGroundingFallback = STATE.searchMode === 'autonomous' && (
        !hasCustomExternalEndpoint ? (isCloudFree || !STATE.settings.openRouterKey || !doesModelSupportTools(effectiveCloudModel)) : !doesModelSupportTools(modelName)
      );
      if (STATE.searchMode === 'default' || (STATE.webSearchEnabled && needsGroundingFallback)) {
        try {
          const searchRes = await getWebSearchContext(promptText, session, bubbleText, needsGroundingFallback);
          if (searchRes && searchRes.systemPromptContext) {
            systemContent = systemContent
              ? `${systemContent}\n\n${searchRes.systemPromptContext}`
              : searchRes.systemPromptContext;
            if (searchRes.sources && Array.isArray(searchRes.sources)) {
              if (!webSources) webSources = [];
              webSources.push(...searchRes.sources);
            }
            bubbleText.innerHTML = '<span class="typing-cursor"></span>';
          }
        } catch (searchErr) {
          console.warn('Web search grounding error:', searchErr);
        }
      }

      if (personaPrompt) {
        systemContent = `${systemContent}\n\n### MANDAT MUTLAK PERSONA (PENEGASAN AKHIR):\n[PENTING: Terlepas dari semua instruksi pencarian web, tool, atau format di atas, Anda WAJIB TETAP MENGADOPSI IDENTITAS DAN KARAKTER PERSONA BERIKUT DALAM SETIAP RESPON]:\n${personaPrompt}\n----------------------------------------`;
      }

      const rawImgs = Array.isArray(image) ? image : (image ? [image] : []);
      const resolvedImgs = await Promise.all(rawImgs.map(resolveImageToDataUrlSafe));
      const messagesPayload = buildSanitizedMessagesPayload(session, resolvedImgs, 'ollama', systemContent, modelName);

      const requestBody = {
        model: modelName,
        sessionId: session?.id || null,
        messages: messagesPayload,
        stream: true,
        options: {
          temperature: parseFloat(STATE.settings.temperature),
          top_p: parseFloat(STATE.settings.topP),
          repeat_penalty: 1.15
        },
        endpoint: ep
      };
      // Tool video YouTube selalu disertakan; tool web hanya saat Mode Pencarian Web aktif.
      const selectedOllamaTools = getSelectableAutonomousTools(canRunAutonomous);
      if (selectedOllamaTools.length > 0) requestBody.tools = selectedOllamaTools;
      if (session?.id) {
        requestBody.sessionId = session.id;
      }
      if (STATE.userId) {
        requestBody.userId = STATE.userId;
      }
      if (STATE.settings.ollamaApiKey) {
        requestBody.apiKey = STATE.settings.ollamaApiKey;
      }
      if (STATE.settings.openRouterKey) {
        requestBody.openRouterKey = STATE.settings.openRouterKey;
      }

      const headers = { 'Content-Type': 'application/json' };
      if (session?.id) {
        headers['X-Session-ID'] = session.id;
      }
      if (STATE.userId) {
        headers['X-User-ID'] = STATE.userId;
      }
      if (STATE.settings.ollamaApiKey) {
        headers['Authorization'] = `Bearer ${STATE.settings.ollamaApiKey}`;
        headers['x-ollama-key'] = STATE.settings.ollamaApiKey;
      }
      if (STATE.settings.openRouterKey) {
        headers['x-openrouter-key'] = STATE.settings.openRouterKey;
      }

      let chatUrl = '/api/ollama/chat';
      if (IS_GITHUB_PAGES) {
        if (location.protocol === 'https:' && /^http:\/\/(?:localhost|127\.0\.0\.1|\[::1\])/i.test(ep)) {
          throw new Error('mixed_content: Browser HTTPS memblokir koneksi ke Ollama localhost HTTP di GitHub Pages.');
        }
        chatUrl = resolveEndpointUrl(ep, 'api/chat');
      } else {
        // Pada Vercel / server gateway: jika di halaman HTTPS dan endpoint masih loopback,
        // alihkan endpoint ke https://ollama.com agar backend menjangkau Ollama Cloud tanpa mixed content
        if (location.protocol === 'https:' && /^http:\/\/(?:localhost|127\.0\.0\.1|\[::1\])/i.test(ep)) {
          requestBody.endpoint = 'https://ollama.com';
        }
        chatUrl = '/api/ollama/chat';
      }

      let response = await fetch(chatUrl, {
        method: 'POST',
        headers,
        body: JSON.stringify(requestBody),
        signal: STATE.abortController?.signal
      });

      // Auto-retry fallback: jika model lokal Ollama menolak parameter tools (HTTP 400/422/500 "model does not support tools")
      if (!response.ok && requestBody.tools && (response.status === 400 || response.status === 422 || response.status === 500)) {
        console.warn(`[Ollama] Model ${modelName} returned HTTP ${response.status} with tools enabled. Retrying without tools parameter...`);
        delete requestBody.tools;
        response = await fetch(chatUrl, {
          method: 'POST',
          headers,
          body: JSON.stringify(requestBody),
          signal: STATE.abortController?.signal
        });
      }

      if (!response.ok) {
        let errDetail = `HTTP ${response.status}`;
        try {
          const errData = await response.json();
          if (errData && errData.error) {
            errDetail = typeof errData.error === 'object' ? (errData.error.message || JSON.stringify(errData.error)) : errData.error;
          }
        } catch (je) {
          try {
            const raw = await response.text();
            if (raw) errDetail = raw.substring(0, 200);
          } catch (te) {}
        }
        throw new Error(errDetail);
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      let doneReason = null;
      const accumulatedToolCalls = [];
      streamRenderer = new StreamBufferRenderer(bubbleText, () => smartScrollChatToBottom(false), executedHudHtml);

      function mergeToolCallsInto(targetArr, toolCallsArray) {
        if (!Array.isArray(toolCallsArray)) return;
        toolCallsArray.forEach((tc, defaultIdx) => {
          const idx = tc.index ?? defaultIdx;
          if (!targetArr[idx]) {
            targetArr[idx] = {
              id: tc.id || `call_${Date.now()}_${idx}`,
              type: tc.type || 'function',
              function: {
                name: tc.function?.name || '',
                arguments: typeof tc.function?.arguments === 'object' ? tc.function.arguments : (tc.function?.arguments || '')
              }
            };
          } else {
            if (tc.id) targetArr[idx].id = tc.id;
            if (tc.function?.name) {
              if (!targetArr[idx].function.name) {
                targetArr[idx].function.name = tc.function.name;
              } else if (targetArr[idx].function.name !== tc.function.name && !targetArr[idx].function.name.endsWith(tc.function.name)) {
                targetArr[idx].function.name += tc.function.name;
              }
            }
            if (tc.function?.arguments) {
              if (typeof tc.function.arguments === 'object') {
                targetArr[idx].function.arguments = tc.function.arguments;
              } else if (typeof targetArr[idx].function.arguments === 'string') {
                targetArr[idx].function.arguments += tc.function.arguments;
              } else {
                targetArr[idx].function.arguments = tc.function.arguments;
              }
            }
          }
        });
      }

      while (true) {
        const { done, value } = await reader.read();
        if (done) {
          buffer += decoder.decode();
          break;
        }

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop(); // keep partial line

        for (const line of lines) {
          if (!line.trim()) continue;
          let parsed;
          try {
            parsed = JSON.parse(line);
          } catch (pe) {
            continue;
          }
          if (parsed.error) {
            const errStr = typeof parsed.error === 'object' ? (parsed.error.message || JSON.stringify(parsed.error)) : parsed.error;
            throw new Error(errStr);
          }
          if (parsed.done_reason) doneReason = parsed.done_reason;
          const chunk = parsed.message?.content || parsed.response || '';
          const reasoningChunk = parsed.message?.reasoning || parsed.reasoning || '';
          if (reasoningChunk) {
            streamRenderer.appendReasoning(reasoningChunk);
          }
          if (chunk) {
            if (!firstTokenTime) firstTokenTime = performance.now();
            tokenCount++;
            if (tokenCount % 25 === 0) {
              BioEndocrine.secreteDopamine(0.3, 'Ollama streaming aktif');
            }
            streamRenderer.append(chunk);
            if (streamRenderer.isLoopTerminated) {
              console.warn('[Ollama] Model token degeneration loop detected and gracefully halted.');
              try { await reader.cancel(); } catch (_) {}
              break;
            }
          }
          if (parsed.message?.tool_calls && Array.isArray(parsed.message.tool_calls)) {
            mergeToolCallsInto(accumulatedToolCalls, parsed.message.tool_calls);
          }
        }
      }

      if (buffer && buffer.trim()) {
        try {
          const parsed = JSON.parse(buffer.trim());
          if (parsed.error) {
            const errStr = typeof parsed.error === 'object' ? (parsed.error.message || JSON.stringify(parsed.error)) : parsed.error;
            throw new Error(errStr);
          }
          if (parsed.done_reason) doneReason = parsed.done_reason;
          const chunk = parsed.message?.content || parsed.response || '';
          const reasoningChunk = parsed.message?.reasoning || parsed.reasoning || '';
          if (reasoningChunk) {
            streamRenderer.appendReasoning(reasoningChunk);
          }
          if (chunk) {
            if (!firstTokenTime) firstTokenTime = performance.now();
            tokenCount++;
            streamRenderer.append(chunk);
          }
          if (parsed.message?.tool_calls && Array.isArray(parsed.message.tool_calls)) {
            mergeToolCallsInto(accumulatedToolCalls, parsed.message.tool_calls);
          }
        } catch (_) {}
      }

      // render:false → render final tunggal ada di bawah (finalRenderedContent),
      // sehingga renderMarkdown + enhanceCodeBlocks/hljs tidak dijalankan dua kali.
      fullText = safeAssistantText(streamRenderer.finish({ render: false }));

      // ==================== OLLAMA AUTONOMOUS LIVE WEB SEARCH DIGESTION ENGINE ====================
      const canRunAutonomousSearch = Boolean(STATE.webSearchEnabled || STATE.searchMode === 'autonomous');
      const maxAutonomousRounds = 3;
      let autonomousRound = 0;
      let consecutiveFailedRounds = 0;
      let preambleHtml = '';
      const conversationChain = [...messagesPayload];
      let currentRoundText = fullText;
      let currentRoundNativeCalls = accumulatedToolCalls;
      const executedToolSignatures = new Set();
      let allAccumulatedToolResponsesText = '';

      // Loop tetap dijalankan walau Mode Pencarian Web mati: filter izin di bawah
      // yang memblokir tool web, sementara search_youtube selalu diperbolehkan.
      while (autonomousRound < maxAutonomousRounds && !streamRenderer.isLoopTerminated) {
        if (STATE.abortController?.signal?.aborted) {
          const abortErr = new Error('The operation was aborted');
          abortErr.name = 'AbortError';
          throw abortErr;
        }

        const validNativeCalls = currentRoundNativeCalls.filter(tc => tc && tc.function && isKnownAutonomousTool(tc.function.name) && isAutonomousToolAllowed(tc.function.name, canRunAutonomousSearch));
        const inlineCalls = extractInlineToolCalls(currentRoundText).filter(tc => tc && tc.function && isKnownAutonomousTool(tc.function.name) && isAutonomousToolAllowed(tc.function.name, canRunAutonomousSearch));
        let rawAutonomousCalls = validNativeCalls.length > 0 ? validNativeCalls : inlineCalls;

        if (rawAutonomousCalls.length === 0) {
          break; // Model selesai merumuskan respon tanpa pemanggilan tool tambahan
        }

        // Filter out duplicate or loop tool calls
        const roundSignatures = new Set();
        const detectedAutonomousCalls = rawAutonomousCalls.filter(call => {
          if (!call || !call.function || !isKnownAutonomousTool(call.function.name)) return false;
          const sig = getAutonomousToolSignature(call);
          if (executedToolSignatures.has(sig) || roundSignatures.has(sig)) return false; // Cegah pemanggilan tool berulang (loop / duplicate)
          roundSignatures.add(sig);
          return true;
        });

        if (detectedAutonomousCalls.length === 0) {
          break; // Model selesai merumuskan respon final tanpa pemanggilan tool tambahan
        }

        autonomousRound++;
        let roundToolResponsesText = '';
        const toolSummaryList = [];

        // Amankan teks pembuka yang telah digenerasi model sebelum pemanggilan tool agar tidak terhapus
        const cleanAssistant = scrubRawToolCallArtifacts(currentRoundText).trim();
        if (!preambleHtml && cleanAssistant && cleanAssistant.length > 20) {
          preambleHtml = `<div class="autonomous-preamble-text" style="margin-bottom:8px;">${renderMarkdown(cleanAssistant)}</div>`;
        }

        const toolTaskItems = detectedAutonomousCalls.map(call => {
          const toolName = call.function.name;
          let previewArg = '';
          try {
            const raw = (typeof call.function.arguments === 'string') ? JSON.parse(call.function.arguments) : call.function.arguments;
            let parsedArgs = {};
            if (raw && typeof raw === 'object') {
              parsedArgs = raw;
            } else if (raw !== null && raw !== undefined) {
              parsedArgs = { query: String(raw), url: String(raw) };
            }
            if (parsedArgs.code) {
              previewArg = String(parsedArgs.code).replace(/\s+/g, ' ').slice(0, 40);
            } else if (parsedArgs.topic || parsedArgs.topik) {
              previewArg = String(parsedArgs.topic || parsedArgs.topik).slice(0, 40);
            } else if (parsedArgs.content || parsedArgs.isi || parsedArgs.konten || parsedArgs.catatan) {
              previewArg = String(parsedArgs.content || parsedArgs.isi || parsedArgs.konten || parsedArgs.catatan).slice(0, 40);
            } else {
              previewArg = parsedArgs.query || parsedArgs.cari || parsedArgs.kata_kunci || parsedArgs.judul || parsedArgs.url || parsedArgs.tautan || parsedArgs.link || parsedArgs.q || parsedArgs.keyword || parsedArgs.target || (Object.keys(parsedArgs).length === 0 ? (promptText || '') : JSON.stringify(parsedArgs));
            }
          } catch (_) {
            previewArg = String(call.function.arguments || '');
          }

          executedToolSignatures.add(getAutonomousToolSignature(call));
          const summary = `${toolName}("${previewArg.substring(0, 40)}")`;
          return { call, toolName, previewArg, summary };
        });

        toolTaskItems.forEach(item => toolSummaryList.push(item.summary));

        // Tampilkan visual status loading untuk seluruh tool secara simultan
        bubbleText.innerHTML = preambleHtml + executedHudHtml + toolTaskItems.map(item => createAutonomousToolHudHtml(item.toolName, item.previewArg, 'loading')).join('');
        smartScrollChatToBottom(true);

        // Eksekusi seluruh tool secara paralel (Promise.all) untuk memangkas latensi jaringan
        const toolExecResults = await Promise.all(
          toolTaskItems.map(async (item) => {
            const toolExecRes = await executeAutonomousWebTool(item.toolName, item.call.function.arguments, promptText, session);
            return { ...item, toolExecRes };
          })
        );

        for (const resItem of toolExecResults) {
          const { toolName, previewArg, toolExecRes } = resItem;
          if (toolExecRes.sources && Array.isArray(toolExecRes.sources)) {
            if (!webSources) webSources = [];
            webSources.push(...toolExecRes.sources);
          }
          if (Array.isArray(toolExecRes.videoIds)) {
            toolExecRes.videoIds.forEach((vid) => {
              if (vid && !foundYouTubeIds.includes(vid)) foundYouTubeIds.push(vid);
            });
          }
          roundToolResponsesText += `\n[HASIL PENGUMPULAN DATA OTONOM (${toolName})]:\n${toolExecRes.text}\n`;
          executedHudHtml += createAutonomousToolHudHtml(toolName, previewArg, 'done');
        }
        allAccumulatedToolResponsesText += roundToolResponsesText;

        if (STATE.abortController?.signal?.aborted) {
          const abortErr = new Error('The operation was aborted');
          abortErr.name = 'AbortError';
          throw abortErr;
        }

        // Tampilkan HUD bahwa data berita live sedang disintesis oleh AI
        bubbleText.innerHTML = preambleHtml + executedHudHtml + `<div class="autonomous-digesting-box" style="margin-top:8px;"><span class="typing-cursor"></span> <span style="font-size:0.85em; opacity:0.85; font-style:italic; color:var(--neon-teal);"><i class="fa-solid fa-bolt"></i> Menyintesis hasil dan data otonom terbaru...</span></div>`;
        smartScrollChatToBottom(true);

        if (cleanAssistant) {
          conversationChain.push({ role: 'assistant', content: cleanAssistant });
        } else {
          conversationChain.push({ role: 'assistant', content: `[Mengeksekusi penelusuran otonom: ${toolSummaryList.join(', ')}]` });
        }

        const allToolsInRoundFailed = toolExecResults.length > 0 && toolExecResults.every(r => {
          if (r.toolExecRes && r.toolExecRes.success === false) return true;
          const t = String(r.toolExecRes?.text || '').trim();
          if (t.startsWith('Error:') || t.startsWith('Error eksekusi:') || t.startsWith('Error Keamanan:') || t.includes('Gagal membaca URL')) return true;
          if (t.includes('Error eksekusi:') || t.includes('Error Keamanan:') || t.includes('Error:')) return true;
          if (t.includes('tidak ditemukan video') || t.includes('Tidak ditemukan hasil spesifik')) return true;
          return false;
        });

        if (allToolsInRoundFailed) {
          consecutiveFailedRounds++;
        } else {
          consecutiveFailedRounds = 0;
        }

        // CIRCUIT BREAKER: Jika seluruh tool gagal dalam 2 putaran berturut-turut,
        // putuskan siklus dan paksa sintesis jawaban akhir untuk mencegah pemborosan token / looping tanpa henti.
        const circuitBreakerTripped = consecutiveFailedRounds >= 2;
        const isLastRound = circuitBreakerTripped || (autonomousRound >= maxAutonomousRounds - 1);
        const roundInstruction = isLastRound
          ? `[INFORMASI / DATA OTONOM TELAH TERSEDIA]:
${circuitBreakerTripped ? 'PERINGATAN SISTEM (CIRCUIT BREAKER AKTIF): Pemanggilan tool berturut-turut mengalami kegagalan akses (kemungkinan kendala jaringan/lingkungan). JANGAN memanggil tool lagi. Gunakan pengetahuan dasar yang Anda miliki untuk menjawab secara langsung, atau jelaskan dengan jujur kepada pengguna bahwa data eksternal tidak dapat diakses saat ini.' : 'Gunakan seluruh data hasil di atas untuk menjawab pertanyaan pengguna secara komprehensif, jelas, faktual, dan akurat.'}
Jika hasilnya berupa video YouTube: jelaskan dan rekomendasikan video yang paling relevan (judul, channel, durasi, tayangan), lalu WAJIB sisipkan tautan video pilihan Anda dengan format markdown [Judul Video](https://www.youtube.com/watch?v=ID) agar kartu video dapat ditampilkan dan diputar langsung di dalam percakapan.
Jawablah secara langsung dan tuntas tanpa penolakan kaku, tanpa basa-basi robotik, dan tanpa format pemanggilan tool lagi.`
          : `[INFORMASI / DATA OTONOM TELAH TERSEDIA]:
Data hasil eksekusi tool di atas telah disediakan untuk Anda.
Jika informasi sudah cukup lengkap, berikan jawaban akhir secara langsung dan tuntas kepada pengguna.
Namun jika Anda masih memerlukan data pendukung tambahan (misalnya membaca artikel lengkap dengan browse_web_page dari URL hasil pencarian, mencari memori tambahan, atau mengeksekusi kalkulasi kode Python), Anda dapat memanggil tool berikutnya yang relevan.`;

        conversationChain.push({
          role: 'user',
          content: `[DATA HASIL EKSEKUSI TOOL OTONOM]:\n${roundToolResponsesText}\n\n${roundInstruction}`
        });

        const digestionBody = {
          model: modelName,
          messages: conversationChain,
          stream: true,
          options: requestBody.options,
          endpoint: ep
        };
        if (!isLastRound && selectedOllamaTools && selectedOllamaTools.length > 0) {
          digestionBody.tools = selectedOllamaTools;
        }
        if (session?.id) digestionBody.sessionId = session.id;
        if (STATE.settings.ollamaApiKey) digestionBody.apiKey = STATE.settings.ollamaApiKey;
        if (STATE.settings.openRouterKey) digestionBody.openRouterKey = STATE.settings.openRouterKey;

        currentRoundText = '';
        currentRoundNativeCalls = [];

        try {
          const digestionRes = await fetch(chatUrl, {
            method: 'POST',
            headers,
            body: JSON.stringify(digestionBody),
            signal: STATE.abortController?.signal
          });

          if (!digestionRes.ok) {
            let errDetail = `HTTP ${digestionRes.status}`;
            try {
              const errJson = await digestionRes.json();
              if (errJson?.error) errDetail = typeof errJson.error === 'object' ? errJson.error.message : errJson.error;
            } catch (_) {}
            console.warn(`[Ollama Autonomous Digestion Round ${autonomousRound}] Error: ${errDetail}`);
            if (!fullText.trim()) {
              fullText = (allAccumulatedToolResponsesText || (webSources && webSources.length > 0))
                ? synthesizeAutonomousWebSummary(allAccumulatedToolResponsesText, webSources)
                : (cleanAssistant || `[Pencarian selesai: ${toolSummaryList.join(', ')}. Sistem menyelesaikan penelusuran].`);
            }
            break;
          }

          const digestionReader = digestionRes.body.getReader();
          let digestionBuffer = '';
          const digestionContentBox = document.createElement('div');
          digestionContentBox.className = 'autonomous-digested-output';
          bubbleText.innerHTML = preambleHtml + executedHudHtml;
          bubbleText.appendChild(digestionContentBox);

          const digestionRenderer = new StreamBufferRenderer(digestionContentBox, () => smartScrollChatToBottom(false));
          currentRoundNativeCalls = [];
          currentRoundText = '';

          while (true) {
            const { done, value } = await digestionReader.read();
            if (done) {
              digestionBuffer += decoder.decode();
              break;
            }
            digestionBuffer += decoder.decode(value, { stream: true });
            const dLines = digestionBuffer.split('\n');
            digestionBuffer = dLines.pop();

            for (const dLine of dLines) {
              if (!dLine.trim()) continue;
              try {
                const dParsed = JSON.parse(dLine);
                const chunk = dParsed.message?.content || dParsed.response || '';
                const dReasoning = dParsed.message?.reasoning || dParsed.reasoning || '';
                if (dReasoning) {
                  digestionRenderer.appendReasoning(dReasoning);
                }
                if (chunk) {
                  tokenCount++;
                  digestionRenderer.append(chunk);
                  currentRoundText += chunk;
                  if (digestionRenderer.isLoopTerminated) {
                    console.warn('[Ollama Digestion] Degeneration loop detected and gracefully halted.');
                    try { await digestionReader.cancel(); } catch (_) {}
                    break;
                  }
                }
                if (dParsed.message?.tool_calls && Array.isArray(dParsed.message.tool_calls)) {
                  mergeToolCallsInto(currentRoundNativeCalls, dParsed.message.tool_calls);
                }
              } catch (_) {}
            }
          }

          if (digestionBuffer && digestionBuffer.trim()) {
            try {
              const dParsed = JSON.parse(digestionBuffer.trim());
              const chunk = dParsed.message?.content || dParsed.response || '';
              const dReasoning = dParsed.message?.reasoning || dParsed.reasoning || '';
              if (dReasoning) {
                digestionRenderer.appendReasoning(dReasoning);
              }
              if (chunk) {
                tokenCount++;
                digestionRenderer.append(chunk);
                currentRoundText += chunk;
              }
              if (dParsed.message?.tool_calls && Array.isArray(dParsed.message.tool_calls)) {
                mergeToolCallsInto(currentRoundNativeCalls, dParsed.message.tool_calls);
              }
            } catch (_) {}
          }
          const finishedDigestion = digestionRenderer.finish({ render: false });
          if (finishedDigestion) currentRoundText = finishedDigestion;
          fullText = currentRoundText;
          if (digestionRenderer.isLoopTerminated) {
            break;
          }
          if (!fullText.trim() && (allAccumulatedToolResponsesText || (webSources && webSources.length > 0))) {
            fullText = synthesizeAutonomousWebSummary(allAccumulatedToolResponsesText, webSources);
          }
        } catch (digestionErr) {
          // H3: AbortError JANGAN ditelan oleh catch tool-round ini. Dulu abort saat
          // eksekusi tool/digestion jatuh ke jalur "sukses": bunyi selesai + notifikasi
          // desktop padahal pengguna menekan Stop. Teruskan ke catch luar agar
          // penangan AbortError yang menyelesaikan (toast "dihentikan" + parsial).
          if (digestionErr && (digestionErr.name === 'AbortError' || STATE.abortController?.signal?.aborted)) {
            throw digestionErr;
          }
          console.warn(`[Ollama Autonomous Digestion Round ${autonomousRound}] Fetch error:`, digestionErr);
          if (!fullText.trim()) {
            fullText = (allAccumulatedToolResponsesText || (webSources && webSources.length > 0))
              ? synthesizeAutonomousWebSummary(allAccumulatedToolResponsesText, webSources)
              : (cleanAssistant || '');
          }
          break;
        }
      }

      // ===== AI INTERACTIVE TASK TRACKER =====
      const detectedTasks = parseAiTasksBlock(fullText);
      if (detectedTasks && STATE.taskTracker.enabled) {
        setTaskTrackerTasks(detectedTasks);
      }
      if (fullText.indexOf('<<<ZOZ_TASKS') !== -1) {
        fullText = hideTaskBlocksForDisplay(fullText).trim();
      }

      // ===== AI FILE STUDIO & WORKSPACE AUTO-SAVE =====
      // Ekstrak file yang dibuat/diedit AI, lalu hapus bloknya dari gelembung agar tidak
      // tampil kode mentah berulang (kartu file digantikan oleh kartu di bawah).
      const extractedAiFiles = extractGeneratedFiles(fullText, wantsFile);
      const generatedFiles = extractedAiFiles.files;
      if (generatedFiles.length > 0) {
        fullText = stripGeneratedFileBlocks(fullText, extractedAiFiles.rawBlocks);
        await processAiGeneratedWorkspaceFiles(generatedFiles);
      } else if (fullText.indexOf('<<<ZOZ_FILE') !== -1 || fullText.indexOf('<<<END_ZOZ_FILE') !== -1 || fullText.indexOf('<<<ZOZ_EDIT') !== -1) {
        // M2: ada marker tapi TIDAK ada blok utuh (stream terputus sebelum
        // <<<END_ZOZ_FILE / END yatim). Dulu marker + isi blok tampil mentah di
        // gelembung final dan persist ke riwayat — padahal saat streaming barisnya
        // disembunyikan. Buang sisa blok (hideFileBlocksForDisplay memangkas dari
        // marker terbuka sampai akhir teks — tak ada isi setelah blok tak tertutup).
        fullText = stripGeneratedFileBlocks(hideFileBlocksForDisplay(fullText), []);
      }

      // Ekstrak permintaan hapus berkas oleh AI jika ada
      const filesToDelete = extractDeletedFiles(fullText);
      if (filesToDelete.length > 0) {
        fullText = stripDeletedFileBlocks(fullText);
        if (STATE.localWorkspace.enabled && STATE.localWorkspace.aiCanWrite) {
          for (const delName of filesToDelete) {
            await deleteWorkspaceDocumentSilent(delName, { author: 'ai', note: 'Dihapus oleh AI' });
          }
        }
      }

      // Pastikan tidak ada gelembung obrolan kosong saat file dimodifikasi/dibuat
      if (!fullText.trim() && generatedFiles.length > 0) {
        const names = generatedFiles.map(f => `**${escapeHtml(f.name)}**`).join(', ');
        fullText = `✅ **Pembaruan Berkas Berhasil!** AI telah memodifikasi dan menyimpan berkas ${names} ke direktori lokal Anda. Versi cadangan otomatis dicatat di Riwayat Versi.`;
      }

      // Bersihkan sisa tag tool_call dan residu raw JSON jika ada sebelum render markdown final
      const cleanFinalText = scrubRawToolCallArtifacts(fullText);
      if (cleanFinalText && cleanFinalText.trim()) {
        fullText = cleanFinalText;
      } else if (!canRunAutonomousSearch && (extractInlineToolCalls(fullText).length > 0 || currentRoundNativeCalls.length > 0)) {
        fullText = 'Model mencoba melakukan penelusuran web untuk menjawab pertanyaan ini, namun fitur **Pencarian Web** saat ini sedang nonaktif. Silakan aktifkan ikon bola dunia (🌐 Pencarian Web) pada bilah kontrol di bawah untuk mengizinkan penelusuran data langsung.';
      }

      if (!fullText.trim()) {
        if (webSources && webSources.length > 0) {
          fullText = synthesizeAutonomousWebSummary(allAccumulatedToolResponsesText, webSources);
        } else if (preambleHtml) {
          fullText = 'Model menyelesaikan penelusuran namun tidak menghasilkan respon teks tambahan.';
        }
      }

      if (!fullText.trim() && generatedFiles.length === 0 && !preambleHtml) {
        if (STATE.abortController?.signal?.aborted) {
          // H3: dibatalkan sebelum ada teks sama sekali → HAPUS baris & beri tahu
          // pengguna. Dulu kondisi ini di-skip saat aborted sehingga gelembung KOSONG
          // tersimpan sebagai jawaban "selesai" dan tetap terkirim sebagai konteks.
          assistantRow.remove();
          showToast('Generasi dihentikan oleh pengguna.');
          return;
        }
        throw new Error('Model Ollama menyelesaikan koneksi tanpa menghasilkan respon teks.');
      }

      fullText = safeAssistantText(fullText);
      const totalTime = ((performance.now() - startTime) / 1000).toFixed(2);
      const tps = totalTime > 0 ? (tokenCount / totalTime).toFixed(1) : '0';

      const finalRenderedContent = (preambleHtml ? preambleHtml : '') + (executedHudHtml ? executedHudHtml + renderMarkdown(fullText) : renderMarkdown(fullText)).trim();
      bubbleText.innerHTML = finalRenderedContent.trim();
      enhanceCodeBlocks(bubbleText);
      enhanceChatImages(bubbleText);
      if (webSources && webSources.length > 0) {
        webSources = deduplicateSources(webSources);
        renderMessageSources(assistantRow, webSources, true);
      }
      renderYouTubeCardsForMessage(assistantRow, fullText, foundYouTubeIds);
      renderMessageFiles(assistantRow, generatedFiles);
      metaBox.innerHTML = `
        <strong>${escapeHtml(modelName)}</strong>
        <span class="meta-model-badge">Ollama</span>
        <span>⏱️ ${totalTime}s</span>
        <span>⚡ ${tps} tps</span>
      `;

      assistantRow.dataset.fullContent = fullText;

      // Check if output is cut in half and provide one-click continuation button
      if (isOutputTruncated(fullText, doneReason === 'length' ? 'length' : null)) {
        attachContinuationButton(assistantRow.querySelector('.message-content-box') || assistantRow, session, assistantRow, modelName, 'ollama', fullText);
      }

      // Save to session if session is still alive
      if (STATE.sessions.some(s => s.id === session.id)) {
        session.messages.push({
          role: 'assistant',
          content: fullText,
          model: modelName,
          engine: 'ollama',
          sources: webSources,
          files: generatedFiles.length > 0 ? generatedFiles : undefined,
          stats: { duration: totalTime, tps: tps, tokens: tokenCount },
          timestamp: new Date().toISOString()
        });
        session.updatedAt = new Date().toISOString();
        savePersistedState();
        renderChatHistory(els.searchHistoryInput?.value || '');
      }
      AudioEngine.receive();
      notifyAiCompletion('🤖 ' + modelName, fullText);
      BioEndocrine.secreteDopamine(12, `Ollama inferensi sukses: ${modelName}`);
      return true;

    } catch (err) {
      if (err.name === 'AbortError') {
        // render:false → baris di bawah langsung mengganti innerHTML (atau baris
        // dihapus), jadi render dari finish hanya akan dibuang.
        const partialRaw = streamRenderer ? streamRenderer.finish({ render: false }) : '';
        const stoppedPartial = sanitizePartialResponseWithFiles(partialRaw);
        const partialText = stoppedPartial.text;
        if (partialText && partialText.trim() && STATE.sessions.some(s => s.id === session.id)) {
          const stoppedText = `${partialText.trim()}\n\n*[Respons dihentikan oleh pengguna]*`;
          bubbleText.innerHTML = renderMarkdown(stoppedText);
          enhanceCodeBlocks(bubbleText);
          enhanceChatImages(bubbleText);
          renderMessageFiles(assistantRow, stoppedPartial.files);
          if (webSources && webSources.length > 0) {
            renderMessageSources(assistantRow, webSources, true);
          }
          const totalTime = ((performance.now() - startTime) / 1000).toFixed(2);
          metaBox.innerHTML = `
            <strong>${escapeHtml(modelName)}</strong>
            <span class="meta-model-badge">Ollama</span>
            <span>⏱️ ${totalTime}s (Dihentikan)</span>
          `;
          session.messages.push({
            role: 'assistant',
            content: stoppedText,
            model: modelName,
            engine: 'ollama',
            sources: webSources,
            files: stoppedPartial.files.length > 0 ? stoppedPartial.files : undefined,
            stats: { duration: totalTime, tokens: tokenCount, stopped: true },
            timestamp: new Date().toISOString()
          });
          session.updatedAt = new Date().toISOString();
          savePersistedState();
          renderChatHistory(els.searchHistoryInput?.value || '');
        } else {
          assistantRow.remove();
        }
        showToast('Generasi dihentikan oleh pengguna.');
        return false;
      } else {
        BioEndocrine.secreteStress(22, `Ollama error: ${err?.message || 'Engine exception'}`);
        // Auto-Router fallback: bersihkan gelembung sementara dan kembalikan false agar caller langsung beralih ke OpenRouter
        if (runOptions && runOptions.autoFallback) {
          try { assistantRow.remove(); } catch (_) {}
          return false;
        }

        // Auto Cloud Fallback (jika model belum di-pull di server Ollama lokal, 404, 401, atau Ollama offline):
        const errLower = (err?.message || String(err || '')).toLowerCase();
        const isNotFoundOrOffline = errLower.includes('404') || 
                                    errLower.includes('not found') || 
                                    errLower.includes('failed to fetch') || 
                                    errLower.includes('networkerror') || 
                                    errLower.includes('mixed_content') ||
                                    errLower.includes('unauthorized') ||
                                    errLower.includes('401') ||
                                    err?.name === 'TypeError';

        const allowCloudFallback = runOptions ? (runOptions.autoCloudFallback !== false) : true;
        if (allowCloudFallback && isNotFoundOrOffline) {
          try { assistantRow.remove(); } catch (_) {}
          const fallbackModel = mapOllamaModelToOpenRouter(modelName);
          console.warn(`[Ollama Failover] Model ${modelName} tidak tersedia di server Ollama (${err?.message}). Mengalihkan otomatis ke Cloud OpenRouter (${fallbackModel})...`);
          showToast(`🔀 Model ${modelName} dialihkan otomatis ke Cloud (${fallbackModel})...`, 'info');
          selectModel(fallbackModel, 'openrouter', true);
          return await runOpenRouterStreaming(session, promptText, image, fallbackModel);
        }

        // render:false → bubbleText.innerHTML diganti tanpa syarat beberapa baris
        // di bawah (kartu error), jadi render dari finish hanya akan dibuang.
        const rescuePartial = sanitizePartialResponseWithFiles(streamRenderer ? streamRenderer.finish({ render: false }) : '');
        const partialText = scrubRawToolCallArtifacts(rescuePartial.text);
        const hasPartialText = Boolean(partialText && partialText.trim());

        if (hasPartialText && STATE.sessions.some(s => s.id === session.id)) {
          const rescuedText = `${partialText.trim()}\n\n*[Koneksi terputus saat streaming]*`;
          const totalTime = ((performance.now() - startTime) / 1000).toFixed(2);

          session.messages.push({
            role: 'assistant',
            content: rescuedText,
            model: modelName,
            engine: 'ollama',
            sources: webSources,
            files: rescuePartial.files.length > 0 ? rescuePartial.files : undefined,
            stats: { duration: totalTime, tokens: tokenCount, interrupted: true },
            timestamp: new Date().toISOString()
          });
          session.updatedAt = new Date().toISOString();
          savePersistedState();
          renderChatHistory(els.searchHistoryInput?.value || '');

          if (metaBox) {
            metaBox.innerHTML = `
              <strong>${escapeHtml(modelName)}</strong>
              <span class="meta-model-badge">Ollama</span>
              <span>⏱️ ${totalTime}s (Terputus)</span>
            `;
          }
        }

        const actualHasImage = Array.isArray(image) ? image.length > 0 : Boolean(image);
        const errorHtml = formatModelErrorMessage('ollama', modelName, err, actualHasImage, STATE.webSearchEnabled);

        const rescuedHtml = hasPartialText ? `
          <div class="partial-rescued-content" style="margin-bottom:12px; padding-bottom:12px; border-bottom:1px dashed rgba(255,255,255,0.15);">
            ${renderMarkdown(partialText.trim())}
          </div>
        ` : '';

        bubbleText.innerHTML = `
          ${rescuedHtml}
          ${errorHtml}
          <div style="margin-top:10px; display:flex; gap:8px; flex-wrap:wrap;">
            <button class="btn btn-sm btn-primary switch-openrouter-btn" style="font-size:0.75rem;">
              <i class="fa-solid fa-bolt"></i> Beralih & Jalankan via OpenRouter
            </button>
            <button class="btn btn-sm btn-outline retry-send-btn" style="border-color:var(--neon-cyan); color:var(--neon-cyan); font-size:0.75rem;">
              <i class="fa-solid fa-rotate-right"></i> Coba Kirim Ulang
            </button>
            <button class="btn btn-sm btn-outline open-settings-btn" style="border-color:var(--neon-amber); color:var(--neon-amber); font-size:0.75rem;">
              <i class="fa-solid fa-gear"></i> Buka Pengaturan
            </button>
          </div>
        `;

        if (hasPartialText) {
          enhanceCodeBlocks(bubbleText);
          renderMessageFiles(assistantRow, rescuePartial.files);
          if (webSources && webSources.length > 0) {
            renderMessageSources(assistantRow, webSources, true);
          }
        }

        bubbleText.querySelector('.switch-openrouter-btn')?.addEventListener('click', () => {
          if (STATE.isGenerating || STATE.isSending) return;
          assistantRow.remove();
          setEngineMode('openrouter');
          const targetFallback = mapOllamaModelToOpenRouter(modelName) || STATE.settings.openRouterModel || 'openrouter/free';
          selectModel(targetFallback, 'openrouter');
          runOpenRouterStreaming(session, promptText, image, targetFallback);
        });

        bubbleText.querySelector('.retry-send-btn')?.addEventListener('click', () => {
          if (STATE.isGenerating || STATE.isSending) return;
          assistantRow.remove();
          runOllamaStreaming(session, promptText, image, modelName);
        });

        bubbleText.querySelector('.open-settings-btn')?.addEventListener('click', () => {
          syncSettingsModalFields();
          openModal('settingsModal');
        });

        AudioEngine.error();
        return false;
      }
    } finally {
      setGeneratingState(false);
    }
  }

  // --- OPENROUTER & CLOUD AI STREAMING EXECUTION ---
  async function runOpenRouterStreaming(session, promptText, image, modelName, runOptions = {}) {
    const displayModel = runOptions.displayModel || modelName;
    const engineLabel = runOptions.engineLabel || (STATE.mode === 'ollama' ? 'Ollama Cloud' : 'OpenRouter');
    const engineMode = runOptions.engineMode || (STATE.mode === 'ollama' ? 'ollama' : 'openrouter');
    const effectiveTargetModel = (modelName && modelName.includes('/'))
      ? modelName
      : (mapOllamaModelToOpenRouter(modelName) || 'openrouter/free');

    const hasClientKey = Boolean(STATE.settings.openRouterKey);
    const hasBackendKey = Boolean(DeviceStorage.isDeviceBackendAvailable || !IS_GITHUB_PAGES);
    if (!hasClientKey && !hasBackendKey) {
      if (runOptions && runOptions.autoFallback) {
        return false;
      }
      const assistantRow = appendMessageElement('assistant', '', null, displayModel || 'OpenRouter Gateway');
      const bubbleText = assistantRow.querySelector('.msg-text-content');
      
      bubbleText.innerHTML = `
        <div style="background:rgba(255,82,0,0.08); border:1px solid rgba(255,82,0,0.3); border-radius:10px; padding:14px 16px; margin:4px 0;">
          <div style="display:flex; align-items:center; gap:8px; color:var(--neon-amber); font-weight:700; margin-bottom:8px; font-size:0.95rem;">
            <i class="fa-solid fa-key"></i> OpenRouter API Key Diperlukan
          </div>
          <p style="margin:0 0 12px 0; font-size:0.85rem; color:var(--text-muted); line-height:1.5;">
            Untuk menjalankan model cloud (<strong>${escapeHtml(displayModel || 'Model Cloud')}</strong>) di hosting browser statis, masukkan API Key OpenRouter gratis Anda di menu Pengaturan. Kunci tersimpan aman di browser Anda.
          </p>
          <div style="display:flex; flex-wrap:wrap; gap:8px;">
            <button class="btn btn-sm btn-primary open-settings-key-btn" style="font-size:0.78rem;">
              <i class="fa-solid fa-gear"></i> Buka Pengaturan & Masukkan API Key
            </button>
            <button class="btn btn-sm btn-outline retry-openrouter-btn" style="border-color:var(--neon-amber); color:var(--neon-amber); font-size:0.78rem;">
              <i class="fa-solid fa-rotate-right"></i> Coba Kirim Ulang
            </button>
            <button class="btn btn-sm btn-outline switch-ollama-btn" style="border-color:var(--neon-cyan); color:var(--neon-cyan); font-size:0.78rem;">
              <i class="fa-solid fa-cloud"></i> Beralih ke Ollama Cloud
            </button>
            <button class="btn btn-sm btn-outline cancel-turn-btn" style="border-color:var(--text-dim); color:var(--text-muted); font-size:0.78rem;">
              <i class="fa-solid fa-trash-can"></i> Hapus Pesan Ini
            </button>
          </div>
        </div>
      `;

      bubbleText.querySelector('.open-settings-key-btn')?.addEventListener('click', () => {
        syncSettingsModalFields();
        openModal('settingsModal');
      });

      bubbleText.querySelector('.retry-openrouter-btn')?.addEventListener('click', () => {
        if (STATE.isGenerating || STATE.isSending) return;
        assistantRow.remove();
        runOpenRouterStreaming(session, promptText, image, modelName, runOptions);
      });

      bubbleText.querySelector('.switch-ollama-btn')?.addEventListener('click', () => {
        if (STATE.isGenerating || STATE.isSending) return;
        assistantRow.remove();
        setEngineMode('ollama');
        runOllamaStreaming(session, promptText, image, STATE.settings.ollamaModel);
      });

      bubbleText.querySelector('.cancel-turn-btn')?.addEventListener('click', () => {
        assistantRow.remove();
        const lastMsgIdx = session.messages.length - 1;
        if (lastMsgIdx >= 0 && session.messages[lastMsgIdx].role === 'user') {
          session.messages.splice(lastMsgIdx, 1);
          savePersistedState();
          renderCurrentSession();
        }
      });

      AudioEngine.error();
      smartScrollChatToBottom(true);
      return;
    }

    setGeneratingState(true);
    STATE.abortController = new AbortController();

    const startTime = performance.now();
    let firstTokenTime = null;
    let tokenCount = 0;

    const assistantRow = appendMessageElement('assistant', '', null, displayModel);
    const bubbleText = assistantRow.querySelector('.msg-text-content');
    const metaBox = assistantRow.querySelector('.message-meta');
    bubbleText.innerHTML = '<span class="typing-cursor"></span>';
    smartScrollChatToBottom(true);

    let fullText = '';
    let webSources = null;
    let streamRenderer = null;
    let actualModelUsed = null;
    let executedHudHtml = '';
    const foundYouTubeIds = []; // ID video hasil tool search_youtube (dipakai render kartu)
    const wantsFile = isFileGenerationRequest(promptText); // niat "buatkan file/website" untuk AI File Studio

    try {
      let personaPrompt = STATE.settings.systemPrompt ? STATE.settings.systemPrompt.trim() : '';
      const canRunAutonomous = Boolean(STATE.webSearchEnabled || STATE.searchMode === 'autonomous');
      let systemContent = '';
      if (personaPrompt) {
        systemContent = `### MANDAT PERSONA UTAMA (PRIORITAS TERTINGGI - IDENTITAS KARAKTER ANDA)\n[PENTING: Anda WAJIB mengadopsi persona dan gaya komunikasi berikut dalam SETIAP respon]:\n${personaPrompt}\n----------------------------------------`;
      }
      if (canRunAutonomous) {
        systemContent = systemContent ? `${systemContent}\n\n${getAutonomousSystemDirective()}` : getAutonomousSystemDirective();
      }
      // Tool video YouTube hanya diumumkan bila toggle "Cari Video YouTube" aktif
      // (agar model tidak memanggil tool yang tidak dikirim).
      if (STATE.isYouTubeSearchMode) {
        systemContent = systemContent
          ? `${systemContent}\n\n${getYouTubeToolDirective()}`
          : getYouTubeToolDirective();
      }

      // AI File Studio: selalu diumumkan agar model tahu format blok ZOZ_FILE
      // ketika pengguna meminta pembuatan file / website.
      systemContent = systemContent
        ? `${systemContent}\n\n${getFileStudioDirective()}`
        : getFileStudioDirective();

      // UNIVERSAL YOUTUBE METADATA GROUNDING FOR ALL MODELS
      try {
        const ytRes = await getYouTubeGroundingContext(promptText, bubbleText);
        if (ytRes && ytRes.groundingContext) {
          systemContent = `${systemContent}\n\n${ytRes.groundingContext}`;
          bubbleText.innerHTML = '<span class="typing-cursor"></span>';
        }
      } catch (ytErr) {
        console.warn('YouTube client grounding error:', ytErr);
      }

      const effectiveInitialModel = (modelName && modelName.includes('/'))
        ? modelName
        : (mapOllamaModelToOpenRouter(modelName) || 'openrouter/free');

      // Deteksi apakah model gratis atau berbayar
      const isFreeModel = Boolean(
        effectiveInitialModel.includes(':free') ||
        effectiveInitialModel.endsWith('/free') ||
        effectiveInitialModel === 'openrouter/free' ||
        (STATE.openRouterModels || []).some(m => m.id === effectiveInitialModel && (m.cat === 'free' || m.tag === 'Free'))
      );

      // WEB SEARCH GROUNDING:
      // Aktif pada mode default search, atau sebagai fallback otomatis ketika mode autonomous search
      // berjalan pada model gratis / model tanpa dukungan tools (agar tetap mendapat data internet terkini).
      const needsGroundingFallback = STATE.searchMode === 'autonomous' && (isFreeModel || !STATE.settings.openRouterKey || !doesModelSupportTools(effectiveInitialModel));
      if (STATE.searchMode === 'default' || (STATE.webSearchEnabled && needsGroundingFallback)) {
        try {
          const searchRes = await getWebSearchContext(promptText, session, bubbleText, needsGroundingFallback);
          if (searchRes && searchRes.systemPromptContext) {
            systemContent = systemContent
              ? `${systemContent}\n\n${searchRes.systemPromptContext}`
              : searchRes.systemPromptContext;
            if (searchRes.sources && Array.isArray(searchRes.sources)) {
              if (!webSources) webSources = [];
              webSources.push(...searchRes.sources);
            }
            bubbleText.innerHTML = '<span class="typing-cursor"></span>';
          }
        } catch (searchErr) {
          console.warn('Web search grounding error:', searchErr);
        }
      }

      if (personaPrompt) {
        systemContent = `${systemContent}\n\n### MANDAT MUTLAK PERSONA (PENEGASAN AKHIR):\n[PENTING: Terlepas dari semua instruksi pencarian web, tool, atau format di atas, Anda WAJIB TETAP MENGADOPSI IDENTITAS DAN KARAKTER PERSONA BERIKUT DALAM SETIAP RESPON]:\n${personaPrompt}\n----------------------------------------`;
      }

      const rawImgs = Array.isArray(image) ? image : (image ? [image] : []);
      const resolvedImgs = await Promise.all(rawImgs.map(resolveImageToDataUrlSafe));
      const messagesPayload = buildSanitizedMessagesPayload(session, resolvedImgs, 'openrouter', systemContent, effectiveInitialModel);

      // Siapkan pool kandidat model:
      // - Selalu sertakan fallback gratis terverifikasi agar saat model pilihan kehabisan kredit (HTTP 402)
      //   atau mengalami gangguan upstream (404/429/502/503), sistem dapat melakukan Smart Failover secara otomatis.
      const candidateModels = [
        effectiveInitialModel,
        ...LIVE_FREE_OPENROUTER_FALLBACKS
      ].filter(Boolean).filter((m, idx, arr) => arr.indexOf(m) === idx && !DEACTIVATED_OR_BROKEN_OPENROUTER_MODELS.has(m));

      let response = null;
      let lastErrDetail = '';
      let activeMessagesPayload = null;
      let activeEndpoint = '';
      let activeHeaders = {};
      let activeRouteType = '';
      const selectedAutonomousTools = getSelectableAutonomousTools(canRunAutonomous);

      for (let i = 0; i < candidateModels.length; i++) {
        const currentModel = candidateModels[i];
        const currentIsFree = Boolean(
          currentModel.includes(':free') ||
          currentModel.endsWith('/free') ||
          currentModel === 'openrouter/free' ||
          (STATE.openRouterModels || []).some(m => m.id === currentModel && (m.cat === 'free' || m.tag === 'Free'))
        );
        const currentIsImageCapable = isModelCapableOfImageGeneration(currentModel);
        const currentMessagesPayload = buildSanitizedMessagesPayload(session, resolvedImgs, 'openrouter', systemContent, currentModel);

        const isLiquid = Boolean(currentModel && (currentModel.includes('liquid') || currentModel.includes('lfm-')));
        const isReasoning = Boolean(currentModel && (/\/o[1-9]|\b(r1|reasoning|deepseek-r)\b/i.test(currentModel) || currentModel.toLowerCase().includes('reasoning') || currentModel.toLowerCase().includes('-r1')));

        const basePayload = {
          model: currentModel,
          messages: currentMessagesPayload,
          stream: true,
          provider: {
            allow_fallbacks: true
          }
        };

        if (!isReasoning) {
          basePayload.temperature = parseFloat(STATE.settings.temperature) || 0.7;
          basePayload.repetition_penalty = 1.05;
        }
        if (!isLiquid && !isReasoning) {
          basePayload.top_p = parseFloat(STATE.settings.topP) || 0.9;
        }

        if (currentIsImageCapable && (STATE.isImageGenMode || isImageGenerationTrigger(promptText))) {
          basePayload.modalities = ['text', 'image'];
        }

        // Pasang tools HANYA jika bukan model gratis, API key ada, dan model mendukung tools
        const canUseTools = doesModelSupportTools(currentModel);
        if (!currentIsFree && canUseTools && STATE.settings.openRouterKey) {
          const validFunctionTools = (selectedAutonomousTools || []).filter(t => t && t.type === 'function' && t.function && t.function.name);
          if (validFunctionTools.length > 0) {
            basePayload.tools = validFunctionTools;
            basePayload.tool_choice = 'auto';
          }
        }

        // DUAL-PATH RESILIENCE: Coba rute primer, jika terhambat CORS/network/404, otomatis coba rute sekunder
        const tryDirectFirst = IS_GITHUB_PAGES;
        const routesToTry = tryDirectFirst ? ['direct', 'proxy'] : ['proxy', 'direct'];

        let res = null;
        let routeErrDetail = '';

        for (const routeType of routesToTry) {
          if (STATE.abortController?.signal?.aborted) break;

          let targetUrl = '';
          let targetHeaders = {};
          let targetBody = {};

          if (routeType === 'direct') {
            // Direct call ke OpenRouter API (CORS-compliant: JANGAN kirim X-User-ID/X-Session-ID agar lolos preflight)
            targetUrl = 'https://openrouter.ai/api/v1/chat/completions';
            targetHeaders = {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${STATE.settings.openRouterKey || ''}`,
              'HTTP-Referer': location.origin || 'https://zozi0999.github.io/zoz_router',
              'X-Title': 'ZOZ Router'
            };
            targetBody = { ...basePayload };
          } else {
            // Proxy backend (/api/openrouter/chat)
            targetUrl = '/api/openrouter/chat';
            targetHeaders = {
              'Content-Type': 'application/json'
            };
            if (STATE.settings.openRouterKey) {
              targetHeaders['Authorization'] = `Bearer ${STATE.settings.openRouterKey}`;
            }
            if (session?.id) {
              targetHeaders['X-Session-ID'] = session.id;
            }
            if (STATE.userId) {
              targetHeaders['X-User-ID'] = STATE.userId;
            }
            targetBody = {
              ...basePayload,
              sessionId: session?.id || null,
              userId: STATE.userId || null,
              apiKey: STATE.settings.openRouterKey || undefined
            };
          }

          try {
            let attemptRes = await fetch(targetUrl, {
              method: 'POST',
              headers: targetHeaders,
              body: JSON.stringify(targetBody),
              signal: STATE.abortController?.signal
            });

            // Resiliensi HTTP 400 & 404: Tangani penolakan tools, top_p, modalities, temperature, atau parameter upstream
            if (attemptRes.status === 400 || (attemptRes.status === 404 && targetBody.modalities)) {
              let shouldRetry = false;
              if (targetBody.modalities) {
                console.warn(`[OpenRouter] Model ${currentModel} menolak parameter modalities. Menghapus modalities dan mengulang...`);
                delete targetBody.modalities;
                delete basePayload.modalities;
                shouldRetry = true;
              }
              if (targetBody.tools) {
                console.warn(`[OpenRouter] Model ${currentModel} mengembalikan HTTP 400 dengan tools. Mengulang langsung tanpa tools...`);
                delete targetBody.tools;
                delete targetBody.tool_choice;
                delete basePayload.tools;
                delete basePayload.tool_choice;
                shouldRetry = true;
              }
              if (targetBody.top_p) {
                console.warn(`[OpenRouter] Model ${currentModel} mengembalikan HTTP 400. Menghapus top_p dan mengulang...`);
                delete targetBody.top_p;
                delete basePayload.top_p;
                shouldRetry = true;
              }
              if (targetBody.repetition_penalty) {
                console.warn(`[OpenRouter] Model ${currentModel} mengembalikan HTTP 400. Menghapus repetition_penalty dan mengulang...`);
                delete targetBody.repetition_penalty;
                delete basePayload.repetition_penalty;
                shouldRetry = true;
              }
              if (targetBody.temperature && isReasoning) {
                delete targetBody.temperature;
                delete basePayload.temperature;
                shouldRetry = true;
              }
              if (shouldRetry) {
                const retryRes = await fetch(targetUrl, {
                  method: 'POST',
                  headers: targetHeaders,
                  body: JSON.stringify(targetBody),
                  signal: STATE.abortController?.signal
                });
                if (retryRes.ok) {
                  attemptRes = retryRes;
                }
              }
            }

            // Jika proxy mengembalikan 404 (misal static host tanpa server), fallback ke direct
            if (routeType === 'proxy' && attemptRes.status === 404) {
              console.warn(`[OpenRouter Proxy 404] Backend proxy tidak tersedia di host ini. Beralih ke direct OpenRouter API...`);
              continue;
            }

            if (attemptRes.ok) {
              res = attemptRes;
              activeEndpoint = targetUrl;
              activeHeaders = targetHeaders;
              activeRouteType = routeType;
              break;
            }

            let attemptErr = `HTTP ${attemptRes.status}`;
            try {
              const errJson = await attemptRes.json();
              if (errJson && errJson.error) {
                const baseErr = typeof errJson.error === 'object' ? (errJson.error.message || JSON.stringify(errJson.error)) : errJson.error;
                const rawUpstream = errJson.details?.error?.metadata?.raw || errJson.error?.metadata?.raw;
                attemptErr = rawUpstream ? `${baseErr} (${rawUpstream})` : baseErr;
              }
            } catch (je) {
              try {
                const raw = await attemptRes.text();
                if (raw) attemptErr = raw.substring(0, 200);
              } catch (_) {}
            }

            routeErrDetail = attemptErr;

            // Jika error adalah 401/403/402, jangan loop rute lain untuk model ini
            if (attemptRes.status === 401 || attemptRes.status === 403 || attemptRes.status === 402) {
              break;
            }
          } catch (netErr) {
            if (STATE.abortController?.signal?.aborted) throw netErr;
            console.warn(`[OpenRouter Dual-Path] Jalur ${routeType} mengalami kendala:`, netErr.message);
            routeErrDetail = netErr.message || String(netErr);
            // Lanjut mencoba rute alternatif
            continue;
          }
        }

        if (res && res.ok) {
          response = res;
          activeMessagesPayload = currentMessagesPayload;
          if (i > 0) {
            actualModelUsed = currentModel;
          }
          break;
        }

        lastErrDetail = routeErrDetail || 'Gagal terhubung ke penyedia model OpenRouter.';

        // Hentikan failover jika autentikasi ditolak mutlak (401/403)
        if (lastErrDetail.includes('401') || lastErrDetail.includes('403') || lastErrDetail.includes('API Key tidak valid')) {
          throw new Error(`OpenRouter Authentication Error: API Key tidak valid atau belum dipasang.`);
        }

        // Cek apakah bisa failover ke model berikutnya:
        // Berlaku untuk semua kegagalan model (402, 404, 429, 400, 500, 502, 503, 504, network failure) selama bukan penolakan auth API Key
        const isAuthRejection = lastErrDetail.includes('401') || lastErrDetail.includes('403') || lastErrDetail.includes('API Key tidak valid');
        const canFailover = (i < candidateModels.length - 1) && !isAuthRejection;

        if (canFailover) {
          const nextCandidate = candidateModels[i + 1];
          const reasonNotice = (lastErrDetail.includes('402') || lastErrDetail.includes('credit'))
            ? 'memerlukan saldo berbayar'
            : ((lastErrDetail.includes('429') || lastErrDetail.includes('rate limit'))
                ? 'mencapai batas kuota sementara'
                : 'sedang sibuk/gangguan');
          console.warn(`[OpenRouter Smart Failover] Model ${currentModel} ${reasonNotice} (${lastErrDetail}). Mengalihkan ke ${nextCandidate}...`);
          bubbleText.innerHTML = `<span class="typing-cursor"></span> <span style="font-size:0.85em; opacity:0.8; font-style:italic;">Model <b>${escapeHtml(currentModel)}</b> ${reasonNotice}. Mengalihkan otomatis ke <b>${escapeHtml(nextCandidate)}</b>...</span>`;
          await new Promise(r => setTimeout(r, 600));
          continue;
        } else {
          throw new Error(lastErrDetail);
        }
      }

      if (!response || !response.ok) {
        throw new Error(lastErrDetail || 'Gagal memanggil model OpenRouter.');
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      let finishReason = null;
      const collectedImages = [];
      const accumulatedToolCalls = [];
      streamRenderer = new StreamBufferRenderer(bubbleText, () => smartScrollChatToBottom(false), executedHudHtml);

      while (true) {
        const { done, value } = await reader.read();
        if (done) {
          buffer += decoder.decode();
          break;
        }

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop();

        for (const line of lines) {
          const trimmed = line.trim();
          if (!trimmed || !trimmed.startsWith('data:')) continue;
          const jsonStr = trimmed.replace(/^data:\s*/, '');
          if (jsonStr === '[DONE]') break;

          let parsed;
          try {
            parsed = JSON.parse(jsonStr);
          } catch (pe) {
            continue;
          }
          if (parsed.error) {
            const errStr = typeof parsed.error === 'object' ? (parsed.error.message || JSON.stringify(parsed.error)) : parsed.error;
            const rawUpstream = parsed.error?.metadata?.raw;
            throw new Error(rawUpstream ? `${errStr} (${rawUpstream})` : errStr);
          }
          if (parsed.choices?.[0]?.finish_reason) {
            finishReason = parsed.choices[0].finish_reason;
          }

          // Tangkap gambar yang dihasilkan model (seperti Gemini Flash Image / Nano Banana di OpenRouter)
          const rawImgs = parsed.choices?.[0]?.delta?.images 
            || parsed.choices?.[0]?.message?.images 
            || parsed.choices?.[0]?.images
            || (parsed.data && Array.isArray(parsed.data) ? parsed.data : null);
          if (Array.isArray(rawImgs) && rawImgs.length > 0) {
            rawImgs.forEach(img => {
              const url = img?.image_url?.url || img?.url || (img?.b64_json ? `data:${img.media_type || 'image/png'};base64,${img.b64_json}` : (typeof img === 'string' ? img : null));
              if (url && !collectedImages.includes(url)) {
                collectedImages.push(url);
              }
            });
          }

          // Tangkap tool_calls delta inkremental
          const deltaTc = parsed.choices?.[0]?.delta?.tool_calls;
          if (Array.isArray(deltaTc)) {
            deltaTc.forEach(tc => {
              const idx = tc.index ?? 0;
              if (!accumulatedToolCalls[idx]) {
                accumulatedToolCalls[idx] = {
                  id: tc.id || `call_${Date.now()}_${idx}`,
                  type: tc.type || 'function',
                  function: {
                    name: tc.function?.name || '',
                    arguments: tc.function?.arguments || ''
                  }
                };
              } else {
                if (tc.id) accumulatedToolCalls[idx].id = tc.id;
                if (tc.function?.name) {
                  if (!accumulatedToolCalls[idx].function.name) {
                    accumulatedToolCalls[idx].function.name = tc.function.name;
                  } else if (accumulatedToolCalls[idx].function.name !== tc.function.name && !accumulatedToolCalls[idx].function.name.endsWith(tc.function.name)) {
                    accumulatedToolCalls[idx].function.name += tc.function.name;
                  }
                }
                if (tc.function?.arguments) accumulatedToolCalls[idx].function.arguments += tc.function.arguments;
              }
            });
          }

          const reasoningDelta = parsed.choices?.[0]?.delta?.reasoning 
            || parsed.choices?.[0]?.delta?.reasoning_content 
            || parsed.choices?.[0]?.delta?.thought 
            || '';
          if (reasoningDelta) {
            if (!firstTokenTime) firstTokenTime = performance.now();
            tokenCount++;
            streamRenderer.appendReasoning(reasoningDelta);
          }

          const delta = parsed.choices?.[0]?.delta?.content;
          if (delta) {
            if (!firstTokenTime) firstTokenTime = performance.now();
            tokenCount++;
            streamRenderer.append(delta);
            if (streamRenderer.isLoopTerminated) {
              console.warn('[OpenRouter] Model token degeneration loop detected and gracefully halted.');
              try { await reader.cancel(); } catch (_) {}
              break;
            }
          }
        }
      }

      if (buffer && buffer.trim()) {
        const trimmed = buffer.trim();
        if (trimmed && trimmed.startsWith('data:')) {
          const jsonStr = trimmed.replace(/^data:\s*/, '');
          if (jsonStr !== '[DONE]') {
            try {
              const parsed = JSON.parse(jsonStr);
              if (parsed.error) {
                const errStr = typeof parsed.error === 'object' ? (parsed.error.message || JSON.stringify(parsed.error)) : parsed.error;
                const rawUpstream = parsed.error?.metadata?.raw;
                throw new Error(rawUpstream ? `${errStr} (${rawUpstream})` : errStr);
              }
              if (parsed.choices?.[0]?.finish_reason) {
                finishReason = parsed.choices[0].finish_reason;
              }
              const reasoningDelta = parsed.choices?.[0]?.delta?.reasoning 
                || parsed.choices?.[0]?.delta?.reasoning_content 
                || parsed.choices?.[0]?.delta?.thought 
                || '';
              if (reasoningDelta) {
                if (!firstTokenTime) firstTokenTime = performance.now();
                tokenCount++;
                streamRenderer.appendReasoning(reasoningDelta);
              }
              const delta = parsed.choices?.[0]?.delta?.content;
              if (delta) {
                if (!firstTokenTime) firstTokenTime = performance.now();
                tokenCount++;
                streamRenderer.append(delta);
                if (tokenCount % 25 === 0) {
                  BioEndocrine.secreteDopamine(0.3, 'Streaming token lancar');
                }
              }
              const deltaTc = parsed.choices?.[0]?.delta?.tool_calls;
              if (Array.isArray(deltaTc)) {
                deltaTc.forEach(tc => {
                  const idx = tc.index ?? 0;
                  if (!accumulatedToolCalls[idx]) {
                    accumulatedToolCalls[idx] = {
                      id: tc.id || `call_${Date.now()}_${idx}`,
                      type: tc.type || 'function',
                      function: {
                        name: tc.function?.name || '',
                        arguments: tc.function?.arguments || ''
                      }
                    };
                  } else {
                    if (tc.id) accumulatedToolCalls[idx].id = tc.id;
                    if (tc.function?.name) {
                      if (!accumulatedToolCalls[idx].function.name) {
                        accumulatedToolCalls[idx].function.name = tc.function.name;
                      } else if (accumulatedToolCalls[idx].function.name !== tc.function.name && !accumulatedToolCalls[idx].function.name.endsWith(tc.function.name)) {
                        accumulatedToolCalls[idx].function.name += tc.function.name;
                      }
                    }
                    if (tc.function?.arguments) accumulatedToolCalls[idx].function.arguments += tc.function.arguments;
                  }
                });
              }
            } catch (_) {}
          }
        }
      }

      // render:false → render final tunggal ada di bawah (finalRenderedContent),
      // sehingga renderMarkdown + enhanceCodeBlocks/hljs tidak dijalankan dua kali.
      fullText = safeAssistantText(streamRenderer.finish({ render: false }));

      // ==================== UNIVERSAL AUTONOMOUS LIVE WEB SEARCH DIGESTION ENGINE ====================
      const canRunAutonomousSearch = Boolean(STATE.webSearchEnabled || STATE.searchMode === 'autonomous');
      const maxAutonomousRounds = 3;
      let autonomousRound = 0;
      let consecutiveFailedRounds = 0;
      let preambleHtml = '';
      const conversationChain = [...(activeMessagesPayload || messagesPayload)];
      let currentRoundText = fullText;
      let currentRoundNativeCalls = accumulatedToolCalls;
      const executedToolSignatures = new Set();
      let allAccumulatedToolResponsesText = '';

      // Loop tetap dijalankan walau Mode Pencarian Web mati: filter izin di bawah
      // yang memblokir tool web, sementara search_youtube selalu diperbolehkan.
      while (autonomousRound < maxAutonomousRounds && !streamRenderer.isLoopTerminated) {
        if (STATE.abortController?.signal?.aborted) {
          const abortErr = new Error('The operation was aborted');
          abortErr.name = 'AbortError';
          throw abortErr;
        }

        const validNativeCalls = currentRoundNativeCalls.filter(tc => tc && tc.function && isKnownAutonomousTool(tc.function.name) && isAutonomousToolAllowed(tc.function.name, canRunAutonomousSearch));
        const inlineCalls = extractInlineToolCalls(currentRoundText).filter(tc => tc && tc.function && isKnownAutonomousTool(tc.function.name) && isAutonomousToolAllowed(tc.function.name, canRunAutonomousSearch));
        let rawAutonomousCalls = validNativeCalls.length > 0 ? validNativeCalls : inlineCalls;

        if (rawAutonomousCalls.length === 0) {
          break; // Model selesai merumuskan respon tanpa pemanggilan tool tambahan
        }

        // Filter out duplicate or loop tool calls
        const roundSignatures = new Set();
        const detectedAutonomousCalls = rawAutonomousCalls.filter(call => {
          if (!call || !call.function || !isKnownAutonomousTool(call.function.name)) return false;
          const sig = getAutonomousToolSignature(call);
          if (executedToolSignatures.has(sig) || roundSignatures.has(sig)) return false; // Cegah pemanggilan tool berulang (loop / duplicate)
          roundSignatures.add(sig);
          return true;
        });

        if (detectedAutonomousCalls.length === 0) {
          break; // Model selesai merumuskan respon final tanpa pemanggilan tool tambahan
        }

        autonomousRound++;
        let roundToolResponsesText = '';
        const toolSummaryList = [];

        // Amankan teks pembuka yang telah digenerasi model sebelum pemanggilan tool agar tidak terhapus
        const cleanAssistant = scrubRawToolCallArtifacts(currentRoundText).trim();
        if (!preambleHtml && cleanAssistant && cleanAssistant.length > 20) {
          preambleHtml = `<div class="autonomous-preamble-text" style="margin-bottom:8px;">${renderMarkdown(cleanAssistant)}</div>`;
        }

        const toolTaskItems = detectedAutonomousCalls.map(call => {
          const toolName = call.function.name;
          let previewArg = '';
          try {
            const raw = (typeof call.function.arguments === 'string') ? JSON.parse(call.function.arguments) : call.function.arguments;
            let parsedArgs = {};
            if (raw && typeof raw === 'object') {
              parsedArgs = raw;
            } else if (raw !== null && raw !== undefined) {
              parsedArgs = { query: String(raw), url: String(raw) };
            }
            if (parsedArgs.code) {
              previewArg = String(parsedArgs.code).replace(/\s+/g, ' ').slice(0, 40);
            } else if (parsedArgs.topic || parsedArgs.topik) {
              previewArg = String(parsedArgs.topic || parsedArgs.topik).slice(0, 40);
            } else if (parsedArgs.content || parsedArgs.isi || parsedArgs.konten || parsedArgs.catatan) {
              previewArg = String(parsedArgs.content || parsedArgs.isi || parsedArgs.konten || parsedArgs.catatan).slice(0, 40);
            } else {
              previewArg = parsedArgs.query || parsedArgs.cari || parsedArgs.kata_kunci || parsedArgs.judul || parsedArgs.url || parsedArgs.tautan || parsedArgs.link || parsedArgs.q || parsedArgs.keyword || parsedArgs.target || (Object.keys(parsedArgs).length === 0 ? (promptText || '') : JSON.stringify(parsedArgs));
            }
          } catch (_) {
            previewArg = String(call.function.arguments || '');
          }

          executedToolSignatures.add(getAutonomousToolSignature(call));
          const summary = `${toolName}("${previewArg.substring(0, 40)}")`;
          return { call, toolName, previewArg, summary };
        });

        toolTaskItems.forEach(item => toolSummaryList.push(item.summary));

        // Tampilkan visual status loading untuk seluruh tool secara simultan
        bubbleText.innerHTML = preambleHtml + executedHudHtml + toolTaskItems.map(item => createAutonomousToolHudHtml(item.toolName, item.previewArg, 'loading')).join('');
        smartScrollChatToBottom(true);

        // Eksekusi seluruh tool secara paralel (Promise.all) untuk memangkas latensi jaringan
        const toolExecResults = await Promise.all(
          toolTaskItems.map(async (item) => {
            const toolExecRes = await executeAutonomousWebTool(item.toolName, item.call.function.arguments, promptText, session);
            return { ...item, toolExecRes };
          })
        );

        for (const resItem of toolExecResults) {
          const { toolName, previewArg, toolExecRes } = resItem;
          if (toolExecRes.sources && Array.isArray(toolExecRes.sources)) {
            if (!webSources) webSources = [];
            webSources.push(...toolExecRes.sources);
          }
          if (Array.isArray(toolExecRes.videoIds)) {
            toolExecRes.videoIds.forEach((vid) => {
              if (vid && !foundYouTubeIds.includes(vid)) foundYouTubeIds.push(vid);
            });
          }
          roundToolResponsesText += `\n[HASIL PENGUMPULAN DATA OTONOM (${toolName})]:\n${toolExecRes.text}\n`;
          executedHudHtml += createAutonomousToolHudHtml(toolName, previewArg, 'done');
        }
        allAccumulatedToolResponsesText += roundToolResponsesText;

        if (STATE.abortController?.signal?.aborted) {
          const abortErr = new Error('The operation was aborted');
          abortErr.name = 'AbortError';
          throw abortErr;
        }

        // Tampilkan HUD bahwa data berita live sedang disintesis oleh AI
        bubbleText.innerHTML = preambleHtml + executedHudHtml + `<div class="autonomous-digesting-box" style="margin-top:8px;"><span class="typing-cursor"></span> <span style="font-size:0.85em; opacity:0.85; font-style:italic; color:var(--neon-teal);"><i class="fa-solid fa-bolt"></i> Menyintesis hasil dan data otonom terbaru...</span></div>`;
        smartScrollChatToBottom(true);

        if (cleanAssistant) {
          conversationChain.push({ role: 'assistant', content: cleanAssistant });
        } else {
          conversationChain.push({ role: 'assistant', content: `[Mengeksekusi penelusuran otonom: ${toolSummaryList.join(', ')}]` });
        }

        const allToolsInRoundFailed = toolExecResults.length > 0 && toolExecResults.every(r => {
          if (r.toolExecRes && r.toolExecRes.success === false) return true;
          const t = String(r.toolExecRes?.text || '').trim();
          if (t.startsWith('Error:') || t.startsWith('Error eksekusi:') || t.startsWith('Error Keamanan:') || t.includes('Gagal membaca URL')) return true;
          if (t.includes('Error eksekusi:') || t.includes('Error Keamanan:') || t.includes('Error:')) return true;
          if (t.includes('tidak ditemukan video') || t.includes('Tidak ditemukan hasil spesifik')) return true;
          return false;
        });

        if (allToolsInRoundFailed) {
          consecutiveFailedRounds++;
        } else {
          consecutiveFailedRounds = 0;
        }

        // CIRCUIT BREAKER: Jika seluruh tool gagal dalam 2 putaran berturut-turut,
        // putuskan siklus dan paksa sintesis jawaban akhir untuk mencegah pemborosan token / looping tanpa henti.
        const circuitBreakerTripped = consecutiveFailedRounds >= 2;
        const isLastRound = circuitBreakerTripped || (autonomousRound >= maxAutonomousRounds - 1);
        const roundInstruction = isLastRound
          ? `[INFORMASI / DATA OTONOM TELAH TERSEDIA]:
${circuitBreakerTripped ? 'PERINGATAN SISTEM (CIRCUIT BREAKER AKTIF): Pemanggilan tool berturut-turut mengalami kegagalan akses (kemungkinan kendala jaringan/lingkungan). JANGAN memanggil tool lagi. Gunakan pengetahuan dasar yang Anda miliki untuk menjawab secara langsung, atau jelaskan dengan jujur kepada pengguna bahwa data eksternal tidak dapat diakses saat ini.' : 'Gunakan seluruh data hasil di atas untuk menjawab pertanyaan pengguna secara komprehensif, jelas, faktual, dan akurat.'}
Jika hasilnya berupa video YouTube: jelaskan dan rekomendasikan video yang paling relevan (judul, channel, durasi, tayangan), lalu WAJIB sisipkan tautan video pilihan Anda dengan format markdown [Judul Video](https://www.youtube.com/watch?v=ID) agar kartu video dapat ditampilkan dan diputar langsung di dalam percakapan.
Jawablah secara langsung dan tuntas tanpa penolakan kaku, tanpa basa-basi robotik, dan tanpa format pemanggilan tool lagi.`
          : `[INFORMASI / DATA OTONOM TELAH TERSEDIA]:
Data hasil eksekusi tool di atas telah disediakan untuk Anda.
Jika informasi sudah cukup lengkap, berikan jawaban akhir secara langsung dan tuntas kepada pengguna.
Namun jika Anda masih memerlukan data pendukung tambahan (misalnya membaca artikel lengkap dengan browse_web_page dari URL hasil pencarian, mencari memori tambahan, atau mengeksekusi kalkulasi kode Python), Anda dapat memanggil tool berikutnya yang relevan.`;

        conversationChain.push({
          role: 'user',
          content: `[DATA HASIL EKSEKUSI TOOL OTONOM]:\n${roundToolResponsesText}\n\n${roundInstruction}`
        });

        // Jalankan panggilan streaming ke model untuk putaran berikutnya
        const activeDigestionModel = actualModelUsed || modelName;
        const isDigestionLiquid = Boolean(activeDigestionModel && (activeDigestionModel.includes('liquid') || activeDigestionModel.includes('lfm-')));
        const isDigestionReasoning = Boolean(activeDigestionModel && (activeDigestionModel.includes('/o1') || activeDigestionModel.includes('/o3')));

        const digestionRequestBody = {
          model: activeDigestionModel,
          messages: conversationChain,
          stream: true,
          provider: {
            allow_fallbacks: true
          }
        };
        const canDigestionUseTools = doesModelSupportTools(activeDigestionModel);
        const isDigestionFree = Boolean(
          activeDigestionModel.includes(':free') ||
          activeDigestionModel.endsWith('/free') ||
          activeDigestionModel === 'openrouter/free' ||
          (STATE.openRouterModels || []).some(m => m.id === activeDigestionModel && (m.cat === 'free' || m.tag === 'Free'))
        );
        if (!isLastRound && !isDigestionFree && canDigestionUseTools && STATE.settings.openRouterKey && selectedAutonomousTools && selectedAutonomousTools.length > 0) {
          const validFunctionTools = selectedAutonomousTools.filter(t => t && t.type === 'function' && t.function && t.function.name);
          if (validFunctionTools.length > 0) {
            digestionRequestBody.tools = validFunctionTools;
            digestionRequestBody.tool_choice = 'auto';
          }
        }
        if (!isDigestionReasoning) {
          digestionRequestBody.temperature = parseFloat(STATE.settings.temperature) || 0.7;
        }
        if (!isDigestionLiquid && !isDigestionReasoning) {
          digestionRequestBody.top_p = parseFloat(STATE.settings.topP) || 0.9;
        }

        const isDirectRoute = activeRouteType === 'direct' || (!activeEndpoint || activeEndpoint.includes('openrouter.ai'));
        if (isDirectRoute) {
          delete digestionRequestBody.sessionId;
          delete digestionRequestBody.userId;
          delete digestionRequestBody.apiKey;
        } else {
          if (session?.id) digestionRequestBody.sessionId = session.id;
          if (STATE.userId) digestionRequestBody.userId = STATE.userId;
          digestionRequestBody.apiKey = STATE.settings.openRouterKey || undefined;
        }

        const digestionUrl = activeEndpoint || (isDirectRoute ? 'https://openrouter.ai/api/v1/chat/completions' : '/api/openrouter/chat');
        const digestionHeaders = (activeHeaders && Object.keys(activeHeaders).length > 0) ? activeHeaders : {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${STATE.settings.openRouterKey || ''}`,
          'HTTP-Referer': location.origin || 'https://zozi0999.github.io/zoz_router',
          'X-Title': 'ZOZ Router'
        };

        currentRoundText = '';
        currentRoundNativeCalls = [];

        try {
          let digestionRes = await fetch(digestionUrl, {
            method: 'POST',
            headers: digestionHeaders,
            body: JSON.stringify(digestionRequestBody),
            signal: STATE.abortController?.signal
          });

          // Fallback resiliensi: jika model menolak tools di putaran lanjutan (HTTP 400/422)
          if (!digestionRes.ok && digestionRequestBody.tools && (digestionRes.status === 400 || digestionRes.status === 422)) {
            console.warn(`[OpenRouter Autonomous Digestion Round ${autonomousRound}] Model returned HTTP ${digestionRes.status} with tools. Retrying without tools...`);
            delete digestionRequestBody.tools;
            delete digestionRequestBody.tool_choice;
            digestionRes = await fetch(digestionUrl, {
              method: 'POST',
              headers: digestionHeaders,
              body: JSON.stringify(digestionRequestBody),
              signal: STATE.abortController?.signal
            });
          }

          if (!digestionRes.ok) {
            let errDetail = `HTTP ${digestionRes.status}`;
            try {
              const errJson = await digestionRes.json();
              if (errJson && errJson.error) {
                errDetail = typeof errJson.error === 'object' ? (errJson.error.message || JSON.stringify(errJson.error)) : errJson.error;
              }
            } catch (_) {}
            console.warn(`[OpenRouter Autonomous Digestion Round ${autonomousRound}] Error:`, errDetail);
            if (!fullText.trim()) {
              fullText = (allAccumulatedToolResponsesText || (webSources && webSources.length > 0))
                ? synthesizeAutonomousWebSummary(allAccumulatedToolResponsesText, webSources)
                : (cleanAssistant || `[Pencarian selesai: ${toolSummaryList.join(', ')}. Sistem menyelesaikan penelusuran].`);
            }
            break;
          }

          const digestionReader = digestionRes.body.getReader();
          let digestionBuffer = '';
          const digestionContentBox = document.createElement('div');
          digestionContentBox.className = 'autonomous-digested-output';
          bubbleText.innerHTML = preambleHtml + executedHudHtml;
          bubbleText.appendChild(digestionContentBox);

          const digestionRenderer = new StreamBufferRenderer(digestionContentBox, () => smartScrollChatToBottom(false));

          while (true) {
            const { done, value } = await digestionReader.read();
            if (done) {
              digestionBuffer += decoder.decode();
              break;
            }
            digestionBuffer += decoder.decode(value, { stream: true });
            const dLines = digestionBuffer.split('\n');
            digestionBuffer = dLines.pop();

            for (const dLine of dLines) {
              const dTrimmed = dLine.trim();
              if (!dTrimmed || !dTrimmed.startsWith('data:')) continue;
              const dJson = dTrimmed.replace(/^data:\s*/, '');
              if (dJson === '[DONE]') break;
              try {
                const dParsed = JSON.parse(dJson);
                const dReasoning = dParsed.choices?.[0]?.delta?.reasoning 
                  || dParsed.choices?.[0]?.delta?.reasoning_content 
                  || dParsed.choices?.[0]?.delta?.thought 
                  || '';
                if (dReasoning) {
                  tokenCount++;
                  digestionRenderer.appendReasoning(dReasoning);
                }
                const dDelta = dParsed.choices?.[0]?.delta?.content;
                if (dDelta) {
                  tokenCount++;
                  digestionRenderer.append(dDelta);
                  if (digestionRenderer.isLoopTerminated) {
                    console.warn('[OpenRouter Digestion] Degeneration loop detected and gracefully halted.');
                    try { await digestionReader.cancel(); } catch (_) {}
                    break;
                  }
                }
                const deltaTc = dParsed.choices?.[0]?.delta?.tool_calls;
                if (Array.isArray(deltaTc)) {
                  deltaTc.forEach(tc => {
                    const idx = tc.index ?? 0;
                    if (!currentRoundNativeCalls[idx]) {
                      currentRoundNativeCalls[idx] = {
                        id: tc.id || `call_${Date.now()}_${idx}`,
                        type: tc.type || 'function',
                        function: {
                          name: tc.function?.name || '',
                          arguments: tc.function?.arguments || ''
                        }
                      };
                    } else {
                      if (tc.id) currentRoundNativeCalls[idx].id = tc.id;
                      if (tc.function?.name) {
                        if (!currentRoundNativeCalls[idx].function.name) {
                          currentRoundNativeCalls[idx].function.name = tc.function.name;
                        } else if (currentRoundNativeCalls[idx].function.name !== tc.function.name && !currentRoundNativeCalls[idx].function.name.endsWith(tc.function.name)) {
                          currentRoundNativeCalls[idx].function.name += tc.function.name;
                        }
                      }
                      if (tc.function?.arguments) currentRoundNativeCalls[idx].function.arguments += tc.function.arguments;
                    }
                  });
                }
              } catch (_) {}
            }
          }

          if (digestionBuffer && digestionBuffer.trim() && digestionBuffer.trim().startsWith('data:')) {
            const dJson = digestionBuffer.trim().replace(/^data:\s*/, '');
            if (dJson !== '[DONE]') {
              try {
                const dParsed = JSON.parse(dJson);
                const dReasoning = dParsed.choices?.[0]?.delta?.reasoning 
                  || dParsed.choices?.[0]?.delta?.reasoning_content 
                  || dParsed.choices?.[0]?.delta?.thought 
                  || '';
                if (dReasoning) {
                  tokenCount++;
                  digestionRenderer.appendReasoning(dReasoning);
                }
                const dDelta = dParsed.choices?.[0]?.delta?.content;
                if (dDelta) {
                  tokenCount++;
                  digestionRenderer.append(dDelta);
                }
                const deltaTc = dParsed.choices?.[0]?.delta?.tool_calls;
                if (Array.isArray(deltaTc)) {
                  deltaTc.forEach(tc => {
                    const idx = tc.index ?? 0;
                    if (!currentRoundNativeCalls[idx]) {
                      currentRoundNativeCalls[idx] = {
                        id: tc.id || `call_${Date.now()}_${idx}`,
                        type: tc.type || 'function',
                        function: {
                          name: tc.function?.name || '',
                          arguments: tc.function?.arguments || ''
                        }
                      };
                    } else {
                      if (tc.id) currentRoundNativeCalls[idx].id = tc.id;
                      if (tc.function?.name) {
                        if (!currentRoundNativeCalls[idx].function.name) {
                          currentRoundNativeCalls[idx].function.name = tc.function.name;
                        } else if (currentRoundNativeCalls[idx].function.name !== tc.function.name && !currentRoundNativeCalls[idx].function.name.endsWith(tc.function.name)) {
                          currentRoundNativeCalls[idx].function.name += tc.function.name;
                        }
                      }
                      if (tc.function?.arguments) currentRoundNativeCalls[idx].function.arguments += tc.function.arguments;
                    }
                  });
                }
              } catch (_) {}
            }
          }
          currentRoundText = digestionRenderer.finish({ render: false });
          fullText = currentRoundText;
          if (digestionRenderer.isLoopTerminated) {
            break;
          }
          if (!fullText.trim() && (allAccumulatedToolResponsesText || (webSources && webSources.length > 0))) {
            fullText = synthesizeAutonomousWebSummary(allAccumulatedToolResponsesText, webSources);
          }
        } catch (digestionErr) {
          // H3: sama seperti jalur Ollama — AbortError diteruskan ke catch luar,
          // bukan dipaksa jadi respons "selesai" yang menyesatkan.
          if (digestionErr && (digestionErr.name === 'AbortError' || STATE.abortController?.signal?.aborted)) {
            throw digestionErr;
          }
          console.warn(`[OpenRouter Autonomous Digestion Round ${autonomousRound}] Fetch error:`, digestionErr);
          if (!fullText.trim()) {
            fullText = (allAccumulatedToolResponsesText || (webSources && webSources.length > 0))
              ? synthesizeAutonomousWebSummary(allAccumulatedToolResponsesText, webSources)
              : (cleanAssistant || '');
          }
          break;
        }
      }

      // ===== AI INTERACTIVE TASK TRACKER =====
      const detectedTasks = parseAiTasksBlock(fullText);
      if (detectedTasks && STATE.taskTracker.enabled) {
        setTaskTrackerTasks(detectedTasks);
      }
      if (fullText.indexOf('<<<ZOZ_TASKS') !== -1) {
        fullText = hideTaskBlocksForDisplay(fullText).trim();
      }

      // ===== AI FILE STUDIO & WORKSPACE AUTO-SAVE =====
      // Ekstrak file yang dibuat/diedit AI, lalu hapus bloknya dari gelembung agar tidak
      // tampil kode mentah berulang (kartu file digantikan oleh kartu di bawah).
      const extractedAiFiles = extractGeneratedFiles(fullText, wantsFile);
      const generatedFiles = extractedAiFiles.files;
      if (generatedFiles.length > 0) {
        fullText = stripGeneratedFileBlocks(fullText, extractedAiFiles.rawBlocks);
        await processAiGeneratedWorkspaceFiles(generatedFiles);
      } else if (fullText.indexOf('<<<ZOZ_FILE') !== -1 || fullText.indexOf('<<<END_ZOZ_FILE') !== -1 || fullText.indexOf('<<<ZOZ_EDIT') !== -1) {
        // M2: ada marker tapi TIDAK ada blok utuh (stream terputus sebelum
        // <<<END_ZOZ_FILE / END yatim). Dulu marker + isi blok tampil mentah di
        // gelembung final dan persist ke riwayat — padahal saat streaming barisnya
        // disembunyikan. Buang sisa blok (hideFileBlocksForDisplay memangkas dari
        // marker terbuka sampai akhir teks — tak ada isi setelah blok tak tertutup).
        fullText = stripGeneratedFileBlocks(hideFileBlocksForDisplay(fullText), []);
      }

      // Ekstrak permintaan hapus berkas oleh AI jika ada
      const filesToDelete = extractDeletedFiles(fullText);
      if (filesToDelete.length > 0) {
        fullText = stripDeletedFileBlocks(fullText);
        if (STATE.localWorkspace.enabled && STATE.localWorkspace.aiCanWrite) {
          for (const delName of filesToDelete) {
            await deleteWorkspaceDocumentSilent(delName, { author: 'ai', note: 'Dihapus oleh AI' });
          }
        }
      }

      // Pastikan tidak ada gelembung obrolan kosong saat file dimodifikasi/dibuat
      if (!fullText.trim() && generatedFiles.length > 0) {
        const names = generatedFiles.map(f => `**${escapeHtml(f.name)}**`).join(', ');
        fullText = `✅ **Pembaruan Berkas Berhasil!** AI telah memodifikasi dan menyimpan berkas ${names} ke direktori lokal Anda. Versi cadangan otomatis dicatat di Riwayat Versi.`;
      }

      // Bersihkan sisa tag tool_call dan residu raw JSON jika ada sebelum render markdown final
      const cleanFinalText = scrubRawToolCallArtifacts(fullText);
      if (cleanFinalText && cleanFinalText.trim()) {
        fullText = cleanFinalText;
      } else if (!canRunAutonomousSearch && (extractInlineToolCalls(fullText).length > 0 || accumulatedToolCalls.length > 0)) {
        fullText = 'Model mencoba melakukan penelusuran web untuk menjawab pertanyaan ini, namun fitur **Pencarian Web** saat ini sedang nonaktif. Silakan aktifkan ikon bola dunia (🌐 Pencarian Web) pada bilah kontrol di bawah untuk mengizinkan penelusuran data langsung.';
      }

      if (!fullText.trim()) {
        if (webSources && webSources.length > 0) {
          fullText = synthesizeAutonomousWebSummary(allAccumulatedToolResponsesText, webSources);
        } else if (preambleHtml) {
          fullText = 'Model menyelesaikan penelusuran namun tidak menghasilkan respon teks tambahan.';
        }
      }

      if (!fullText.trim() && generatedFiles.length === 0 && !preambleHtml && collectedImages.length === 0) {
        if (STATE.abortController?.signal?.aborted) {
          // H3: sama seperti Ollama — jangan simpan gelembung kosong sebagai jawaban.
          assistantRow.remove();
          showToast('Generasi dihentikan.');
          return;
        }
        throw new Error('Model OpenRouter menyelesaikan koneksi tanpa menghasilkan respon teks.');
      }

      fullText = safeAssistantText(fullText);
      const totalTime = ((performance.now() - startTime) / 1000).toFixed(2);
      const tps = totalTime > 0 ? (tokenCount / totalTime).toFixed(1) : '0';

      let renderedMarkdown = renderMarkdown(fullText);
      let imagesHtml = '';
      if (collectedImages.length > 0) {
        imagesHtml = `
          <div class="chat-generated-images-grid" style="margin-top: 12px; display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px;">
            ${collectedImages.map(url => createGeneratedImageCardHtml({
              url: url,
              imageUrl: url,
              prompt: promptText,
              model: modelName,
              duration: totalTime
            })).join('')}
          </div>
        `;
      }

      const finalRenderedContent = (preambleHtml ? preambleHtml : '') + (executedHudHtml ? executedHudHtml + renderedMarkdown + imagesHtml : renderedMarkdown + imagesHtml);
      bubbleText.innerHTML = finalRenderedContent.trim();
      enhanceCodeBlocks(bubbleText);
      enhanceChatImages(bubbleText);
      if (collectedImages.length > 0) {
        attachImageCardListeners(assistantRow, promptText, collectedImages[0]);
      }
      if (webSources && webSources.length > 0) {
        webSources = deduplicateSources(webSources);
        renderMessageSources(assistantRow, webSources, true);
      }
      renderYouTubeCardsForMessage(assistantRow, fullText, foundYouTubeIds);
      renderMessageFiles(assistantRow, generatedFiles);
      const effectiveDisplay = (actualModelUsed && actualModelUsed !== displayModel && actualModelUsed !== modelName) ? `${displayModel} → ${actualModelUsed} (Failover)` : displayModel;
      metaBox.innerHTML = `
        <strong title="${actualModelUsed ? escapeHtml('Model dialihkan ke ' + actualModelUsed) : escapeHtml(displayModel)}">${escapeHtml(effectiveDisplay)}</strong>
        <span class="meta-model-badge" style="${engineLabel === 'Ollama Cloud' ? 'background:rgba(0,242,254,0.15); color:var(--neon-cyan);' : 'background:rgba(255,82,0,0.15); color:var(--neon-amber);'}">${engineLabel}</span>
        ${collectedImages.length > 0 ? '<span class="meta-model-badge" style="background:rgba(255,0,127,0.18); border-color:#FF007F; color:#FF66B2;"><i class="fa-solid fa-wand-magic-sparkles"></i> Gambar Dibuat</span>' : ''}
        <span>⏱️ ${totalTime}s</span>
        <span>⚡ ${tps} tps</span>
      `;

      assistantRow.dataset.fullContent = fullText;

      // Check if output is cut in half and provide one-click continuation button
      if (isOutputTruncated(fullText, finishReason)) {
        attachContinuationButton(assistantRow.querySelector('.message-content-box') || assistantRow, session, assistantRow, actualModelUsed || displayModel, engineMode, fullText);
      }

      // Save to session if session is still alive
      if (STATE.sessions.some(s => s.id === session.id)) {
        session.messages.push({
          role: 'assistant',
          content: fullText,
          model: actualModelUsed || displayModel,
          engine: engineMode,
          images: collectedImages.length > 0 ? collectedImages : undefined,
          files: generatedFiles.length > 0 ? generatedFiles : undefined,
          imageUrl: collectedImages[0] || undefined,
          sources: webSources,
          stats: { duration: totalTime, tps: tps, tokens: tokenCount },
          timestamp: new Date().toISOString()
        });
        session.updatedAt = new Date().toISOString();
        savePersistedState();
        renderChatHistory(els.searchHistoryInput?.value || '');
      }
      AudioEngine.receive();
      notifyAiCompletion('🤖 ' + (actualModelUsed || displayModel), fullText);
      BioEndocrine.secreteDopamine(12, `OpenRouter inferensi sukses: ${actualModelUsed || displayModel}`);
      return true;

    } catch (err) {
      if (err.name === 'AbortError') {
        // render:false → baris di bawah langsung mengganti innerHTML (atau baris
        // dihapus), jadi render dari finish hanya akan dibuang.
        const partialRaw = streamRenderer ? streamRenderer.finish({ render: false }) : '';
        const stoppedPartial = sanitizePartialResponseWithFiles(partialRaw);
        const partialText = stoppedPartial.text;
        if (partialText && partialText.trim() && STATE.sessions.some(s => s.id === session.id)) {
          const stoppedText = `${partialText.trim()}\n\n*[Respons dihentikan oleh pengguna]*`;
          bubbleText.innerHTML = renderMarkdown(stoppedText);
          enhanceCodeBlocks(bubbleText);
          renderMessageFiles(assistantRow, stoppedPartial.files);
          if (webSources && webSources.length > 0) {
            renderMessageSources(assistantRow, webSources, true);
          }
          const totalTime = ((performance.now() - startTime) / 1000).toFixed(2);
          metaBox.innerHTML = `
            <strong>${escapeHtml(displayModel)}</strong>
            <span class="meta-model-badge" style="${engineLabel === 'Ollama Cloud' ? 'background:rgba(0,242,254,0.15); color:var(--neon-cyan);' : 'background:rgba(255,82,0,0.15); color:var(--neon-amber);'}">${engineLabel}</span>
            <span>⏱️ ${totalTime}s (Dihentikan)</span>
          `;
          session.messages.push({
            role: 'assistant',
            content: stoppedText,
            model: displayModel,
            engine: engineMode,
            sources: webSources,
            files: stoppedPartial.files.length > 0 ? stoppedPartial.files : undefined,
            stats: { duration: totalTime, tokens: tokenCount, stopped: true },
            timestamp: new Date().toISOString()
          });
          session.updatedAt = new Date().toISOString();
          savePersistedState();
          renderChatHistory(els.searchHistoryInput?.value || '');
        } else {
          assistantRow.remove();
        }
        showToast('Generasi dihentikan.');
        return false;
      } else {
        BioEndocrine.secreteStress(22, `OpenRouter error: ${err?.message || 'Stream exception'}`);
        // Auto-Router fallback: bersihkan gelembung sementara dan kembalikan false agar caller langsung beralih ke engine lain
        if (runOptions && runOptions.autoFallback) {
          try { assistantRow.remove(); } catch (_) {}
          return false;
        }

        // render:false → bubbleText.innerHTML diganti tanpa syarat beberapa baris
        // di bawah (kartu error), jadi render dari finish hanya akan dibuang.
        const rescuePartial = sanitizePartialResponseWithFiles(streamRenderer ? streamRenderer.finish({ render: false }) : '');
        const partialText = scrubRawToolCallArtifacts(rescuePartial.text);
        const hasPartialText = Boolean(partialText && partialText.trim());

        if (hasPartialText && STATE.sessions.some(s => s.id === session.id)) {
          const rescuedText = `${partialText.trim()}\n\n*[Koneksi terputus saat streaming]*`;
          const totalTime = ((performance.now() - startTime) / 1000).toFixed(2);

          session.messages.push({
            role: 'assistant',
            content: rescuedText,
            model: displayModel,
            engine: engineMode,
            sources: webSources,
            files: rescuePartial.files.length > 0 ? rescuePartial.files : undefined,
            stats: { duration: totalTime, tokens: tokenCount, interrupted: true },
            timestamp: new Date().toISOString()
          });
          session.updatedAt = new Date().toISOString();
          savePersistedState();
          renderChatHistory(els.searchHistoryInput?.value || '');

          if (metaBox) {
            metaBox.innerHTML = `
              <strong>${escapeHtml(displayModel)}</strong>
              <span class="meta-model-badge" style="${engineLabel === 'Ollama Cloud' ? 'background:rgba(0,242,254,0.15); color:var(--neon-cyan);' : 'background:rgba(255,82,0,0.15); color:var(--neon-amber);'}">${engineLabel}</span>
              <span>⏱️ ${totalTime}s (Terputus)</span>
            `;
          }
        }

        const actualHasImage = Array.isArray(image) ? image.length > 0 : Boolean(image);
        const errorHtml = formatModelErrorMessage(engineMode, displayModel, err, actualHasImage, STATE.webSearchEnabled);

        const isFreeModel = Boolean(modelName && (modelName.includes(':free') || modelName.endsWith('/free') || modelName === 'openrouter/free'));
        const fallbackModelCandidate = (modelName === 'openrouter/free') 
          ? 'nvidia/nemotron-3-super-120b-a12b:free' 
          : 'openrouter/free';
        const fallbackLabel = (modelName === 'openrouter/free') 
          ? 'Nemotron 3 Super 120B (Free)' 
          : 'OpenRouter Free Router';

        const rescuedHtml = hasPartialText ? `
          <div class="partial-rescued-content" style="margin-bottom:12px; padding-bottom:12px; border-bottom:1px dashed rgba(255,255,255,0.15);">
            ${renderMarkdown(partialText.trim())}
          </div>
        ` : '';

        bubbleText.innerHTML = `
          ${rescuedHtml}
          ${errorHtml}
          <div style="margin-top:10px; display:flex; gap:8px; flex-wrap:wrap;">
            <button class="btn btn-sm btn-outline retry-send-btn" style="border-color:var(--neon-cyan); color:var(--neon-cyan); font-size:0.75rem;">
               <i class="fa-solid fa-rotate-right"></i> Coba Kirim Ulang
            </button>
            <button class="btn btn-sm btn-outline switch-free-model-btn" data-fallback="${fallbackModelCandidate}" style="border-color:var(--neon-teal); color:var(--neon-teal); font-size:0.75rem;">
              <i class="fa-solid fa-bolt"></i> Ganti ke ${fallbackLabel} &amp; Kirim Ulang
            </button>
            <button class="btn btn-sm btn-outline open-settings-btn" style="border-color:var(--neon-amber); color:var(--neon-amber); font-size:0.75rem;">
              <i class="fa-solid fa-gear"></i> Buka Pengaturan & Key
            </button>
          </div>
        `;

        if (hasPartialText) {
          enhanceCodeBlocks(bubbleText);
          renderMessageFiles(assistantRow, rescuePartial.files);
          if (webSources && webSources.length > 0) {
            renderMessageSources(assistantRow, webSources, true);
          }
        }

        bubbleText.querySelector('.retry-send-btn')?.addEventListener('click', () => {
          if (STATE.isGenerating || STATE.isSending) return;
          assistantRow.remove();
          runOpenRouterStreaming(session, promptText, image, modelName, runOptions);
        });

        bubbleText.querySelector('.switch-free-model-btn')?.addEventListener('click', (e) => {
          if (STATE.isGenerating || STATE.isSending) return;
          const targetFallback = e.currentTarget.dataset.fallback || 'openrouter/free';
          selectModel(targetFallback);
          assistantRow.remove();
          runOpenRouterStreaming(session, promptText, image, targetFallback);
        });

        bubbleText.querySelector('.open-settings-btn')?.addEventListener('click', () => {
          syncSettingsModalFields();
          openModal('settingsModal');
        });

        AudioEngine.error();
        return false;
      }
    } finally {
      setGeneratingState(false);
    }
  }

  // --- AUTO ROUTER (SMART ROUTING) ---
  async function runAutoRouterStreaming(session, promptText, image) {
    try {
      setGeneratingState(true);
      // Check if Ollama is online & runnable on current deployment
      const isOllamaOnline = await checkOllamaHealth();
      const hasOllamaCloudKey = Boolean(STATE.settings.ollamaApiKey);
      const isLoopbackEndpoint = /^http:\/\/(?:localhost|127\.0\.0\.1|\[::1\])/i.test(STATE.settings.ollamaEndpoint);
      const isCloudHosted = Boolean(IS_CLOUD_HOSTED || location.protocol === 'https:');
      const isOllamaRunnable = isOllamaOnline && (!isCloudHosted || !isLoopbackEndpoint || hasOllamaCloudKey);
      
      // Policy check
      const policy = STATE.settings.autoPolicy || 'cloud_first';
      const isLongOrHeavy = (promptText.length > 800) || (promptText.toLowerCase().includes('buatkan sistem') || promptText.toLowerCase().includes('arsitektur kompleks'));
      const canRunOpenRouter = Boolean(STATE.settings.openRouterKey || DeviceStorage.isDeviceBackendAvailable || !IS_GITHUB_PAGES);

      if (policy === 'cloud_heavy' && isLongOrHeavy && canRunOpenRouter) {
        showToast('🔀 Auto-Router: Mengarahkan tugas kompleks ke OpenRouter Cloud...', 'info');
        const orOk = await runOpenRouterStreaming(session, promptText, image, STATE.settings.openRouterModel || 'openrouter/free', { autoFallback: true });
        if (!orOk && isOllamaRunnable) {
          console.warn('Auto-Router: OpenRouter gagal / tidak merespons, beralih ke Ollama Engine...');
          showToast('🔀 Auto-Router: OpenRouter tidak tersedia, beralih ke Ollama...', 'info');
          await runOllamaStreaming(session, promptText, image, STATE.settings.ollamaModel);
        }
      } else if (policy === 'cloud_first' && canRunOpenRouter) {
        showToast('🔀 Auto-Router: Menggunakan OpenRouter Cloud...', 'info');
        const orOk = await runOpenRouterStreaming(session, promptText, image, STATE.settings.openRouterModel || 'openrouter/free', { autoFallback: true });
        if (!orOk && isOllamaRunnable) {
          console.warn('Auto-Router: OpenRouter gagal / tidak merespons, beralih ke Ollama Engine...');
          showToast('🔀 Auto-Router: OpenRouter tidak tersedia, beralih ke Ollama...', 'info');
          await runOllamaStreaming(session, promptText, image, STATE.settings.ollamaModel);
        }
      } else if (isOllamaRunnable) {
        showToast('🔀 Auto-Router: Menghubungi Ollama Engine...', 'info');
        const ollamaOk = await runOllamaStreaming(session, promptText, image, STATE.settings.ollamaModel, { autoFallback: true });
        if (!ollamaOk && canRunOpenRouter) {
          console.warn('Auto-Router: Ollama gagal / tidak merespons, otomatis beralih ke OpenRouter Cloud...');
          showToast('🔀 Auto-Router: Ollama tidak tersedia, beralih ke OpenRouter Cloud...', 'info');
          await runOpenRouterStreaming(session, promptText, image, STATE.settings.openRouterModel || 'openrouter/free');
        }
      } else if (canRunOpenRouter) {
        showToast('🔀 Auto-Router: Menggunakan OpenRouter Cloud...', 'info');
        await runOpenRouterStreaming(session, promptText, image, STATE.settings.openRouterModel || 'openrouter/free');
      } else {
        // Kedua engine tidak siap: tampilkan kartu bantuan interaktif dan pulihkan composer
        const assistantRow = appendMessageElement('assistant', '', null, 'Auto-Router Engine');
        const bubbleText = assistantRow.querySelector('.msg-text-content');
        const metaBox = assistantRow.querySelector('.message-meta');
        
        bubbleText.innerHTML = `
          <div style="background:rgba(255,170,0,0.08); border:1px solid rgba(255,170,0,0.35); border-radius:10px; padding:14px; margin-bottom:12px; line-height:1.5;">
            <div style="font-weight:700; color:var(--neon-amber); margin-bottom:6px; display:flex; align-items:center; gap:8px; font-size:0.9rem;">
              <i class="fa-solid fa-triangle-exclamation"></i> Auto-Router: Tidak Ada Engine AI yang Siap
            </div>
            <div style="font-size:0.83rem; color:var(--text-main); margin-bottom:8px;">
              Ollama Cloud Engine tidak dapat dihubungi pada <code>${escapeHtml(STATE.settings.ollamaEndpoint)}</code> dan <strong>OpenRouter API Key</strong> belum dikonfigurasi di Pengaturan.
            </div>
            <div style="font-size:0.8rem; color:var(--text-secondary); background:rgba(0,0,0,0.3); padding:8px 10px; border-radius:6px; border-left:3px solid var(--neon-cyan);">
              💡 <strong>Solusi:</strong> Masukkan Ollama API Key atau OpenRouter API Key di menu Pengaturan agar Auto-Router dapat mengeksekusi model Cloud secara lancar.
            </div>
          </div>
          <div style="margin-top:10px; display:flex; gap:8px; flex-wrap:wrap;">
            <button class="btn btn-sm btn-primary open-settings-btn" style="font-size:0.75rem;">
              <i class="fa-solid fa-sliders"></i> Buka Pengaturan & Masukkan API Key
            </button>
            <button class="btn btn-sm btn-outline retry-router-btn" style="border-color:var(--neon-cyan); color:var(--neon-cyan); font-size:0.75rem;">
              <i class="fa-solid fa-rotate-right"></i> Cek Ulang Status Ollama Cloud
            </button>
          </div>
        `;

        bubbleText.querySelector('.open-settings-btn')?.addEventListener('click', () => {
          syncSettingsModalFields();
          openModal('settingsModal');
        });

        bubbleText.querySelector('.retry-router-btn')?.addEventListener('click', async () => {
          if (STATE.isGenerating || STATE.isSending) return;
          assistantRow.remove();
          await runAutoRouterStreaming(session, promptText, image);
        });

        if (metaBox) {
          metaBox.innerHTML = `
            <strong>Auto-Router</strong>
            <span class="meta-model-badge" style="background:rgba(255,50,50,0.2); color:#ff6b6b;">Offline</span>
          `;
        }

        AudioEngine.error();
        showToast('Ollama offline dan OpenRouter Key belum disetting.', 'error');
        smartScrollChatToBottom(true);
      }
    } finally {
      setGeneratingState(false);
    }
  }

  function setGeneratingState(isGen) {
    STATE.isGenerating = isGen;
    if (els.sendPromptBtn) {
      els.sendPromptBtn.style.display = isGen ? 'none' : 'flex';
    }
    if (els.stopGenerationBtn) {
      els.stopGenerationBtn.style.display = isGen ? 'flex' : 'none';
    }
  }

  function stopGeneration() {
    if (activeChatPollTimer) {
      clearInterval(activeChatPollTimer);
      activeChatPollTimer = null;
    }
    const activeCursor = els.messagesList?.querySelector('.typing-cursor');
    if (activeCursor) {
      const bubbleText = activeCursor.closest('.msg-text-content');
      activeCursor.remove();
      if (bubbleText) {
        enhanceCodeBlocks(bubbleText);
        enhanceChatImages(bubbleText);
      }
    }
    const activeSession = findCurrentActiveSession();
    if (activeSession?.id && !IS_GITHUB_PAGES) {
      fetch('/api/chat/stop', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-User-ID': STATE.userId
        },
        body: JSON.stringify({ sessionId: activeSession.id, userId: STATE.userId })
      }).catch(() => {});
    }
    if (STATE.currentDeepResearchTaskId && !IS_GITHUB_PAGES) {
      const abortTaskId = STATE.currentDeepResearchTaskId;
      STATE.currentDeepResearchTaskId = null;
      fetch('/api/batal-riset/' + abortTaskId, {
        method: 'POST',
        headers: { 'X-User-ID': STATE.userId }
      }).catch(() => {});
    }
    if (STATE.abortController) {
      STATE.abortController.abort();
    }
    setGeneratingState(false);
  }

  // ==================== IMAGE VISION & MEDIA HANDLER ====================
  function isImageFile(file) {
    if (!file) return false;
    if (file.type && typeof file.type === 'string' && file.type.startsWith('image/')) return true;
    const name = file.name || '';
    const ext = (name.split('.').pop() || '').toLowerCase();
    const imageExtensions = ['png', 'jpg', 'jpeg', 'webp', 'gif', 'bmp', 'svg', 'ico', 'heic', 'heif', 'tiff', 'jfif', 'avif'];
    return imageExtensions.includes(ext);
  }

  // Client-side instant image compressor (Reduces 10MB camera photo to ~80KB WebP)
  function compressImageToWebP(file, maxDimension = 1024, quality = 0.8) {
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
          let { width, height } = img;
          if (width > maxDimension || height > maxDimension) {
            if (width > height) {
              height = Math.round((height * maxDimension) / width);
              width = maxDimension;
            } else {
              width = Math.round((width * maxDimension) / height);
              height = maxDimension;
            }
          }
          const canvas = document.createElement('canvas');
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return resolve(e.target.result);
          ctx.drawImage(img, 0, 0, width, height);
          try {
            const dataUrl = canvas.toDataURL('image/webp', quality);
            resolve(dataUrl);
          } catch (err) {
            resolve(e.target.result);
          }
        };
        img.onerror = () => resolve(e.target.result);
        img.src = e.target.result;
      };
      reader.onerror = () => resolve(null);
      reader.readAsDataURL(file);
    });
  }

  async function processSingleImageFile(file) {
    if (!file || typeof file.size !== 'number' || file.size <= 0) return false;
    try {
      const compressedDataUrl = await compressImageToWebP(file, 1024, 0.8) || (await new Promise(r => {
        const reader = new FileReader();
        reader.onload = ev => r(ev.target.result);
        reader.onerror = () => r(null);
        reader.readAsDataURL(file);
      }));

      if (compressedDataUrl) {
        if (!Array.isArray(STATE.attachedImages)) STATE.attachedImages = [];
        STATE.attachedImages.push(compressedDataUrl);
        // Upload to disk in background if backend is available
        if (DeviceStorage.isDeviceBackendAvailable) {
          DeviceStorage.uploadFile(compressedDataUrl).catch(() => {});
        }
        return true;
      }
    } catch (err) {
      console.warn('Image processing warning:', err.message);
    }
    return false;
  }

  async function handleImageUpload(e) {
    const files = Array.from(e.target.files || []);
    if (!files || files.length === 0) return;

    let addedCount = 0;
    for (const file of files) {
      if (!file || typeof file.size !== 'number' || file.size <= 0 || !isImageFile(file)) continue;
      const ok = await processSingleImageFile(file);
      if (ok) addedCount++;
    }

    if (els.imageFileInput) els.imageFileInput.value = '';
    if (els.cameraFileInput) els.cameraFileInput.value = '';
    renderAttachmentPreviews();

    if (addedCount > 0) {
      AudioEngine.click();
    }
  }

  function removeAttachedImage(idx) {
    if (idx >= 0 && idx < STATE.attachedImages.length) {
      STATE.attachedImages.splice(idx, 1);
      renderAttachmentPreviews();
      AudioEngine.click();
    }
  }

  function clearAttachedImages() {
    STATE.attachedImages = [];
    if (els.imageFileInput) els.imageFileInput.value = '';
    if (els.cameraFileInput) els.cameraFileInput.value = '';
    renderAttachmentPreviews();
  }

  function clearAttachedImage() {
    clearAttachedImages();
  }

