  // ==================== LOCAL WORKSPACE & USER DOCUMENT MANAGEMENT ENGINE ====================
  // Mendukung deteksi direktori lokal lintas platform:
  // 1. Laptop/Desktop (Chrome/Edge/Brave/Opera): File System Access API (showDirectoryPicker) dengan akses baca/tulis langsung ke disk.
  // 2. Ponsel/HP (Android/iOS & browser mobile): HTML5 Directory Input (webkitdirectory) & File Provider Virtual Workspace.
  // 3. AI Autonomous Document Management: AI bisa membaca dokumen, membuat dokumen baru, dan mengelola berkas lokal.

  function isDesktopFileSystemSupported() {
    const isMobileDevice = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
    return typeof window.showDirectoryPicker === 'function' && !isMobileDevice;
  }

  function formatBytes(bytes, decimals = 1) {
    if (!bytes || bytes === 0) return '0 B';
    const k = 1024;
    const dm = decimals < 0 ? 0 : decimals;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + ' ' + sizes[i];
  }

  function getFileIconClass(fileName = '') {
    const ext = fileName.split('.').pop().toLowerCase();
    switch (ext) {
      case 'pdf': return 'fa-solid fa-file-pdf';
      case 'doc':
      case 'docx': return 'fa-solid fa-file-word';
      case 'xls':
      case 'xlsx':
      case 'csv': return 'fa-solid fa-file-excel';
      case 'ppt':
      case 'pptx': return 'fa-solid fa-file-powerpoint';
      case 'js':
      case 'ts':
      case 'jsx':
      case 'tsx':
      case 'html':
      case 'css':
      case 'py':
      case 'java':
      case 'c':
      case 'cpp':
      case 'json':
      case 'xml':
      case 'yaml':
      case 'yml':
      case 'sql': return 'fa-solid fa-file-code';
      case 'md':
      case 'markdown': return 'fa-brands fa-markdown';
      case 'zip':
      case 'rar':
      case '7z':
      case 'tar':
      case 'gz': return 'fa-solid fa-file-zipper';
      case 'png':
      case 'jpg':
      case 'jpeg':
      case 'gif':
      case 'webp':
      case 'svg': return 'fa-solid fa-file-image';
      default: return 'fa-solid fa-file-lines';
    }
  }

  function downloadBlob(blob, filename) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 200);
  }

  async function scanDirectoryHandle(dirHandle, path = '') {
    const results = [];
    try {
      for await (const entry of dirHandle.values()) {
        const curPath = path ? `${path}/${entry.name}` : entry.name;
        if (entry.kind === 'file') {
          try {
            const file = await entry.getFile();
            results.push({
              name: entry.name,
              path: curPath,
              size: file.size,
              type: file.type || 'application/octet-stream',
              lastModified: file.lastModified,
              handle: entry,
              rawFile: file,
              content: null
            });
          } catch (fileErr) {
            console.warn('Gagal membaca file dari handle:', entry.name, fileErr);
          }
        } else if (entry.kind === 'directory' && !entry.name.startsWith('.')) {
          const subResults = await scanDirectoryHandle(entry, curPath);
          results.push(...subResults);
        }
      }
    } catch (scanErr) {
      console.warn('Error saat scan direktori handle:', scanErr);
    }
    return results;
  }

  async function setConnectedLocalWorkspace(dirName, dirHandle, platform, files = []) {
    STATE.localWorkspace.dirName = dirName || 'Direktori Dokumen';
    STATE.localWorkspace.dirHandle = dirHandle || null;
    STATE.localWorkspace.platform = platform || (isDesktopFileSystemSupported() ? 'desktop-fs' : 'mobile-virtual');
    STATE.localWorkspace.files = files || [];
    STATE.localWorkspace.enabled = true;
    STATE.settings.localWorkspaceEnabled = true;
    loadWorkspaceSnapshots();

    // Pastikan konten teks terbaca ke dalam memori untuk berkas umum (mis. README, file kode, dsb)
    for (const f of STATE.localWorkspace.files) {
      if (!f.content && f.rawFile && (f.size || 0) < 500000) {
        try {
          f.content = await extractFileContent(f.rawFile);
        } catch (_) {}
      }
    }

    try {
      const meta = {
        dirName: STATE.localWorkspace.dirName,
        platform: STATE.localWorkspace.platform,
        fileCount: STATE.localWorkspace.files.length,
        fileNames: STATE.localWorkspace.files.slice(0, 50).map(f => ({ name: f.name, path: f.path, size: f.size }))
      };
      localStorage.setItem('zoz_local_workspace_meta', JSON.stringify(meta));
      localStorage.setItem('zoz_router_settings_v1', JSON.stringify(STATE.settings));
      await WorkspaceDB.saveWorkspace(STATE.localWorkspace);
    } catch (_) {}

    updateLocalWorkspaceUI();
    showToast(`📁 Direktori "${STATE.localWorkspace.dirName}" berhasil terhubung (${STATE.localWorkspace.files.length} berkas).`);
    AudioEngine.click();
  }

  async function disconnectLocalWorkspace() {
    STATE.localWorkspace.enabled = false;
    STATE.localWorkspace.dirName = '';
    STATE.localWorkspace.dirHandle = null;
    STATE.localWorkspace.files = [];
    STATE.localWorkspace.pendingChanges = {};
    STATE.settings.localWorkspaceEnabled = false;

    try {
      localStorage.removeItem('zoz_local_workspace_meta');
      localStorage.setItem('zoz_router_settings_v1', JSON.stringify(STATE.settings));
      await WorkspaceDB.clearWorkspace();
    } catch (_) {}

    updateLocalWorkspaceUI();
    showToast('Akses direktori lokal telah diputuskan.');
    AudioEngine.click();
  }

  function updateLocalWorkspaceUI() {
    const isSupported = isDesktopFileSystemSupported();
    const isEnabled = Boolean(STATE.localWorkspace.enabled);
    const hasFiles = STATE.localWorkspace.files && STATE.localWorkspace.files.length > 0;
    const dirName = STATE.localWorkspace.dirName || 'Belum Ada Direktori Terhubung';
    const totalCount = STATE.localWorkspace.files ? STATE.localWorkspace.files.length : 0;
    let totalSize = 0;
    if (STATE.localWorkspace.files) {
      STATE.localWorkspace.files.forEach(f => { totalSize += (f.size || 0); });
    }

    if (els.settingLocalWorkspaceToggle) {
      els.settingLocalWorkspaceToggle.checked = isEnabled;
    }

    if (els.workspacePlatformBadge) {
      if (STATE.localWorkspace.platform === 'server-fs') {
        els.workspacePlatformBadge.innerHTML = '<i class="fa-solid fa-bolt"></i> Server Proyek / Mode Claude Code';
        els.workspacePlatformBadge.style.color = '#38bdf8';
        els.workspacePlatformBadge.style.borderColor = 'rgba(56, 189, 248, 0.4)';
      } else if (isSupported) {
        els.workspacePlatformBadge.innerHTML = '<i class="fa-solid fa-laptop"></i> Laptop / Native File System';
        els.workspacePlatformBadge.style.color = 'var(--neon-cyan)';
        els.workspacePlatformBadge.style.borderColor = 'rgba(0, 240, 255, 0.4)';
      } else {
        els.workspacePlatformBadge.innerHTML = '<i class="fa-solid fa-mobile-screen"></i> Ponsel / Browser Mobile Storage';
        els.workspacePlatformBadge.style.color = 'var(--neon-teal)';
        els.workspacePlatformBadge.style.borderColor = 'rgba(0, 255, 194, 0.4)';
      }
    }

    if (els.workspaceConnectedDirName) {
      els.workspaceConnectedDirName.textContent = isEnabled && STATE.localWorkspace.dirName
        ? `📁 ${STATE.localWorkspace.dirName}`
        : 'Belum Ada Direktori Terhubung';
    }
    if (els.workspaceConnectedDirDetails) {
      let platformModeText = 'Virtual Storage HP';
      if (STATE.localWorkspace.platform === 'server-fs') {
        platformModeText = 'Claude Code Live Disk I/O (Tanpa Unduh)';
      } else if (STATE.localWorkspace.platform === 'desktop-fs') {
        platformModeText = 'Akses Langsung Hard Disk Laptop (Tanpa Unduh)';
      }
      els.workspaceConnectedDirDetails.textContent = isEnabled && STATE.localWorkspace.dirName
        ? `${totalCount} berkas terdeteksi • Total ukuran: ${formatBytes(totalSize)} • Mode: ${platformModeText}`
        : 'Pilih folder dari HP atau laptop Anda untuk mulai dikelola AI';
    }

    if (els.btnRefreshLocalWorkspace) {
      els.btnRefreshLocalWorkspace.style.display = (isEnabled && STATE.localWorkspace.dirName) ? 'inline-flex' : 'none';
    }
    if (els.btnDisconnectLocalWorkspace) {
      els.btnDisconnectLocalWorkspace.style.display = (isEnabled && STATE.localWorkspace.dirName) ? 'inline-flex' : 'none';
    }
    if (els.btnSelectLocalWorkspaceText) {
      els.btnSelectLocalWorkspaceText.textContent = (isEnabled && STATE.localWorkspace.dirName)
        ? 'Ganti Direktori'
        : 'Pilih / Hubungkan Folder';
    }

    if (els.workspaceFileExplorerCard) {
      els.workspaceFileExplorerCard.style.display = (isEnabled && hasFiles) ? 'block' : 'none';
    }
    if (els.workspaceFileCount) {
      els.workspaceFileCount.textContent = String(totalCount);
    }

    if (els.workspaceComposerPill) {
      els.workspaceComposerPill.style.display = (isEnabled && STATE.localWorkspace.dirName) ? 'flex' : 'none';
    }
    if (els.workspaceComposerPillName) {
      els.workspaceComposerPillName.textContent = `Direktori: ${dirName}`;
    }
    if (els.workspaceComposerPillBadge) {
      els.workspaceComposerPillBadge.textContent = `${totalCount} berkas`;
    }

    if (els.attachWorkspaceDesc) {
      els.attachWorkspaceDesc.textContent = (isEnabled && STATE.localWorkspace.dirName)
        ? `Terhubung: ${dirName} (${totalCount} berkas)`
        : 'Hubungkan folder HP/Laptop untuk dikelola AI';
    }

    renderWorkspaceFileList();
  }

  // ==================== FILE SNAPSHOTS & ROLLBACK ENGINE (v257) ====================
  function getWorkspaceSnapshotStorageKey() {
    const dir = STATE.localWorkspace.dirName || 'global_workspace';
    return `zoz_workspace_snapshots_${encodeURIComponent(dir)}`;
  }

  function loadWorkspaceSnapshots() {
    try {
      const key = getWorkspaceSnapshotStorageKey();
      const raw = localStorage.getItem(key);
      if (raw) {
        STATE.localWorkspace.snapshots = JSON.parse(raw) || {};
      } else {
        STATE.localWorkspace.snapshots = {};
      }
    } catch (_) {
      STATE.localWorkspace.snapshots = {};
    }
  }

  function saveWorkspaceSnapshotsToStorage() {
    try {
      const key = getWorkspaceSnapshotStorageKey();
      localStorage.setItem(key, JSON.stringify(STATE.localWorkspace.snapshots || {}));
    } catch (_) {}
  }

  function captureFileSnapshot(fileName, content, author = 'ai', note = '') {
    if (!STATE.localWorkspace.enableSnapshots) return;
    if (!fileName || typeof content !== 'string') return;
    if (!STATE.localWorkspace.snapshots) STATE.localWorkspace.snapshots = {};
    if (!Array.isArray(STATE.localWorkspace.snapshots[fileName])) {
      STATE.localWorkspace.snapshots[fileName] = [];
    }
    const list = STATE.localWorkspace.snapshots[fileName];
    const versionNum = list.length + 1;
    const snap = {
      id: `snap_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
      version: versionNum,
      timestamp: Date.now(),
      content: content,
      size: new Blob([content]).size,
      author: author || 'ai',
      note: note || (author === 'ai' ? 'Disimpan oleh AI' : 'Versi cadangan pengguna')
    };
    list.unshift(snap);
    // Maksimal simpan 20 versi per berkas
    if (list.length > 20) list.pop();
    saveWorkspaceSnapshotsToStorage();
    renderWorkspaceFileList();
  }

  async function rollbackFileSnapshot(fileName, snapshotId) {
    const list = (STATE.localWorkspace.snapshots && STATE.localWorkspace.snapshots[fileName]) || [];
    const snap = list.find(s => s.id === snapshotId);
    if (!snap) {
      showToast('Snapshot tidak ditemukan.', 'error');
      return;
    }
    if (!confirm(`Kembalikan berkas "${fileName}" ke Versi ${snap.version} (${new Date(snap.timestamp).toLocaleString()})?`)) {
      return;
    }
    const currentFile = (STATE.localWorkspace.files || []).find(f => f.name === fileName);
    if (currentFile && currentFile.content) {
      captureFileSnapshot(fileName, currentFile.content, 'user', `Sebelum rollback ke v${snap.version}`);
    }
    await createWorkspaceDocument(fileName, snap.content, { silent: true, isRollback: true });
    showToast(`🔄 Berkas "${fileName}" berhasil di-rollback ke Versi ${snap.version}!`);
    AudioEngine.success();
    if (STATE.localWorkspace.activeViewFile && STATE.localWorkspace.activeViewFile.name === fileName) {
      STATE.localWorkspace.activeViewFile.content = snap.content;
      if (els.workspaceDocViewerContent) els.workspaceDocViewerContent.textContent = snap.content;
      renderDocViewerSnapshots(fileName);
    }
  }

  function renderDocViewerSnapshots(fileName) {
    if (!els.workspaceDocSnapshotsList) return;
    const list = (STATE.localWorkspace.snapshots && STATE.localWorkspace.snapshots[fileName]) || [];
    if (els.docViewerSnapshotCount) {
      els.docViewerSnapshotCount.textContent = String(list.length);
    }
    if (list.length === 0) {
      els.workspaceDocSnapshotsList.innerHTML = `<div class="snapshot-empty">Belum ada riwayat snapshot untuk berkas ini. Snapshot otomatis dibuat saat berkas diubah atau ditimpa.</div>`;
      return;
    }
    let html = '';
    list.forEach(s => {
      const timeStr = new Date(s.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }) + ' ' + new Date(s.timestamp).toLocaleDateString();
      const authorBadge = s.author === 'ai' ? '🤖 AI' : '👤 Pengguna';
      html += `
        <div class="snapshot-item" data-id="${s.id}">
          <div class="snapshot-item-left">
            <span class="snapshot-version-tag">v${s.version}</span>
            <span class="snapshot-author">${authorBadge}</span>
            <span class="snapshot-time">${timeStr} • ${formatBytes(s.size)}</span>
          </div>
          <div class="snapshot-actions">
            <button type="button" class="btn btn-xs btn-outline btn-preview-snapshot" data-name="${escapeHtml(fileName)}" data-id="${s.id}" title="Pratinjau versi ini di editor">
              <i class="fa-solid fa-eye"></i> Pratinjau
            </button>
            <button type="button" class="btn btn-xs btn-primary-neon btn-rollback-snapshot" data-name="${escapeHtml(fileName)}" data-id="${s.id}" title="Kembalikan file ke versi ini">
              <i class="fa-solid fa-clock-rotate-left"></i> Rollback
            </button>
          </div>
        </div>
      `;
    });
    els.workspaceDocSnapshotsList.innerHTML = html;
  }

  // ==================== INTERACTIVE TASK TRACKER ENGINE (v257-v259) ====================
  function getTaskTrackerDirective() {
    return `[INTERACTIVE TASK TRACKER PROTOCOL]
Jika pengguna meminta tugas kompleks, pengerjaan bertahap, analisis dokumen, atau pembuatan/modifikasi berkas direktori lokal, Anda DAPAT menyertakan daftar subtask di awal respons dengan format terstruktur berikut:

<<<ZOZ_TASKS>>>
[
  {"id":"1", "subject":"Periksa berkas direktori lokal", "status":"completed", "activeForm":"Selesai memeriksa"},
  {"id":"2", "subject":"Analisis dan modifikasi kode", "status":"completed", "activeForm":"Selesai memodifikasi"},
  {"id":"3", "subject":"Simpan perubahan ke direktori lokal", "status":"waiting_approval", "activeForm":"Menunggu izin pengguna"}
]
<<<END_ZOZ_TASKS>>>

Aturan:
- status WAJIB salah satu dari: "pending", "in_progress", "completed", atau "waiting_approval" (khusus subtask yang menyimpan/menimpa berkas ke direktori lokal pengguna agar pengguna dapat menyetujui lewat tombol persetujuan).
- Setiap task memiliki id unik, subject ringkas, dan activeForm jelas.
- Sistem Zoz Router akan menampilkan checklist visual interaktif real-time di antarmuka pengguna lengkap dengan tombol persetujuan interaktif!`;
  }

  function parseAiTasksBlock(text) {
    if (!text || typeof text !== 'string') return null;
    const startIdx = text.indexOf('<<<ZOZ_TASKS>>>');
    if (startIdx === -1) return null;
    const endIdx = text.indexOf('<<<END_ZOZ_TASKS>>>', startIdx);
    if (endIdx === -1) return null;
    const jsonStr = text.slice(startIdx + '<<<ZOZ_TASKS>>>'.length, endIdx).trim();
    try {
      const parsed = JSON.parse(jsonStr);
      if (Array.isArray(parsed) && parsed.length > 0) {
        return parsed.map((t, idx) => ({
          id: String(t.id || idx + 1),
          subject: String(t.subject || t.title || 'Tugas ' + (idx + 1)),
          status: ['completed', 'in_progress', 'pending', 'waiting_approval'].includes(t.status) ? t.status : 'pending',
          activeForm: String(t.activeForm || ''),
          description: String(t.description || ''),
          fileName: t.fileName ? String(t.fileName) : undefined
        }));
      }
    } catch (_) {}
    return null;
  }

  function setTaskTrackerTasks(newTasks) {
    if (!Array.isArray(newTasks)) return;
    STATE.taskTracker.tasks = newTasks;
    STATE.taskTracker.visible = true;
    renderTaskTrackerUI();
  }

  function toggleTaskStatus(taskId) {
    const task = (STATE.taskTracker.tasks || []).find(t => t.id === taskId);
    if (!task) return;
    if (task.status === 'waiting_approval') {
      approveWorkspacePendingChange(task.fileName || task.id);
      return;
    }
    if (task.status === 'completed') {
      task.status = 'pending';
      task.activeForm = 'Menunggu';
    } else if (task.status === 'pending') {
      task.status = 'in_progress';
      task.activeForm = 'Sedang dikerjakan...';
    } else {
      task.status = 'completed';
      task.activeForm = 'Selesai';
    }
    renderTaskTrackerUI();
    AudioEngine.click();
  }

  function deleteTask(taskId) {
    const idx = (STATE.taskTracker.tasks || []).findIndex(t => t.id === taskId);
    if (idx >= 0) {
      STATE.taskTracker.tasks.splice(idx, 1);
      renderTaskTrackerUI();
      AudioEngine.click();
    }
  }

  function renderTaskTrackerUI() {
    const tasks = STATE.taskTracker.tasks || [];
    const isVisible = Boolean(STATE.taskTracker.visible && tasks.length > 0);

    if (els.taskTrackerCard) {
      els.taskTrackerCard.style.display = isVisible ? 'block' : 'none';
    }

    if (!isVisible) return;

    const total = tasks.length;
    const completed = tasks.filter(t => t.status === 'completed').length;
    const pct = total > 0 ? Math.round((completed / total) * 100) : 0;

    if (els.taskTrackerProgressBadge) {
      els.taskTrackerProgressBadge.textContent = `${completed}/${total} Selesai (${pct}%)`;
    }
    if (els.taskTrackerProgressFill) {
      els.taskTrackerProgressFill.style.width = `${pct}%`;
    }

    if (els.taskTrackerBody) {
      els.taskTrackerBody.style.display = STATE.taskTracker.isExpanded !== false ? 'block' : 'none';
    }
    if (els.btnTaskTrackerToggleExpand) {
      els.btnTaskTrackerToggleExpand.innerHTML = STATE.taskTracker.isExpanded !== false
        ? '<i class="fa-solid fa-chevron-up"></i>'
        : '<i class="fa-solid fa-chevron-down"></i>';
    }

    if (!els.taskTrackerList) return;

    let html = '';
    tasks.forEach(t => {
      let icon = 'fa-regular fa-circle';
      if (t.status === 'completed') icon = 'fa-solid fa-circle-check';
      else if (t.status === 'in_progress') icon = 'fa-solid fa-circle-notch fa-spin';
      else if (t.status === 'waiting_approval') icon = 'fa-solid fa-shield-halved';

      const isWaitingApproval = t.status === 'waiting_approval';
      const waitTag = isWaitingApproval
        ? `<span class="task-active-form approval-wait-tag"><i class="fa-solid fa-hourglass-half"></i> ${escapeHtml(t.activeForm || 'Menunggu Izin Pengguna...')}</span>`
        : '';
      const inProgTag = (t.status === 'in_progress' && t.activeForm)
        ? `<span class="task-active-form"><i class="fa-solid fa-bolt"></i> ${escapeHtml(t.activeForm)}</span>`
        : '';

      const approvalActions = isWaitingApproval
        ? `<div class="task-approval-actions">
            <button type="button" class="btn btn-xs btn-approval-allow" data-task-id="${escapeHtml(t.id)}" data-file-name="${escapeHtml(t.fileName || '')}">
              <i class="fa-solid fa-check"></i> Izinkan & Simpan
            </button>
            <button type="button" class="btn btn-xs btn-approval-reject" data-task-id="${escapeHtml(t.id)}" data-file-name="${escapeHtml(t.fileName || '')}">
              <i class="fa-solid fa-xmark"></i> Tolak
            </button>
          </div>`
        : '';

      html += `
        <div class="task-tracker-item status-${t.status}" data-id="${escapeHtml(t.id)}">
          <button type="button" class="task-status-btn" data-id="${escapeHtml(t.id)}" title="${isWaitingApproval ? 'Klik untuk izinkan & simpan tugas ini' : 'Klik untuk ubah status tugas'}">
            <i class="${icon}"></i>
          </button>
          <div class="task-item-content">
            <span class="task-subject">${escapeHtml(t.subject)}</span>
            ${waitTag}
            ${inProgTag}
            ${approvalActions}
          </div>
          <button type="button" class="task-delete-btn" data-id="${escapeHtml(t.id)}" title="Hapus tugas">
            <i class="fa-solid fa-xmark"></i>
          </button>
        </div>
      `;
    });

    els.taskTrackerList.innerHTML = html;
  }

  // ==================== WORKSPACE USER APPROVAL ENGINE (v259) ====================
  async function approveWorkspacePendingChange(fileNameOrTaskId, fallbackFileObj = null) {
    if (!fileNameOrTaskId && !fallbackFileObj) return;
    let targetKey = null;
    let pending = null;

    if (fileNameOrTaskId && STATE.localWorkspace.pendingChanges && STATE.localWorkspace.pendingChanges[fileNameOrTaskId]) {
      targetKey = fileNameOrTaskId;
      pending = STATE.localWorkspace.pendingChanges[fileNameOrTaskId];
    } else if (fileNameOrTaskId && STATE.localWorkspace.pendingChanges) {
      for (const [k, v] of Object.entries(STATE.localWorkspace.pendingChanges)) {
        if (v.taskId === fileNameOrTaskId || v.name === fileNameOrTaskId || v.path === fileNameOrTaskId || k === fileNameOrTaskId) {
          targetKey = k;
          pending = v;
          break;
        }
      }
    }

    if (!pending && STATE.taskTracker.tasks && fileNameOrTaskId) {
      const task = STATE.taskTracker.tasks.find(t => t.id === fileNameOrTaskId);
      if (task && task.fileName && STATE.localWorkspace.pendingChanges && STATE.localWorkspace.pendingChanges[task.fileName]) {
        targetKey = task.fileName;
        pending = STATE.localWorkspace.pendingChanges[task.fileName];
      }
    }

    // FALLBACK CERDAS: Jika pending tidak ada di memori (misal riwayat/refresh), gunakan objek berkas dari kartu obrolan
    if (!pending && fallbackFileObj) {
      pending = {
        name: fallbackFileObj.name,
        path: fallbackFileObj.path || fallbackFileObj.name,
        content: fallbackFileObj.rawContent || fallbackFileObj.content || '',
        author: 'ai',
        isEdit: Boolean(fallbackFileObj.isEdit || findWorkspaceFile(fallbackFileObj.name)),
        note: 'Disetujui pengguna via kartu obrolan'
      };
      targetKey = fallbackFileObj.name;
    }

    if (!pending) {
      showToast(`Tidak ada perubahan tertunda untuk "${fileNameOrTaskId}".`, 'info');
      return;
    }

    const saveName = pending.path || pending.name;
    const isEdit = Boolean(pending.isEdit || findWorkspaceFile(pending.name) || findWorkspaceFile(pending.path));
    try {
      await createWorkspaceDocument(saveName, pending.content, {
        silent: false,
        author: pending.author || 'ai',
        note: pending.note || (isEdit ? 'Modifikasi berkas via Task Tracker' : 'Disetujui pengguna via Task Tracker'),
        isEdit: isEdit
      });

      // Hapus dari pendingChanges
      if (targetKey && STATE.localWorkspace.pendingChanges) {
        delete STATE.localWorkspace.pendingChanges[targetKey];
      }
      if (pending.name && STATE.localWorkspace.pendingChanges) {
        delete STATE.localWorkspace.pendingChanges[pending.name];
      }

      // Perbarui Task Tracker AI
      if (STATE.taskTracker.tasks) {
        STATE.taskTracker.tasks.forEach(t => {
          if (t.id === pending.taskId || t.fileName === pending.name || (t.status === 'waiting_approval' && t.subject.includes(pending.name))) {
            t.status = 'completed';
            t.activeForm = isEdit ? 'Selesai Dimodifikasi' : 'Disetujui & Disimpan';
          }
        });
        renderTaskTrackerUI();
      }

      // Perbarui visual kartu berkas di gelembung obrolan
      document.querySelectorAll('.ai-file-card').forEach(card => {
        if (card._aiFile && (card._aiFile.name === pending.name || card._aiFile.name === targetKey)) {
          card._aiFile.pendingApproval = false;
          card._aiFile.isEdit = isEdit;
          const badge = card.querySelector('.file-approval-pending-tag');
          if (badge) {
            badge.className = isEdit ? 'file-workspace-tag file-edited-tag' : 'file-workspace-tag';
            badge.innerHTML = isEdit
              ? '<i class="fa-solid fa-folder-check"></i> Berkas Direktori Telah Diperbarui'
              : '<i class="fa-solid fa-folder-check"></i> Direktori Lokal';
          }
          const allowBtn = card.querySelector('.ai-file-btn.allow-pending');
          if (allowBtn) {
            allowBtn.remove();
          }
          const actions = card.querySelector('.ai-file-actions');
          if (actions && !actions.querySelector('.open-workspace-doc')) {
            const openBtn = document.createElement('button');
            openBtn.className = 'ai-file-btn open-workspace-doc';
            openBtn.type = 'button';
            openBtn.dataset.act = 'open-workspace-doc';
            openBtn.dataset.name = pending.name;
            openBtn.innerHTML = '<i class="fa-solid fa-folder-open"></i> Buka di Direktori';
            actions.appendChild(openBtn);
          }
        }
      });

      showToast(isEdit ? `✅ Berkas "${pending.name}" berhasil diedit dan diperbarui di direktori!` : `✅ Perubahan "${pending.name}" berhasil diizinkan dan disimpan ke direktori lokal!`);
      AudioEngine.success();
    } catch (err) {
      console.error('Gagal menyetujui perubahan workspace:', err);
      showToast(`Gagal menyimpan perubahan: ${err.message}`, 'error');
    }
  }

  function rejectWorkspacePendingChange(fileNameOrTaskId) {
    if (!fileNameOrTaskId) return;
    let targetKey = null;
    let pending = null;

    if (STATE.localWorkspace.pendingChanges && STATE.localWorkspace.pendingChanges[fileNameOrTaskId]) {
      targetKey = fileNameOrTaskId;
      pending = STATE.localWorkspace.pendingChanges[fileNameOrTaskId];
    } else if (STATE.localWorkspace.pendingChanges) {
      for (const [k, v] of Object.entries(STATE.localWorkspace.pendingChanges)) {
        if (v.taskId === fileNameOrTaskId || v.name === fileNameOrTaskId || v.path === fileNameOrTaskId || k === fileNameOrTaskId) {
          targetKey = k;
          pending = v;
          break;
        }
      }
    }

    const fileName = pending ? pending.name : fileNameOrTaskId;

    if (targetKey && STATE.localWorkspace.pendingChanges) {
      delete STATE.localWorkspace.pendingChanges[targetKey];
    }
    if (pending && pending.name && STATE.localWorkspace.pendingChanges) {
      delete STATE.localWorkspace.pendingChanges[pending.name];
    }

    // Perbarui status task di Task Tracker
    if (STATE.taskTracker.tasks) {
      STATE.taskTracker.tasks.forEach(t => {
        if (t.id === (pending && pending.taskId) || t.fileName === fileName || (t.status === 'waiting_approval' && t.subject.includes(fileName))) {
          t.status = 'pending';
          t.activeForm = 'Ditolak oleh pengguna';
        }
      });
      renderTaskTrackerUI();
    }

    // Perbarui kartu berkas di gelembung obrolan
    document.querySelectorAll('.ai-file-card').forEach(card => {
      if (card._aiFile && (card._aiFile.name === fileName || card._aiFile.name === targetKey)) {
        card._aiFile.pendingApproval = false;
        const badge = card.querySelector('.file-approval-pending-tag');
        if (badge) {
          badge.className = 'file-workspace-tag';
          badge.style.background = 'rgba(239, 68, 68, 0.15)';
          badge.style.color = '#ef4444';
          badge.style.borderColor = 'rgba(239, 68, 68, 0.4)';
          badge.innerHTML = '<i class="fa-solid fa-ban"></i> Ditolak Pengguna';
        }
        const allowBtn = card.querySelector('.ai-file-btn.allow-pending');
        if (allowBtn) {
          allowBtn.remove();
        }
      }
    });

    showToast(`❌ Perubahan pada "${fileName}" dibatalkan tanpa menyentuh disk.`);
    AudioEngine.click();
  }

  function renderWorkspaceFileList() {
    if (!els.workspaceFileList) return;
    const files = STATE.localWorkspace.files || [];
    const filter = (STATE.localWorkspace.activeFilter || '').toLowerCase().trim();

    const filtered = filter
      ? files.filter(f => (f.name && f.name.toLowerCase().includes(filter)) || (f.path && f.path.toLowerCase().includes(filter)))
      : files;

    if (filtered.length === 0) {
      els.workspaceFileList.innerHTML = filter
        ? `<div class="workspace-empty-list">Tidak ada berkas yang cocok dengan "${escapeHtml(filter)}".</div>`
        : `<div class="workspace-empty-list">Tidak ada berkas di dalam direktori ini.</div>`;
      return;
    }

    let html = '';
    filtered.forEach((file, index) => {
      const iconCls = getFileIconClass(file.name);
      const sizeStr = formatBytes(file.size);
      const displayPath = file.path || file.name;
      const snapList = (STATE.localWorkspace.snapshots && STATE.localWorkspace.snapshots[file.name]) || [];
      const snapBadge = snapList.length > 0
        ? `<button type="button" class="file-snapshot-badge btn-workspace-view-snapshots" data-name="${escapeHtml(file.name)}" title="Tersedia ${snapList.length} versi cadangan. Klik untuk buka"><i class="fa-solid fa-clock-rotate-left"></i> ${snapList.length} versi</button>`
        : '';
      html += `
        <div class="workspace-file-item" data-index="${index}">
          <div class="workspace-file-item-left">
            <i class="${iconCls}"></i>
            <div class="file-item-meta">
              <div class="file-item-name" title="${escapeHtml(displayPath)}">${escapeHtml(file.name)} ${snapBadge}</div>
              <div class="file-item-sub">${escapeHtml(displayPath !== file.name ? displayPath : '')} • ${sizeStr}</div>
            </div>
          </div>
          <div class="workspace-file-item-actions">
            <button type="button" class="btn btn-xs btn-outline btn-workspace-view-file" data-name="${escapeHtml(file.name)}" title="Pratinjau Dokumen">
              <i class="fa-solid fa-eye"></i>
            </button>
            <button type="button" class="btn btn-xs btn-outline btn-workspace-edit-file" data-name="${escapeHtml(file.name)}" title="Edit Berkas Langsung">
              <i class="fa-solid fa-pen-to-square"></i>
            </button>
            <button type="button" class="btn btn-xs btn-outline btn-workspace-download-file" data-name="${escapeHtml(file.name)}" title="Unduh Berkas">
              <i class="fa-solid fa-download"></i>
            </button>
            <button type="button" class="btn btn-xs btn-outline btn-danger-hover btn-workspace-delete-file" data-name="${escapeHtml(file.name)}" title="Hapus Berkas">
              <i class="fa-solid fa-trash-can"></i>
            </button>
          </div>
        </div>
      `;
    });

    els.workspaceFileList.innerHTML = html;
  }

  function setDocViewerEditMode(isEditing) {
    if (!els.workspaceDocViewerContent || !els.workspaceDocViewerEditor) return;
    if (isEditing) {
      els.workspaceDocViewerContent.style.display = 'none';
      els.workspaceDocViewerEditor.style.display = 'block';
      if (els.btnSaveDocViewerContent) els.btnSaveDocViewerContent.style.display = 'inline-flex';
      if (els.btnEditDocViewerContent) {
        els.btnEditDocViewerContent.innerHTML = '<i class="fa-solid fa-eye"></i> Mode Pratinjau';
      }
      els.workspaceDocViewerEditor.focus();
    } else {
      els.workspaceDocViewerContent.style.display = 'block';
      els.workspaceDocViewerEditor.style.display = 'none';
      if (els.btnSaveDocViewerContent) els.btnSaveDocViewerContent.style.display = 'none';
      if (els.btnEditDocViewerContent) {
        els.btnEditDocViewerContent.innerHTML = '<i class="fa-solid fa-pen-to-square"></i> Edit Berkas';
      }
    }
  }

  async function resolveFileHandleFromPath(rootDirHandle, fullPath, create = true) {
    const normalized = fullPath.replace(/^[./\\]+/, '').trim();
    const parts = normalized.split(/[/\\]/);
    const fileName = parts.pop();
    let current = rootDirHandle;
    for (const part of parts) {
      if (!part || part === '.') continue;
      current = await current.getDirectoryHandle(part, { create: !!create });
    }
    return await current.getFileHandle(fileName, { create: !!create });
  }

  async function removeFileFromWorkspaceHandle(rootDirHandle, fullPath) {
    const normalized = fullPath.replace(/^[./\\]+/, '').trim();
    const parts = normalized.split(/[/\\]/);
    const fileName = parts.pop();
    let current = rootDirHandle;
    for (const part of parts) {
      if (!part || part === '.') continue;
      current = await current.getDirectoryHandle(part, { create: false });
    }
    await current.removeEntry(fileName);
  }

  async function previewWorkspaceDocument(fileName, startInEditMode = false) {
    const fileObj = (STATE.localWorkspace.files || []).find(f => f.name === fileName || f.path === fileName);
    if (!fileObj) {
      showToast(`Berkas "${fileName}" tidak ditemukan.`);
      return;
    }

    let textContent = fileObj.content || '';
    if (!textContent) {
      showToast('Membaca isi berkas...');
      try {
        let rawFile = fileObj.rawFile;
        if (!rawFile && fileObj.handle) {
          rawFile = await fileObj.handle.getFile();
        }
        if (rawFile) {
          textContent = await extractFileContent(rawFile);
          fileObj.content = textContent;
        } else {
          textContent = '[Konten file tidak dapat dibaca atau file kosong]';
        }
      } catch (readErr) {
        textContent = `[Gagal membaca file: ${readErr.message}]`;
      }
    }

    STATE.localWorkspace.activeViewFile = { ...fileObj, content: textContent };

    if (els.workspaceDocViewerTitle) els.workspaceDocViewerTitle.textContent = fileObj.name;
    if (els.docViewerPath) els.docViewerPath.textContent = fileObj.path || fileObj.name;
    if (els.docViewerSize) els.docViewerSize.textContent = formatBytes(fileObj.size);
    if (els.workspaceDocViewerContent) els.workspaceDocViewerContent.textContent = textContent;
    if (els.workspaceDocViewerEditor) els.workspaceDocViewerEditor.value = textContent;

    setDocViewerEditMode(startInEditMode);

    // Render snapshot history
    renderDocViewerSnapshots(fileObj.name);
    if (els.workspaceDocSnapshotsPanel) {
      els.workspaceDocSnapshotsPanel.style.display = 'none';
    }

    openModal('workspaceDocViewerModal');
    AudioEngine.click();
  }

  async function createWorkspaceDocument(fileName, content, options = {}) {
    if (!fileName) return;
    const cleanName = fileName.trim();
    const cleanContent = content || '';
    const normalizedPath = cleanName.replace(/^[./\\]+/, '');
    const parts = normalizedPath.split(/[/\\]/);
    const baseFileName = parts[parts.length - 1];
    const isDocx = baseFileName.toLowerCase().endsWith('.docx');
    const isPdf = baseFileName.toLowerCase().endsWith('.pdf');

    let binaryBlob = null;
    let base64Payload = null;

    if (isDocx) {
      try {
        binaryBlob = await compileMarkdownToDocxBlob(cleanContent, baseFileName);
        base64Payload = await blobToBase64(binaryBlob);
      } catch (compileErr) {
        console.warn('Gagal kompilasi DOCX blob:', compileErr);
      }
    } else if (isPdf) {
      try {
        binaryBlob = await compileMarkdownToPdfBlob(cleanContent, baseFileName);
        base64Payload = await blobToBase64(binaryBlob);
      } catch (compileErr) {
        console.warn('Gagal kompilasi PDF blob:', compileErr);
      }
    }

    const existingFile = findWorkspaceFile(cleanName) || findWorkspaceFile(normalizedPath) || findWorkspaceFile(baseFileName);
    const isEdit = Boolean(options.isEdit || existingFile);

    // FITUR 2: Snapshot & Rollback Berkas
    if (!options.isRollback && STATE.localWorkspace.enableSnapshots && existingFile) {
      let prevContent = existingFile.content;
      if (!prevContent && existingFile.rawFile) {
        try { prevContent = await extractFileContent(existingFile.rawFile); } catch (_) {}
      }
      if (prevContent) {
        captureFileSnapshot(existingFile.name, prevContent, options.author || 'ai', options.note || (isEdit ? 'Sebelum modifikasi berkas' : 'Sebelum pembaruan dokumen'));
      }
    }

    try {
      // 1. CLAUDE-CODE PARITY: Tulis Langsung ke Disk Fisik Server Proyek jika Backend Tersedia
      if (STATE.localWorkspace.platform === 'server-fs' || (ServerWorkspaceAPI && ServerWorkspaceAPI.isAvailable)) {
        try {
          const writeContent = base64Payload || cleanContent;
          const writeEncoding = base64Payload ? 'base64' : 'utf8';
          const res = await ServerWorkspaceAPI.writeFile(normalizedPath, writeContent, options.note || (isEdit ? 'Modifikasi berkas oleh AI' : 'Dokumen baru'), writeEncoding);
          if (res && res.success) {
            const existingIdx = (STATE.localWorkspace.files || []).findIndex(f =>
              f.name === cleanName || f.path === cleanName || f.name === baseFileName || f.path === normalizedPath
            );
            const newEntry = {
              name: baseFileName,
              path: normalizedPath,
              size: res.size || (binaryBlob ? binaryBlob.size : cleanContent.length),
              type: isDocx ? 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' : (isPdf ? 'application/pdf' : 'text/plain'),
              lastModified: res.lastModified || Date.now(),
              handle: null,
              rawFile: binaryBlob ? new File([binaryBlob], baseFileName, { type: binaryBlob.type }) : null,
              content: cleanContent
            };
            if (existingIdx >= 0) {
              STATE.localWorkspace.files[existingIdx] = newEntry;
            } else {
              STATE.localWorkspace.files.unshift(newEntry);
            }
            if (STATE.localWorkspace.activeViewFile && (STATE.localWorkspace.activeViewFile.name === baseFileName || STATE.localWorkspace.activeViewFile.path === normalizedPath)) {
              STATE.localWorkspace.activeViewFile.content = cleanContent;
            }
            await WorkspaceDB.saveWorkspace(STATE.localWorkspace);
            updateLocalWorkspaceUI();
            if (!options.silent) {
              showToast(isEdit ? `✅ Berkas "${normalizedPath}" berhasil diperbarui langsung di direktori lokal tanpa unduh!` : `✅ Berkas "${normalizedPath}" berhasil disimpan langsung ke direktori lokal!`);
              AudioEngine.success();
            }
            return;
          }
        } catch (serverFsErr) {
          console.warn('Gagal menulis via Server Workspace API, beralih ke fallback:', serverFsErr);
        }
      }

      if (STATE.localWorkspace.platform === 'desktop-fs' && STATE.localWorkspace.dirHandle) {
        try {
          const fileHandle = await resolveFileHandleFromPath(STATE.localWorkspace.dirHandle, normalizedPath, true);
          const writable = await fileHandle.createWritable();
          if (binaryBlob) {
            await writable.write(binaryBlob);
          } else {
            await writable.write(cleanContent);
          }
          await writable.close();

          const newFile = await fileHandle.getFile();
          const existingIdx = (STATE.localWorkspace.files || []).findIndex(f =>
            f.name === cleanName || f.path === cleanName || f.name === baseFileName || f.path === normalizedPath
          );
          const newEntry = {
            name: baseFileName,
            path: normalizedPath,
            size: newFile.size,
            type: newFile.type || (isDocx ? 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' : (isPdf ? 'application/pdf' : 'text/plain')),
            lastModified: Date.now(),
            handle: fileHandle,
            rawFile: newFile,
            content: cleanContent
          };
          if (existingIdx >= 0) {
            STATE.localWorkspace.files[existingIdx] = newEntry;
          } else {
            STATE.localWorkspace.files.unshift(newEntry);
          }
          await WorkspaceDB.saveWorkspace(STATE.localWorkspace);
          updateLocalWorkspaceUI();
          if (!options.silent) {
            showToast(isEdit ? `✅ Berkas "${normalizedPath}" berhasil diperbarui di direktori!` : `✅ Berkas "${normalizedPath}" berhasil disimpan ke direktori lokal!`);
            AudioEngine.success();
          }
          return;
        } catch (fsErr) {
          console.warn('Gagal menulis langsung ke disk, beralih ke penyimpanan virtual:', fsErr);
        }
      }

      const blob = binaryBlob || new Blob([cleanContent], { type: 'text/plain;charset=utf-8' });
      const rawFile = new File([blob], baseFileName, { type: blob.type || 'text/plain', lastModified: Date.now() });
      const existingIdx = (STATE.localWorkspace.files || []).findIndex(f =>
        f.name === cleanName || f.path === cleanName || f.name === baseFileName || f.path === normalizedPath
      );
      const newEntry = {
        name: baseFileName,
        path: normalizedPath,
        size: blob.size,
        type: blob.type || 'text/plain',
        lastModified: Date.now(),
        handle: null,
        rawFile: rawFile,
        content: cleanContent
      };
      if (existingIdx >= 0) {
        STATE.localWorkspace.files[existingIdx] = newEntry;
      } else {
        STATE.localWorkspace.files.unshift(newEntry);
      }

      await WorkspaceDB.saveWorkspace(STATE.localWorkspace);
      updateLocalWorkspaceUI();

      // PENTING: JANGAN PERNAH MENDOWNLOAD BERKAS DUPLIKAT BARU JIKA INI MERUPAKAN MODIFIKASI BERKAS YANG SUDAH ADA!
      if (!isEdit && existingIdx < 0 && !options.noDownload) {
        downloadBlob(blob, baseFileName);
      }

      if (!options.silent) {
        if (isEdit || existingIdx >= 0) {
          showToast(`✅ Berkas "${normalizedPath}" berhasil diedit dan diperbarui di direktori!`);
        } else {
          showToast(`✅ Berkas "${normalizedPath}" dibuat dan disimpan ke direktori!`);
        }
        AudioEngine.success();
      }
    } catch (err) {
      console.error('Gagal membuat dokumen:', err);
      showToast(`Gagal membuat/mengedit dokumen: ${err.message}`, 'error');
    }
  }

  async function deleteWorkspaceDocument(fileName) {
    const idx = (STATE.localWorkspace.files || []).findIndex(f => f.name === fileName || f.path === fileName);
    if (idx < 0) return;
    const fileObj = STATE.localWorkspace.files[idx];

    if (!confirm(`Hapus berkas "${fileName}" dari direktori lokal?`)) return;

    if (STATE.localWorkspace.enableSnapshots) {
      let prevContent = fileObj.content;
      if (!prevContent && fileObj.rawFile) {
        try { prevContent = await extractFileContent(fileObj.rawFile); } catch (_) {}
      }
      if (prevContent) {
        captureFileSnapshot(fileObj.name, prevContent, 'user', 'Sebelum penghapusan berkas');
      }
    }

    try {
      if (STATE.localWorkspace.platform === 'server-fs' || (ServerWorkspaceAPI && ServerWorkspaceAPI.isAvailable)) {
        try {
          await ServerWorkspaceAPI.deleteFile(fileObj.path || fileObj.name);
        } catch (delErr) {
          console.warn('Gagal menghapus via ServerWorkspaceAPI:', delErr);
        }
      }
      if (STATE.localWorkspace.platform === 'desktop-fs' && STATE.localWorkspace.dirHandle) {
        try {
          await removeFileFromWorkspaceHandle(STATE.localWorkspace.dirHandle, fileObj.path || fileObj.name);
        } catch (delErr) {
          console.warn('Gagal menghapus via handle:', delErr);
        }
      }
      STATE.localWorkspace.files.splice(idx, 1);
      updateLocalWorkspaceUI();
      showToast(`Berkas "${fileName}" telah dihapus.`);
      AudioEngine.click();
    } catch (err) {
      showToast(`Gagal menghapus berkas: ${err.message}`, 'error');
    }
  }

  async function deleteWorkspaceDocumentSilent(fileName, options = {}) {
    const idx = (STATE.localWorkspace.files || []).findIndex(f => f.name === fileName || f.path === fileName);
    if (idx < 0) return;
    const fileObj = STATE.localWorkspace.files[idx];

    if (STATE.localWorkspace.enableSnapshots) {
      let prevContent = fileObj.content;
      if (!prevContent && fileObj.rawFile) {
        try { prevContent = await extractFileContent(fileObj.rawFile); } catch (_) {}
      }
      if (prevContent) {
        captureFileSnapshot(fileObj.name, prevContent, options.author || 'ai', options.note || 'Sebelum penghapusan oleh AI');
      }
    }

    try {
      if (STATE.localWorkspace.platform === 'server-fs' || (ServerWorkspaceAPI && ServerWorkspaceAPI.isAvailable)) {
        try {
          await ServerWorkspaceAPI.deleteFile(fileObj.path || fileObj.name);
        } catch (delErr) {
          console.warn('Gagal menghapus via ServerWorkspaceAPI:', delErr);
        }
      }
      if (STATE.localWorkspace.platform === 'desktop-fs' && STATE.localWorkspace.dirHandle) {
        try {
          await removeFileFromWorkspaceHandle(STATE.localWorkspace.dirHandle, fileObj.path || fileObj.name);
        } catch (delErr) {
          console.warn('Gagal menghapus via handle:', delErr);
        }
      }
      STATE.localWorkspace.files.splice(idx, 1);
      updateLocalWorkspaceUI();
      showToast(`🗑️ Berkas "${fileName}" telah dihapus.`);
    } catch (err) {
      console.warn('Gagal menghapus berkas silent:', err);
    }
  }

  async function exportWorkspaceAsZip() {
    if (!STATE.localWorkspace.files || STATE.localWorkspace.files.length === 0) {
      showToast('Tidak ada berkas untuk diekspor.');
      return;
    }
    if (typeof JSZip === 'undefined') {
      showToast('Pustaka JSZip belum siap.', 'error');
      return;
    }

    showToast('Mengemas seluruh berkas ke ZIP...');
    try {
      const zip = new JSZip();
      for (const item of STATE.localWorkspace.files) {
        let contentToZip = null;
        if (item.content) {
          contentToZip = item.content;
        } else if (item.rawFile) {
          contentToZip = await item.rawFile.arrayBuffer();
        } else if (item.handle) {
          const f = await item.handle.getFile();
          contentToZip = await f.arrayBuffer();
        }
        if (contentToZip !== null) {
          zip.file(item.path || item.name, contentToZip);
        }
      }

      const zipBlob = await zip.generateAsync({ type: 'blob' });
      const zipName = `${STATE.localWorkspace.dirName || 'dokumen_lokal'}_bundle.zip`;
      downloadBlob(zipBlob, zipName);
      showToast(`📦 Berhasil mengunduh "${zipName}"!`);
      AudioEngine.success();
    } catch (zipErr) {
      console.error('Gagal membuat ZIP:', zipErr);
      showToast(`Gagal membuat ZIP: ${zipErr.message}`, 'error');
    }
  }

  async function refreshLocalWorkspace() {
    if (STATE.localWorkspace.platform === 'server-fs' || (ServerWorkspaceAPI && ServerWorkspaceAPI.isAvailable)) {
      showToast('Memindai ulang direktori proyek server...');
      try {
        const files = await ServerWorkspaceAPI.getFiles();
        STATE.localWorkspace.files = files;
        await WorkspaceDB.saveWorkspace(STATE.localWorkspace);
        updateLocalWorkspaceUI();
        showToast(`Sinkronisasi selesai: ${files.length} berkas di disk proyek.`);
        AudioEngine.click();
        return;
      } catch (err) {
        console.warn('Refresh server files error:', err);
      }
    }
    if (STATE.localWorkspace.platform === 'desktop-fs' && STATE.localWorkspace.dirHandle) {
      showToast('Memindai ulang direktori lokal...');
      try {
        const files = await scanDirectoryHandle(STATE.localWorkspace.dirHandle);
        STATE.localWorkspace.files = files;
        updateLocalWorkspaceUI();
        showToast(`Sinkronisasi selesai: ${files.length} berkas.`);
        AudioEngine.click();
        return;
      } catch (err) {
        console.warn('Refresh handle error:', err);
      }
    }
    showToast('Silakan pilih folder lagi untuk memindai pembaruan berkas di HP.');
    els.btnSelectLocalWorkspace?.click();
  }

  const MUSIC_AUDIO_RE = /lyria|musicgen|suno|udio|stable-audio|gpt-audio/i;
  const DEFAULT_MUSIC_MODEL = 'google/lyria-3-clip-preview';
  function isAudioMusicModel(id) { 
    const s = String(id || '').trim();
    return s === 'off' || MUSIC_AUDIO_RE.test(s); 
  }
  function normalizeMusicModelSetting() {
    if (!STATE.settings.musicModel || !isAudioMusicModel(STATE.settings.musicModel)) {
      STATE.settings.musicModel = DEFAULT_MUSIC_MODEL;
      try { localStorage.setItem('zoz_router_settings_v1', JSON.stringify(STATE.settings)); } catch (_) {}
      if (els.settingMusicModel) els.settingMusicModel.value = DEFAULT_MUSIC_MODEL;
    }
  }

  function getMusicModelDisplayName(modelId) {
    if (!modelId || modelId === 'off') return 'Nonaktif (Mode Obrolan)';
    const foundOR = (STATE.openRouterModels || []).find(m => m.id === modelId);
    if (foundOR) return foundOR.name || foundOR.id;
    const foundCurated = CURATED_OPENROUTER_MUSIC_MODELS.find(m => m.id === modelId);
    if (foundCurated) return foundCurated.name;
    const foundOllama = (STATE.ollamaModels || []).find(m => (m.id || m.name || m.model) === modelId);
    if (foundOllama) return foundOllama.name || foundOllama.model || foundOllama.id;
    const m = String(modelId).toLowerCase();
    if (m === 'qwen2.5:1.5b') return 'Qwen 2.5 1.5B (Lokal)';
    if (m === 'llama3.2:3b') return 'Llama 3.2 3B (Lokal)';
    if (m === 'openrouter/free') return 'OpenRouter Free Auto';
    if (m.includes('/')) {
      const parts = modelId.split('/');
      return parts[1] ? parts[1].replace(/[-_]/g, ' ') : modelId;
    }
    return modelId;
  }

  function getMusicModelBadgeText(modelId) {
    if (!modelId || modelId === 'off') return 'Music';
    const m = String(modelId).toLowerCase();
    if (m.includes('qwen2.5:1.5b')) return 'Qwen 1.5B';
    if (m.includes('qwen2.5:7b') || m.includes('qwen-2.5-72b') || m.includes('qwen2.5') || m.includes('qwen')) return 'Qwen';
    if (m.includes('llama-3.3') || m.includes('llama3.3')) return 'Llama 3.3';
    if (m.includes('llama3.2:3b') || m.includes('llama3.2')) return 'Llama 3.2';
    if (m.includes('llama')) return 'Llama';
    if (m.includes('gemini-2.0') || m.includes('gemini-2') || m.includes('gemini')) return 'Gemini';
    if (m.includes('deepseek-v4') || m.includes('deepseek-r1') || m.includes('deepseek')) return 'DeepSeek';
    if (m.includes('gpt-4o')) return 'GPT-4o';
    if (m.includes('gpt-4') || m.includes('gpt-3') || m.includes('gpt')) return 'GPT';
    if (m.includes('claude-3.5') || m.includes('claude') || m.includes('haiku') || m.includes('sonnet')) return 'Claude';
    if (m.includes('mistral') || m.includes('codestral') || m.includes('mixtral')) return 'Mistral';
    if (m.includes('nemotron')) return 'Nemotron';
    if (m.includes('granite')) return 'Granite';
    if (m.includes('kimi')) return 'Kimi';
    if (m.includes('gemma')) return 'Gemma';
    if (m.includes('openrouter/free')) return 'OR Free';
    if (m.includes('/')) {
      const part = modelId.split('/')[1] || modelId;
      return part.slice(0, 10);
    }
    if (m.includes(':')) {
      return m.split(':')[0].slice(0, 10);
    }
    return modelId.slice(0, 10);
  }

  function updateMusicGenModeUI() {
    normalizeMusicModelSetting();
    const isMusicMode = Boolean(STATE.isMusicGenMode);
    const activeModel = STATE.settings.musicModel || 'google/lyria-3-clip-preview';
    const badgeText = getMusicModelBadgeText(activeModel);
    const displayName = getMusicModelDisplayName(activeModel);

    if (els.composerBox) {
      els.composerBox.classList.toggle('music-mode-active', isMusicMode);
    }
    if (els.musicGenToggleBtn) {
      els.musicGenToggleBtn.classList.toggle('active', isMusicMode);
      els.musicGenToggleBtn.setAttribute('aria-pressed', String(isMusicMode));
      els.musicGenToggleBtn.setAttribute('title', isMusicMode 
        ? `Mode Musik Aktif: ${displayName} (Klik untuk ganti model / nonaktifkan)` 
        : 'AI Music Studio - Pilih Model Musik AI');
    }
    if (els.musicModelBadge) {
      els.musicModelBadge.innerText = badgeText;
      els.musicModelBadge.style.display = isMusicMode ? 'inline-block' : 'none';
    }
    if (els.sendPromptBtn) {
      if (isMusicMode) {
        els.sendPromptBtn.setAttribute('title', `Gubah Musik dengan ${displayName} (Enter)`);
        els.sendPromptBtn.setAttribute('aria-label', `Gubah Musik dengan ${displayName} (Enter)`);
      } else if (!STATE.isImageGenMode) {
        els.sendPromptBtn.setAttribute('title', 'Kirim Prompt (Enter)');
        els.sendPromptBtn.setAttribute('aria-label', 'Kirim Prompt (Enter)');
      }
    }
    if (els.promptInput && isMusicMode) {
      els.promptInput.placeholder = `Deskripsikan musik, beat, atau melodi untuk digubah dengan ${badgeText}...`;
    } else if (els.promptInput && !STATE.isImageGenMode) {
      els.promptInput.placeholder = '';
    }
    if (els.attachOptionGenMusic) {
      els.attachOptionGenMusic.classList.toggle('active', isMusicMode);
    }
    if (els.musicModeIndicator) {
      els.musicModeIndicator.style.display = isMusicMode ? 'flex' : 'none';
      // Selalu reset ikon ke nota musik, agar tidak menyimpan ikon silang
      // sisa hover saat mode musik dinonaktifkan lalu diaktifkan kembali.
      const indicatorIcon = els.musicModeIndicator.querySelector('i');
      if (indicatorIcon) {
        indicatorIcon.className = 'fa-solid fa-music';
      }
    }

    if (els.musicGenActiveModelLabel) {
      els.musicGenActiveModelLabel.textContent = displayName;
    }
    if (els.musicGenActiveCard) {
      els.musicGenActiveCard.style.display = 'none';
    }

    // Sinkronisasi status checked pada popup modal/dropdown musik
    $$('.music-model-item').forEach(item => {
      const itemModel = item.dataset.model;
      const isSelected = isMusicMode ? (itemModel === activeModel) : (itemModel === 'off');
      item.classList.toggle('active', isSelected);
      const checkIcon = item.querySelector('.music-model-check');
      if (checkIcon) checkIcon.style.display = isSelected ? 'block' : 'none';
    });
    updateToolActiveDot();
    updateActiveModeCardsState();
  }

  function switchMusicModelTab(tabName) {
    const isOR = tabName === 'openrouter';
    if (els.tabBtnMusicOllama) els.tabBtnMusicOllama.classList.toggle('active', !isOR);
    if (els.tabBtnMusicOpenRouter) els.tabBtnMusicOpenRouter.classList.toggle('active', isOR);
    if (els.paneMusicOllama) els.paneMusicOllama.style.display = isOR ? 'none' : 'flex';
    if (els.paneMusicOpenRouter) els.paneMusicOpenRouter.style.display = isOR ? 'flex' : 'none';

    if (isOR) {
      updateMusicOpenRouterStatusBar();
      populateMusicOpenRouterModels(els.musicModelSearchInput?.value || '');
    } else {
      populateMusicOllamaModels(els.musicOllamaSearchInput?.value || '');
    }
    if (els.musicModelDropdown) {
      els.musicModelDropdown.scrollTop = 0;
    }
  }

  function updateMusicOpenRouterStatusBar() {
    if (!els.musicOpenRouterStatusBar) return;
    const hasKey = Boolean(STATE.settings.openRouterKey);
    els.musicOpenRouterStatusBar.className = `music-model-status-bar ${hasKey ? 'connected' : 'warning'}`;
    els.musicOpenRouterStatusBar.innerHTML = hasKey
      ? `<span><i class="fa-solid fa-circle-check" style="color:var(--neon-teal);"></i> API Key Terhubung • Cloud Neural Music Models Siap</span>
         <button class="status-action-btn" id="musicOpenRouterConfigBtn" type="button">Pengaturan</button>`
      : `<span><i class="fa-solid fa-circle-exclamation" style="color:var(--neon-amber);"></i> Butuh OpenRouter Key untuk cloud models</span>
         <button class="status-action-btn" id="musicOpenRouterConfigBtn" type="button">Buka Pengaturan</button>`;

    const cfgBtn = els.musicOpenRouterStatusBar.querySelector('#musicOpenRouterConfigBtn');
    cfgBtn?.addEventListener('click', (e) => {
      e.stopPropagation();
      closeMusicModelDropdown();
      const modal = $('#settingsModal');
      if (modal) {
        modal.querySelectorAll('.settings-tab-btn').forEach(btn => btn.classList.toggle('active', btn.dataset.tab === 'tabProviders'));
        modal.querySelectorAll('.settings-tab-pane').forEach(pane => pane.classList.toggle('active', pane.id === 'tabProviders'));
      }
      openModal('settingsModal');
      AudioEngine.click();
    });
  }

  function populateMusicOllamaModels(searchQuery = '') {
    if (!els.musicModelOllamaList) return;
    // Model Ollama adalah model teks: tidak bisa menghasilkan audio. Arahkan ke model musik asli.
    if (els.musicOllamaCountText) els.musicOllamaCountText.innerText = 'tidak tersedia';
    els.musicModelOllamaList.innerHTML = '<div style="padding: 18px 10px; text-align: center; color: var(--text-dim); font-size: 0.76rem; line-height: 1.55;"><i class="fa-solid fa-circle-info" style="font-size: 1.2rem; margin-bottom: 8px; display: block; color: var(--neon-amber);"></i>Model Ollama hanya menghasilkan <strong>teks</strong>, bukan suara.<br>Untuk musik AI asli, buka tab <strong>OpenRouter (Cloud)</strong> dan pilih <strong>Google Lyria 3</strong>.</div>';
    return;
  }

  function populateMusicOpenRouterModels(searchQuery = '') {
    if (!els.musicModelOpenRouterList) return;
    const q = (typeof searchQuery === 'string' ? searchQuery : (els.musicModelSearchInput?.value || '')).toLowerCase().trim();
    const activeModel = STATE.settings.musicModel || 'google/lyria-3-clip-preview';
    const isMusicMode = Boolean(STATE.isMusicGenMode);
    const cat = STATE.musicOpenRouterCatFilter || 'all';

    // Ambil seluruh model resmi yang terdaftar dari OpenRouter API (STATE.openRouterModels)
    const allModelsMap = new Map();

    // Masukkan curated rekomendasi awal sebagai base enrichment jika ada
    CURATED_OPENROUTER_MUSIC_MODELS.forEach(m => allModelsMap.set(m.id, m));

    // Masukkan SELURUH 468+ model resmi dari OpenRouter
    if (Array.isArray(STATE.openRouterModels) && STATE.openRouterModels.length > 0) {
      STATE.openRouterModels.forEach(m => {
        if (!m.hasAudioOutput && !isAudioMusicModel(m.id)) return;
        if (!allModelsMap.has(m.id)) {
          allModelsMap.set(m.id, {
            id: m.id,
            name: m.name || m.id,
            provider: 'openrouter',
            tag: m.tag || (m.id.includes(':free') ? 'Free' : 'Cloud'),
            cat: m.cat || (m.id.includes(':free') ? 'free' : 'flagship'),
            desc: m.description || m.desc || m.id
          });
        } else {
          // Merge description & name jika belum lengkap
          const existing = allModelsMap.get(m.id);
          if (m.name && (!existing.name || existing.name === existing.id)) existing.name = m.name;
          if (m.description && (!existing.desc || existing.desc === existing.id)) existing.desc = m.description;
        }
      });
    } else {
      // Pemicu fetch otomatis jika daftar belum tersedia
      fetchOpenRouterModelsList().then(() => {
        if (Array.isArray(STATE.openRouterModels) && STATE.openRouterModels.length > 0) {
          populateMusicOpenRouterModels(els.musicModelSearchInput?.value || '');
        }
      }).catch(() => {});
    }

    // Pastikan activeModel muncul jika merupakan OpenRouter model
    if (activeModel.includes('/') && !allModelsMap.has(activeModel)) {
      allModelsMap.set(activeModel, {
        id: activeModel,
        name: getMusicModelDisplayName(activeModel),
        provider: 'openrouter',
        tag: 'Cloud Model',
        cat: 'cloud',
        desc: activeModel
      });
    }

    let list = Array.from(allModelsMap.values());

    // 1. Filter Kategori Pills (Semua, Gratis, Google, OpenAI, Anthropic, Meta, DeepSeek, Qwen, Mistral)
    if (cat !== 'all') {
      list = list.filter(m => {
        const idLow = (m.id || '').toLowerCase();
        const nameLow = (m.name || '').toLowerCase();
        if (cat === 'free') {
          return idLow.includes(':free') || idLow.endsWith('/free') || idLow === 'openrouter/free' || m.tag === 'Free' || m.cat === 'free';
        }
        if (cat === 'google') {
          return idLow.includes('google') || idLow.includes('gemini') || nameLow.includes('google');
        }
        if (cat === 'openai') {
          return idLow.includes('openai') || idLow.includes('gpt') || nameLow.includes('openai');
        }
        if (cat === 'anthropic') {
          return idLow.includes('anthropic') || idLow.includes('claude') || nameLow.includes('anthropic');
        }
        if (cat === 'meta') {
          return idLow.includes('meta') || idLow.includes('llama') || nameLow.includes('meta');
        }
        if (cat === 'deepseek') {
          return idLow.includes('deepseek') || nameLow.includes('deepseek');
        }
        if (cat === 'qwen') {
          return idLow.includes('qwen') || nameLow.includes('qwen');
        }
        if (cat === 'mistral') {
          return idLow.includes('mistral') || nameLow.includes('mistral');
        }
        return true;
      });
    }

    // 2. Filter Pencarian Teks Cerdas
    if (q) {
      list = list.filter(m => 
        (m.id && m.id.toLowerCase().includes(q)) || 
        (m.name && m.name.toLowerCase().includes(q)) ||
        (m.desc && m.desc.toLowerCase().includes(q)) ||
        (m.tag && m.tag.toLowerCase().includes(q))
      );
    }

    // Perbarui counter model resmi OpenRouter
    if (els.musicOpenRouterCountText) {
      els.musicOpenRouterCountText.innerText = `${list.length} Model Resmi`;
    }

    if (list.length === 0) {
      els.musicModelOpenRouterList.innerHTML = `
        <div style="padding: 24px 8px; text-align: center; color: var(--text-dim); font-size: 0.72rem;">
          <i class="fa-solid fa-ghost" style="font-size: 1.3rem; margin-bottom: 8px; display: block; opacity: 0.5;"></i>
          Tidak ada model OpenRouter yang cocok dengan filter & kata kunci "<strong>${escapeHtml(q || cat)}</strong>"<br>
          Gunakan baris kustom di bawah untuk memasukkan ID model secara manual.
        </div>
      `;
      return;
    }

    // Batasi render DOM hingga 75 item teratas untuk menjaga responsivitas 60 FPS
    const maxRender = 75;
    const itemsToRender = list.slice(0, maxRender);
    const hasMore = list.length > maxRender;

    let itemsHtml = itemsToRender.map(m => {
      const isSelected = isMusicMode && (m.id === activeModel);
      let icon = 'fa-solid fa-cloud';
      let accentClass = 'cloud-accent';
      const idLow = m.id.toLowerCase();

      if (idLow.includes('gemini') || idLow.includes('google')) { 
        icon = 'fa-brands fa-google'; 
        accentClass = 'gemini-accent'; 
      } else if (idLow.includes('llama') || idLow.includes('meta')) { 
        icon = 'fa-solid fa-infinity'; 
        accentClass = 'llama-accent'; 
      } else if (idLow.includes('qwen')) { 
        icon = 'fa-solid fa-dragon'; 
        accentClass = 'qwen-accent'; 
      } else if (idLow.includes('deepseek')) { 
        icon = 'fa-solid fa-eye'; 
        accentClass = 'gemini-accent'; 
      } else if (idLow.includes('claude') || idLow.includes('anthropic')) { 
        icon = 'fa-solid fa-brain'; 
        accentClass = 'flux-accent'; 
      } else if (idLow.includes('gpt') || idLow.includes('openai')) { 
        icon = 'fa-solid fa-microchip'; 
        accentClass = 'cloud-accent'; 
      } else if (idLow.includes('mistral')) { 
        icon = 'fa-solid fa-wind'; 
        accentClass = 'flux-accent'; 
      } else if (idLow.includes('free')) { 
        icon = 'fa-solid fa-bolt-lightning'; 
        accentClass = 'flux-accent'; 
      }

      const isFree = idLow.includes(':free') || idLow.endsWith('/free') || idLow === 'openrouter/free' || m.tag === 'Free' || m.cat === 'free';
      const tagText = isFree ? 'Gratis' : (m.tag || 'OpenRouter');

      return `
        <button class="music-model-item ${isSelected ? 'active' : ''}" type="button" data-model="${escapeHtml(m.id)}">
          <div class="music-model-icon-box ${accentClass}">
            <i class="${icon}"></i>
          </div>
          <div class="music-model-info">
            <div class="music-model-title-row">
              <span class="music-model-title">${escapeHtml(m.name || m.id)}</span>
              <span class="music-model-tag ${isFree ? 'free-tag' : ''}">${escapeHtml(tagText)}</span>
            </div>
            <span class="music-model-desc">${escapeHtml(m.desc || m.id)}</span>
          </div>
          <i class="fa-solid fa-check music-model-check" style="${isSelected ? 'display: block;' : 'display: none;'}"></i>
        </button>
      `;
    }).join('');

    if (hasMore) {
      itemsHtml += `
        <div style="padding: 10px 8px; text-align: center; color: var(--text-dim); font-size: 0.72rem; border-top: 1px dashed var(--border-color); margin-top: 6px;">
          <i class="fa-solid fa-list-check" style="margin-right: 4px; color: var(--neon-teal);"></i>
          Menampilkan ${maxRender} dari <strong>${list.length}</strong> model resmi OpenRouter.<br>
          Ketik nama model di kotak pencarian untuk menemukan model spesifik lainnya.
        </div>
      `;
    }

    els.musicModelOpenRouterList.innerHTML = itemsHtml;

    els.musicModelOpenRouterList.querySelectorAll('.music-model-item').forEach(item => {
      item.addEventListener('click', (e) => {
        e.stopPropagation();
        const modelVal = item.dataset.model;
        if (modelVal) setMusicModel(modelVal);
      });
    });
  }

  function toggleMusicModelDropdown(e) {
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    if (!els.musicModelDropdown) return;
    const isHidden = els.musicModelDropdown.style.display === 'none' || !els.musicModelDropdown.style.display;
    if (isHidden) {
      openMusicModelDropdown();
    } else {
      closeMusicModelDropdown();
    }
  }

  function openMusicModelDropdown() {
    if (!els.musicModelDropdown) return;
    normalizeMusicModelSetting();
    closeAttachmentDropdown();
    closeSearchDropdown();
    closeImageModelDropdown();
    els.musicModelDropdown.style.display = 'flex';
    els.musicModelDropdown.scrollTop = 0;
    els.musicGenToggleBtn?.setAttribute('aria-expanded', 'true');

    // Auto-fetch model resmi OpenRouter jika belum di-cache
    if (!STATE.openRouterModels || STATE.openRouterModels.length <= 10) {
      fetchOpenRouterModelsList().then(() => {
        if (els.paneMusicOpenRouter && els.paneMusicOpenRouter.style.display !== 'none') {
          populateMusicOpenRouterModels(els.musicModelSearchInput?.value || '');
        }
      }).catch(() => {});
    }

    // Auto-fetch model resmi Ollama jika belum ada
    if (!STATE.ollamaModels || STATE.ollamaModels.length === 0) {
      checkOllamaHealth().then(() => {
        if (els.paneMusicOllama && els.paneMusicOllama.style.display !== 'none') {
          populateMusicOllamaModels(els.musicOllamaSearchInput?.value || '');
        }
      }).catch(() => {});
    }

    switchMusicModelTab('openrouter');

    AudioEngine.click();
  }

  function closeMusicModelDropdown() {
    if (!els.musicModelDropdown) return;
    els.musicModelDropdown.style.display = 'none';
    els.musicGenToggleBtn?.setAttribute('aria-expanded', 'false');
  }

  function setMusicModel(modelVal) {
    if (modelVal === 'off') {
      STATE.isMusicGenMode = false;
      updateMusicGenModeUI();
      closeMusicModelDropdown();
      AudioEngine.click();
      showToast('ℹ️ Mode AI Music Studio dinonaktifkan. Kembali ke obrolan biasa.');
      return;
    }

    STATE.settings.musicModel = modelVal;
    STATE.isMusicGenMode = true;
    STATE.isImageGenMode = false;
    try {
      localStorage.setItem('zoz_router_settings_v1', JSON.stringify(STATE.settings));
    } catch (_) {}
    if (els.settingMusicModel) {
      els.settingMusicModel.value = modelVal;
    }
    updateMusicGenModeUI();
    updateImageGenModeUI();
    closeMusicModelDropdown();
    AudioEngine.success();
    els.promptInput?.focus();
    const displayName = getMusicModelDisplayName(modelVal);
    if (modelVal.includes('/') && !STATE.settings.openRouterKey) {
      showToast(`⚠️ Model musik ${displayName} dipilih. Butuh OpenRouter Key di Pengaturan untuk memanggil cloud model.`, 'warning');
    } else {
      showToast(`🎵 Model Musik Aktif: ${displayName}`);
    }
  }

  function switchImageModelTab(tabName) {
    const isOR = tabName === 'openrouter';
    if (els.tabBtnPollinations) els.tabBtnPollinations.classList.toggle('active', !isOR);
    if (els.tabBtnOpenRouter) els.tabBtnOpenRouter.classList.toggle('active', isOR);
    if (els.panePollinations) els.panePollinations.style.display = isOR ? 'none' : 'flex';
    if (els.paneOpenRouter) els.paneOpenRouter.style.display = isOR ? 'flex' : 'none';

    if (els.imageModelDropdown) {
      els.imageModelDropdown.scrollTop = 0;
    }

    if (isOR) {
      updateImageModelStatusBar();
      populateOpenRouterImageModels(els.imageModelSearchInput?.value || '');
    }
  }

  function updateImageModelStatusBar() {
    if (!els.openRouterStatusBar) return;
    const hasKey = Boolean(STATE.settings.openRouterKey);
    els.openRouterStatusBar.className = `image-model-status-bar ${hasKey ? 'connected' : 'warning'}`;
    els.openRouterStatusBar.innerHTML = hasKey
      ? `<span><i class="fa-solid fa-circle-check" style="color:var(--neon-teal);"></i> API Key Terhubung • 59+ Cloud Image Engines</span>
         <button class="status-action-btn" id="openRouterConfigBtn" type="button">Pengaturan</button>`
      : `<span><i class="fa-solid fa-circle-exclamation" style="color:var(--neon-amber);"></i> Butuh OpenRouter Key untuk cloud models</span>
         <button class="status-action-btn" id="openRouterConfigBtn" type="button">Buka Pengaturan</button>`;

    const cfgBtn = els.openRouterStatusBar.querySelector('#openRouterConfigBtn');
    cfgBtn?.addEventListener('click', (e) => {
      e.stopPropagation();
      closeImageModelDropdown();
      const modal = $('#settingsModal');
      if (modal) {
        modal.querySelectorAll('.settings-tab-btn').forEach(btn => btn.classList.toggle('active', btn.dataset.tab === 'tabProviders'));
        modal.querySelectorAll('.settings-tab-pane').forEach(pane => pane.classList.toggle('active', pane.id === 'tabProviders'));
      }
      openModal('settingsModal');
      AudioEngine.click();
    });
  }

  function populateOpenRouterImageModels(searchQuery = '') {
    if (!els.imageModelOpenRouterList) return;
    const q = (searchQuery || '').toLowerCase().trim();
    
    // Gabungkan model terkurasi dan hasil fetch live OpenRouter
    const allModelsMap = new Map();
    CURATED_OPENROUTER_IMAGE_MODELS.forEach(m => allModelsMap.set(m.id, m));
    if (Array.isArray(STATE.availableImageModels)) {
      STATE.availableImageModels.forEach(m => {
        if (m.provider === 'openrouter' || (m.id && m.id.includes('/'))) {
          if (!allModelsMap.has(m.id)) allModelsMap.set(m.id, m);
        }
      });
    }

    // Pastikan model kustom aktif yang dipilih pengguna tetap muncul di daftar jika belum ada
    const activeModel = STATE.settings.imageModel || 'flux';
    if (activeModel.includes('/') && !allModelsMap.has(activeModel)) {
      allModelsMap.set(activeModel, {
        id: activeModel,
        name: getImageModelDisplayName(activeModel),
        provider: 'openrouter',
        cat: 'custom',
        tag: 'Custom • Cloud',
        desc: `Model Kustom OpenRouter: ${activeModel}`
      });
    }

    let list = Array.from(allModelsMap.values());
    if (q) {
      list = list.filter(m => 
        m.id.toLowerCase().includes(q) || 
        (m.name && m.name.toLowerCase().includes(q)) ||
        (m.desc && m.desc.toLowerCase().includes(q)) ||
        (m.tag && m.tag.toLowerCase().includes(q))
      );
    }

    if (list.length === 0) {
      els.imageModelOpenRouterList.innerHTML = `
        <div style="padding: 16px 8px; text-align: center; color: var(--text-dim); font-size: 0.72rem;">
          <i class="fa-solid fa-ghost" style="font-size: 1.2rem; margin-bottom: 6px; display: block; opacity: 0.5;"></i>
          Tidak ada model OpenRouter yang cocok dengan "<strong>${escapeHtml(q)}</strong>"<br>
          Gunakan baris kustom di atas untuk memasukkan model secara manual.
        </div>
      `;
      return;
    }

    const isImageMode = Boolean(STATE.isImageGenMode);

    els.imageModelOpenRouterList.innerHTML = list.map(m => {
      const isSelected = isImageMode && (m.id === activeModel);
      let icon = 'fa-cloud';
      let accentClass = 'cloud-accent';
      const idLow = m.id.toLowerCase();
      if (idLow.includes('flux')) { icon = 'fa-bolt-lightning'; accentClass = 'flux-accent'; }
      else if (idLow.includes('gemini')) { icon = 'fa-brands fa-google'; accentClass = 'realism-accent'; }
      else if (idLow.includes('gpt') || idLow.includes('openai')) { icon = 'fa-microchip'; accentClass = 'cloud-accent'; }
      else if (idLow.includes('recraft')) { icon = 'fa-vector-square'; accentClass = 'anime-accent'; }
      else if (idLow.includes('grok')) { icon = 'fa-rocket'; accentClass = 'turbo-accent'; }
      else if (idLow.includes('seedream')) { icon = 'fa-seedling'; accentClass = 'cgi-accent'; }
      else if (idLow.includes('qwen')) { icon = 'fa-dragon'; accentClass = 'mj-accent'; }
      else if (idLow.includes('krea')) { icon = 'fa-palette'; accentClass = 'pro-accent'; }

      return `
        <button class="image-model-item ${isSelected ? 'active' : ''}" type="button" data-model="${escapeHtml(m.id)}">
          <div class="image-model-icon-box ${accentClass}">
            <i class="${icon}"></i>
          </div>
          <div class="image-model-info">
            <div class="image-model-title-row">
              <span class="image-model-title">${escapeHtml(m.name || m.id)}</span>
              <span class="image-model-tag">${escapeHtml(m.tag || 'OpenRouter')}</span>
            </div>
            <span class="image-model-desc">${escapeHtml(m.desc || m.id)}</span>
          </div>
          <i class="fa-solid fa-check image-model-check" style="${isSelected ? 'display: block;' : 'display: none;'}"></i>
        </button>
      `;
    }).join('');

    // Pasang listener klik ke item model OpenRouter
    els.imageModelOpenRouterList.querySelectorAll('.image-model-item').forEach(item => {
      item.addEventListener('click', (e) => {
        e.stopPropagation();
        const modelVal = item.dataset.model;
        if (modelVal) setImageModel(modelVal);
      });
    });
  }

  function toggleImageModelDropdown(e) {
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    if (!els.imageModelDropdown) return;
    const isHidden = els.imageModelDropdown.style.display === 'none' || !els.imageModelDropdown.style.display;
    if (isHidden) {
      openImageModelDropdown();
    } else {
      closeImageModelDropdown();
    }
  }

  function openImageModelDropdown() {
    if (!els.imageModelDropdown) return;
    closeAttachmentDropdown();
    closeSearchDropdown();
    closeMusicModelDropdown();
    els.imageModelDropdown.style.display = 'flex';
    els.imageModelDropdown.scrollTop = 0;
    els.imageGenToggleBtn?.setAttribute('aria-expanded', 'true');

    // Auto switch ke tab OpenRouter jika model saat ini adalah model cloud OpenRouter
    const currentModel = STATE.settings.imageModel || 'flux';
    if (currentModel.includes('/')) {
      switchImageModelTab('openrouter');
    } else {
      switchImageModelTab('pollinations');
    }

    AudioEngine.click();
  }

  function closeImageModelDropdown() {
    STATE.photoEditAwaitingModel = false;
    if (!els.imageModelDropdown) return;
    els.imageModelDropdown.style.display = 'none';
    els.imageGenToggleBtn?.setAttribute('aria-expanded', 'false');
  }

  function setImageModel(modelVal) {
    STATE.photoEditAwaitingModel = false;
    if (modelVal === 'off') {
      STATE.isImageGenMode = false;
      updateImageGenModeUI();
      closeImageModelDropdown();
      clearPhotoEdit();
      AudioEngine.click();
      showToast('ℹ️ Mode Buat Gambar dinonaktifkan. Kembali ke obrolan biasa.');
      return;
    }

    STATE.settings.imageModel = modelVal;
    STATE.isImageGenMode = true;
    STATE.isMusicGenMode = false;
    try {
      localStorage.setItem('zoz_router_settings_v1', JSON.stringify(STATE.settings));
    } catch (_) {}
    updateImageGenModeUI();
    updateMusicGenModeUI();
    closeImageModelDropdown();
    AudioEngine.success();
    els.promptInput?.focus();
    const displayName = getImageModelDisplayName(modelVal);
    if (STATE.photoEditImage) {
      if (modelVal.includes('/') && !STATE.settings.openRouterKey) {
        showToast(`⚠️ Model Edit Foto ${displayName} dipilih. Butuh OpenRouter Key di Pengaturan.`, 'warning');
      } else {
        showToast(`🎨 Model Edit Foto Aktif: ${displayName}`);
      }
    } else {
      if (modelVal.includes('/') && !STATE.settings.openRouterKey) {
        showToast(`⚠️ Model ${displayName} aktif. Butuh OpenRouter Key di Pengaturan untuk menghasilkan gambar.`, 'warning');
      } else {
        showToast(`🎨 Model Gambar Aktif: ${displayName}`);
      }
    }
  }

  function togglePromptVisibility(forceState) {
    if (typeof forceState === 'boolean') {
      STATE.isPromptHidden = forceState;
    } else {
      STATE.isPromptHidden = !STATE.isPromptHidden;
    }

    updatePromptVisibilityUI(false);

    try {
      localStorage.setItem('zoz_prompt_hidden', STATE.isPromptHidden ? 'true' : 'false');
    } catch (_) {}

    AudioEngine.click();
    if (navigator.vibrate) {
      try { navigator.vibrate(25); } catch (_) {}
    }
  }

  function updatePromptVisibilityUI(silent = false) {
    const isHidden = Boolean(STATE.isPromptHidden);
    if (els.mainComposerContainer) {
      els.mainComposerContainer.classList.toggle('composer-collapsed', isHidden);
    }

    if (els.neutronCrownBtn) {
      els.neutronCrownBtn.classList.toggle('state-blue', isHidden);
      els.neutronCrownBtn.classList.toggle('state-red', !isHidden);
      // A11y: label DIPERBARUI sesuai state, bukan dihapus — dulu title/aria-label
      // dibuang setiap toggle sehingga tombol permanen "tak bernama" di screen reader.
      const crownLabel = isHidden ? 'Tampilkan kembali kolom prompt' : 'Sembunyikan kolom prompt';
      els.neutronCrownBtn.setAttribute('title', crownLabel);
      els.neutronCrownBtn.setAttribute('aria-label', crownLabel);
    }

    if (!silent && !isHidden) {
      setTimeout(() => {
        els.promptInput?.focus();
        autoResizeTextarea(els.promptInput);
      }, 60);
    }
  }

  async function runImageGeneration(session, promptText, customModel = null, referenceImage = null) {
    if (!promptText || !promptText.trim()) return;
    const cleanPrompt = promptText.trim();
    const activeImageModel = (customModel && typeof customModel === 'string') ? customModel : (STATE.settings.imageModel || 'flux');
    const isImgEdit = Boolean(referenceImage); // mode Edit Foto AI (img2img)
    
    setGeneratingState(true);
    STATE.abortController = new AbortController();

    const startTime = performance.now();
    const assistantRow = appendMessageElement('assistant', '', null, 'AI Image Studio');
    const bubbleText = assistantRow.querySelector('.msg-text-content');
    const metaBox = assistantRow.querySelector('.message-meta');

    // Render Creation Animation HUD
    bubbleText.innerHTML = `
      <div class="image-gen-hud">
        <div class="image-gen-header">
          <div class="image-gen-title-box">
            <i class="fa-solid fa-atom fa-spin" style="color:#FF007F;"></i>
            <span>${isImgEdit ? 'AI Photo Edit Studio (Img2Img)' : 'AI Image Studio (Neural Synthesis)'}</span>
          </div>
          <span class="image-gen-badge">${escapeHtml(activeImageModel)}</span>
        </div>
        <div class="image-gen-canvas-wrapper">
          <div class="image-gen-canvas-grid"></div>
          <div class="image-gen-laser-beam"></div>
          <div class="image-gen-holo-center">
            <div class="image-gen-holo-icon-wrap">
              <div class="image-gen-holo-ring"></div>
              <i class="fa-solid fa-wand-magic-sparkles image-gen-holo-core"></i>
            </div>
            <div class="image-gen-holo-label">Sintesis Kuantum Aktif</div>
          </div>
        </div>
        <div class="image-gen-telemetry">
          <div class="image-gen-status-row">
            <span class="image-gen-status-text">
              <i class="fa-solid fa-circle-notch fa-spin" style="color:#FF007F;"></i>
              <span class="image-gen-step-msg">[Langkah 1/3] Mengonversi semantik prompt ke ruang laten...</span>
            </span>
            <span class="image-gen-percent-text">15%</span>
          </div>
          <div class="image-gen-progress-track">
            <div class="image-gen-progress-fill" style="width: 15%;"></div>
          </div>
          <div class="image-gen-prompt-quote" title="${escapeHtml(cleanPrompt)}">
            "${escapeHtml(cleanPrompt)}"
          </div>
        </div>
      </div>
    `;
    smartScrollChatToBottom(true);

    const stepMsgEl = bubbleText.querySelector('.image-gen-step-msg');
    const percentEl = bubbleText.querySelector('.image-gen-percent-text');
    const progressFillEl = bubbleText.querySelector('.image-gen-progress-fill');

    function updateHudStep(stepText, percent) {
      if (stepMsgEl) stepMsgEl.innerText = stepText;
      if (percentEl) percentEl.innerText = `${percent}%`;
      if (progressFillEl) progressFillEl.style.width = `${percent}%`;
      smartScrollChatToBottom(false);
    }

    // Step 2 & Step 3 timed progression
    const timerStep2 = setTimeout(() => {
      updateHudStep(`[Langkah 2/3] Denoising matriks difusi ${escapeHtml(activeImageModel)}...`, 50);
    }, 700);

    const timerStep3 = setTimeout(() => {
      updateHudStep('[Langkah 3/3] Materialisasi kuantum, upscaling & render final...', 85);
    }, 2200);

    const isCloudModel = activeImageModel.includes('/');
    const displayName = getImageModelDisplayName(activeImageModel);

    try {
      if (isCloudModel && !STATE.settings.openRouterKey) {
        throw new Error(`Model cloud OpenRouter (${displayName}) memerlukan API Key. Silakan masukkan OpenRouter API Key Anda di menu Pengaturan > Provider Cloud, atau pilih model gratis di tab Pollinations.`);
      }

      let finalImageUrl = '';
      let resultModel = activeImageModel;
      let actualSeed = Math.floor(Math.random() * 100000000);

      if (!IS_GITHUB_PAGES) {
        try {
          const targetSessId = session ? session.id : (STATE.currentSessionId || null);
          const res = await fetch('/api/generate-image', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': STATE.settings.openRouterKey ? `Bearer ${STATE.settings.openRouterKey}` : '',
              'x-session-id': targetSessId || '',
              'X-User-ID': STATE.userId || 'default',
              'x-user-id': STATE.userId || 'default'
            },
            body: JSON.stringify({
              userId: STATE.userId || 'default',
              sessionId: targetSessId,
              prompt: cleanPrompt,
              model: activeImageModel,
              width: 1024,
              height: 1024,
              openRouterKey: STATE.settings.openRouterKey || '',
              // Foto referensi Img2Img (bila aktif) — server memilih jalur
              // Pollinations img2img POST / OpenRouter input_references otomatis.
              ...(isImgEdit ? { referenceImage: referenceImage } : {})
            }),
            signal: STATE.abortController?.signal
          });

          if (res.ok) {
            const data = await res.json();
            if (data.success && (data.url || data.localUrl)) {
              finalImageUrl = data.url || data.localUrl;
              resultModel = data.model || resultModel;
              actualSeed = data.seed || actualSeed;
            } else {
              throw new Error(data.error || 'Server tidak mengembalikan data gambar');
            }
          } else {
            let errorMsg = `Server HTTP ${res.status}`;
            try {
              const errData = await res.json();
              if (errData && errData.error) {
                errorMsg = typeof errData.error === 'object' ? (errData.error.message || JSON.stringify(errData.error)) : errData.error;
              }
            } catch (_) {}
            throw new Error(errorMsg);
          }
        } catch (serverErr) {
          if (serverErr.name === 'AbortError') throw serverErr;
          if (isCloudModel) {
            // Direct client-side OpenRouter API call if server endpoint is offline or errored
            if (STATE.settings.openRouterKey) {
              try {
                updateHudStep(`[Langkah 2/3] Menghubungi OpenRouter API langsung (${escapeHtml(displayName)})...`, 60);
                const directRes = await fetch('https://openrouter.ai/api/v1/images', {
                  method: 'POST',
                  headers: {
                    'Authorization': `Bearer ${STATE.settings.openRouterKey}`,
                    'Content-Type': 'application/json',
                    'HTTP-Referer': 'https://github.com/Zozi0999/zoz_router',
                    'X-Title': 'Zoz Router Image Studio'
                  },
                  body: JSON.stringify({
                    model: activeImageModel,
                    prompt: cleanPrompt,
                    aspect_ratio: '1:1',
                    // Kesimetrian dengan jalur server: foto referensi ikut dikirim
                    // sebagai input_references (skema resmi: object ContentPartImage)
                    // saat mode Edit Foto aktif.
                    ...(isImgEdit && referenceImage ? { input_references: [{ type: 'image_url', image_url: { url: referenceImage } }] } : {})
                  }),
                  signal: STATE.abortController?.signal
                });
                const directData = await directRes.json().catch(() => ({}));
                if (directRes.ok && directData.data?.[0]) {
                  const it = directData.data[0];
                  if (it.b64_json) {
                    finalImageUrl = `data:${it.media_type || 'image/png'};base64,${it.b64_json}`;
                  } else if (it.url) {
                    finalImageUrl = it.url;
                  }
                  resultModel = activeImageModel;
                } else {
                  const msg = typeof directData.error === 'object' ? (directData.error.message || JSON.stringify(directData.error)) : (directData.error || serverErr.message);
                  throw new Error(msg);
                }
              } catch (directErr) {
                if (directErr.name === 'AbortError') throw directErr;
                throw new Error(`Gagal menghasilkan gambar dari model OpenRouter (${displayName}): ${directErr.message}`);
              }
            } else {
              throw serverErr;
            }
          } else {
            console.warn('Backend image gen fallback ke direct Pollinations AI:', serverErr);
          }
        }
      }

      // Client-side Direct OpenRouter (untuk GitHub Pages jika IS_GITHUB_PAGES bernilai true)
      if (isCloudModel && !finalImageUrl) {
        if (STATE.settings.openRouterKey) {
          updateHudStep(`[Langkah 2/3] Menghubungi OpenRouter API langsung (${escapeHtml(displayName)})...`, 60);
          const directRes = await fetch('https://openrouter.ai/api/v1/images', {
            method: 'POST',
            headers: {
              'Authorization': `Bearer ${STATE.settings.openRouterKey}`,
              'Content-Type': 'application/json',
              'HTTP-Referer': 'https://github.com/Zozi0999/zoz_router',
              'X-Title': 'Zoz Router Image Studio'
            },
            body: JSON.stringify({
              model: activeImageModel,
              prompt: cleanPrompt,
              aspect_ratio: '1:1',
              ...(isImgEdit && referenceImage ? { input_references: [{ type: 'image_url', image_url: { url: referenceImage } }] } : {})
            }),
            signal: STATE.abortController?.signal
          });
          const directData = await directRes.json().catch(() => ({}));
          if (directRes.ok && directData.data?.[0]) {
            const it = directData.data[0];
            if (it.b64_json) {
              finalImageUrl = `data:${it.media_type || 'image/png'};base64,${it.b64_json}`;
            } else if (it.url) {
              finalImageUrl = it.url;
            }
            resultModel = activeImageModel;
          } else {
            const msg = typeof directData.error === 'object' ? (directData.error.message || JSON.stringify(directData.error)) : (directData.error || 'OpenRouter API gagal merespons');
            throw new Error(`Gagal menghasilkan gambar dari model OpenRouter (${displayName}): ${msg}`);
          }
        } else {
          throw new Error(`Model cloud OpenRouter (${displayName}) memerlukan API Key. Masukkan API Key di menu Pengaturan > Provider Cloud.`);
        }
      }

      // Client-side Direct Pollinations Fallback (HANYA UNTUK MODEL NON-CLOUD / POLLINATIONS)
      if (!isCloudModel && !finalImageUrl) {
        actualSeed = Math.floor(Math.random() * 100000000);
        let styledPrompt = cleanPrompt;
        const lowModel = activeImageModel.toLowerCase();
        if (lowModel === 'flux-realism' && !/photo|realis|cinematic/i.test(cleanPrompt)) {
          styledPrompt = `${cleanPrompt}, photorealistic, ultra-detailed 8k photography, cinematic lighting`;
        } else if (lowModel === 'flux-anime' && !/anime|manga|2d/i.test(cleanPrompt)) {
          styledPrompt = `${cleanPrompt}, anime aesthetic, high quality Japanese manga style, vibrant colors, detailed line art`;
        } else if (lowModel === 'flux-3d' && !/3d|cgi|render/i.test(cleanPrompt)) {
          styledPrompt = `${cleanPrompt}, 3d digital render, octane render, unreal engine 5, 3d cgi volumetric lighting`;
        } else if (lowModel === 'midjourney' && !/artistic|midjourney/i.test(cleanPrompt)) {
          styledPrompt = `${cleanPrompt}, midjourney aesthetic, artistic concept art, dramatic composition, breathtaking detail`;
        } else if (lowModel === 'flux-pro' && !/masterpiece|pro/i.test(cleanPrompt)) {
          styledPrompt = `${cleanPrompt}, masterpiece, professional award-winning composition, ultra sharp details`;
        }

        // Direct Pollinations POST jika mode edit foto dengan data URI base64
        if (isImgEdit && referenceImage && referenceImage.startsWith('data:')) {
          try {
            const pollPostRes = await fetch('https://image.pollinations.ai/', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                prompt: styledPrompt,
                model: activeImageModel,
                image: referenceImage,
                width: 1024,
                height: 1024,
                nologo: true,
                seed: actualSeed
              }),
              signal: STATE.abortController?.signal
            });
            if (pollPostRes.ok) {
              const blob = await pollPostRes.blob();
              if (blob && blob.size > 0) {
                finalImageUrl = URL.createObjectURL(blob);
              }
            }
          } catch (pollErr) {
            console.warn('Client direct Pollinations POST Img2Img notice:', pollErr);
          }
        }

        if (!finalImageUrl) {
          let urlPrompt = styledPrompt;
          if (urlPrompt.length > 800) {
            const cut = urlPrompt.slice(0, 800);
            const lastSpace = cut.lastIndexOf(' ');
            urlPrompt = (lastSpace > 600 ? cut.slice(0, lastSpace) : cut).trim();
          }
          const encoded = encodeURIComponent(urlPrompt);
          finalImageUrl = `https://image.pollinations.ai/prompt/${encoded}?width=1024&height=1024&model=${encodeURIComponent(activeImageModel)}&seed=${actualSeed}&nologo=true&enhance=true`;
          if (isImgEdit && referenceImage && /^https?:\/\//i.test(referenceImage)) {
            finalImageUrl += `&image=${encodeURIComponent(referenceImage)}`;
          }
        }
      }
      // Preload image to ensure 100% materialization animation (with 25s safety timeout to prevent infinite UI hang)
      await new Promise((resolve, reject) => {
        const testImg = new Image();
        const timeout = setTimeout(() => {
          // If preloading takes > 25s, proceed so UI doesn't hang indefinitely
          resolve();
        }, 25000);
        testImg.onload = () => {
          clearTimeout(timeout);
          resolve();
        };
        testImg.onerror = () => {
          clearTimeout(timeout);
          reject(new Error('Gagal memuat visual gambar yang digenerasi.'));
        };
        const abortSig = STATE.abortController?.signal;
        if (abortSig) {
          if (abortSig.aborted) {
            clearTimeout(timeout);
            return reject(new DOMException('Aborted', 'AbortError'));
          }
          abortSig.addEventListener('abort', () => {
            clearTimeout(timeout);
            reject(new DOMException('Aborted', 'AbortError'));
          }, { once: true });
        }
        testImg.src = finalImageUrl;
      });

      clearTimeout(timerStep2);
      clearTimeout(timerStep3);
      updateHudStep('[Langkah 3/3] Selesai! Menampilkan karya visual...', 100);

      const endTime = performance.now();
      const totalDuration = ((endTime - startTime) / 1000).toFixed(2);

      // Render Result Card with Materialization Animation
      const cardItem = {
        url: finalImageUrl,
        imageUrl: finalImageUrl,
        prompt: cleanPrompt,
        model: resultModel,
        width: 1024,
        height: 1024,
        seed: actualSeed,
        duration: totalDuration
      };

      bubbleText.innerHTML = createGeneratedImageCardHtml(cardItem);
      attachImageCardListeners(assistantRow, cleanPrompt, finalImageUrl, resultModel, referenceImage || null);

      if (metaBox) {
        metaBox.innerHTML = `
          <strong>AI Image Studio</strong>
          <span class="meta-model-badge" style="background:rgba(255,0,127,0.18); border-color:#FF007F; color:#FF66B2;"><i class="fa-solid fa-wand-magic-sparkles"></i> ${escapeHtml(resultModel)}</span>
          <span>⏱️ ${totalDuration}s</span>
        `;
      }

      // Save to Session if session is still alive
      if (STATE.sessions.some(s => s.id === session.id)) {
        session.messages.push({
          role: 'assistant',
          content: `[Gambar AI Hasil Generasi: "${cleanPrompt}"]`,
          type: 'image_generation',
          isImageGen: true,
          imageUrl: finalImageUrl,
          url: finalImageUrl,
          prompt: cleanPrompt,
          model: resultModel,
          referenceImage: referenceImage || null,
          isPhotoEdit: isImgEdit,
          width: 1024,
          height: 1024,
          seed: actualSeed,
          stats: { duration: totalDuration },
          timestamp: new Date().toISOString()
        });
        session.updatedAt = new Date().toISOString();
        savePersistedState();
        renderChatHistory(els.searchHistoryInput?.value || '');
      }

      AudioEngine.success();
      smartScrollChatToBottom(true);

    } catch (err) {
      clearTimeout(timerStep2);
      clearTimeout(timerStep3);

      if (err.name === 'AbortError') {
        assistantRow.remove();
        showToast('Generasi gambar dibatalkan oleh pengguna.');
      } else {
        console.error('Image gen error:', err);
        const isKeyOrCloudErr = isCloudModel || (err.message && (err.message.includes('API Key') || err.message.includes('OpenRouter') || err.message.includes('kredit')));
        bubbleText.innerHTML = `
          <div style="background:rgba(255,0,127,0.08); border:1px solid rgba(255,0,127,0.4); border-radius:10px; padding:14px; line-height:1.5;">
            <div style="font-weight:700; color:#FF2E93; margin-bottom:6px; display:flex; align-items:center; gap:8px;">
              <i class="fa-solid fa-triangle-exclamation"></i> Gagal Menghasilkan Gambar AI
            </div>
            <div style="font-size:0.83rem; color:var(--text-main); margin-bottom:8px;">
              ${escapeHtml(err.message || 'Terjadi gangguan saat memproses rendering difusi.')}
            </div>
            <div style="margin-top:10px; display:flex; flex-wrap:wrap; gap:8px;">
              <button class="btn btn-sm btn-primary retry-img-btn" style="font-size:0.75rem;">
                <i class="fa-solid fa-rotate-right"></i> Coba Generate Ulang
              </button>
              ${isKeyOrCloudErr ? `
              <button class="btn btn-sm btn-outline open-key-settings-btn" style="font-size:0.75rem; border-color:var(--neon-teal); color:var(--neon-teal);">
                <i class="fa-solid fa-key"></i> Buka Pengaturan API Key
              </button>
              ` : ''}
            </div>
          </div>
        `;
        bubbleText.querySelector('.retry-img-btn')?.addEventListener('click', () => {
          if (STATE.isGenerating || STATE.isSending) return;
          assistantRow.remove();
          runImageGeneration(session, cleanPrompt, activeImageModel, referenceImage || null);
        });
        bubbleText.querySelector('.open-key-settings-btn')?.addEventListener('click', () => {
          const modal = $('#settingsModal');
          if (modal) {
            modal.querySelectorAll('.settings-tab-btn').forEach(btn => btn.classList.toggle('active', btn.dataset.tab === 'tabProviders'));
            modal.querySelectorAll('.settings-tab-pane').forEach(pane => pane.classList.toggle('active', pane.id === 'tabProviders'));
          }
          openModal('settingsModal');
          setTimeout(() => els.settingOpenRouterKey?.focus(), 120);
        });
        AudioEngine.error();
      }
    } finally {
      setGeneratingState(false);
      STATE.abortController = null;
    }
  }

  // ====================================================
  // AI MUSIC STUDIO & CYBER AUDIO PLAYER ENGINE
  // ====================================================
  function buildCyberAudioPlayerCardHtml(track) {
    const safeUrl = escapeHtml(track.url || track.audioUrl || '');
    const safeTitle = escapeHtml(track.title || 'Singularity Cyber Audio');
    const safeGenre = escapeHtml(track.genre || 'Cyberpunk');
    const bpm = track.bpm || null;
    const dur = track.duration || 15;
    const safePrompt = escapeHtml(track.prompt || '');
    const aiSummary = escapeHtml(track.aiSummary || '');
    const isAiComposed = Boolean(track.aiComposed);
    const trackId = 'cyber_audio_' + Math.random().toString(36).substring(2, 9);

    return `
      <div class="cyber-audio-card" id="${trackId}">
        <div class="cyber-audio-body">
          <div class="cyber-audio-title-row">
            <div class="cyber-audio-title"><i class="fa-solid fa-headphones" style="color:var(--neon-teal); margin-right:6px;"></i> ${safeTitle}</div>
            <div style="display:flex; gap:6px; align-items:center;">
              <span class="image-meta-badge" style="color:var(--neon-teal); border-color:rgba(0,255,194,0.4);"><i class="fa-solid fa-compact-disc"></i> ${safeGenre.toUpperCase()}</span>
              ${isAiComposed ? `<span class="image-meta-badge" style="color:#00F0FF; border-color:rgba(0,240,255,0.4); background:rgba(0,240,255,0.1);"><i class="fa-solid fa-brain"></i> AI Composed</span>` : ''}
            </div>
          </div>
          ${aiSummary ? `<div class="cyber-audio-ai-summary" style="font-size:0.75rem; color:var(--text-dim); margin-top:5px; margin-bottom:8px; line-height:1.45; display:flex; align-items:flex-start; gap:6px; border-left:2px solid var(--neon-teal); padding-left:8px; background:rgba(0,255,194,0.03); border-radius:0 6px 6px 0;"><i class="fa-solid fa-wand-magic-sparkles" style="color:var(--neon-teal); margin-top:2px; flex-shrink:0;"></i><span>${aiSummary}</span></div>` : ''}
          <div class="cyber-audio-wave-wrap">
            <canvas class="cyber-audio-wave-canvas" width="480" height="48"></canvas>
          </div>
          <div class="cyber-audio-controls-row">
            <button type="button" class="cyber-audio-play-btn" data-url="${safeUrl}" title="Putar / Jeda Audio"><i class="fa-solid fa-play"></i></button>
            <div class="cyber-audio-scrubber-wrap">
              <input type="range" class="cyber-audio-scrubber" min="0" max="100" value="0" step="0.1">
              <div class="cyber-audio-time-row">
                <span class="curr-time">0:00</span>
                <span class="total-time">0:${dur < 10 ? '0' + dur : dur}</span>
              </div>
            </div>
            <audio preload="metadata" src="${safeUrl}" style="display:none;"></audio>
          </div>
          <div class="image-meta-badges">
            ${bpm ? `<span class="image-meta-badge"><i class="fa-solid fa-gauge-high"></i> ${bpm} BPM</span>` : ''}
            <span class="image-meta-badge"><i class="fa-solid fa-clock"></i> ${dur}s</span>
            <span class="image-meta-badge" style="color:var(--neon-teal); border-color:rgba(0,255,194,0.3);"><i class="fa-solid fa-microchip"></i> ${isAiComposed ? 'AI Neural Music Architect' : 'Neural Audio Synth'}</span>
          </div>
          <div class="image-actions-bar">
            <a href="${safeUrl}" download="${safeTitle}.mp3" class="btn btn-xs btn-outline">
              <i class="fa-solid fa-download"></i> Unduh Audio
            </a>
            ${safePrompt ? `<button type="button" class="btn btn-xs btn-outline copy-audio-prompt-btn" data-prompt="${safePrompt}"><i class="fa-solid fa-copy"></i> Salin Prompt</button>` : ''}
          </div>
        </div>
      </div>
    `;
  }

  function attachAudioPlayerListeners(container) {
    if (!container) return;
    const cards = container.querySelectorAll('.cyber-audio-card');
    cards.forEach(card => {
      if (card.dataset.listenersAttached) return;
      card.dataset.listenersAttached = 'true';

      const audio = card.querySelector('audio');
      const playBtn = card.querySelector('.cyber-audio-play-btn');
      const scrubber = card.querySelector('.cyber-audio-scrubber');
      const currTimeEl = card.querySelector('.curr-time');
      const totalTimeEl = card.querySelector('.total-time');
      const canvas = card.querySelector('.cyber-audio-wave-canvas');
      const copyPromptBtn = card.querySelector('.copy-audio-prompt-btn');

      if (!audio || !playBtn) return;

      // ID rAF disimpan pada ELEMEN AUDIO (bukan variabel lokal per-kartu) supaya
      // listener pause/ended/error bisa membatalkan loop dari mana pun — dulu hanya
      // tombol pause manual & 'ended' yang membatalkan, sehingga loop waveform bocor
      // terus berjalan saat kartu lain mengambil alih pemutaran (audio.pause() massal).
      function stopWaveAnim() {
        if (audio._waveAnimId) {
          cancelAnimationFrame(audio._waveAnimId);
          clearTimeout(audio._waveAnimId);
          audio._waveAnimId = null;
        }
      }
      function drawWaveform(isPlaying) {
        if (!canvas || typeof canvas.getContext !== 'function') return;
        stopWaveAnim(); // cegah penumpukan beberapa loop pada kartu yang sama

        // Hemat daya: jika tab tersembunyi atau kartu audio berada di luar viewport, tunda render
        if (isPlaying && (document.hidden || !canvas.offsetParent)) {
          audio._waveAnimId = setTimeout(() => {
            if (!audio.paused) drawWaveform(true);
          }, 500);
          return;
        }

        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        const w = canvas.width;
        const h = canvas.height;
        ctx.clearRect(0, 0, w, h);

        const bars = 48;
        const barW = w / bars;
        const now = performance.now() * 0.005;

        // Inisialisasi gradien SEKALI per frame, bukan 48 kali per frame (menghemat 5.600+ alokasi Skia/detik)
        const grad = ctx.createLinearGradient(0, 0, 0, h);
        grad.addColorStop(0, '#00FFC2');
        grad.addColorStop(1, '#00F0FF');
        ctx.fillStyle = grad;

        for (let b = 0; b < bars; b++) {
          let barHeight;
          if (isPlaying) {
            barHeight = (Math.sin(now + b * 0.4) * 0.5 + 0.5) * (h * 0.75) + 4;
          } else {
            barHeight = Math.sin(b * 0.3) * (h * 0.3) + (h * 0.35);
          }
          ctx.fillRect(b * barW + 1, h - barHeight, barW - 2, barHeight);
        }

        if (isPlaying) {
          audio._waveAnimId = requestAnimationFrame(() => drawWaveform(true));
        }
      }
      drawWaveform(false);

      playBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        if (audio.paused) {
          document.querySelectorAll('.cyber-audio-card audio').forEach(a => { if (a !== audio) a.pause(); });
          document.querySelectorAll('.cyber-audio-card .cyber-audio-play-btn').forEach(b => { if (b !== playBtn) b.innerHTML = '<i class="fa-solid fa-play"></i>'; });

          audio.play().then(() => {
            playBtn.innerHTML = '<i class="fa-solid fa-pause"></i>';
            drawWaveform(true);
          }).catch(err => {
            console.warn('Audio play error:', err);
          });
        } else {
          audio.pause();
          playBtn.innerHTML = '<i class="fa-solid fa-play"></i>';
          stopWaveAnim();
          drawWaveform(false);
        }
      });

      audio.addEventListener('timeupdate', () => {
        if (!audio.duration) return;
        const pct = (audio.currentTime / audio.duration) * 100;
        if (scrubber) scrubber.value = pct;
        if (currTimeEl) {
          const mins = Math.floor(audio.currentTime / 60);
          const secs = Math.floor(audio.currentTime % 60);
          currTimeEl.innerText = `${mins}:${secs < 10 ? '0' + secs : secs}`;
        }
      });

      audio.addEventListener('loadedmetadata', () => {
        if (!audio.duration || !totalTimeEl) return;
        const mins = Math.floor(audio.duration / 60);
        const secs = Math.floor(audio.duration % 60);
        totalTimeEl.innerText = `${mins}:${secs < 10 ? '0' + secs : secs}`;
      });

      audio.addEventListener('ended', () => {
        playBtn.innerHTML = '<i class="fa-solid fa-play"></i>';
        drawWaveform(false);
        if (scrubber) scrubber.value = 0;
      });

      // Resume dari LUAR tombol (media key OS, play() eksternal, kartu lain selesai
      // dipause-massal) wajib menghidupkan lagi loop waveform + ikon pause. Listener
      // 'play' mencakup SEMUA jalur pemutaran (klik tombol di atas ikut tercakup —
      // idempoten karena drawWaveform selalu stopWaveAnim dulu).
      audio.addEventListener('play', () => {
        playBtn.innerHTML = '<i class="fa-solid fa-pause"></i>';
        drawWaveform(true);
      });

      // Pause dari LUAR tombol (kartu lain diputar, media key OS, error sumber)
      // wajib menghentikan rAF loop + mengembalikan ikon — kalau tidak, loop tidak
      // pernah berhenti dan tombol terlihat masih "pause" padahal audio sudah diam.
      audio.addEventListener('pause', () => {
        playBtn.innerHTML = '<i class="fa-solid fa-play"></i>';
        stopWaveAnim();
        drawWaveform(false);
      });
      audio.addEventListener('error', () => {
        playBtn.innerHTML = '<i class="fa-solid fa-play"></i>';
        stopWaveAnim();
        drawWaveform(false);
      });

      scrubber?.addEventListener('input', () => {
        if (!audio.duration) return;
        audio.currentTime = (scrubber.value / 100) * audio.duration;
      });


      copyPromptBtn?.addEventListener('click', (e) => {
        e.stopPropagation();
        copyTextToClipboard(copyPromptBtn.dataset.prompt || '', () => {
          showToast('📋 Prompt musik berhasil disalin!');
        });
      });
    });
  }

